// Generated by tools/docs/generate-docs-bundle.mjs — do not edit by hand (the same file in packages/grip-forge and packages/mcp-client).
// The docs read by `grip-forge docs` and the MCP tool `gripforge_docs`, embedded so they read offline.

export interface DocTopic { id: string; title: string; summary: string; source: string; text: string }

export const DOC_TOPICS: readonly DocTopic[] = [
 {
  "id": "glossary",
  "title": "Glossary",
  "summary": "The words of the docs: KitHost, module, ABI, slot, view, hook, passport…",
  "source": "docs/glossary.md",
  "text": "# Glossary\n\nThe words of the GripForge docs, in plain English. `grip-forge docs glossary`, MCP `gripforge_docs { topic: \"glossary\" }`.\n\n| Word | Meaning |\n|---|---|\n| **ABI** | The binary contract between the player and a presentation module: `gripforge:present@1` (`format/src/present_abi.rs`, described in `format/present.wit`). Version 1, extended only by appended variants (v1.1, v1.2). |\n| **Adapter** | The implementation of a kit for one target (web, rust, godot, unity, unreal). Its status: `native` (runs), `files` (emits engine files), `recipe` (a checklist), `planned` (nothing yet). |\n| **API reference** | The generated documentation of a kit: config, hooks, events, views, services, verbs, slots, collections, mod points, module, targets, changelog, examples (`docs/kit-api.md`). |\n| **Archetype** | A reusable entity template of `game.engine` (`kind`, components, model slot) that scenes place as instances. |\n| **Bare player** | The Bevy player without any game or kit code: renderer, generic layers, module host (`docs/player.md`). |\n| **Board (planche)** | The before/after capture comparison of the player: 0 = identical, under 5 = good (`qa/player-planche.py`). |\n| **Capability** | A contract a kit provides or requires (`combat.health`, `game.engine@^1`). Any kit providing it satisfies a requirement. Also the name of the service object another kit reads. |\n| **Caps** | Bits the host announces to modules (`Init::host.caps`): what it draws beyond the baseline (WGSL materials, post passes, web UI…). |\n| **Claim** | A module saying \"I draw this entity / this part\": the generic layer then leaves it alone. |\n| **Collection** | A list of documents a kit owns in the project data (`missions`, `boons`, `rooms`), with a schema. |\n| **Command trace** | The text form of the commands a module sends, one per line (meshes and textures as size + digest, floats to 4 decimals), written by the SDK harness and compared in tests (`tests/<name>.trace`). |\n| **Compiled presenter** | The old presenters compiled into the player (`player/src/kits`, features `builtin-presenters` / `legacy`), removed: every kit is drawn by its module. `qa/player-no-kit-code-check.mjs` keeps them out. |\n| **Config** | The settings of a kit in a project (`installed[].config`), validated by its `configSchema`. |\n| **Event** | A message a kit emits on the bus when something happened (`combat.died`), with a payload schema. Others listen to it; scripts react to it. |\n| **Fingerprint** | A hash of the sources of a package or module; it names the files so a cache never mixes versions. |\n| **Fragment** | A piece of web UI (React components or HTML templates) mounted by `ui.webui` over the game. |\n| **FrameIn / FrameOut** | The input of a module each frame (what changed in what it declared) and its answer (the list of commands), postcard bytes. |\n| **game.engine** | The kit every game is built on: scenes, content, scripts, hooks, mods, saves (`docs/game-engine.md`). |\n| **Generic layer** | What the player draws for every game without a module: entities and their bound models, camera, ground, lights. |\n| **Harness** | The SDK test runner (`sdk/src/harness.rs`): replays snapshots through a module exactly as a host would and checks its command trace, without a GPU. |\n| **Hook** | A decision of a kit a game or a mod may intercept before it applies (damage, purchase, spawn): change mutable fields or cancel. |\n| **InputTracker** | The part of a host that turns successive snapshots into the deltas each module declared (`FrameIn`); every host has one (a port for a non-Bevy host). |\n| **Kit host (Rust)** | `native/gripforge-kithost`: the Rust mirror of the TypeScript KitHost, same kits and same contract, used natively and for parity tests. |\n| **Kit** | A brick of gameplay or presentation (`combat.core`, `world.rooms`): manifest, runtime, README, API notes. |\n| **KitHost** | The runtime that runs the kits of a game: TypeScript in the page (web), Rust (`gripforge-kithost`) natively. It makes a snapshot each frame. |\n| **Library** | The workspace store of assets (models, textures, sounds, VFX) of the GripForge site; slots bind its items. |\n| **Live settings** | Values of a kit's `<capability>.settings` service a game or a reaction may change while the game runs (`engine.moddable.settings`). |\n| **Manifest** | The declaration of a kit (`manifest.ts`): id, version, capabilities, config schema, events, hooks, slots… Its hash locks the version. |\n| **Mod points** | What a kit lets mods change (`engine.moddable`): config keys, collections, live settings, registries. |\n| **Mod** | A `gripforge.mod/1` JSON document applied over a project before the kits mount: config, collections, hooks, scripts. Data only, never code. |\n| **Module (presentation module)** | The drawing of one kit, in plain Rust compiled to `.wasm`, run by the module host. It reads its needs and answers commands. |\n| **Module host** | The part of the player that runs modules and applies their commands, by family (mesh, material, node, scene, fx, ui, skeleton, camera/post/audio). |\n| **naga** | The shader translator the hosts use to validate WGSL and turn it into GLSL ES 3.0 (WebGL2), HLSL, SPIR-V or MSL. |\n| **Needs** | What a module declares it reads: components, events, data, views of services, settings, shared keys, commands it may send. |\n| **Parity fixture** | A list of operations played on the TypeScript and on the Rust kit host to prove they behave the same (`gripforge-kithost/parity/*.json`). |\n| **Passport (mesh passport)** | What an asset says about itself: real size, orientation, skeleton, colliders, clips, plus sections kits own (`lod` for render.lod). Made by the studios (`packages/core/src/mesh-passport.ts`), carried by the game in the `asset_passports` collection of `asset.meta`; kits read it instead of guessing from the file. |\n| **Port** | An interface a kit runtime gets from its host instead of importing an engine: physics, assets (`ctx.physics`, `ctx.assets`), so the same kit code runs headless. |\n| **postcard** | The compact binary encoding (a Rust serde format) of every ABI payload; field order is encoding order. |\n| **Preset** | A genre template: the kits, configs, data and control scheme a new game of that genre starts with. |\n| **Registry** | A collection of things \"by type\" (enemy types, weapons) where a document may `extends` another. |\n| **Role (of a kit)** | How a kit plugs into game.engine: `world` (builds a scene's ground), `layer` (dresses a scene), `content` (vocabulary: components, verbs, collections), `actor` (places actors), `view` (shows content), `flow` (game life cycle, saves), `service` (a pure service). |\n| **Scene** | A place of a game in `game.engine`: its world kit document, its layers, its instances and its data; a game moves between scenes. |\n| **Share** | State computed by a module and published to other modules (`out.share`). Never a copy of a kit view. |\n| **Slot** | A named place where a kit draws a Library item (`player_model`, `ground_texture`), bound by the project. |\n| **Snapshot** | What the KitHost sends the player each frame: entities, views, vars, new events. |\n| **Start pack** | What `game.engine` hands an agent when a project starts: the content order, where custom code goes, what to fill next. |\n| **StdMaterial** | The baseline material of the ABI (glTF metallic-roughness or unlit) every host must reproduce. |\n| **Tap** | One interception of a hook (a hooks document): `{ hook, match?, if?, set?, add?, mul?, cancel? }`. |\n| **Trigger DSL / script** | Rules `{ when: <condition>, then: [<actions>] }` of game.engine that react to events and state; kits add verbs to it. |\n| **ui.webui** | The kit that carries every HUD and menu of the web player as DOM. |\n| **Var** | A GameState path a kit publishes (`player.health`), readable by the HUD and scripts. |\n| **Verb** | An action or condition of the script language a kit provides (`give_item`, `has_item`). |\n| **View** | (1) A web interface of a kit, declared in its manifest (`webViews`). (2) A method of a service a module polls (`world.atmosphere.sky`). |\n| **wasmtime / AOT / .cwasm / wasmi / Pulley** | Native WebAssembly runtimes: wasmtime compiles modules ahead of time (AOT) into `.cwasm` files; wasmi and Pulley interpret them where compiling is not allowed (iOS). Planned for the native hosts. |\n| **WebGL2 fallback** | Every web player package holds WebGPU and WebGL2 and switches by itself; mandatory. |\n| **WGSL dialect** | The subset of WGSL a module may send: plain functions, no imports, no bindings, no compute. |\n"
 },
 {
  "id": "kit-api",
  "title": "Kit API reference",
  "summary": "How to read the API reference of a kit (grip-forge kit api <id>, gripforge_gamekit_api) and how it is made and checked.",
  "source": "docs/kit-api.md",
  "text": "# The API reference of the kits\n\nEvery kit has a complete, generated API reference. It is the first thing to read before configuring a kit, writing a\nmod for it, or writing its presentation module.\n\n## Where to read it\n\n| Who | How |\n|---|---|\n| AI agent (MCP) | `gripforge_gamekit_api { id, sections? }` (compact Markdown), or `gripforge_gamekit_get { id, section: \"api\" }` (JSON) |\n| CLI | `grip-forge kit api <id> [--section config,hooks] [--json] [--full]` |\n| HTTP | `GET /api/v1/gamekits/<id>/api` (JSON), `?format=md`, `&compact=1`, `&sections=config,hooks` |\n| Catalogue | the **API** tab of a kit page |\n| Code | `defaultRegistry().apiReference(id)`, `kitApiMarkdown(ref)` (`@gripforge/gamekits`) |\n\n## What it holds\n\n| Section | From | Content |\n|---|---|---|\n| summary | `kits/<id>/api.ts` | 3 to 5 lines: what the kit does, when to use it, with which kits |\n| config | manifest `configSchema` + notes | every key at every depth: type, default, unit, limits, flags `mod` (a mod may set it), `live` (read again while running), `scene` (a scene may override it) |\n| hooks | `engine.hooks` | payload fields, mutable fields, cancellable, targets, example tap |\n| events | `events.emits` / `listens` | when, payload fields, sample payload; for a listened topic, the kits that emit it |\n| views | `webViews`, `vars` | web interfaces of the kit and its HUD variables |\n| services | `provides` + runtime | capabilities, the service object (`ctx.services.get`) and its methods |\n| verbs | `engine.verbs`, `extensions` | script actions and conditions with their arguments |\n| slots | `assets` | asset slots: kinds, required, creature role and clips |\n| collections | `data`, `engine.registries` | data collections: fields, example document, mod / live / per scene, registry with `extends` |\n| inputs | `inputs`, `sticks` | input actions and default keys |\n| modding | `engine.moddable` | every mod point in one place |\n| module | `native/gripforge-runtime/modules/<dir>` | the Bevy presentation module: version, needs, commands to the kit host, ABI command families, WGSL files, web UI (`web/ui.json`) |\n| parity | adapters, Rust kit host, module | status per target |\n| changelog | manifest | versions, breaking changes |\n| examples | notes, or generated | a config, and a `gripforge.mod/1` mod that adapts the kit |\n| readme | `docs.ts` | the README of the kit (full form only) |\n\n## How it is made\n\n- `packages/gamekits/src/api-reference.ts` builds the reference (`kitApiReference`), renders Markdown\n  (`kitApiMarkdown`) and scores it (`kitApiScore`).\n- `kits/<id>/api.ts` holds the hand-written notes (`KitApiDocs`): the summary and, per element, a better\n  `description`, a `unit`, `when` it happens, an `example`; service methods; examples. It is **not** part of the\n  manifest: improving the wording bumps no version and keeps the integrity hash.\n- `tools/gamekits/generate-kit-api.mjs` writes `kit-api.generated.ts`: the imports of the notes, the services found in\n  the web runtime, the Rust kit host mirror, and the presentation module read from its Rust sources (needs, the\n  `out.*` helpers it calls mapped to ABI commands and to the families of `player/src/module_host.rs`, `web/ui.json`).\n  `--check` fails when it is stale.\n\n## The check (CI)\n\n`node qa/gamekits-api-docs-check.mjs` (in `pnpm qa:gamekits`, so in the `kits` job of `network.yml`):\n\n- the generated sources are up to date; every reference builds and holds the sections the kit has;\n- per kit, **coverage** (elements described / elements) and **quality** (elements that are described, at least 25\n  characters, not just the name again, with a unit for a number, saying when an emitted event or a hook happens);\n- `qa/gamekits-api-docs-baseline.json` only goes up: a kit may not fall below its line, a new kit must arrive at 100 %\n  coverage with a summary. After an improvement: `--write-baseline`.\n\nOptions: `--kit=<id>` (every issue of one kit), `--report` (table of every kit), `--json=<file>`, `--src` (read the\nTypeScript sources with `node --import ./qa/ts-register.mjs`, no build).\n\n## Writing the notes of a kit\n\n```ts\nimport type { KitApiDocs } from '../../api-reference.js';\nexport const api: KitApiDocs = {\n  summary: `What it does. When to use it. Which kits it works with.`,\n  config: { quotaMB: { unit: 'MB', when: 'Read at start.' } },\n  events: { 'asset.cache.hit': { when: 'Emitted when …' } },\n  services: { 'asset.cache': { description: '…', methods: { 'stats()': 'Returns …' } } },\n  examples: { config: { quotaMB: 1024 } },\n};\n```\n\nModel: `kits/asset.cache/api.ts`. Then `node tools/gamekits/generate-kit-api.mjs` and the check with `--kit=<id>`.\nWrite from the code (manifest, runtime, README), in simple English; never invent a key or a unit.\n"
 },
 {
  "id": "third-party",
  "title": "Third-party developer guide",
  "summary": "Modules, mods, UI and games made outside GripForge: SDK, needs, commands, WGSL, caps, assets, fonts, ui.webui, publishing, ABI compatibility.",
  "source": "docs/third-party-guide.md",
  "text": "# Third-party developer guide\n\nFor developers outside GripForge who build **presentation modules**, **mods**, **UI** or **games** on GripForge kits.\nEverything here is a public contract: what you may rely on, how to build, test, ship and install. Words in *italics*\nare in the [glossary](glossary.md). Readable offline: `grip-forge docs third-party`, or the MCP tool `gripforge_docs`\n(topic `third-party`).\n\nContents: 1. What you can build · 2. Reading a kit's API · 3. Writing a mod · 4. Writing a presentation module ·\n5. Host capabilities (caps) · 6. Your own assets, fonts and UI · 7. Publishing and installing · 8. ABI compatibility\nrules · 9. Checklist.\n\n## 1. What you can build\n\n| You want to… | Build | Runs as | Trust |\n|---|---|---|---|\n| change rules, numbers, content of a game | a **mod** (`gripforge.mod/1` JSON) | data applied before the kits mount | untrusted data: only what kits declare moddable |\n| react to events, intercept decisions | **hooks** and **scripts** documents (in a mod or in the project) | data, run by `game.engine` | same as a mod |\n| draw a kit differently, or draw a new kit | a **presentation module** (Rust → `.wasm`) | sandboxed WebAssembly, no imports | can only send ABI commands |\n| add a rule of game logic no kit and no mod can express | a **kit logic module** (Rust → `.wasm`, built alone): [kit-third-party.md](kit-third-party.md), `grip-forge docs kit-third-party` | its own WebAssembly beside the core, as every kit of the game (the kit modules are the Rust logic of the page) | sandboxed: it only calls the `kithost.*` interfaces of the core |\n| add a HUD or a menu | a **ui.webui fragment** (React components or HTML templates) | code in the page | the trust of mod scripts (see §6.3) |\n| a whole game | a project made of kits (CLI / MCP) | the kits | — |\n\nA mod never carries code that runs in the game logic. A module never touches the game state: it reads what it\ndeclared and answers commands.\n\n## 2. Reading a kit's API\n\nEvery kit has a generated API reference: config keys (type, default, unit, limits, mod / live flags), hooks\n(payload, mutable fields, cancellable), events (payload), views, services, script verbs, asset slots, data\ncollections, mod points, its presentation module (needs, ABI families, web UI), target parity, changelog and\nexamples of a config and of a mod. Read it **before** configuring a kit, writing a mod or a module for it:\n\n- CLI: `grip-forge kit api <id> [--section config,hooks] [--json]`\n- MCP: `gripforge_gamekit_api { id, sections? }`, or `gripforge_gamekit_get { id, section: \"api\" }`\n- HTTP: `GET /api/v1/gamekits/<id>/api` (`?format=md`, `?compact=1`)\n- Catalogue: the **API** tab of the kit page.\n\nHow the reference is made and checked: [kit-api.md](kit-api.md).\n\n## 3. Writing a mod\n\nA mod is one JSON document (`gripforge.mod/1`), stored in the `mods` collection of `game.engine` in a project:\n\n```json\n{\n  \"schema\": \"gripforge.mod/1\",\n  \"id\": \"hard_mode\", \"name\": \"Hard mode\", \"version\": \"1.0.0\",\n  \"requires\": { \"game.engine\": \"^1.2\", \"combat.core\": \"^1\" },\n  \"config\": { \"combat.core\": { \"playerHealth\": 60, \"friendlyFire\": true } },\n  \"data\": {\n    \"hooks\": { \"add\": [\n      { \"id\": \"harder_hits\", \"hook\": \"combat.damage\", \"mul\": { \"amount\": 1.5 } },\n      { \"id\": \"no_heal_in_boss\", \"hook\": \"combat.heal\", \"if\": [{ \"var\": \"boss.active\", \"op\": \"==\", \"value\": true }], \"cancel\": true, \"reason\": \"boss\" }\n    ] }\n  }\n}\n```\n\n- **Config**: `config.<kit>.<key>` merges an object key by key and **replaces** anything else — an array is replaced\n  whole. To change ONE element of a config list, use `configPatch` (game.engine 1.3):\n  `\"configPatch\": { \"survival.needs\": { \"update\": { \"needs\": [{ \"match\": { \"id\": \"hunger\" }, \"set\": { \"drain\": 0.3 } }] } } }`\n  — operations `set` (by dotted path), `append`, `update` (`match` + `set`) and `remove` on the lists at a path.\n- **What you may touch**: only config keys, collections and live settings the kit lists in its *mod points*\n  (`engine.moddable`, section \"Mod points\" of its API reference). Anything else refuses the whole mod.\n- **Content**: `data.<collection>` with `remove: [ids]`, `patch: [{ id, set?, remove?, update?, append? }]`,\n  `add: [documents]`, applied in that order. A *registry* collection accepts `{ \"id\": \"fire_imp\", \"extends\": \"imp\" }`.\n- **Hooks** (a *tap*): `{ id, hook, priority?, match?, if?, set?, add?, mul?, min?, max?, cancel?, reason? }` — change\n  the mutable fields of a decision or cancel it. The hook list and their payloads are in the kit's API reference.\n- **Scripts**: rules `{ when: <condition>, then: [<actions>] }` on events; verbs are listed per kit.\n- **What validation does not check**: `applied` means the mod's config and documents were accepted. A tap is checked\n  when the decision runs: a tap that writes a field the hook does not list as `mutable`, or a value of the wrong\n  type, is dropped at run time (event `engine.hook.refused`); a hook name no kit declares is only a warning\n  (`hook_unknown`). Take hook names and mutable fields from the kit's API reference, and watch `engine.hook.refused`\n  while testing. A hook runs only when the kit asks that decision: its API reference says when.\n- **Order and failure**: mods apply in the game's order (`mods.order`), after the mods they depend on; one error\n  refuses the whole mod (readable codes: `config_not_moddable`, `collection_not_moddable`, `kit_incompatible`…).\n- **The game decides**: `game.engine` config `mods.enabled`, `mods.disabled`, `mods.deny: { kits, collections, hooks }`.\n\nInstall, validate, order: MCP `gripforge_game_mods { project_id, action: validate | install | enable | disable | order | remove, mod }`.\nFull format and every rule: `grip-forge docs modding` (§3 is the mod format, §4 hooks, §13 game.engine 1.3).\n\n## 4. Writing a presentation module\n\nA module is the presentation of **one kit**, in plain Rust (no Bevy, no engine), compiled to\n`wasm32-unknown-unknown`. The recipe with every detail is [PORTING.md](../native/gripforge-runtime/modules/PORTING.md)\n(`grip-forge docs porting`); the contract is `format/src/present_abi.rs` and its engine-neutral description\n`format/present.wit` (`grip-forge docs abi`).\n\n### 4.1 The SDK\n\n```rust\nuse gripforge_present_sdk::{Module, Needs, Out, World, abi::*, export_module};\n\n#[derive(Default)]\npub struct Storm { built: bool }\n\nimpl Module for Storm {\n    const KIT: &'static str = \"zone.shrink\";   // the kit it draws\n    const VERSION: &'static str = \"1.0.0\";     // the kit version it follows\n    fn needs() -> Needs { Needs::new().polled(\"zone.shrink\", \"zone.storm\", \"view\", 1) }\n    fn init(&mut self, world: &World, init: &Init, out: &mut Out) {}\n    fn frame(&mut self, world: &World, out: &mut Out) { /* read world, write out */ }\n}\nexport_module!(Storm);\n```\n\n### 4.2 Needs: declare what you read\n\nThe host sends a module only what it declared, as deltas:\n\n| `Needs::` | Gives | Example |\n|---|---|---|\n| `components(&[…])` | entities carrying one of them (`transform`: every entity) | `&[\"duel.fighter\"]` |\n| `events(&[…])` | events of these topics, new this frame (`duel.*`, `*`) | `&[\"fx.effect\"]` |\n| `data(&[…])` | project collections, in `Init::data` | `&[\"boons\"]` |\n| `polled(name, service, method, every)` | a service view read every N snapshots | `(\"sky\",\"world.atmosphere\",\"sky\",3)` |\n| `view(name, service, method, &on)` | a view read at start and on these events | `&[\"engine.scene.entered\"]` |\n| `grid(name, service, method, half, step, &on)` | a view sampled around the player | ground heights |\n| `commands(&[…])` | what you may ask the kit host: `capability.method`, `emit:<topic>` | `&[\"emit:hud.action.choose\"]` |\n| `.0.shared` / `.0.settings` | shared keys of other modules; settings (`graphics.*`, `project.platform`) | — |\n\nA module of a kit already lists its needs in that kit's API reference (section \"Presentation module\").\n\n### 4.3 Commands\n\n`out.*` helpers, one per ABI command family: mesh, material, node, scene, fx, ui, skeleton, camera / post / audio,\nplus kit host requests (`kit_call`, `kit_emit`), `share`, `log`, `undrawn`. Ids are yours, one space per kind.\nConventions: right handed, Y up, metres, seconds, linear RGBA colours (UI: sRGB), quaternions `[x, y, z, w]`.\n\n### 4.4 WGSL\n\nCustom shading is plain WGSL functions — no `#import`, no binding, no storage buffer, no compute, nothing WebGPU-only.\nYou write `gf_shade(GfIn) -> vec4<f32>` or `gf_surface(GfIn, GfSurface) -> GfSurface` (optional `gf_displace`), a\npost pass `gf_post(uv, color)`, a surface layer `gf_layer`, a UI shader `gf_ui(uv, size, time)`. The host provides\n`gf_param`, `gf_tex`, `gf_tex_layer`, `gf_time` (and `gf_scene_depth` with the `SCENE_DEPTH` cap), validates with naga\nand translates to GLSL ES 3.0 for WebGL2. Lighting, fog and tone mapping are the host's. Full dialect: the end of\n`present.wit`.\n\n### 4.5 Build\n\n```sh\ncd native/gripforge-runtime/modules\ncargo build --release --target wasm32-unknown-unknown -p gf-present-<kit-with-dashes>\nnode build.mjs <dir>            # fingerprinted build + present-modules.json entry\n```\n\nThe same `.wasm` serves WebGPU, WebGL2 and native hosts. **Native libraries** (`.so` / `.dll` / `.dylib`): the crate is\n`cdylib` + `rlib`, but `export_module!` exports the ABI symbols only on `wasm32` today; native Bevy will run the\n`.wasm` under wasmtime (ahead-of-time `.cwasm`), and the Godot / Unity / Unreal hosts (planned) will load either the\n`.wasm` or a native library exposing the same `gf_*` functions. Ship the `.wasm`: it is the portable form.\n\n**Calling other modules**: a module may call functions of another module (a kit's logic, a service) and expose its\nown, through the player, with versioned interfaces (`.gfi`) and no recompilation of the other side —\n`gripforge_present_sdk::calls`. The contract is [module-calls.md](module-calls.md) (`grip-forge docs module-calls`).\n\n### 4.6 Test without a GPU\n\n```rust\n#[test]\nfn trace() { gripforge_present_sdk::harness::check::<Storm>(\"tests/storm.player.json\", \"tests/storm.trace\"); }\n```\n\n`cargo test -p gf-present-<kit>` replays snapshots exactly as a host would (postcard included) and compares the\ncommand trace; `GF_BLESS=1` writes the reference. Visual check: the before/after board (`docs/player.md` §6).\n\n## 5. Host capabilities (caps)\n\n`Init::host` gives `engine` (`bevy`, later `godot`, `unity`, `unreal`), `backend` (`webgpu`, `webgl2`, `vulkan`…) and\n`caps`, a bit set of what the host draws beyond the baseline (meshes, nodes, `StdMaterial`). **Degrade when a cap is\nmissing** — never assume one.\n\n| Cap | Bit | Meaning |\n|---|---|---|\n| `WGSL_MATERIAL` | 0 | `MaterialWgsl` |\n| `POST_PASS` | 1 | full-screen passes of the module |\n| `SHADOWS` | 2 | shadow maps |\n| `HDR` | 3 | HDR target (bloom-ready colours) |\n| `AUDIO` | 4 | `AudioPlay` |\n| `UI` | 5 | UI trees |\n| `BONES` | 6 | bone overrides, IK |\n| `DECALS` | 7 | projected decals |\n| `FLOAT_TEXTURES` | 8 | float texture formats |\n| `TEXTURE_ARRAYS` | 9 | 2D texture arrays (`gf_tex_layer`) |\n| `WGSL_SURFACE` | 10 | `gf_surface` (lit by the host) |\n| `SCENE_DEPTH` | 11 | `gf_scene_depth(uv)` in materials |\n| `WEB_UI` | 12 | React / template fragments (`UiWeb`): the web only |\n| `RENDER_TARGETS` | 13 | `RenderTarget` textures |\n\n**What the Bevy web player announces today** (`player/src/module_host.rs`): `SHADOWS | UI | WGSL_MATERIAL |\nFLOAT_TEXTURES`, the same on WebGPU and on WebGL2 (half and full float textures are stored as `Rgba16Float`,\nfilterable on WebGL2 too). Everything of the WGSL dialect works on both backends: the WebGL2 path is mandatory, so a\nhost never needs a \"WebGL2-safe\" cap — the dialect itself is the WebGL2-safe subset. The few differences are in the\ndialect description: under WebGL2 `gf_depth` answers 1e9 (no depth texture). `Init::host.backend` (`webgpu` or\n`webgl2`) tells which one runs if you want to choose a cheaper path. A feature without its cap bit may still be\napplied by the host; when it is not, the command comes back `Refused`.\n\n```rust\nfn init(&mut self, _w: &World, init: &Init, out: &mut Out) {\n    self.fancy = init.host.caps & caps::WGSL_MATERIAL != 0;\n}\n```\n\n**Test both sides**: the harness fixture sets `host.caps`; write one trace with the cap and one without. In a browser,\n`?renderer=webgl2` and `?renderer=webgpu` force a backend. A command the host does not apply answers\n`HostResult::Refused` (read it in `world.results`) and is listed in `kithost.undrawn`.\n\n## 6. Your own assets, fonts and UI\n\n### 6.1 Assets\n\nKits draw what the project binds to their **asset slots** (`bindings`: slot → Library item). A module draws a slot's\nmodel with `ModelInstances` / `ModelSpawn` and a slot's texture with `TextureSlot`; it never fetches a URL. To bring\nyour own model or texture: upload it to the Library (MCP / site), bind it to the slot. The slots of a kit, with the\nkinds they accept and the animation clips a creature slot needs, are in its API reference.\n\n### 6.2 Fonts and theme\n\nThe game's look is the `ui.theme` kit: colours, `typography.font` (a family), `typography.fontFile` (TTF / OTF /\nWOFF2: a URL on the web, `res://` on Godot, a Resources path on Unity, an asset path on Unreal), logo and background.\nFragments get it as props (`theme`) and as `--gf-*` CSS variables: write `var(--gf-accent, <your colour>)`.\n\n### 6.3 UI with ui.webui\n\nA module ships `web/ui.json` + `web/ui.mjs` (React components and / or HTML templates); a game or a mod can declare a\nfragment in the `fragments` config of `ui.webui`. Props: `kit`, `views`, `vars`, `shared`, `theme`, `config`, `lang`,\n`dispatch(event, payload)`. `dispatch` sends only events declared as `emit:<event>` in the module's needs; a UI never\nfeeds game input. Templates bind with `data-gf-text`, `data-gf-show`, `data-gf-width` / `data-gf-of`,\n`data-gf-on-click`. **Trust**: a `mod:<id>` UI runs in the page with the trust of mod scripts; it is not loaded when the\ngame says `mods.enabled: false`, disables the mod, or denies the kit. Details: PORTING.md §8.\n\n## 7. Publishing and installing\n\n- **A mod**: validate then install it in a project with `gripforge_game_mods` (MCP) or `PATCH …/data` (`mods`\n  collection). Players' mods are merged by the application into the project before the host mounts it.\n- **A module**: today the published modules are those of `native/gripforge-runtime/modules` (one folder per kit,\n  contributed by pull request), built by `build.mjs` and shipped as the modules package (`docs/player.md` §4). A module\n  enters the published list when its kit's before/after board is green. A module for a kit of your own game goes\n  with that game's export (`--modules game`).\n- **A UI fragment**: inside its module (`web/`), or declared by the game or a mod in `ui.webui` `fragments`.\n\n## 8. ABI compatibility rules\n\n- `gf_abi()` returns `1`: the `gripforge:present@1` contract. **v1 is frozen**: no field is ever added to an existing\n  struct (postcard has no optional field).\n- Evolutions are **appended** enum variants only — of `Cmd`, `HostResult`, `Ext`, `Parent`, `Fog`… — marked\n  `v1.1` / `v1.2` in `present_abi.rs`. v1.1: shaders, clips, entity animation, sampled texture slots, `NodeNode`,\n  fog reach. v1.2: node meshes / materials / textures owned by the module, `ReadConfig`, web UI (`UiWeb`,\n  `UiProps`), render targets, UI images, shaders and gradients, entity materials, `ModelSpawn`, material options and\n  clearcoat, `SceneSet`, `ClaimOccupants`.\n- Every command is encoded on its own: a host that does not know a command **skips and reports it**, the others\n  apply. So an older host runs a newer module (degraded), a newer host runs an older module unchanged.\n- A module built for `gf_abi() != 1` is refused at load. A change that cannot be appended is a new ABI (`@2`).\n- Settings keys (`FrameIn::settings`) and shared keys may be added freely.\n\n## 9. Checklist\n\n- [ ] Read the kit's API reference (`grip-forge kit api <id>`).\n- [ ] Mod: only moddable keys and collections; validated with `gripforge_game_mods action=validate`.\n- [ ] Module: needs declared, caps checked, WGSL dialect only, `cargo test` trace green, wasm32 release builds,\n      no Bevy in `cargo tree`.\n- [ ] UI: `emit:<event>` declared for every `dispatch`; works without the theme.\n- [ ] Both WebGPU and WebGL2 checked.\n"
 },
 {
  "id": "player",
  "title": "The Bevy web player",
  "summary": "The bare player, its kernel, the module host and its 8 families, the loader, the player / modules / set packages, the native window (native-logic), the board, frame-rate checks, deployment.",
  "source": "docs/player.md",
  "text": "# The Bevy web player\n\nThe player that runs every GripForge game in the browser. It is written in Rust with the Bevy engine, compiled to\nWebAssembly, and it holds **no game**: the game logic runs in the page (the KitHost), and what is drawn comes from\nthe presentation modules of the kits the game uses. This page explains how the pieces fit, how they are built and\ndeployed, and how they are checked. Words in *italics* are in the [glossary](glossary.md).\n\nRelated: [PORTING.md](../native/gripforge-runtime/modules/PORTING.md) (write a module),\n[third-party-guide.md](third-party-guide.md) (modules, mods and UI made outside GripForge),\n[bevy-player-deploy.md](bevy-player-deploy.md) (production), [bevy-kit-port.md](bevy-kit-port.md) (history of the port),\n[kit-api.md](kit-api.md) (the API reference of the kits).\n\n## 1. The pieces\n\n```\npage (apps/web, or an exported game)\n ├─ KitHost (TypeScript)      runs the kits: rules, hooks, events, saves → a snapshot per frame\n ├─ ui.webui fragment layer   every HUD and menu, as DOM (React components, templates, drawn UI trees)\n └─ <iframe> presenter.html   the Bevy player\n      ├─ renderer             WebGPU, else WebGL2 (both always shipped)\n      ├─ generic layer        draws what every game has: entities with a bound model, ground, camera, lights\n      └─ module host          runs the presentation modules (.wasm), applies their commands\n```\n\n- **The bare player** (`native/gripforge-runtime/player`, built with `--no-default-features --features webgpu|webgl2`)\n  is the renderer, the generic layers and the module host. Nothing in it knows a kit or a game.\n- **No compiled presenter**: `player/src/kits`, `build.rs` and the features `builtin-presenters` and `legacy` are\n  gone, with the views of the compiled games and the Android entry point. Every kit is drawn by its module; `kits.rs`\n  keeps only the frame they all share. `node qa/player-no-kit-code-check.mjs` (CI `rust-runtime.yml`) fails if\n  any of it comes back.\n- **The `native-logic` feature** (native only, a `compile_error!` in wasm) runs the Rust kit host in the process\n  (`gripforge-runtime`, `gripforge-kithost`; `kit_player::Source::Local`): see §5.\n- **The kernel** of the player is what stays when no module is loaded: the renderer selection, the generic layers\n  (entities and their models, animation clips, camera, lights, post-processing of `world.lighting`), the bridge\n  that receives the snapshots, and the module host.\n\nThe hosted page adapter (`apps/web/src/lib/gamekits/host-web.ts`) exposes the same `LibraryAssets` port to React\nkit views through `host.assets` and to the renderer through `web.assets`, including with WASM logic. Rust receives\nonly the serializable slot URL map; clip references, import transforms and image metadata remain in the browser.\nCheck this boundary with `node --import ./tools/generation/register.mjs qa/wasm-page-assets-check.mjs`.\n\n## 2. The module host and its 8 families\n\n`player/src/module_host.rs` loads nothing itself: the page instantiates every module and registers it\n(`module_register`). Each frame, after the generic layer has reconciled the entities, the host:\n\n1. builds the `FrameIn` of each module (only what the module declared in its *needs*, as deltas: `InputTracker`);\n2. calls the module (`gf_frame`) synchronously through the page (`gfModules.call`);\n3. applies the commands it answers, in order, each to its family.\n\n| Family (file under `player/src/module_host/`) | Commands |\n|---|---|\n| `mesh.rs` | meshes, textures bound to slots |\n| `material.rs` | standard (PBR) and WGSL materials, shaders, textures, material options |\n| `node.rs` | nodes, instancing, models of slots, entity materials, claims, picking |\n| `scene.rs` | lights, scene (fog, sun, ambient, exposure), environment, surface layers, `SceneSet` |\n| `fx.rs` | particles, trails, ribbons, decals, ground rings |\n| `ui.rs` | UI trees, web components, UI images and shaders, gradients |\n| `skeleton.rs` | bone overrides, two-bone IK, clips, entity looks and offsets |\n| `camera_post_audio.rs` | camera pose, mode and shake, post passes, render targets, audio |\n\nRequests to the kit host (`KitCall`, `KitEmit`, `ReadConfig`), shared state (`Share`) and diagnostics (`Log`,\n`Undrawn`) are handled by the host itself. A command a family does not do yet is refused, reported to the module\n(`HostResult::Refused`) and listed in the `kithost.undrawn` variable; nothing else breaks. A module that traps is\nleft out (console warning) and the game goes on.\n\n## 3. The loader\n\n`web/presenter.js` (in the iframe):\n\n1. reads `renderer-manifest.json` and picks WebGPU, else WebGL2 (`?renderer=webgpu|webgl2` forces one, for a check);\n2. reads `present-modules.json` (`cache: 'no-store'`: the list is versioned with the modules, not with the player);\n3. for each module: `WebAssembly.compileStreaming(fetch(wasm))` — the browser keeps the compiled code with the\n   cached response, so a second visit compiles nothing — then instantiates it **once** for the whole game,\n   checks `gf_abi() == 1`, reads `gf_needs()` and registers it;\n4. hands the module list (with their web UI entries) to the page in the `ready` message.\n\nEvery file the presenter loads carries the fingerprint of its package (`?v=<fingerprint>`): a stale cache cannot\nmix two packages. `asset.preload` and `asset.cache` serve the `.wasm` files like any other asset of the game.\n\n## 4. Three packages: player, modules, sets\n\n| Package | Content | Fingerprint of | Built by |\n|---|---|---|---|\n| player | the bare player (WebGPU + WebGL2 builds), presenter.js, probe | the player sources | `native/gripforge-runtime/web/build.mjs --release --modules none` |\n| modules | `present-modules.json` + `modules/<dir>-<fp>.wasm` (+ `.ui.mjs`) | the set of modules (`modulesFingerprint`) | `native/gripforge-runtime/modules/build.mjs --out <dir>` |\n| set | relative links to one player and one modules package | both | `tools/deploy/bevy-player.mjs` |\n\nA change of a module is a new modules package, never a new player. A module is rebuilt only when the fingerprint\nof its sources, of the shared crates it uses, of the SDK / ABI and of `Cargo.lock` changes. A game export\n(`--modules game`) ships only the modules of the game's kits.\n\n## 5. The native window (`native-logic`)\n\n`cargo run -p gripforge-player --features native-logic -- <game.json>` opens a kit host game in a desktop window:\nthe binary requires `native-logic`, which runs the Rust kit host in the process. It plays kit host games only (the\ncompiled games of `gripforge-runtime` are no longer played by it). Until a native runner of the modules exists\n(wasmtime), the native window draws the generic layers only, not what the modules draw. Every module is served:\nthere is no list of kits held back. The Android player of the compiled games is retired; Android will run the game\nin a WebView.\n\n## 6. The before/after board (planche)\n\n`qa/player-planche.sh <web package> <prefix> <scenes> <out>` replays recorded scenes (`examples/present-tools`,\n`marks.txt`) in a package and captures each marked instant in WebGL2 and WebGPU; `qa/player-planche.py` compares the\ncaptures of the new package with the reference (`ref`) on a grid. **0 = identical, under 5 = good**, over 10 = the\nmodule is not done. Run it on a machine with a GPU and a display, never in CI.\n\n## 7. Frame-rate check\n\n`qa/export-fps-check.mjs --url <served export> [--backend webgpu|webgl2|both]` walks the hero by clicks for a few\nseconds and prints `fps <mean> p95 <ms> max <ms> first-click <ms>` per backend; it fails under the floors\n(`--min-fps-webgpu 30`, `--min-fps-webgl2 20`). `--setup '<js>'` evaluates code once the game is ready (A/B of a\nsetting); `--max-ticks N` caps the catch-up ticks of the KitHost. Never run by CI (no game in CI).\n\n### Where the time of a frame goes (`render_stats().cpu`)\n\n`gripforgePresenter.renderStats()` (the frame of the player) answers, beside what the frame draws, `cpu`: milliseconds\nof the player's thread per frame since the previous read — the stages (`kitFrame`, `kitViews`, `kitPresent`, `kitHud`,\n`transforms`, `extract`, `prepare`, `render`…, `idle`: the page and the wait for the display), `spans` inside the kit\nlayer (`frame.wireTake`, `views.views`, `present.changes`, and per presentation module `module.<kit>.input`, `.call`,\n`.apply`: `[ms per frame, calls per frame]`), `counts` per frame (`wire.bytes`, `wire.entities`, `module.calls`,\n`module.in.bytes`, `module.out.bytes`) and `worst`, the longest frame since the last read with its stages and its\nspans of half a millisecond or more (a door, a spawn). Marks are taken only once a page asked: nothing otherwise\n(`frame_cost.rs`).\n\nThe kit layer copies nothing for what did not change: the binary frames are written in place in the snapshot of the\nframe, the modules read that snapshot where it is (`SnapshotLoan`), the vars, the views and the clips that changed\nare found once per frame for every module, and an entity drawn as its key asks is compared in place (`SettledLook`).\n\n`qa/module-budget-check.mjs --url <served game> [--swap-dir <built modules>]` times the call of every presentation\nmodule of the page and fails when one goes over 1 ms per frame (or the page over 4 ms). `render_stats()` of the\nplayer (`gripforgePresenter.renderStats()` in the player frame) says what a frame draws — meshes, triangles, shadow\ncasters, textures and how many have mipmaps, `msaa`, `shadowMap`, `renderScale`, `adaptiveStep`, `post`, `bloom` — and,\nper module, the milliseconds per frame the host spends for it (`modules`: `feed`, `encode`, `call`, `apply`, `cmds`;\n`modulesMs`: the whole pass).\n\n### What the player decides about the picture\n\n- **Antialiasing**: the player's choice (`antialiasing` of the graphics settings: `off`, `msaa2`, `msaa4`; `fxaa` and\n  `taa` are drawn without MSAA), else the game's own default (`defaults.antialiasing` of its settings.graphics\n  config), else 4 samples. WebGPU has no 2 samples: `msaa2` is drawn with 4 there.\n- **Adaptive quality** (OFF unless the page or the game sends `adaptive: true` in the graphics settings; never in a\n  stepped replay, so the boards compare the same picture): while the frames are late (under 50 per second over two\n  seconds), what the player did not choose is lowered a step at a time — MSAA 2, MSAA off and a 1024 shadow map,\n  render scale 0.8, then 0.67 and a 512 shadow map — and given back after a calm while. It gives up when two steps buy\n  nothing (a slow display, the logic). It is off by default because no pair measured a gain from it: on the dungeon\n  with an integrated GPU and no vsync it went down to the last step for nothing, with vsync it stayed at step 0, and\n  on a discrete GPU the frame is bound by the main thread.\n- **Textures of a glTF** get their mipmaps once loaded (trilinear, anisotropy 8); `anisotropy` (1 to 16) and\n  `normalMapLod` (the first mip level the normal maps are read from) are graphics settings for an A/B.\n- **Normal maps** of a glTF are drawn with the strength their material asks for (`normalTexture.scale`, which the\n  engine's loader does not read): the player copies the map with its relief scaled, as Three.js `normalScale` does.\n  `normalMapsScaled` of `render_stats()` counts them.\n- **Pipelines** are warmed when a mesh arrives: it is drawn for its first frames whatever the camera sees, so the\n  backend links its programs while the level loads.\n\n## 8. Interface: ui.webui only\n\nUnder the Bevy web player **every HUD and every menu is web UI**, carried by the kit `ui.webui` — never bevy_ui.\nA module gives its interface as a UI tree (`out.ui`), as React components or HTML templates (`web/ui.mjs`, a\n*fragment*), or as a texture / UI shader placed in a tree node; all end in the fragment layer of ui.webui\n(`packages/gamekits/src/kits/ui.webui/runtime/web/fragments.ts`). Details: PORTING.md §6 and §8.\n\n## 9. Deployment with packages dropped beforehand\n\nThe player package is not in git. A deployment (`tools/deploy/bevy-player.mjs ensure`) links the set that matches\nthe commit: player first, then modules, then the set. If a package is missing on the server it is built there\n(slow); a package built elsewhere can be **dropped** on the server first (`bevy-player-<fp>.tar.gz` + `.sha256`,\n`bevy-modules-<fp>.tar.gz`), then the push deploys in seconds. The slot's `apps/web/public/runtime-rust` links to\n`~/gripforge-shared/runtime-rust/sets/<player fp>-<modules fp>`. Procedure: [bevy-player-deploy.md](bevy-player-deploy.md).\n\n## 10. Rules\n\n- **WebGL2 fallback is mandatory**: every package that builds, exports or serves a web player holds WebGPU **and**\n  WebGL2 and picks automatically (`node qa/rust-runtime-webgl-fallback-check.mjs`). A module uses neither compute\n  shaders nor storage buffers.\n- **No game code in the player**, no kit name tested in it: what a kit draws is in its module.\n- **No Three.js fallback**: if Bevy cannot start, the page says what is missing (`BevyPlayerUnavailable`).\n- **No game in CI**: the board and the frame-rate check are run by hand.\n"
 },
 {
  "id": "render-budget",
  "title": "Render budget of a game's models",
  "summary": "What a model costs to draw on a player's machine (mesh parts, triangles, textures), the budget gripforge game-budget and game-export check, and the lighter version to make.",
  "source": "docs/render-budget.md",
  "text": "# Render budget of a game's models\n\nA web game is played on whatever its player has. Most of the time that is an integrated GPU, and under Linux a\nChrome without flags has no WebGPU: the player then draws in WebGL2. A level that holds 60 frames per second on a\nworkstation with a discrete card can run at half of that there. What costs is rarely the logic: it is how the models\nwere exported.\n\n`gripforge game-budget` reads the `.glb` models of a folder and says which ones are over the budget, with the lighter\nversion to make. `gripforge game-export` runs the same check on the exported game and prints the warnings after the\nexport (`budget` in `--json`). A warning never refuses an export.\n\n```sh\ngripforge game-budget ./my-game/assets          # every .glb under the folder\ngripforge game-budget level.glb hero.glb --json\n```\n\nExit code 2 when a model is over the budget.\n\n## What is counted\n\n| | per model | whole game | why it costs |\n|---|---|---|---|\n| mesh parts (primitives placed by the scenes) | 300 | 1,000 | each is a draw call, and a shadow caster drawn again in the shadow map |\n| triangles (as placed: an instanced mesh counts each time) | 150,000 | 500,000 | vertex work, twice with shadows |\n| largest texture side | 2048 px | — | a web player keeps textures uncompressed: 2048² is 21 MB with its mipmaps |\n| texture memory once decoded | 64 MB | 256 MB | integrated GPUs share the system memory |\n| texel density (texels of base colour per metre of a part) | 256 | — | a game camera shows 50 to 100 pixels per metre: a texture tiled tighter puts several texels in each pixel, and a grainy one (stone, fabric, a noisy normal map) shimmers when the camera moves, whatever the filtering |\n\nThe numbers come from a measured case: a dungeon level exported as 2,570 mesh parts and 2.96 million triangles\n(1,649 mesh entities in the player, 1,644 of them shadow casters, 254,000 triangles in a frame of which 137,000 only for\nthe shadow map, 52 MB of textures) ran at 18 to 50 frames per second on an Intel Iris Xe in WebGL2. On that machine, of\nan 18 ms frame at a standstill: rendering at 75 % of the resolution bought 6 ms, turning MSAA off 4.5 ms, turning the\nshadows off 2.3 ms; a smaller shadow map, a lower anisotropy or a coarser normal map bought nothing measurable.\n\n## The lighter version\n\n- **Too many mesh parts**: merge what shares a material — in Blender, join the static objects of a room; or\n  `npx @gltf-transform/cli join in.glb out.glb`. Instance repeated props (`gltf-transform instance`). Keep one object per\n  room (the player culls rooms) and per thing that moves.\n- **Too many triangles**: `npx @gltf-transform/cli simplify in.glb out.glb --ratio 0.5 --error 0.001`; delete the faces no\n  camera sees.\n- **Textures**: `npx @gltf-transform/cli resize in.glb out.glb --width 1024 --height 1024`; share one texture set between\n  the materials of a level; `gltf-transform prune` removes the unused ones.\n- **Texel density**: tile the texture less (scale the UVs), or resize it; a repeat every metre or two of a 1024 px\n  texture is 500 to 1,000 texels per metre.\n- **Noisy normal maps** shimmer when a texel is about a pixel wide and the light grazes the surface: blur the normal map\n  slightly or lower its `scale` in the material.\n\n## What the player does by itself\n\nThe Bevy web player gives every glTF texture its mipmaps (trilinear, anisotropy 8), honours the strength of a normal map\n(`normalTexture.scale` of the material: a faint relief is not lit as a full one), honours the game's antialiasing\nsetting, and lowers by itself what the player did not choose while frames are late (MSAA samples, then the shadow map,\nthen the render scale; `adaptive: false` in the graphics settings turns that off). `render_stats()` of the player page\nreports what a frame draws and what each presentation module costs; `qa/module-budget-check.mjs` fails when a module\ngoes over a millisecond per frame.\n"
 },
 {
  "id": "scene-optim",
  "title": "Scene optimiser of the player",
  "summary": "What the player does to the static scenery of a game on its own — identical meshes and materials shared, static parts merged, zones streamed around the camera, kept shadows of what does not move, simplified copies far away — the sceneOptim settings, what render_stats().sceneOptim reports, measured.",
  "source": "docs/scene-optim.md",
  "text": "# Scene optimiser of the player\n\nThe Bevy player makes the static scenery of **any** game cheaper to draw, when its files are loaded. Nothing is\nspecific to a game and nothing has to be asked: every lever is on by default. Code:\n`native/gripforge-runtime/player/src/scene_optim.rs` (tests in the same file), cost of a frame per stage:\n`frame_cost.rs`.\n\n| Lever | What it does | What it leaves alone |\n| --- | --- | --- |\n| `clone` | Meshes and standard materials with the same content (vertices, indices, values, textures) share one handle, whatever the file they come from: the renderer batches them. | Nothing is freed: the files keep their own copies in memory. |\n| `merge` | In a scene (a room of a level, a model made of many pieces), the static parts that share a material, shadow flags and a vertex layout become one mesh, by chunks of `merge.vertices`. | Nodes a file animates, skinned or morphed meshes, hidden nodes, mirrored or sheared nodes, parts above `merge.partTriangles`, instances of a mesh above `merge.instanceTriangles` (they stay instances). A scene one of whose merged parts is moved or hidden afterwards (a kit, a module, a mod) is given back its parts and never merged again. |\n| `lod` | Each static mesh of at least `lod.minTriangles` triangles left unmerged gets a simplified copy (vertex clustering, at most `lod.ratio` of its triangles), drawn while the part covers less than `lod.screen` of the height of the view. | Meshes the simplification does not reduce by 15 %. |\n| `staticShadows` | The static scenery is drawn into the shadow map of the sun only when something of it changes; its depth is kept in a texture, and the other frames start the map from that copy and draw the moving casters over it (`shadow_cache.rs`). Each cascade is enlarged by `staticShadows.snap` of its side and centred on whole steps of that margin, so the kept depth lasts until the camera has crossed a step. | A static caster that moves is drawn with the moving ones from then on. The frame that takes the depth again draws no moving caster in the map (one frame). **WebGPU only**: on the WebGL2 fallback a shader cannot read a depth texture, the map is drawn in full each frame as before. Scenes with several suns casting shadows, and devices where the copy never succeeds (it gives up by itself), are drawn as before. The map is `snap` coarser. |\n| `streaming` | A level drawn zone by zone (`model.sceneCull` of `world.rooms`: zones, links through doors) only keeps the zones of the ring of the camera: those drawn and those their doors lead to. A zone that left the ring is unloaded after `streaming.linger` seconds; one zone is spawned a frame on the way back. Pieces carrying `model.cullKey` get their look only inside the ring, `streaming.perFrame` a frame ahead of being shown. | The files themselves stay loaded (one file holds every zone). Streaming starts once the level is placed: its box is measured with every zone. |\n\n## Settings\n\nDefaults: everything on, `merge: { instanceTriangles: 400, partTriangles: 4000, vertices: 60000 }`,\n`lod: { minTriangles: 600, ratio: 0.5, screen: 0.08 }`, `streaming: { linger: 4, perFrame: 8 }`,\n`staticShadows: { snap: 0.125 }`.\n\n- **Per game**: `variables[\"render.sceneOptim\"]` of the project — `false` (everything off) or an object naming the\n  levers to change, each `false`, `true` or an object of its keys:\n\n  ```json\n  { \"variables\": { \"render.sceneOptim\": { \"merge\": { \"instanceTriangles\": 0 }, \"lod\": false } } }\n  ```\n\n  The web renderer hands it to the player as `configs[\"*\"].sceneOptim`.\n- **Per page or device**: `renderer.applyGraphics({ sceneOptim: … })`, same shape, applied over the game's. A\n  change puts every scene back as its file gave it and optimises again with the new settings, so a measure can\n  compare both in the same page.\n\n## Measuring\n\n`gripforgePresenter.renderStats()` (and the `render_stats()` export of the player) carries:\n\n- `cpu`: milliseconds per frame of each stage of the thread of the player since the last read — `first`,\n  `preUpdate`, `kitFrame`, `kitViews`, `kitPresent`, `kitHud`, `update`, `transforms`, `postUpdate`, `visibility`, `lightVisibility`, `last`, `extract`,\n  `prepareAssets`, `manageViews`, `queue`, `sort`, `prepare`, `render`, `cleanup`, then `busy` (their sum), `idle`\n  and `total`;\n- `sceneOptim`: scenes and parts looked at, mesh and material assets against unique contents, parts merged and\n  merged meshes, scenes taken out of the merge, simplified meshes and parts drawing one now, zones loaded, time\n  spent optimising (total and worst frame), static shadow casters, frames that drew the static shadow again\n  (`shadowRefreshes`) against frames that reused it (`shadowReused`).\n"
 },
 {
  "id": "porting",
  "title": "Writing a presentation module (PORTING)",
  "summary": "The recipe of a module: folder, SDK, needs, commands, shaders, ui.webui, build, tests, rules.",
  "source": "native/gripforge-runtime/modules/PORTING.md",
  "text": "# Porting a kit presenter to a presentation module\n\nA module is the presentation of **one kit**, written in plain Rust (no Bevy, no engine), compiled to\n`wasm32-unknown-unknown` in seconds. The player only loads it: changing a module never rebuilds the player.\nABI: **`gripforge:present@1`, at level v1.2** — `../format/src/present_abi.rs` (reference) and `../format/present.wit`\n(engine-neutral description, commented for a host that is not Bevy). Example: `zone_shrink/`.\n\nRead also: the API reference of the kit you draw (`grip-forge kit api <kit>`, MCP `gripforge_gamekit_api`: its\nmodule section lists what the current module reads and sends), `docs/player.md` (the player, the module host, the\npackages, the board) and `docs/third-party-guide.md` (caps, assets, fonts, UI, compatibility).\nOffline: `grip-forge docs porting | abi | player | third-party`, MCP `gripforge_docs`.\n\n## 0. The ABI at v1.2, in short\n`gf_abi()` stays `1`: v1 is frozen and grows only by **appended** variants (never a field added to a struct: postcard\nhas no optional field), so an older host skips and reports what it does not know (`HostResult::Refused`).\n- **v1.1**: `Shader` (prepared shaders, §5), `EntityAnim`, `NodeClips`, `NodeChild`, `TextureSlotSampled`,\n  `MaterialTweak`, `EntityClipsFade`, `AmbientFlash`; `Parent::NodeNode`; `Fog::Reach`; `HostResult::Clips`;\n  `Ext::EventTimes`, `Ext::Models`.\n- **v1.2**: models and materials owned by the module (`NodeMeshOwn`, `NodeMaterial`, `NodeTexture`, `NodeRelease`,\n  `EntityMaterial`, `ModelSpawn`, `MaterialOptions`, `MaterialClearcoat`), `ClaimOccupants`, `ReadConfig`\n  (→ `HostResult::Config`), the UI (`UiWeb`, `UiProps`, `UiWebFree` → `HostResult::UiEvent`; `UiImage`, `UiShader`,\n  `UiGradient`; `RenderTarget`), `SceneSet` (keys of the scene owned by world.lighting: sky, post…),\n  `HostResult::MeshAttrs`, `Materials`, `SlotFile`; the web UI of a module (§8).\n- **Caps** (`Init::host.caps`, `caps::*`): what the host draws beyond the baseline; degrade without one\n  (`docs/third-party-guide.md` §5).\n\n## 1. Where\n- One folder per kit: `modules/<kit with _>/` (`zone.shrink` → `modules/zone_shrink/`), crate named\n  `gf-present-<kit-with-dashes>`, `crate-type = [\"cdylib\", \"rlib\"]`. This folder is one cargo workspace\n  (`members = [\"*\"]`): no `[workspace]` in your crate, dependencies through `workspace = true`.\n- Code shared by several kits: a generic helper goes in the SDK (`sdk/`, ask the maintainers of the SDK); code shared by a\n  family of kits (a track shape, a rig) goes in a crate of its own here, `modules/shared_<name>/`, used by path.\n- Fixtures and traces: `modules/<kit>/tests/<name>.player.json` and `<name>.trace`.\n\n```toml\n[package]\nname = \"gf-present-zone-shrink\"\nversion.workspace = true\nedition.workspace = true\nlicense.workspace = true\n[lib]\ncrate-type = [\"cdylib\", \"rlib\"]\n[dependencies]\ngripforge-present-sdk.workspace = true\nserde_json.workspace = true        # glam: gripforge_present_sdk::glam\n```\n\n## 2. Plug the pure functions on the SDK\n```rust\nuse gripforge_present_sdk::{Module, Needs, Out, World, abi::*, color, export_module, mesh, out::overlay};\n\n#[derive(Default)]\npub struct MyKit { built: bool }               // retained state: what Local<…> and marker components were\n\nimpl Module for MyKit {\n    const KIT: &'static str = \"zone.shrink\";\n    const VERSION: &'static str = \"1.0.0\";    // the kit's version\n    fn needs() -> Needs {                      // was Presenter::needs (same builder: views, events, components…)\n        Needs::new().polled(\"zone.shrink\", \"zone.storm\", \"view\", 1)\n    }\n    fn init(&mut self, world: &World, init: &Init, out: &mut Out) {}   // world.config = the kit's config\n    fn frame(&mut self, world: &World, out: &mut Out) {\n        // read: world.view(name), world.events_of(topic), world.entities / entity(id) / component(id, name),\n        //       world.time (render time), world.dt, world.step (0 when paused), world.camera, world.player(),\n        //       world.stage, world.clips, world.vars, world.data, world.shared, world.settings,\n        //       world.results (answers to Watch*/KitCall), world.changed\n        // write: out.mesh / material / draw / transform / visible / … one helper per command family\n    }\n}\nexport_module!(MyKit);                         // gf_abi, gf_alloc, gf_needs, gf_init, gf_frame (wasm only)\n```\nRules of the translation from a Bevy presenter:\n- `Commands::spawn((Mesh3d, MeshMaterial3d, Transform, …))` → `out.mesh(id, MeshData)`, `out.material(id,\n  StdMaterial)`, `out.draw(node, mesh, material, xf, flags)`. Ids are yours (`const`s or counters), one space\n  per kind; resend `material(id, …)` to change it (a colour that breathes every frame).\n- `Query<&mut Transform>` writes → `out.transform(id, xf)`; `Visibility` → `out.visible(id, bool)` (batched).\n- `ChildOf(view root)` of a kit entity → `NodeSpec { parent: Parent::Entity(id), .. }`; a named node of its\n  model → `Parent::EntityNode`; tinting, fading, hiding a view → `out.entity_look`; keeping it after it left →\n  `out.entity_linger`; moving its root over the generic layer → `out.entity_offset`.\n- `NotShadowCaster/Receiver` → `NodeFlags::UNSHADOWED`; `draw::overlay` → `out::overlay`; `Srgba::hex` →\n  `color::hex` (linear RGBA!); `toneMapped: false` (the old `raw()`/`Shown`) → `StdMaterial { tone_mapped:\n  false }`: the host undoes its tone curve.\n- `KitCommands` → `out.kit_call / kit_emit` (declare them in `needs.commands`; a reply comes back in\n  `world.results`); a `Claims` entry → `out.claim`.\n- Share only for a state computed by the presentation, absent from the simulation (`stage.<kit>`: title,\n  cinematic, HUD hidden) → `out.share` (`needs.shared`). Everything a kit knows goes through its views\n  (`needs.polled` / `needs.view`), even from another module: never republish a view as a Share\n  (world.racetrack polls `world.atmosphere.sky` itself).\n- Meshes: `mesh::{ring, tube, cuboid, quad, plane, sphere, ico_sphere, cylinder, capsule, flat,\n  smooth_normals}`; helpers of `draw.rs`: `util::{Lcg, ease, number, vec3, yaw, matrix}`; themed UI:\n  `ui::{Node, Theme, resolve, …}` (the `ui_menu` base, now in the ABI) → `out.ui(id, drawn)`.\n- Custom WGSL: plain functions, no `#import bevy_pbr`, no binding, no storage buffer, no compute, nothing WebGPU-only\n  (the dialect: end of `present.wit`, and `WgslMaterial` / `PostPass` / `Cmd::SurfaceLayer` in present_abi.rs). You\n  write `gf_shade(GfIn) -> vec4<f32>` or `gf_surface(GfIn, GfSurface) -> GfSurface` (+ optional `gf_displace`, which\n  also runs in the shadow and depth passes), a post pass `gf_post(uv, color)` (with `gf_scene`, `gf_depth`,\n  `gf_world_from_clip`, `gf_eye`; `gf_depth` answers 1e9 under WebGL2), a surface layer `gf_layer(GfIn, GfSurface)`,\n  a UI shader `gf_ui(uv, size, time)`; the host gives `gf_param(i)`, `gf_tex(i, uv)`, `gf_tex_layer(i, uv, layer)`,\n  `gf_time()` and, with `caps::SCENE_DEPTH`, `gf_scene_depth(uv)`. Names a pass declares are prefixed by the host:\n  two passes never collide. Lighting, fog, tone mapping: the host. Check a shader in a test with\n  `harness::check_wgsl(source, vertex, entry)` (SDK feature `wgsl-check`: naga WGSL, then GLSL ES 3.0 as WebGL2 needs) — never a copy of\n  the naga check in a module.\n- Bloom, colour grading, vignette and grain go only through world.lighting → `SceneSet post`; `PostPass` is\n  reserved for an effect of the kit's own.\n\nRules of the duplicate audit (one owner per concern; never a second path beside the one the host has):\n- **Audio**: `AudioPlay` / `AudioStop` are calls of `audio.core` (`play` / `stopSound`), never an audio path of the\n  module; most sounds need no command at all (the cues of audio.core play them from the events of the kits).\n- **Camera**: `CameraMode` is a local override read over the `camera.*` vars the kits own — it never writes them;\n  the lens is `fov_y` in **radians**, as the ABI says. `CameraPose` / `CameraRelease` for a cinematic.\n- **Share**: only for a state computed by the presentation and absent from the simulation (`stage.title`,\n  `stage.cinematic_hud`, `stage.hud_hidden`, a kit's own HUD state); never a copy of a kit view.\n- **Theme**: the UI reads the theme of `ui.theme` through its view (`gf_shared_ui::with_theme`), already sanitized;\n  never a second Rust copy of the theme rules.\n- **Build and package**: `build.mjs` is the only writer of `present-modules.json` (§7).\n- **No compiled presenter**: the player compiles no kit code (`player/src/kits`, `builtin-presenters` are gone;\n  `qa/player-no-kit-code-check.mjs`). What a kit draws is in its module, nowhere else.\n- No game logic in a module: a rule found in a presenter goes to the kit host (note it).\n- Something the ABI lacks: ask the maintainers of the ABI (an issue or a pull request on `format/src/present_abi.rs`,\n  appended variants only), never change it in your module's change; meanwhile `out.undrawn(\"…\")`.\n\n## 3. Build\n```sh\ncd native/gripforge-runtime/modules\nCARGO_TARGET_DIR=<your cargo target dir> nice -n 15 \\\n  cargo build --release --target wasm32-unknown-unknown -p gf-present-zone-shrink\n# → $CARGO_TARGET_DIR/wasm32-unknown-unknown/release/gf_present_zone_shrink.wasm (zone_shrink: 184 KB, 4 s)\n```\nThe same `.wasm` serves WebGPU, WebGL2 and native hosts. The player loads the modules listed in\n`present-modules.json` of its package (schema 2, §7: `{ \"schema\": 2, \"abi\": 1, \"fingerprint\", \"modules\": [{ \"kit\":\n\"zone.shrink\", \"wasm\": \"modules/zone_shrink-<fp>.wasm\", … }] }`): every module is served.\n\n## 4. Test without a GPU: the command trace\n```rust\n#[test]\nfn trace() {\n    gripforge_present_sdk::harness::check::<MyKit>(\"tests/zone.player.json\", \"tests/zone.trace\");\n}\n```\n`cargo test -p gf-present-<kit>` (natively). `GF_BLESS=1 cargo test …` writes the reference trace; commit both\nfiles. The harness goes through exactly what a host does: `InputTracker` builds each `FrameIn` from the\nsnapshots (deltas of what you declared), everything crosses postcard, the commands come back one per line\n(meshes and textures as size + digest, floats to 4 decimals). Pure functions get ordinary unit tests.\n\n**Fixture `<name>.player.json`**: the replay scene format of the player —\n`{ \"config\": { \"kits\": [...], \"configs\": { \"<kit>\": {...}, \"*\": {...} }, \"data\": {...} }, \"step\": 0.01667,\n\"frames\": [HostSnapshot, ...] }` (or just an array of snapshots). A `HostSnapshot` is what the kit host sends:\n`{ \"phase\": \"playing\", \"tick\", \"elapsed\", \"renderTime\", \"entities\": [{ \"id\", \"kind\", \"transform\": {x,y,z,yaw},\n\"model\": {\"slot\"}, \"tags\", \"components\" }], \"views\": { \"<view name>\": <JSON the getter answers> }, \"vars\",\n\"events\": [{ \"topic\", \"payload\", \"entity\" }] }` — `events` holds only the events new in that frame.\n\n**A kit without a fixture**: write a short one (5 to 20 frames walking through the states your presenter draws:\nabsent, appearing, changing, gone — `zone_shrink/tests/zone.player.json` was made by a few lines of Python),\nor take frames of a recorded scene (`examples/present-*/`, `record` writes `scene/<name>.json`, the same format), or a\nkit host snapshot (`KitSim::snapshot()` of gripforge-kithost, `JSON.stringify(host.snapshot())` on the web).\nKeep it small: it is a trace, not a film. The kit host parity fixtures (`gripforge-kithost/parity/*.json`, ops\nlists) are not snapshots.\n\n## 5. Shaders: prepared at build time (v1.1)\nSend a shader once with `out.shader(id, ShaderSource { wgsl, glsl_es300, digest })` and name it `\"@shader:<id>\"`\nin a material's `fragment`/`vertex` or a pass's `wgsl`. `glsl_es300: None` is fine today: the host validates\nand translates it (naga) at load. The SDK build step that validates with naga and fills `glsl_es300` + `digest`\n(so the host compiles nothing at run time and caches by digest in asset.cache) comes with the shader tool of\nthe SDK; the format does not change. Never a Bevy `#import`: lighting, fog and tone mapping are the host's.\n\n## 6. Interface: one channel, ui.webui\n**Under Bevy (web player, and native Bevy once its off-screen path lands) the HUD and the menus are ALWAYS web UI,\ncarried by the kit `ui.webui`** — never bevy_ui, never a mix. A module gives its interface one of these ways; all of\nthem end in the same place, the fragment layer of ui.webui (kits/ui.webui/runtime/web/fragments.ts):\n1. **`ui.tree`** (`ui::{Node, Theme, resolve}` → `out.ui(id, drawn)`): the player sends the drawn trees\n   (`take_ui()` → `gripforge.presenter.ui`) and ui.webui draws them as DOM (`renderUiTree`, `feedTrees`). The host\n   family `ui.rs` (bevy_ui) no longer draws the HUD under Bevy (kept in the tree for now; integration decides).\n2. **React components / templates** (`web/ui.mjs`, `caps::WEB_UI`): a ui.webui FRAGMENT, declared by the module's\n   `web` entry (§8): data by the ui.webui bridge (`{ type: 'fragment', kit, data }`), named events back by `ui:emit`,\n   filtered by the module's `emit:<event>` commands, React handed in by the page.\n3. **Drawn by the module**: a texture (`out.cmd(Cmd::RenderTarget{…})`, a module texture) put in a tree node with\n   `out.ui_image(ui, node_id, texture)`, or a UI shader `fn gf_ui(uv, size, time) -> vec4<f32>` with\n   `out.ui_shader(ui, node_id, Some(wgsl), params, textures)`.\n\n**Godot, Unity, Unreal**: the game chooses its UI way — the engine's native UI (Godot Control, Unity UI Toolkit,\nUnreal UMG, mapped from `ui.tree`) or ui.webui (its off-screen Chromium, rendered as a texture). By default ONE way\nper game; mixing both works (`ui.webui` config `mixNativeUi: true`) but is best avoided.\n\n## 7. Built once, loaded from memory\n- A module is built alone and named by the fingerprint of its sources (`tests/` excepted), of the shared crates it\n  uses, of Cargo.lock and of the SDK/ABI sources: `node modules/build.mjs [dir…]` rebuilds only the modules whose\n  fingerprint changed (cache: `$CARGO_TARGET_DIR/present-modules/modules/<dir>-<fingerprint>.wasm`).\n- **`build.mjs` is the only writer of `present-modules.json`**, the manifest every package ships and everything\n  reads (presenter.js, module-ui.ts / ui.webui, the deployment, the export of a game, the CLI / MCP table):\n  `{ schema: 2, abi, fingerprint, modules: [{ kit, version, dir, fingerprint, wasm: \"modules/<dir>-<fp>.wasm\",\n  sha256, bytes, web?: { ...web/ui.json, ui: \"modules/<dir>-<fp>.ui.mjs\", sha256 } }] }` — paths relative to the\n  manifest, `fingerprint` of the set (`modulesFingerprint`). Shaders travel inside the `.wasm` (§5).\n- **A big data file several modules read is a shared asset, never embedded** (`include_str!` would copy it into\n  every `.wasm`). Its shared crate declares it in `shared_<x>/shared.json` (`{ \"assets\": { \"vfx.recipes\":\n  \"src/recipes.json\" } }`); build.mjs stores it ONCE in the package, named by its content\n  (`modules/shared-vfx.recipes-<sha16>.json`), lists it in `shared` of the manifest (`{ name: { file, sha256, bytes } }`)\n  and in `shared` of each module entry that uses the crate. presenter.js loads it once (asset.preload's hub, else its\n  address: HTTP cache, asset service worker) and hands it to those modules as `Init::data[\"shared:<name>\"]`; the\n  module names it in its needs (`gf_shared_vfx::with_recipes`) and reads it at init (`gf_shared_vfx::use_recipes`).\n  Outside wasm (tests, harness) the crate falls back to its source file.\n- `node modules/build.mjs --out <dir> [--kits a,b]` builds what changed and copies the manifest and its files to a\n  package (`package.mjs <dir>` copies only). `web/build.mjs` does it for the player it builds (`--modules all`,\n  `game` with `--package`: that game's kits only, `none`); the deployment ships the modules as their own package\n  (`tools/deploy/bevy-player.mjs`: a module change is a new modules package, never a new player).\n- A game never compiles a kit: it assembles modules already built; only the game's own module, or a new or missing\n  one, is compiled.\n- Web: `WebAssembly.compileStreaming` from the (cached) response — the browser keeps the compiled code with it —,\n  instantiated once and kept for the whole game (presenter.js). asset.preload / asset.cache serve the `.wasm` as\n  any asset of the package.\n- Native (planned): wasmtime AOT (`.cwasm`) made at build time and loaded as is; Pulley or wasmi on iOS. Today the\n  native player has no module runner yet (`module_host.rs`: \"no native module runner yet\"); `export_module!` exports\n  the `gf_*` symbols on `wasm32` only. A native library (`.so` / `.dll`) of a module for the Godot / Unity / Unreal\n  hosts is planned, with the same `gf_*` functions.\n\n## 8. Web UI in detail (ABI v1.2): a fragment of ui.webui\nOn the web a module may **inject its interface into the page** (HUD, menus) instead of, or on top of, its\n`ui.tree`: React components (the web UI of GripForge is React), HTML/CSS templates with data bindings, or both.\nThe `.wasm` stays the same; the UI is one more file of the module, `modules/<kit>/web/ui.mjs` with its declaration `web/ui.json` (example:\n`hud_action/web/ui.mjs`), packaged as `modules/<kit>.ui.mjs` beside `modules/<kit>.wasm`.\n\n**Declare it** in the module's entry of `present-modules.json`:\n```json\n{ \"kit\": \"hud.action\", \"wasm\": \"modules/hud_action.wasm\",\n  \"web\": { \"ui\": \"modules/hud_action.ui.mjs\", \"views\": [\"hud.action.loading\"],\n           \"vars\": [\"player.health\", \"player.health.max\"], \"shared\": [\"hud.action.hud\"], \"layer\": \"hud\" } }\n```\n`ui`: a `.mjs`/`.js` or a `.html` file of the package under `modules/` (no address, no `..`); `views`: views of\nthe module's own `needs` passed as props; `vars`: KitHost vars passed as props; `shared`: keys the module publishes\nwith `out.share` (`Cmd::Share`); `emits`: the events it may send back (default: the `emit:<event>` commands of the\nmodule's needs); `layer`: `hud` (default) or `menu`; optional `sha256` (checked) and `origin` (`kit`, or `mod:<id>`\nfor a UI a mod brings). A game or a mod may also declare a fragment in the `fragments` config of ui.webui. Mirrored in the ABI as `ModuleInfo.web` (v1.2, appended).\n\n**Write it** — `ui.mjs` imports nothing: React is the page's, handed over (the module never bundles it):\n```js\nexport const gripforgeUi = 1;\nexport function components({ React }) {\n  const h = React.createElement;\n  function Hud({ vars, views, shared, theme, config, lang, dispatch }) {\n    return h('button', { onClick: () => dispatch('hud.action.choose', { index: 0 }) }, `${vars['player.health']}`);\n  }\n  return { Hud };                         // every component is mounted, side by side, with the same props\n}\nexport const templates = { strip: { html: '<b data-gf-text=\"vars/player.health\"></b>', css: 'b{color:var(--gf-accent,#f80)}' } };\n```\n- Props, the same for every component: `kit`, `views`, `vars`, `shared` (only what `web` lists; a removed shared key\n  is absent), `theme` (the `ui.theme` of the game; also set as `--gf-*` CSS variables on the fragment layer:\n  `var(--gf-accent, <your colour>)` keeps your look when the game sets none), `config` (the kit's config), `lang`,\n  `dispatch(event, payload)`. A component redraws only when one of its own values changed.\n- `dispatch` sends a named event to the KitHost **as a command of the module**: declare `emit:<event>` in its\n  `needs.commands`, as for `out.kit_emit`; anything else is refused and reported. A UI never feeds game input.\n- Templates (in `templates`, or a `.html` file whose `<style>` is its CSS), paths with `/` between names:\n  `data-gf-text=\"shared/hud.action.hud/hp\"`, `data-gf-show=\"vars/x\"` (`!vars/x`), `data-gf-width=\"vars/hp\"\n  data-gf-of=\"vars/max\"` (a 0…1 bar), `data-gf-style-<property>`, `data-gf-attr-<name>`, `data-gf-class-<name>`,\n  `data-gf-on-click=\"event\"` + `data-gf-payload='{\"json\":1}'`. Scripts and `on*` attributes of a template are dropped.\n- The fragment layer lets the pointer through to the game except on `button`, `a`, form fields, `[data-gf-on-click]` and\n  `[data-gf-interactive]`. It is inside the play surface: no selection, no drag (apps/web play-surface.ts).\n\n**How the page runs it** (ui.webui: `kits/ui.webui/runtime/web/fragments.ts` — `createFragmentBridge` is the data\nbridge of the ui.webui service, `mountFragments` the DOM layer —; apps/web `use-webui-fragments.ts` hands React and\nthe theme; web/kithost-bridge.mjs `moduleUi()` / `loadWebUi()`): presenter.js reads `present-modules.json` and hands the\nentries to the page with `ready`; the page reads the file through asset.preload's hub (`gripforgeAssets.read`: the\ncache of the `.wasm`) and imports those bytes, else imports it from the package with its fingerprint (`?v=`, as the\n`.wasm`). Each frame the views and vars come from the snapshot the page already makes for the player; the shared\nstate comes from the player (`take_shared()` of the player, posted as `gripforge.presenter.shared`).\n**Trust**: the code of a UI runs in the page with the trust of the mod scripts game.engine runs, under the same\npolicy: a `mod:<id>` UI is not loaded when the game's `game.engine` config says `mods.enabled: false`, lists the\nmod in `mods.disabled`, or the kit in `mods.deny.kits`. A kit's own UI comes with the package and its fingerprint.\n**Without a web UI** (none declared, or it failed to load: reported, never fatal) the module's `ui.tree` is what\nis drawn — as DOM by ui.webui too (`renderUiTree`, from `take_ui()`). WebGPU or WebGL2 changes nothing here.\nNative Bevy: ui.webui is today a headless service there (no page drawn); the off-screen Chromium → texture path of\nGodot/Unity/Unreal is the plan (docs of ui.webui, « Native Bevy »).\n\n## 9. Done when\n`cargo test -p gf-present-<kit>` green (units + trace), the wasm32 release build passes, no Bevy in\n`cargo tree -p gf-present-<kit>`, the board of the kit's scenes is under 5,\n`node tools/gamekits/generate-present-modules.mjs` and `node tools/gamekits/generate-kit-api.mjs` were run (the CLI /\nMCP tables and the API reference of the kit follow the module). A bump of the kit's version bumps the module's `VERSION` in the same change.\n"
 },
 {
  "id": "game-schema",
  "title": "The game schema (gripforge.game-schema/1) — start here",
  "summary": "Everything the logic modules of a game share, decided once at start by the game: the layout of the zone and of an entity row, static lists, event types, input actions, rights per column and per module, wake conditions, placement; overrides of the game, views per module, fingerprint.",
  "source": "docs/game-schema.md",
  "text": "# The game schema (`gripforge.game-schema/1`) — start here\n\n**Everything the logic modules of a game share is decided once, when the game starts, and the game decides.** The host\ncomputes one *game schema* from the manifest of the game and the manifests of its modules: the layout of the shared\nzone and of an entity row, the static lists, the event types, how many input actions there are, who may read and\nwrite what, when a kit is woken, where a module runs. The schema is frozen for the play, versioned, and has a\nfingerprint; each module receives **its view** of it when it is loaded (offsets, rights, numbers).\n\nNothing of this is compiled in a module. The same module binaries, in two games, get two different schemas: no\nlimit is a constant of a module (the 2 MiB zone and the 256 input actions of the first version are now values of the\nschema, with defaults). Readable offline: `grip-forge docs game-schema`, or the MCP tool `gripforge_docs` (topic\n`game-schema`). How the modules run and call each other is in [kit-modules.md](kit-modules.md) and\n[module-calls.md](module-calls.md); this page is the entry point of both.\n\n| Piece | Where |\n|---|---|\n| The computation, the frame (`zone`, `input`, `atoms`), the views, the fingerprint | `native/gripforge-runtime/web/game-schema.mjs` (`computeGameSchema`, `modulesOf`, `fingerprint`) |\n| The registry of sections and the shared helpers | `native/gripforge-runtime/web/game-schema-core.mjs` (`registerSection`) |\n| `entity` (columns, rights, write phases), `indexes` | `native/gripforge-runtime/web/game-schema-world.mjs` |\n| The rows of the entities in the zone, laid out from `entity` | `native/gripforge-kitcall/src/rows.rs` (the bytes), `native/gripforge-kithost/src/kitcall/columns.rs` (the core), `native/gripforge-kit-guest/src/columns.rs` (a kit) — kit-modules.md §7.9 |\n| `events`, `wake`, `placement` | `native/gripforge-runtime/web/game-schema-events.mjs` |\n| Tests (two games, two schemas, nothing recompiled; errors at link time) | `native/gripforge-runtime/web/game-schema.test.mjs`, and on built kit modules `game-schema-kits.test.mjs` |\n| The core's side: the zone laid out from the schema, the schema kept for the core | `native/gripforge-kithost/src/kitcall/zone.rs` (`set_schema`, `schema`), `native/gripforge-kitcall/src/zone.rs` (`Layout::from_schema`) |\n\n## 1. Where the schema comes from\n\n```\n the game (project.schema: overrides, its own columns)      the modules (kit-modules.json: kits[id].schema)\n                         └──────────────┬──────────────────────────┘\n                              computeGameSchema({ project, modules, device })\n                                            │   one schema, frozen, fingerprint = `version`\n                 ┌──────────────────────────┼─────────────────────────────┐\n           the core: sizes of the zone,   each module: its view      tools, saves, peers:\n           rows, lists, wake conditions   (offsets, rights, numbers)  the fingerprint to compare\n```\n\n1. **Each module declares** what it needs in its manifest (`schema` of its entry in `kit-modules.json`): the columns\n   it adds to an entity, what it uses of the others', its indexes, atoms, events, wake conditions, placement.\n   `tools/kit-modules/build.mjs` writes it from the JSON file beside the module's source\n   (`native/gripforge-kithost/src/kits/<kit>.schema.json`; `src/kitcall/core.schema.json` for the core) and the\n   event types from the kit's manifest (`events`); a module built elsewhere writes the same keys in its own entry.\n2. **The game overrides** in `project.schema`: it may restrict a right, force a placement, change a wake condition,\n   enlarge a buffer, raise the number of input actions or of entities, and **add its own columns** to every entity\n   without writing a kit.\n3. **The host computes** the schema before it loads any module, and refuses to start when something does not link:\n   every problem is listed in one error (an unknown column, another version, a write nobody allowed, an override\n   that cannot be met).\n\n```js\nimport { computeGameSchema, modulesOf } from './game-schema.mjs';\nconst schema = computeGameSchema({ project, modules: modulesOf(kitModulesManifest, lock.order) });\nschema.version;                 // \"9f2c41d07b3e5a10\": the fingerprint\nschema.views['combat.core'];    // what combat.core receives at load\n```\n\n## 2. The format\n\n```json\n{ \"schema\": \"gripforge.game-schema/1\", \"version\": \"<fingerprint>\", \"game\": \"<project id>\",\n  \"input\":  { \"actions\": 256 },\n  \"atoms\":  [\"player\", \"enemy\"],\n  \"entity\": { \"capacity\": 1024, \"rowBytes\": 48, \"headerBytes\": 64, \"columns\": [\n      { \"name\": \"core.id@1\", \"type\": \"u32\", \"offset\": 0, \"default\": 0, \"owner\": \"kithost.core\", \"read\": [\"*\"], \"write\": [\"kithost.core\"] },\n      { \"name\": \"core.position@1\", \"type\": \"f64x3\", \"offset\": 8, \"…\": \"…\" },\n      { \"name\": \"core.rotation@1\", \"type\": \"f64\", \"offset\": 32, \"…\": \"…\" },\n      { \"name\": \"combat.health@1\", \"type\": \"f32\", \"offset\": 40, \"default\": 100, \"owner\": \"combat.core\", \"read\": [\"*\"], \"write\": [\"combat.core\"] },\n      { \"name\": \"game.mana@1\", \"type\": \"f32\", \"offset\": 48, \"default\": 50, \"owner\": \"game\", \"read\": [\"*\"], \"write\": [\"combat.core\"] } ],\n      \"phases\": { \"core.position@1\": { \"update\": [\"*\"], \"physics\": [\"kithost.core\"], \"late_update\": [\"*\"], \"events\": [\"*\"], \"idle\": [\"*\"] },\n                  \"game.mana@1\": { \"update\": [\"combat.core\"], \"physics\": [\"combat.core\"], \"…\": \"…\" } } },\n  \"indexes\": [ { \"name\": \"tag:enemy\", \"query\": { \"all\": [\"enemy\"] }, \"id\": 0, \"owner\": \"combat.core\" } ],\n  \"events\": [ { \"type\": \"enemy.killed@1\", \"id\": 0, \"emitters\": [\"combat.core\"], \"listeners\": [\"hud.core\"] } ],\n  \"wake\":   { \"hud.core\": { \"update\": { \"events\": [\"enemy.killed@1\"], \"inputs\": false, \"indexes\": [] }, \"late_update\": \"never\", \"update_idle\": \"never\" } },\n  \"placement\": { \"kithost.core\": \"main\", \"combat.core\": \"main\", \"hud.core\": \"worker\" },\n  \"hooks\":  { \"combat.damage\": { \"owner\": \"combat.core\", \"mutable\": [\"amount\", \"add\", \"multiply\"], \"cancellable\": true, \"fields\": { \"amount\": { \"type\": \"number\", \"minimum\": 0 } } } },\n  \"memory\": { \"initialBytes\": 16777216, \"maxBytes\": 1073741824, \"stackBytes\": 262144, \"shared\": \"auto\",\n              \"modules\": { \"kithost.core\": \"owner\", \"combat.core\": \"common\", \"hud.core\": \"own\" } },\n  \"zone\":   { \"initialBytes\": 4194304, \"maxBytes\": 268435456, \"directoryBytes\": 256, \"buffers\": {\n      \"input\": { \"id\": 1, \"offset\": 256, \"bytes\": 8448 }, \"state\": { \"id\": 2, \"…\": \"…\" }, \"events\": { \"id\": 3, \"…\": \"…\" },\n      \"world\": { \"id\": 4, \"…\": \"…\" }, \"regions\": { \"id\": 5, \"…\": \"…\" } } },\n  \"views\":  { \"hud.core\": { \"module\": \"hud.core\", \"zone\": { \"…\": \"the buffers\" }, \"input\": { \"actions\": 256 },\n      \"atoms\": { \"player\": 0, \"enemy\": 1 }, \"entity\": { \"capacity\": 1024, \"rowBytes\": 48, \"headerBytes\": 64 },\n      \"columns\": { \"combat.health@1\": { \"offset\": 40, \"type\": \"f32\", \"access\": \"r\" }, \"core.position@1\": { \"offset\": 8, \"type\": \"f64x3\", \"access\": \"rw\", \"phases\": [\"update\", \"late_update\", \"events\", \"idle\"] } },\n      \"indexes\": { \"tag:enemy\": 0 }, \"events\": { \"enemy.killed@1\": { \"id\": 0, \"emit\": false, \"listen\": true } },\n      \"wake\": { \"…\": \"…\" }, \"placement\": \"worker\" } } }\n```\n\n| Section | What it fixes | Declared by a module (`schema.…`) | Overridden by the game (`project.schema.…`) |\n|---|---|---|---|\n| `input` | how many action records the zone holds | `input.actions` | `input.actions` (raise) |\n| `atoms` | names used as numbers; number = rank of first declaration | `atoms: [...]` | `atoms: [...]` (more) |\n| `entity` | the row of every entity: base columns (id, position, rotation), the modules' columns, the game's columns; offsets, the capacity; who writes each column at which phase of the step (`phases`) | `columns: [{ name, type, default, read, write, phases }]`, `uses.columns: { \"x@1\": \"r\" \\| \"rw\" }`, `uses.phases: { \"x@1\": [\"update\"] }`, `entity.capacity` | `columns` (its own), `rights: { \"x@1\": { read, write } }` (restrict), `phases: { \"x@1\": { \"<phase>\": [modules] } }` (restrict), `entity.capacity` (raise) |\n| `indexes` | the static lists the core keeps up to date (by tag, by query), so nobody scans the entities | `indexes: [{ name, query }]`, `uses.indexes` | `indexes` (more) |\n| `events` | the event types, their numbers, who emits and who listens | `events: { emits, listens }` | — |\n| `wake` | when a kit is woken for `update`, `late_update`, `update_idle`: `\"always\"`, `\"never\"`, or `{ events, inputs, indexes }` | `wake: { update, … }` | `wake: { \"<kit>\": { update, … } }` |\n| `placement` | where a module runs: `\"main\"`, `\"worker\"`, `\"worker:<group>\"` | `placement` | `placement: { \"<module>\": … }` |\n| `hooks` | the interceptable hooks (`engine.hooks`, topic `mods-engine`): the decisions a module lets others change or cancel **before** it acts — owner, `mutable` fields, `cancellable`. An event only notifies; what must be stoppable is a hook (topic `kit-modules` §7.8) | `hooks: { \"<name>\": { mutable, cancellable, fields } }` | — (a game refuses hooks to mods with `mods.deny.hooks`) |\n| `zone` | the start size, the ceiling, where each buffer starts and its size | `zone.buffers.<name>.bytes` (a minimum) | `zone.initialBytes`, `zone.maxBytes` (lower), `zone.buffers.<name>.bytes` (raise) |\n| `views` | per module: only what it declared or uses, with its access | — | — |\n\n**Names are versioned** (`combat.health@1`): the number is the major of the layout. A module that uses\n`combat.health@2` in a game whose `combat.core` declares `@1` is refused at load with that sentence.\n\n**Column types**: `u8 u16 u32 u64 i32 f32 f64 bool` (scalars), `f64x3` (three f64), `atom` (u32, a number of the\n`atoms` table), `entity` (16 bytes, an entity id), `bits128` (16 bytes of flags). Columns are laid out in declaration\norder — base, modules in the lock's order, game — each at its natural alignment; the row is rounded to 8 bytes.\n\n**Rights.** A column says who reads it and who writes it (`[\"*\"]`: everyone; default: everyone reads, the owner\nwrites). A module other than the owner states its use in `uses.columns`; `\"rw\"` on a column it may not write is an\nerror at link time, never a silent write. **The game can only restrict**: `rights: { \"combat.health@1\": { \"read\":\n[\"combat.core\", \"hud.core\"] } }` leaves the modules that are in both lists; when a module of the game then loses a\nright it needs, the game does not start and the error names the module and the column.\n\n**The row is real.** The core writes one row per entity in the `world` buffer of the zone, at these offsets\n(kit-modules.md §7.9). **The base is fixed** — `core.id@1` at 0, `core.position@1` at 8, `core.rotation@1` at 32 —\nand follows the entity's `transform`; a schema that puts it elsewhere is refused by the core. Everything else is\nadded by the schema, statically, for every entity: the core's own `core.revision@1` and `core.shape@1` (how a kit\nknows without a call that a copy it keeps is current) and `physics.force@1` (where the kits' forces of a tick add\nup) are declared in its entry of `kit-modules.json` like a kit's columns; a kit adds what it declares, the game\nwhat it adds. A kit reads and writes a column by its name (`kx.column`, `kx.set_column`, `kx.add_column`), at the\noffset and with the access of **its view**; a write its view does not give is an error that names the kit and the\ncolumn, at link time when it was declared (`uses.columns`), at the write otherwise.\n\n**The base columns serve the neighbour search.** `Entities::near` (kit-modules.md §7.11) reads `core.position@1`\nof each row to find the entities within a radius: nothing to declare — the base is in every schema — and a game\nthat raises `entity.capacity` keeps the search on the rows for all its entities (an entity that found no row is\nread in its `transform` instead: same answer, slower).\n\n**Write phases** (`entity.phases`). A step has phases, in order: `update` (the kits), `physics` (the step, and the\nposes written back), `late_update`, `events` (the deliveries of the bus), and `idle` (`update_idle` while the game is\nheld). For every column the schema says **who writes it at which phase**: what the column declares (`phases: {\nupdate: ['*'], physics: ['kithost.core'] }`; a phase it does not name: nobody), else its writers at every phase;\nnever more than its `write` list; restricted by the game (`project.schema.phases`). A module may say at which\nphases it writes a column (`uses.phases`); a phase the column does not give it is an error at link time, and its\nview lists the phases left. The base is written by the kits outside the physics step and by the core during it;\n`physics.force@1` by every kit outside it and by the physics alone during it. The phases are declared and linked,\nnot yet checked at each write: they are what a module placed on another thread will be scheduled by (the physics\nfirst).\n\n**The zone.** `initialBytes` is 4 MiB or what the buffers need; `maxBytes` is the ceiling of the device (64 MiB under\n2 GB of memory, 128 MiB under 8 GB, 256 MiB otherwise; half on a mobile) or less when the game says so. The buffers\nfollow each other after the directory; `regions`, the last, takes what is left and is where the zone grows, so **no\noffset moves when it grows**. The size of `input` follows from `input.actions`; `world` from the capacity and the\nrow; a section asks its room with `ctx.need(buffer, bytes)`.\n\n**The fingerprint** (`version`) is the SHA-256 of the schema's content with its keys sorted (16 hexadecimal digits).\nThe ceiling of the zone, which depends on the device, is left out: two devices playing the same game with the same\nmodules compute the same fingerprint, so a save, a replay or a network peer can compare it.\n\n## 3. A game drives its modules\n\n```json\n{ \"id\": \"my-game\",\n  \"schema\": {\n    \"columns\": [ { \"name\": \"game.mana@1\", \"type\": \"f32\", \"default\": 50, \"read\": [\"*\"], \"write\": [\"combat.core\"] } ],\n    \"rights\": { \"combat.health@1\": { \"read\": [\"combat.core\", \"hud.core\"] } },\n    \"input\": { \"actions\": 600 },\n    \"entity\": { \"capacity\": 4096 },\n    \"zone\": { \"buffers\": { \"events\": { \"bytes\": 1048576 } }, \"maxBytes\": 67108864 },\n    \"memory\": { \"initialBytes\": 33554432, \"maxBytes\": 268435456, \"stackBytes\": 524288, \"shared\": false },\n    \"placement\": { \"hud.core\": \"worker\" },\n    \"wake\": { \"hud.core\": { \"update\": { \"events\": [\"enemy.killed@1\"] } } } } }\n```\n\nA game column is like a module's: a name with its version, a type, a default, who reads and who writes. It is part\nof every entity's row from the first frame; no kit has to be written for it.\n\n`memory` is the plan of the **common memory** (kit-modules.md §9): the one memory the core and the kit modules\nplaced in it import. The game may raise its start size and the stack of a kit module, lower its ceiling (the\ndevice's is four times the zone's) and refuse a memory shared between threads (`shared: false`; `true` demands one\nand fails the load where the page cannot make it; absent: shared where the page is cross-origin isolated and the\nbuild has it). `modules` says where each module lives — `owner`, `common` or `own` — as its entry of\n`kit-modules.json` says (a mode is a way a binary was built: the game reads it, it does not change it). The loader\nneeds this plan **before** the core is instantiated — the memory exists first — so the page gives the game at load\n(`kitModules: { manifest, project }`); `commonMemoryPlan(project, device)` is the one function both read. Like the\nzone's, the ceiling is left out of the fingerprint.\n\n## 4. How the schema reaches the core and the kits\n\n- **The loader** (`kithost-wasm.mjs`, with the kit modules): `logic.create({ project, lock, … })` computes the schema\n  of that game (`logic.schemaFor(input)`), gives it to the core — `gf_schema_init(ptr, len)`, the JSON, load-time\n  data — and only then makes the host. A schema that does not link, or that the core refuses, throws there: nothing\n  is mounted. The host made has it as `host.schema`. A web export ships the four `game-schema*.mjs` files with the\n  loader.\n- **The core** (`native/gripforge-kithost/src/kitcall/zone.rs`): `set_schema` lays the zone out (`Layout::from_schema`\n  of `gripforge-kitcall`: start size, ceiling, the offset and the size of each buffer, the number of action records)\n  and keeps the whole schema (`zone::schema()`) for the sections the rest of the core reads (`entity`, `indexes`,\n  `events`, `wake`) and for the view each kit is given at its mount (`schema()[\"views\"][kit id]`).\n- **A kit module** finds the buffers in the zone's directory (`zone::buffers()`), read again each time a kit is\n  mounted, so the same binary follows whatever layout the game it is loaded in has.\n- **Without a schema** (a core driven by an older page, a tool) the defaults hold: 4 MiB, 256 actions.\n- **One schema per core at a time**: giving another one makes the zone again, empty; the hosts made before must be\n  gone. The same schema again changes nothing.\n\nCheck with built kit modules: `GF_KIT_MODULES=<dir> GF_KIT_BUNDLE=<game.json> node --test\nnative/gripforge-runtime/web/game-schema-kits.test.mjs` plays two games on the same binaries and reads the directory\nof the core's zone after each.\n\n## 4b. The memory structures each module declares\n\nThe schema says how big the shared memory is; **what lies in it** is declared structure by structure\n([kit-structures.md](kit-structures.md), generated from `native/gripforge-kitcall/structs.json`): the fixed-layout\nvalue that carries lists and dictionaries between modules of the common memory, the context of a call, the records\nof the zone. Each has a name, a number, a version and its fields; sizes and offsets are computed by the tool\n(`tools/kit-modules/structs.mjs`) and **verified against every binary** the build writes — each wasm carries the\ntable of the structures as its own compiler laid them out (custom section `gripforge.structs`).\n\nIn `kit-modules.json`, beside what a module declares for the schema (`schema`: columns, indexes, events…):\n\n```json\n\"structs\": { \"contract\": \"1.0\", \"section\": \"gripforge.structs\",\n             \"structs\": [ { \"name\": \"FixedValue\", \"id\": 1, \"version\": \"1.0\", \"size\": 16, \"align\": 8,\n                            \"access\": { \"core\": \"read-write\", \"kit\": \"read-write\" },\n                            \"fields\": [ { \"name\": \"tag\", \"type\": \"u8\", \"offset\": 0, \"size\": 1 }, … ] }, … ] },\n\"built\":   { \"core\": \"rustc 1.95.0 (…)\", \"kits\": \"rustc 1.97.1 (…)\" },\n\"core\":    { \"structs\": { \"contract\": \"1.0\", \"role\": \"core\" }, … },\n\"kits\":    { \"combat.melee\": { \"structs\": { \"contract\": \"1.0\", \"role\": \"kit\" }, … } }\n```\n\nA module's `structs` names the contract it was checked against and its role; the structures it reads and writes are\nthose whose `access` names that role. At load the host compares the contract of every kit of the common memory with\nthe core's and refuses by name a kit of another major, or of a later minor (`<kit>@<version> (memory \"common\"):\nstructures contract 2.0, the owner (kithost.core) provides 1.0 — …`). `built` is information: the compiler is never\ncompared. A kit does not declare structures of its own yet (none exposes memory of its own); when one does, they go\nin its schema declarations in the same format and are checked the same way.\n\n## 5. Adding a section\n\nA lot that needs something decided at start adds a section in its own file and imports it from `game-schema.mjs`:\n\n```js\nimport { registerSection } from './game-schema-core.mjs';\nregisterSection('entity', {\n  after: ['atoms'],                              // sections it reads in ctx.schema\n  compute(ctx) { /* … */ return value; },        // plain JSON, deterministic\n  view(ctx, moduleId, value) { return { columns: /* … */ }; },   // merged in views[moduleId]\n});\n```\n\n`ctx`: `game` (the overrides, `project.schema`), `project`, `modules` (`[{ id, version, schema }]`, the core first,\nthen the lock's order), `schema` (the sections computed so far), `device`, `error(message)` (a link error: all are\nthrown together at the end), `need(buffer, bytes)` (room in a buffer of the zone; `zone` is computed last),\n`allowed(declared, override)` (the game's restriction of a list of rights), `has(moduleId)`.\n\nRules for a section: no constant that a game cannot change; the same input gives the same bytes (the fingerprint\ndepends on it); what cannot be linked is `ctx.error`, with the module and the name in the sentence.\n"
 },
 {
  "id": "module-calls",
  "title": "Calls between modules (gripforge:calls@1)",
  "summary": "How modules call each other through the player: direct links, bridge, zone, async replies, registers and stack, threads, publications, .gfi interfaces, tracer, costs.",
  "source": "docs/module-calls.md",
  "text": "# Calls between modules (`gripforge:calls@1`)\n\nHow GripForge modules (one `.wasm` per kit — presentation or logic — and later one `.so` / `.dll` / `.dylib`) call\neach other through the player. Readable offline: `grip-forge docs module-calls`, or the MCP tool `gripforge_docs`\n(topic `module-calls`). Words are in the [glossary](glossary.md); the presentation ABI the player speaks with a\nmodule is a separate contract ([present.wit](../native/gripforge-runtime/format/present.wit)).\n\n| Piece | Where |\n|---|---|\n| Format (headers, statuses, registers, zone sizes, versions) | `native/gripforge-modcall/src/lib.rs` (`no_std`) |\n| Module SDK (`call`, `expose`, regions, publications) | `native/gripforge-modcall/src/guest.rs` (feature `guest`), re-exported by the present SDK as `gripforge_present_sdk::calls` |\n| Zone allocator (Rust, for a native host) | `native/gripforge-modcall/src/zone.rs` |\n| Native host (wasm + native libraries) | `native/gripforge-modhost` — [module-calls-native.md](module-calls-native.md) |\n| Web host | `native/gripforge-runtime/web/module-calls.mjs` (+ `module-calls-worker.mjs`) |\n| Interfaces → bindings | `tools/modcall/gfi.mjs` (`.gfi` → Rust + JS) |\n| Tests, bench | `web/module-calls.test.mjs`, `web/module-calls-bench.mjs`, test modules in `native/gripforge-modcall/test-modules` |\n\n## 1. Principles\n\n- **The host is a switchboard.** It knows no kit and never reads the content of a message: it reads the 32-byte\n  header (who, which call id, which target, which function, where the bytes are), stamps the sender, and delivers.\n  The argument and result bytes are opaque to it (the tracer may copy them, never parse them).\n- **Every module keeps its own linear memory.** A module never sees another module's memory; a buggy module traps\n  alone (`trapped` to its callers, left out), the player and the other modules go on.\n- **Binary only.** Fixed layouts in the hot path, little-endian, never JSON. Manifests are load-time data.\n- **Integers, resolved once.** A target name (`physics.query@^1`) is resolved to a handle once (`gf_resolve`, or at\n  link time for direct links); a function is a stable number from its interface. No string on the hot path.\n- **The host picks the path; the caller's code does not change.** Same thread and loaded → sync paths are allowed;\n  another thread, not loaded yet, or on the call stack → async (or a clear status).\n- **A third-party module is loaded only if the game declares it.** A call to an undeclared module answers\n  `not_declared`; nothing is fetched.\n\n## 2. Call paths\n\n| Path | When | How | Cost (bench §10) |\n|---|---|---|---|\n| **(a) Direct link** | target loaded first, same thread, small scalar arguments | the module imports `gf:<name>@<req>` / `<fn>`; the host wires the target's export `gfx_<fn>` there at instantiation: a wasm→wasm call, no JS, no zone | ≈ a call inside the same wasm |\n| **(b) Bridge** — the base, portable path | any sync call on the same thread | `gf_bridge`: the host reads `[name][args]` in A's memory, copies them into B (B's `gf_alloc`), runs `gf_on_bridge`, copies `[status u32][result]` back into A (A's `gf_alloc`) | ≈ 0.6 µs + the copies |\n| **(c) Zone** — large volumes | big arguments on the same thread | `gf_push` puts the arguments once in the zone (the thread's stack), `gf_invoke` runs B, which reads them **in place** when it maps the zone as a second memory (multi-memory), else copies them out (`gf_zone_read`) | in place: ½ of the bridge at 64 KiB |\n| **Async** — the default | always valid | a call block in the zone, `gf_call(ptr)` answers `pending`; the reply (same id) reaches `gf_on_reply` later, or is taken by `take_reply(id)` | ≈ 3–4 µs same thread; Workers below |\n\nA sync call never crosses a thread and never waits for a load: it answers `other_thread` or `loading` (and the\nload starts), and the module calls async instead. The SDK's `call` is async; `call_sync` is the bridge;\n`call_stack` is the zone path. Direct links need no SDK call at all (an `extern` import).\n\n**About (c) on the same thread.** The registers-and-stack path is an *optional optimisation for large volumes*,\nnot part of the default path: the generated clients use the bridge, and a module calls `call_stack` only on\npurpose. Measured (§13): for a module that copies the zone out (every Rust module today: Rust cannot yet map a\nsecond memory) it is slower than the bridge (Node: 1.4 µs vs 0.66 µs for 8 bytes, 35 µs vs 30 µs for 64 KiB). It\nwins only in Node when the target reads the zone in place (multi-memory: 13.7 µs vs 29.6 µs at 64 KiB); in Chrome\nit does not (31 µs vs 24 µs at 64 KiB). So on the same thread: direct links for small hot functions, the bridge for\nthe rest. The stack stays for nested sync calls that need no allocation and as the base for multi-memory modules\nonce toolchains emit them; it is not a reason to choose a path today. Nested sync calls (A→B→C) work on both paths.\n\n## 3. Messages\n\nEvery integer is little-endian. Blocks are 8-byte aligned by the zone allocator. A \"pointer\" is an **offset in the\nzone**; `0` is never a valid block and means \"none\".\n\n### Call block (`CallHeader`, 32 bytes, then the names, usually then the arguments)\n\n| at | type | field |\n|---|---|---|\n| 0 | u8 | kind = 1 (call) |\n| 1 | u8 | version = 1 |\n| 2 | u16 | flags (bit 0 `FLAG_SYNC` is reserved: a block with it is refused, sync calls never travel as blocks) |\n| 4 | u32 | from: the caller's module id — **stamped by the host** (a module cannot speak for another) |\n| 8 | u32 | call_id: chosen by the caller, unique among its calls in flight |\n| 12 | u16 | target_len: bytes of the target name (`name` or `name@req`) right after the header; 0 when a handle is given |\n| 14 | u16 | func_len: bytes of the function name after the target; 0 = by number |\n| 16 | u32 | func_id: the function number, or `0xFFFFFFFF` (by name) |\n| 20 | u32 | args_ptr: zone offset of the arguments (0 when `args_len` is 0) |\n| 24 | u32 | args_len |\n| 28 | u32 | target handle (from `gf_resolve`) when `target_len` is 0, else 0 |\n\n\"I am `from`, call `call_id`, target `handle`, function `func_id`, arguments at `args_ptr` / `args_len`.\"\n\n### Reply block (`ReplyHeader`, 32 bytes, then usually the result)\n\n| at | type | field |\n|---|---|---|\n| 0 | u8 | kind = 2 (reply) |\n| 1 | u8 | version = 1 |\n| 2 | u16 | status (below) |\n| 4 | u32 | from: the module that answered — stamped by the host; `0` = the host wrote it (target absent, trapped, load failed…) |\n| 8 | u32 | call_id: **the id of the call it answers** |\n| 12 | u32 | to: the caller's module id (stamped by the host) |\n| 16 | u32 | result_ptr (zone offset; 0 when `result_len` is 0) |\n| 20 | u32 | result_len |\n| 24 | u32 | reserved, 0 |\n| 28 | u32 | reserved, 0 |\n\nA `failed` reply carries a UTF-8 message as its result.\n\n### `gf_call` answer (u64)\n\n`status | reply_ptr << 32` — `pending` for an async call (the reply comes later), or a refusal status at once.\n\n### Statuses (u16)\n\n| code | name | meaning |\n|---|---|---|\n| 0 | ok | the function answered; the result is its bytes |\n| 1 | pending | posted; the reply reaches `gf_on_reply` |\n| 2 | loading | sync only: the target is not loaded; its load started (call async, or again later) |\n| 3 | not_declared | the game never declared this target |\n| 4 | no_function | the target has no such function |\n| 5 | failed | the function ran and failed; the result is a UTF-8 message |\n| 6 | trapped | the target trapped (it is left out from then on), or answered something that is not a reply |\n| 7 | reentrant | sync only: the target is on the call stack (A→B→A); call it async |\n| 8 | bad_message | the block is not a call of this contract (kind, version, bounds, UTF-8) |\n| 9 | version | the declared provider does not meet the requirement |\n| 10 | zone_full | no room in the zone for the block |\n| 11 | load_failed | declared, but its load failed |\n| 12 | queue_full | the host's queue of pending messages is full |\n| 13 | stack_overflow | a sync call would pass the stack's size or its maximum depth |\n| 14 | other_thread | sync call to a module placed on another thread |\n\nNew statuses are only added at the end (a module treats an unknown one as an error).\n\n## 4. The host ABI (`gf_calls` imports, `gf_*` exports)\n\nThe ABI version is `major << 16 | minor` (`gf_calls_abi` export; this is `1.0`). It grows **only by additions at\nthe end** (new imports, statuses, register words past 64 bytes); a host refuses a module of another major. What a\nhost offers beyond the base is read with `gf_host_caps()`: bit 0 the zone can be imported as a second memory\n(multi-memory), bit 1 the zone is shared memory, bit 2 Workers, bit 3 the tracer is on.\n\nImports (module `gf_calls`) — all optional, a module imports what it uses:\n\n| import | signature | role |\n|---|---|---|\n| `gf_call` | `(ptr) -> u64` | post a call block (async) |\n| `gf_resolve` | `(name_ptr, len) -> handle` | `name@req` → handle once (0 = not declared / version) |\n| `gf_bridge` | `(handle, func_id, name_ptr, name_len, args_ptr, args_len) -> u64` | sync, path (b): `ptr \\| len << 32` of `[status u32][bytes]` in the caller's memory, or `status << 32` |\n| `gf_push` / `gf_sp` / `gf_pop` | `(src, len) -> at` / `() -> sp` / `(mark)` | the thread's stack (path c); `src = 0xFFFFFFFF` reserves only |\n| `gf_invoke` | `(handle, func_id, name_ptr, name_len, args_at, args_len) -> status` | sync, path (c) |\n| `gf_regs` | `() -> offset` | the registers of this thread |\n| `gf_ret` | `(status, ptr, len)` | the target sets its result (path c) |\n| `gf_zone_alloc` / `gf_zone_free` | `(len) -> ptr` / `(ptr)` | regions of the zone (owned by the module) |\n| `gf_zone_write` / `gf_zone_read` | `(zone_ptr, mem_ptr, len) -> ok` | copy between the module's memory and the zone (write: only into its own blocks) |\n| `gf_zone_size` | `() -> bytes` | current size of the zone |\n| `gf_publish` / `gf_lookup` | `(name, len, ptr, size) -> ok` / `(name, len) -> ptr \\| size << 32` | publications (§7) |\n| `gf_host_caps` | `() -> bits` | capabilities |\n| `zone` (memory) | — | the zone as a second memory (multi-memory only) |\n\nExports of a module (the SDK's `export_calls!()` writes them): `gf_calls_abi`, `gf_alloc(len)` (the host writes\nthere), `gf_on_call(ptr) -> reply_ptr`, `gf_on_reply(ptr)`, `gf_on_bridge(func_id, name_len, ptr, len) -> u64`,\n`gf_on_invoke()`, and optionally `gf_calls_init()` (run once after instantiation: expose functions there) and\ndirect-link exports `gfx_<fn>`.\n\n### Common memory (optional, trusted modules only)\n\nA declaration may say where a module lives: `memory: 'own'` (default: the module owns and exports its memory),\n`'owner'` or `'common'`. This does not change the contract above — a module in its own memory calls and is called\nexactly as before — it adds a second way to load a module, for modules that trust each other (the kit modules of GripForge:\nkit-modules.md §9). What they exchange in that memory has a layout the contract defines, whatever compiler built\neach (kit-modules.md §9.7, kit-structures.md); the host compares the structures contract of each with the owner's\n(`checkStructs`) and refuses by name a module of another major.\n\n- The **owner** (one per host) imports `env.memory`, which the host makes (`memory: { initialBytes, maxBytes,\n  shared, stackBytes }` of the host: the game's plan), and exports the allocator of that memory —\n  `gfx_mem_alloc(size, align) -> ptr`, `gfx_mem_free(ptr, size, align)` (and `gfx_mem_alloc_zeroed`,\n  `gfx_mem_realloc(ptr, size, align, new_size)` for the modules that link them) — and its function table\n  (`__indirect_function_table`, growable). Optional: `gf_mem_link(handle, slot)`.\n- A **common** module is relocatable (a `dylink.0` section). The host asks the owner's allocator a block for its\n  static data and one for its stack, gives it slots of the owner's table, and instantiates it with `env.memory`,\n  `env.__memory_base`, `env.__table_base`, `env.__stack_pointer`, `env.__indirect_function_table`; then runs\n  `__wasm_apply_data_relocs` and `__wasm_call_ctors` when it exports them. If it exports `gfx_mem_enter` and the\n  owner takes `gf_mem_link`, the host puts that function in the owner's table and tells the owner its slot: the\n  owner calls the module there, wasm to wasm.\n- `host.unload(name)` gives the blocks and the slots back; `host.commonMemory()` describes the memory and what is\n  placed in it (with how deep each stack went); `host.checkStacks()` names the modules whose stack overflowed\n  into the guard the host puts under it.\n- **Threads.** A `common` module placed on a Worker (`thread` / `placement`, §8) runs there when the common memory\n  is shared between threads and the owner exports `__stack_pointer`, `__wasm_init_tls`, `__tls_size` and\n  `gf_mem_thread`: the Worker's host makes a second instance of the owner on the same memory\n  (`joinCommonMemory`, with a stack and a thread-local block taken by the main thread: `commonThread`), and places\n  the module with it. Otherwise the module stays on the main thread (`host.threadFallbacks`: name → reason) and\n  its calls are delivered there. The owner itself is never placed on a Worker.\n- `host.post(target, func, bytes)` posts a call from the host itself (the page, a tool), with the same call and\n  reply blocks as a module's `gf_call`, to a module on this thread or on a Worker: `{ status, name, bytes }`.\n- A module declared `common` whose binary is not relocatable, a relocatable binary declared `own`, a `common`\n  module without an owner, or one that does not fit: the load fails with `name@version (memory \"<mode>\"): cause`.\n  The host never loads a module in another mode than the one declared.\n\nEvery `gf_calls` import works the same for a module of the common memory (its `exports.memory` as the host sees it\nis the common memory); the bridge between two of them copies inside one memory. What they gain is what they link\ndirectly: pointers are valid on both sides.\n\n## 5. Registers and stack (path c) — one set per thread\n\nThe registers are 64 bytes in the zone (`gf_regs()`), u32 each:\n\n| at | register | at | register |\n|---|---|---|---|\n| 0 | CALLER (module id) | 32 | RESULT (zone offset) |\n| 4 | CALL_ID | 36 | RESULT_LEN |\n| 8 | TARGET (handle) | 40 | STATUS (`0xFFFF` until set) |\n| 12 | FUNC_ID | 44 | DEPTH (nesting, 0 outside any sync call) |\n| 16 | FUNC_NAME (zone offset) | 48 | SP (stack pointer) |\n| 20 | FUNC_NAME_LEN | 52 | STACK_BASE |\n| 24 | ARGS (zone offset) | 56 | STACK_LIMIT |\n| 28 | ARGS_LEN | 60 | MAX_DEPTH |\n\nThe stack follows the registers in the same block (default 256 KiB, max depth 64; the host options\n`stack: { bytes, maxDepth }`). A call: the caller takes a mark (`gf_sp`), pushes its arguments (bump of SP,\n8-byte aligned), calls `gf_invoke`; the host fills the registers, increments DEPTH, runs B's `gf_on_invoke`, which\nreads the registers, pushes its result above and calls `gf_ret`; back in A, A reads RESULT / RESULT_LEN and pops to\nits mark. A→B→C nest naturally (each pushes above the previous frame); a callee can never pop under its own frame.\nPassing the stack's limit or MAX_DEPTH answers `stack_overflow`; nothing is written past the limit (tested).\nAsynchronous calls never use the stack: they use blocks of the zone and queues / rings.\n\n## 6. The zone\n\nOne growable memory the host owns (a `WebAssembly.Memory`, shared when the page is cross-origin isolated; natively\na byte buffer).\n\n- **Start 4 MiB**, then grows only when an allocation does not fit: doubles, **+32 MiB at most per growth**\n  (more only if the request itself needs it), never past the maximum.\n- **Device ceiling**: `navigator.deviceMemory` < 2 GB → 64 MiB, < 8 GB → 128 MiB, 8 GB and more (or unknown) →\n  256 MiB; **half on a mobile** (`userAgentData.mobile` or a coarse pointer). Natively: `zone_max_for_device(ram,\n  mobile)`, same table. If the browser refuses the memory, the host retries with half the maximum, down to 32 MiB.\n- **The game's manifest** may set `minBytes` / `maxBytes`, kept inside the device bounds.\n- **Allocator**: first fit, 8-byte blocks, offsets `0..8` never given, freed neighbours merged, owners recorded\n  (a module may write and free only its own blocks). No metadata in the zone itself, so a module cannot corrupt the\n  allocator. **Offsets stay valid after a growth**; JS views are made again after every growth (and when a read\n  passes the end of a view: another thread grew a shared zone).\n- **Occupancy counter**: `host.occupancy()` → `{ used, blocks, size, max, deviceMax, peak, grows, refused, shared }`.\n- **At the maximum**: the allocation answers 0 (`zone_full` for a call) — a clear refusal, never a corruption.\n\n## 7. Publications (state read by many, once per frame)\n\nA module that owns a state many modules read every frame (inputs, settings) publishes it once per frame instead of\nanswering calls: `Publication::new(\"input.state\", capacity)` then `write(bytes)` each frame. Readers open it once\n(`Subscription::open(name)`, a lookup) then `read()` without any call: `Some(bytes)` only when it changed.\n\nLayout of a publication block: `[seq u32][len u32][bytes…]`. `seq` is odd while it is written (a seqlock): a reader\nretries when `seq` is odd or changed during its read, so it works across threads on a shared zone.\n\n**Batches, not one call per entity.** Pass arrays (`pack` / `unpack`, `list<T>` in interfaces): one call per frame\nwith all the rays / bodies / units costs one header; a call per entity costs one header each.\n\n## 8. Threads\n\nA module's manifest declares `thread: \"main\" | \"worker\" | \"worker:<group>\"`; the game may force it (`placement`\nin its manifest). `worker` alone gets its own Worker; modules with the same `worker:<group>` share one. Every\nmodule placed off the main thread is loaded there before the start.\n\n- **Shared zone** (page cross-origin isolated, `SharedArrayBuffer`): each Worker gets a region of the same zone\n  (default 8 MiB) and two single-producer single-consumer **lock-free rings** (Atomics) — one each way. Ring layout:\n  `[head u32][tail u32][capacity u32][0 u32]` then `capacity` slots of 16 bytes `[kind u32][ptr u32][a u32][b u32]`\n  (kind 1 call, 2 reply, 3 \"free this block\": a block is always freed by the side whose zone region holds it). The producer writes the slot then `Atomics.store` + `Atomics.notify` on `tail`; the\n  consumer reads at `head`. The page's thread never blocks (`Atomics.waitAsync`); a Worker may. A full ring keeps\n  messages in a backlog and sends them when room returns (backpressure, no loss).\n- **Without isolation** (no COOP/COEP): the same calls go by `postMessage` with transferred `ArrayBuffer`s: each\n  block (and its arguments or result) is copied into a message, batched per microtask, and copied into the other\n  side's zone. Slower (bench) but the module code does not change.\n- Between threads, calls are **async only**; a sync call answers `other_thread`. A direct link to a module on\n  another thread is refused at link time.\n\n**Cross-origin isolation today**: gripforge.ai does **not** send `Cross-Origin-Opener-Policy` /\n`Cross-Origin-Embedder-Policy` (checked 2026-10-12 on `/`, `/demos/dungeon`), so pages are not\n`crossOriginIsolated` and Workers use the `postMessage` fallback. Enabling it needs COOP `same-origin` + COEP\n`require-corp` (or `credentialless`) on the page **and** the player frame, and every cross-origin resource served\nwith CORP/CORS — an owner decision (it affects embeds, third-party scripts, ads, OAuth pop-ups).\n\n## 9. Loading, re-entrance, errors\n\n- **Declared modules** are preloaded before the start, dependencies first (`deps` of the manifest); a `lazy` one at\n  its first call. A call to a module not loaded yet: async waits in the queue and is delivered after the load; sync\n  answers `loading` and starts the load. A failed load answers `load_failed` to every waiting call.\n- **Re-entrance**: async calls are delivered only when no module runs (the queue is pumped after the outermost\n  export returns), so A→B→A async just queues a call to A. A sync call to a module on the stack answers `reentrant`.\n- **Errors go back to the caller**: a function's `Err(message)` → `failed` + message; an unknown function →\n  `no_function`; a trap → `trapped` (written by the host, `from = 0`) and the module is left out.\n\n## 10. Contracts without cross-recompilation\n\nThree levels:\n\n1. **The host ABI** (`gripforge:calls@1`, §4): frozen, grows only at the end, capabilities negotiated.\n2. **Standard interfaces**: `input.settings@1`, `net.core@1`, … — owned by GripForge, versioned.\n3. **Kit interfaces**: `physics.query@1`, `ai.navigation@2`, … — owned by each kit.\n\nEach interface is a declarative `.gfi` file (close to WIT) with **stable function numbers**:\n\n```\ninterface test.b@1.1.0\nfn 1 add(a: i32, b: i32) -> i32\nfn 2 sum_f32(values: list<f32>) -> f32\nfn 3 fail()\ndirect add(a: i32, b: i32) -> i32          // a direct link (scalars only): export gfx_add\nfn 6 mul(a: i32, b: i32) -> i32   since 1.1\n```\n\nTypes: `i32 u32 i64 u64 f32 f64 bool string list<scalar>`. Encoding: parameters one after the other, scalars\nlittle-endian at their size, `bool` one byte, `string` and `list` a u32 count then the items. Compatible evolution\n(checked by `--compat older.gfi`): a minor version only **adds** functions with new numbers; nothing is renumbered,\nrenamed, retyped or removed within a major.\n\n`node tools/modcall/gfi.mjs file.gfi --rust out.rs --js out.mjs [--compat older.gfi]` generates:\n\n- Rust: `NAME`, `VERSION`, `REQUIRE` (`name@^major.minor`), `func::*` numbers, a `Client` (sync + `_async` +\n  `decode_*`), a `Provider` trait and `expose(provider)`, the `direct` imports, and the macros `provides!()` /\n  `consumes!()` which write a custom section `gripforge.calls` (`provides name@version` / `consumes name@^x.y`);\n- JS: the schema (names, argument and result types) the tracer decodes with.\n\n**Manifests.** A module declares what it provides and consumes (`name@semver`, in its binary's custom section and\nin the manifest); the game declares the modules it allows. At link time the host checks: a `consumes` must be met by\nthe provider the game declares, a `provides` must be the version the game declares. A mismatch is refused cleanly\n(the module is not loaded, the reason is logged), never a crash. A module compiled against `test.b@1.0` runs with\n`test.b@1.1` rebuilt alone (tested); one compiled against `1.1` is refused with a `1.0` provider.\n\n**In the player** (`present-modules.json`):\n\n```json\n{\n  \"modules\": [ … presentation modules, as before … ],\n  \"calls\": {\n    \"zone\": { \"minBytes\": 4194304, \"maxBytes\": 67108864 },\n    \"placement\": { \"ai.navigation\": \"worker:logic\" },\n    \"modules\": [\n      { \"name\": \"physics.query\", \"version\": \"1.2.0\", \"wasm\": \"modules/physics_query.wasm\", \"thread\": \"worker:logic\",\n        \"deps\": [\"math.core@^1\"], \"lazy\": false }\n    ]\n  }\n}\n```\n\nA presentation module that imports `gf_calls` / `gf:*` (or exports `gf_on_call`) is linked to the calls host;\nothers are instantiated as before, with no import. The host exists only when a module speaks the contract.\n\n## 11. Tracer\n\nOff by default and free then (no trampoline, one `null` test per host call). On (`?gfTrace` or `?gfTrace=<N>` on the\npage, `new ModuleCallHost({ trace: { bytes: N } })`, or `host.traceOn({ bytes })`): a ring of fixed 48-byte records\noutside the zone:\n\n| at | type | field |\n|---|---|---|\n| 0 | f64 | start (ms, `performance.now()`) |\n| 8 | f32 | duration (µs) |\n| 12 | u8 | kind: 1 post, 2 sync (stack), 3 deliver, 4 reply, 5 direct, 6 refused, 7 bridge |\n| 14 | u16 | status |\n| 16 | u32 | from (module id) |\n| 20 | u32 | to (module id) |\n| 24 | u32 | call id |\n| 28 | u32 | target handle |\n| 32 | u32 | function (number, or interned name with bit 31) |\n| 36 | u32 | args length |\n| 40 | u32 | result length |\n| 44 | u16 / u16 | bytes kept of args / result (the first N, optional) |\n\nDirect links go through a traced trampoline only when the tracer is on at link time. Reading:\n`window.gfModuleCalls.trace({ last })` (names, statuses, values decoded by the target's schema when one is declared,\nelse hexadecimal, `argsTruncated` / `resultTruncated`), `traceJSON()` for tools; out of the frame, post\n`{ type: 'gripforge.presenter.calls-trace', last }` to the presenter frame: it answers the JSON (CLI, MCP, QA).\n\n## 12. Module SDK (Rust)\n\n```rust\nuse gripforge_present_sdk::calls::{self, Target, pack, unpack};   // or gripforge_modcall::guest\n\n#[unsafe(no_mangle)]\npub extern \"C\" fn gf_calls_init() {\n    calls::expose_id(1, \"sum\", |args| Ok(pack(&[unpack::<f32>(args).iter().sum::<f32>()])));\n}\n// Resolved once:\nlet physics = Target::resolve(\"physics.query@^1\").unwrap();\nlet id = calls::call(physics, 1u32, &pack(&rays))?;            // async, the default\ncalls::call_then(physics, 1u32, &args, |result| { … })?;        // async with a callback (gf_on_reply)\nlet r = calls::take_reply(id);                                  // or read the reply later\nlet bytes = calls::call_sync(physics, 1u32, &args)?;            // bridge (same thread, loaded)\nlet bytes = calls::call_stack(physics, 1u32, &args)?;           // zone path (large volumes)\ngripforge_modcall::export_calls!();          // or export_calls!(no_alloc) beside export_module!\n```\n\nRegions: `Region::new(len)` (zone block owned by the module), `write`, `read`, `free_region`. Publications: §7.\n\n## 13. Costs\n\n`node web/module-calls-bench.mjs` (Node 24, main machine, load ≈ 6, ns per call; a call inside the same wasm is\nthe reference):\n\n| path | ns / call |\n|---|---|\n| local (same wasm, not inlined) | 1.5 |\n| direct link | 2.4 |\n| bridge (8 bytes each way) | 662 |\n| zone stack, copy path (8 bytes) | 1 436 |\n| async round trip, same thread | 3 850 |\n| 64 KiB, bridge | 29 585 |\n| 64 KiB, zone, copy path | 34 956 |\n| 64 KiB, zone read in place (multi-memory) | 13 749 |\n| direct link, traced | 187 |\n| bridge, traced | 1 116 |\n| async to a Worker, shared zone + rings (1000 in flight) | 6 162 |\n| async to a Worker, postMessage fallback (1000 in flight) | 17 025 |\n\n**In a browser** (`qa/module-calls-browser-check.mjs`, headless Chrome 146 on the second machine, a laptop CPU —\nnoisier than the table above):\n\n| path | isolated (COOP/COEP) | not isolated (gripforge.ai today) |\n|---|---|---|\n| local (same wasm) | 1.4 | 1.2 |\n| direct link | 8.7 | 4.0 |\n| bridge (8 bytes) | 800 | 1 666 |\n| zone stack, copy path (8 bytes) | 1 178 | 2 500 |\n| async round trip, same thread | 4 738 | 4 350 |\n| 64 KiB, bridge | 24 108 | 27 750 |\n| 64 KiB, zone, copy path | 69 775 | 82 250 |\n| 64 KiB, zone read in place | 30 693 | 35 450 |\n| async to a Worker (1000 in flight) | 15 970 (shared rings) | 50 100 (postMessage) |\n\nTake-aways: use direct links for small hot functions, the bridge for the rest on the same thread, batches (one call\nper frame with arrays), publications for state read by many. Workers cost ~3× more per call without\ncross-origin isolation: batch calls to them.\n\n## 14. Native hosts\n\nOutside a browser the same contract is served by `native/gripforge-modhost`, a Rust library with no engine\ndependency: `.wasm` modules run by an embedded interpreter (wasmi) **and** modules built as native libraries\n(`.so` / `.dll` / `.dylib` exporting the same `gf_*` functions, the host functions handed as a C table), mixed\nfreely, over a byte-buffer zone with the same allocator and ceilings (`zone_max_for_device`). The module SDK builds\nboth forms from one source (`export_calls!()` + `export_calls_native!()`). The native ABI, the manifest, what\ndiffers from this host, the embedding API and the costs: [module-calls-native.md](module-calls-native.md)\n(`grip-forge docs module-calls-native`).\n\nThe common memory (§4) is not built in the native host yet: one memory handed to the owner and to the relocatable\nmodules, their `dylink.0` read, their data and stack taken from the owner's allocator, the owner's table grown — or\nnothing of it for modules loaded as shared libraries of one process, which already share a memory and an allocator.\n"
 },
 {
  "id": "module-calls-native",
  "title": "The native host of the calls between modules",
  "summary": "gripforge-modhost: the same calls contract outside a browser — modules as .wasm (embedded interpreter) and as native libraries (.so / .dll / .dylib), the native C ABI (gf_calls_bind, GfHostApi), the manifest per platform, direct links between forms, embedding API, costs against the web host, kit modules under it.",
  "source": "docs/module-calls-native.md",
  "text": "# The native host of the calls between modules (`gripforge-modhost`)\n\nHow GripForge modules call each other **outside a browser**: the same contract as the web host\n([module-calls.md](module-calls.md), `gripforge:calls@1`), implemented in Rust with no engine dependency, for the\nnative Bevy player and later the Godot, Unity and Unreal hosts. A module exists in **two forms** — a `.wasm` and a\nnative library (`.so` / `.dll` / `.dylib`) — and the host loads the native library where the platform has one and the\n`.wasm` otherwise (and on the web). Readable offline: `grip-forge docs module-calls-native`, or the MCP tool\n`gripforge_docs` (topic `module-calls-native`). Words are in the [glossary](glossary.md).\n\n| Piece | Where |\n|---|---|\n| The host (a Rust library, no Bevy) | `native/gripforge-modhost` (`src/host.rs` the switchboard, `src/form.rs` the two forms, `src/zone.rs`, `src/trace.rs`, `src/manifest.rs`) |\n| The module side as a native library | `native/gripforge-modcall/src/guest.rs` (`guest::native`, `export_calls_native!`) |\n| Bindings (`.gfi` → Rust), with the native direct links and contracts | `tools/modcall/gfi.mjs` |\n| The two test modules in both forms | `native/gripforge-modcall/test-modules` (`build.sh` → `.wasm`, `build-native.sh` → libraries) |\n| Tests | `native/gripforge-modhost/tests/calls.rs` (every pair of forms), `tests/kithost.rs` (the kit host core and the kit modules on the parity fixtures) |\n| Bench | `native/gripforge-modhost/examples/bench.rs` |\n\nStatus: the crate, its tests, its bench and this document. **It is not yet embedded in the Bevy player** (§7 says how),\nand the kits are not yet built as native libraries (§9).\n\n## 1. What is the same as on the web, what differs\n\nThe same: the 32-byte headers, the statuses, the registers and the stack, the zone sizes and its allocator, the\nversion rules (`name@semver`, `^` `~` `=` `>=`), the contract lines of a binary (`provides` / `consumes`), the\nmanifest, the messages of a refused link, the tracer's 48-byte records. A `.wasm` module built for the web host runs\nunchanged: the same file, the same imports (`gf_calls`), the same exports.\n\n| | Web host (`module-calls.mjs`) | Native host (`gripforge-modhost`) |\n|---|---|---|\n| Forms of a module | `.wasm` | `.wasm` (interpreted) **and** native library, mixed freely |\n| Direct link | wasm → wasm | wasm → wasm, native → native (a plain C call), wasm → native (by the import's signature, §4); native → wasm is refused |\n| Bridge | 2 copies (args in, answer out) | wasm → wasm: 2 copies; native target: arguments read where they are; native caller: answer read where it is — native → native copies nothing |\n| Zone | a `WebAssembly.Memory`, shared with Workers | a byte buffer of the host; a native module may read and write it in place (`gf_zone_base`) |\n| Zone as a second memory (multi-memory) | when the engine has it (`gf_host_caps` bit 0) | not offered (bit 0 off): a `.wasm` uses `gf_zone_read` / `gf_zone_write` |\n| Loading | asynchronous (fetch) | synchronous, at `preload()` and at `settle()` (never while a module runs) |\n| Threads (`thread`, `placement`) | Web Workers, rings or messages | not yet: a host runs its modules on the thread that owns it (§10) |\n| A module that fails | a wasm trap: left out, the rest goes on | wasm trap: the same; native: a **panic** is caught (`trapped`, left out), a crash of native code (segfault, abort) takes the process — a native library is trusted code, the `.wasm` form is the sandbox |\n\n## 2. The embedded WebAssembly engine: wasmi\n\n`.wasm` modules are run by **wasmi 2** (a pure-Rust interpreter). The other candidate was wasmtime (a compiler).\n\n| | wasmi | wasmtime |\n|---|---|---|\n| Weight in the host | the whole host is 22 crates (wasmi and its 4 own crates, a wasm parser, serde, libloading), builds in seconds; no C code, no assembly | a compiler back end (Cranelift) and its runtime: 93 crates with the smallest feature set (`cranelift`, `runtime`; counted with `cargo tree`), megabytes of code — or a runtime-only build that needs each module compiled ahead of time **per platform** by the CI |\n| Where it runs | every target Rust has, the same code: Linux, Windows, macOS, Android, **iOS**, consoles, even wasm32 | compiles to machine code on x86-64 and arm64 (and two more); **iOS and consoles forbid generating code at run time**: there it falls back to its own interpreter |\n| Speed | an interpreter: ≈ 20× the cost of compiled code per instruction, but a bridge call between two `.wasm` modules ≈ 0.9 µs, about what the web host pays (§8) | near machine code where it can compile |\n| Sandbox | yes | yes |\n\nThe choice follows from the direction \"each module as `.wasm` **and** as a native library\": on desktop and Android\nthe speed comes from the **native library**, not from a faster wasm engine; the `.wasm` form on a native host is the\nportable fallback, the sandbox for third-party modules, and the only dynamic form on platforms that forbid loading or\ngenerating code (iOS). For that role weight and portability decide, and one engine that behaves the same on every\nplatform is worth more than a fast one on some. The engine is used in one file (`src/form.rs`, the wasmi API mirrors\nwasmtime's): a host for a desktop-only product can swap it. The measured cost of that choice is in §8.\n\nwasmi is built with `auto-dispatch`: tail-call dispatch in optimised builds, the portable loop in debug builds.\n\n## 3. A module as a native library\n\nThe same source builds both forms. In the crate: `crate-type = [\"cdylib\"]`, and beside `export_calls!()`:\n\n```rust\ngripforge_modcall::export_calls!();          // the wasm32 exports (expands to nothing natively)\ngripforge_modcall::export_calls_native!();   // the native exports (expands to nothing for wasm32)\n```\n\n`cargo build --release` gives `lib<name>.so` / `<name>.dll` / `lib<name>.dylib`; `--target wasm32-unknown-unknown`\ngives `<name>.wasm`. The SDK (`call`, `call_sync`, `call_stack`, `expose`, regions, publications, the generated\n`Client` / `Provider`) is the same code in both. Build the library with `panic = \"unwind\"` (a panic is then answered\n`trapped`; with `panic = \"abort\"` it ends the process).\n\n### Exports (C ABI, the same names and function numbers as the `.wasm`)\n\n| export | signature | role |\n|---|---|---|\n| `gf_calls_abi` | `() -> u32` | `major << 16 \\| minor`; another major is refused |\n| `gf_calls_bind` | `(const GfHostApi*)` | **replaces the imports**: the host hands its functions once, before anything else; `NULL` when the host goes away |\n| `gf_calls_init` | `()` | optional, run once after the bind (expose functions there) |\n| `gf_alloc` / `gf_free` | `(u32 len) -> u8*` / `(u8*, u32 len)` | a buffer the embedder writes into |\n| `gf_on_call` | `(u32 call_ptr) -> u32 reply_ptr` | an async call (zone offsets, as in wasm); `0xFFFFFFFF` after a panic |\n| `gf_on_reply` | `(u32 reply_ptr) -> u32` | 0, or `0xFFFFFFFF` after a panic |\n| `gf_on_bridge` | `(u32 func_id, const u8* name, u32 name_len, const u8* args, u32 args_len, u32* out_len) -> const u8*` | the bridge: arguments **read where they are**; answers `[status u32][bytes]`, valid until the module's next bridge call; `NULL` + `0xFFFFFFFF` after a panic |\n| `gf_on_invoke` | `() -> u32` | the registers-and-stack path; 0, or `0xFFFFFFFF` after a panic |\n| `gfx_<fn>` | scalars | direct-link exports, as in wasm |\n| `gf_provides_<iface>` / `gf_consumes_<iface>` | `const char[]` (NUL-terminated) | the contracts: the version provided (`1.1.0`) or the requirement (`^1.1`) for the interface whose name is `<iface>` with every non-alphanumeric character as `_`, lower case (`test.b` → `gf_consumes_test_b`). Written by the generated `provides!()` / `consumes!()` |\n\nOnly two things change from the `.wasm` form, both because a native pointer is 64 bits wide: **memory pointers are\nreal pointers** (`gf_alloc`, the bridge), and the bridge passes its lengths apart instead of packing `ptr | len << 32`.\nZone offsets, handles, call ids, function numbers, statuses, headers and registers are the same integers.\n\n### The host table (`GfHostApi`, `gripforge_modcall::guest::native::HostApi`)\n\nA `#[repr(C)]` struct: `abi u32`, `size u32` (its length: it grows only at the end), `ctx void*` (passed back as the\nfirst argument of every function), `module_id u32`, `reserved u32`, then one function pointer per import of §4 of\nmodule-calls.md, in this order: `gf_call`, `gf_resolve`, `gf_zone_alloc`, `gf_zone_free`, `gf_zone_write`,\n`gf_zone_read`, `gf_zone_size`, `gf_regs`, `gf_sp`, `gf_push` (`src = NULL` reserves only), `gf_pop`, `gf_invoke`,\n`gf_ret`, `gf_bridge`, `gf_publish`, `gf_lookup`, `gf_host_caps`, and two native additions:\n\n- `gf_zone_base(ctx) -> u8*` — the zone **in place**: its first byte. Valid until the next host call that may grow\n  the zone (an allocation, a call): ask again after one. A native module reads any block and writes its own without\n  a copy; the offsets are those every module uses.\n- `gf_link(ctx, \"name@req\", len, \"fn\", len) -> void*` — a direct link: the address of the provider's `gfx_<fn>`,\n  or `NULL` (not declared, version, not loaded, or a provider that is not a native library). The generated bindings\n  ask once and keep it (`guest::native::DirectLink`); a link the host cannot make panics at its first call, which the\n  host answers `trapped`.\n\n`gf_bridge(ctx, handle, func_id, name, name_len, args, args_len, u32* out_len) -> const u8*` answers the address of\n`[status u32][bytes]` (valid until this module calls the host again: copy it at once, the SDK does), or `NULL` with\nthe refusal status in `out_len`.\n\n### Rules of the native form\n\n- **One module instance per library image.** A library keeps its state in its statics, so the same file cannot be\n  two modules: the host refuses the second load with the reason. Load a copy of the file for a second instance.\n- **The host unbinds what it drops** (`gf_calls_bind(NULL)`): what the module still frees afterwards (thread-local\n  destructors) answers as if nothing was declared.\n- **Trusted code.** A native library runs in the process with its rights; ship the `.wasm` form for code you do not\n  trust. macOS needs signed libraries; iOS and consoles do not load libraries at run time: link the module into the\n  executable and register it (`Source::Static(NativeExports { … })`, the same functions by address), or use the\n  `.wasm`.\n- A crate in another language exports the same symbols and reads the same table: nothing in the ABI is Rust.\n\n## 4. Direct links between the forms\n\n| caller → provider | how | cost |\n|---|---|---|\n| `.wasm` → `.wasm` | the provider's export is the caller's import (the same store): the interpreter calls it itself | a call inside the interpreter |\n| native → native | `gf_link` gives the function's address; the bindings call it | a C call through a pointer |\n| `.wasm` → native | the host makes the import from its signature and calls the C function: every combination of up to 4 scalars (`i32` / `i64` / `f32` / `f64`), or up to 6 integers; 64-bit targets | one host call |\n| native → `.wasm` | refused (a `.wasm` function has no address): the link panics at its first call (`trapped`). Use the bridge, or ship the provider as a library too | — |\n| any → a provider that keeps a zone in its own memory | `zone_copy` / `zone_copy_out` / `zone_copy_in` `(off, ptr, len) -> ok`: when the provider has no `gfx_<name>` for them but exports `gfx_zone_base` and `gfx_zone_size`, **the host serves the copy itself** (it sees both memories) — the shared zone of the kit host core, kit-modules.md §7 | one host call |\n\nWith the tracer on at link time, a `.wasm` caller's direct links go through a traced trampoline (kind 5).\n\n## 5. The manifest\n\nThe `calls` object of a game (module-calls.md §10) names the code of a module per form:\n\n```json\n{ \"zone\": { \"minBytes\": 4194304, \"maxBytes\": 67108864 },\n  \"modules\": [\n    { \"name\": \"physics.query\", \"version\": \"1.2.0\",\n      \"wasm\": \"modules/physics_query.wasm\",\n      \"native\": { \"linux-x86_64\": \"native/linux-x86_64/libphysics_query.so\",\n                  \"windows-x86_64\": \"native/windows-x86_64/physics_query.dll\",\n                  \"macos-aarch64\": \"native/macos-aarch64/libphysics_query.dylib\",\n                  \"android-aarch64\": \"native/android-aarch64/libphysics_query.so\" },\n      \"provides\": [\"physics.query@1.2.0\"], \"consumes\": [\"math.core@^1\"],\n      \"deps\": [\"math.core@^1\"], \"lazy\": false, \"reentrant\": false } ] }\n```\n\nThe platform key is `<os>-<arch>` as Rust names them (`manifest::platform()`). The embedder says which form it\nprefers (`Prefer::Native` or `Prefer::Wasm`); a module that lacks that form for this platform is loaded in the other.\nA game package only needs the files of its platform. `consumes` is where a native library's requirements are\nwritten when it carries no `gf_consumes_*` symbol (a `.wasm` carries them in its custom section). `kit-modules.json`\n(kit-modules.md §3) is read by `manifest::from_kit_modules` (the core, then the kits of the game).\n\n**A module is loaded only if the game declares it.** A link or a `consumes` to an undeclared name refuses the load\nwith the reason; a call answers `not_declared`; nothing is searched on disk.\n\nAt link the host checks, for both forms: every `consumes` is met by the provider the game declares; a `provides` is\nthe version the game declares; every direct link has a declared, compatible, loaded provider; the ABI major. A\nrefusal names the module and the two versions (`test.a was compiled against test.b@^1.1; the game provides\ntest.b@1.0.0`), the module is not loaded, the others are.\n\n## 6. Embedding the host (Rust)\n\n```rust\nuse gripforge_modhost::{Host, Options, Val, manifest};\n\nlet calls: serde_json::Value = /* the \"calls\" object of the game */;\nlet (declared, zone) = manifest::from_calls(&calls, game_dir, manifest::Prefer::Native)?;\nlet mut host = Host::new(Options { declared, zone, ..Default::default() })?;\nfor error in host.preload() { log::warn!(\"{error}\"); }   // modules that are not lazy, dependencies first\n\n// each frame\nlet physics = host.module(\"physics.query\").unwrap();\nlet hits = host.call_module(physics, 1, \"\", &rays)?;      // the contract's bridge, the embedder as the caller\nhost.settle();                                            // loads asked by calls, async calls and replies\n```\n\n| `Host` | |\n|---|---|\n| `new(Options)` | `declared`, `zone`, `stack_bytes`, `max_depth`, `trace`, `imports` (functions given to modules that import something else than `gf_calls` / `gf:*`), `max_queue` |\n| `declare`, `preload`, `ensure(name)` | declaring and loading |\n| `settle()`, `pump()` | a frame boundary: pending loads then the queue; or the queue alone |\n| `module(name)`, `form(id)`, `is_dead(id)`, `failure(name)`, `warnings()` | what is loaded, in which form, and why not |\n| `call_module(id, func_id, name, args)` | a function of a module as the contract calls it (by number, or by name) |\n| `call(id, export, &[Val])` | an export of a `.wasm` module (scalars) |\n| `symbol::<T>(id, name)` + `invoke(id, \\|\\| …)` | a symbol of a native module, called with the call stack kept |\n| `put_bytes(id, bytes)`, `get_bytes(id, at, len)` | the module's memory (its `gf_alloc`) |\n| `zone()`, `occupancy()`, `reg(o)`, `stats()` | the zone, its counters, the registers, the call counters |\n| `trace_on(Some(TraceOptions { bytes, capacity }))`, `trace(last)`, `trace_json(last)` | the tracer (**off by default**: one `Option` test per host call, no trampoline); the JSON has the shape of the web host's `traceJSON()` with bytes in hexadecimal |\n\nA sync call to a module that is not loaded answers `loading` and asks for the load; an async call waits. Both are\nserved by the next `settle()`.\n\nThe host is single-threaded and not `Send`: build it on the thread that runs the modules.\n\n## 7. Integrating it in a player (not done yet)\n\n**The Bevy native player** (`native/gripforge-runtime/player`, feature `native-logic`): one `Host` as a non-send\nresource; at start read the game's `calls` object and `kit-modules.json`, `preload()`; give the kit host core its\npage import (`Options.imports`: `env.gf_page_call`); drive the core's exports (`gf_step`, `gf_frame_wire`,\n`gf_apply`…) with `Host::call` in the fixed-step system, then `settle()` once per frame; expose `trace_json()` to the\ntools as the page does (`calls-trace`). Nothing of a kit or a game enters the player: it links one more library crate.\nThe player was not rebuilt for this lot.\n\n**Godot, Unity, Unreal**: the same crate behind a thin C API (`gf_host_new(manifest_json, dir, prefer)`,\n`gf_host_preload`, `gf_host_call_module`, `gf_host_settle`, `gf_host_trace_json`, `gf_host_free`) built as one\nlibrary per platform, bound by a GDExtension, P/Invoke, and an Unreal module. That C wrapper is not written; the\nRust API above is what it wraps one to one.\n\n**iOS, consoles**: no run-time library — native modules are linked in and registered (`Source::Static`), third-party\nmodules stay `.wasm`.\n\n## 8. Costs\n\n`cargo run --release --example bench` (the test modules in both forms; the best of 5 runs), against\n`node web/module-calls-bench.mjs` (the web host) **on the same machine**: the second machine (a 12-thread laptop CPU, Linux x86-64), 2026-10-12, load ≈ 3 during the runs, Node 24.14, Rust 1.95 release build. ns per call.\n\n| path | web host (Node 24, V8) | native host, `.wasm` → `.wasm` (wasmi) | native host, native → native | `.wasm` → native | native → `.wasm` |\n|---|---|---|---|---|---|\n| local call (inside one module, the reference) | 0.6 | 13.6 | 0.5 | 13.6 | 0.5 |\n| **direct link** | 2.8 | 12.5 | **1.1** | 39.3 | — (refused) |\n| **bridge** (8 bytes each way) | 752 | 942 | **95** | 565 | 490 |\n| zone stack, copy path (8 bytes) | 1 280 | 1 042 | 160 | 580 | 628 |\n| async round trip, same thread | 2 989 | 2 884 | 807 | 2 302 | 1 355 |\n| 64 KiB, bridge | 31 176 | 75 771 | 9 970 | 11 828 | 74 842 |\n| 64 KiB, zone, copy path | 34 614 | 77 043 | 13 731 | 14 318 | 77 254 |\n| direct link, traced | 88 | 200 | — | 224 | — |\n| bridge, traced | 559 | 1 034 | 166 | 639 | 1 007 |\n\n(The web host's two Worker rows and its multi-memory row have no native counterpart yet: §10. The columns name the\ncaller's form, then the target's.)\n\n- **Native libraries are what makes the native host fast**: a direct link is a C call (1.1 ns, 2.5× less than the\n  web's wasm-to-wasm link), a bridge call 95 ns — **8× less than the web host** — because nothing is copied by the\n  host between two libraries and no engine border is crossed. The 64 KiB bridge is 3× less than the web's.\n- **The interpreter costs about 20× per instruction** (the local call: 13.6 ns against 0.6 ns under V8), but **a\n  bridge call between two `.wasm` modules costs about the same as on the web** (942 ns against 752 ns): the web host\n  pays its JavaScript and two wasm ↔ JS borders where the native host pays interpreted instructions. What suffers is\n  the module's own computation: the 64 KiB rows are the target summing 16 384 floats (76 µs interpreted, 31 µs under\n  V8, 10 µs native).\n- **Mixed pairs work and sit in between**; a `.wasm` module calling a native provider by a direct link pays one host\n  call (39 ns), still 20× less than a bridge call.\n- The tracer, when on, adds ≈ 70–190 ns per call; off, it is one test.\n\nSo: ship the native library where the platform allows it; keep the `.wasm` as the fallback, the sandbox and the web\nform. A game logic run entirely as interpreted `.wasm` (the kit host core and its kits, §9) works and is correct, at\ninterpreter speed — that is the fallback, not the target.\n\n## 9. The kit host core and the kit modules under the native host\n\n`tests/kithost.rs` loads `kithost.core` and the kit modules (`kit-modules.json`, the `.wasm` built by\n`tools/kit-modules/build.mjs`) under the native host — the core provides the `kithost.*` interfaces, each kit\nconsumes them and links its input reads directly (`gf:kithost.input@^1`) — registers the kits in the core\n(`gf_kits_register`) and replays the parity fixtures of `native/gripforge-kithost/tests/fixtures` through\n`gf_parity`, as `qa/kithost-wasm-parity-check.mjs --kit-modules <dir>` does under the web host:\n\n```\nGF_KIT_MODULES_DIR=<dir of kit-modules.json> [GF_PARITY_ONLY=combat] cargo test --release --test kithost -- --nocapture\n```\n\nMeasured 2026-10-12 (second machine, release build) with the core and the **160 kit modules** built from master\n(`kit-modules.json`: 4.4 MB core, all 160 kits declared, loaded and registered in 0.4 s):\n\n| family of fixtures | fixtures | identical | need the native test kits (as under the web host) | differ | time | bridge calls |\n|---|---|---|---|---|---|---|\n| `combat*` | 36 | 30 | 6 | 0 | 16.8 s | 326 259 |\n| `input*` | 38 | 38 | 0 | 0 | 12.1 s | 84 460 |\n| `ui*` | 39 | 39 | 0 | 0 | 12.4 s | 84 824 |\n| `hud*` | 33 | 32 | 1 | 0 | 19.5 s | 149 371 |\n| `game*` | 30 | 26 | 4 | 0 | 7.0 s | 19 653 |\n| `vehicle*` | 28 | 11 | 17 | 0 | 10.0 s | 37 238 |\n| `character*` | 22 | 17 | 5 | 0 | 14.5 s | 182 424 |\n| `fps*` | 22 | 22 | 0 | 0 | 33.5 s | 515 966 |\n| **eight families** | **248** | **215** | 33 | **0** | | |\n| `moba*`, each fixture alone | 33 | 25 | 1 | 0 | 7 fixtures did not end in 150 s each | |\n\nEvery fixture that ran to its end gives the trace of the TypeScript kit host, bit for bit, as under the web host\n(direct links to the core's input reads included). **The whole set (864 files) was not run to its end**: the\nfixtures that play a full match with bots and navigation (`moba.hero.bots`, `moba.lanes.arena`, `.match`,\n`.three_lanes`…) take minutes each in the interpreter (one that ended took 140 s); the web host replays them all, V8 compiling the same modules.\nThat is the interpreter's speed on the modules' own computation (§8), not the calls: the run above makes ≈ 20 000\nbridge calls per second of wall time, far under what the host can switch. It is the measured reason why game logic\nbelongs in native libraries on a native host (below), with the `.wasm` as the fallback.\n\n**What is missing to run the kits as native libraries** (the `.wasm` kit modules run today; this is the remaining\nwork, in order):\n\n1. `native/gripforge-kit-guest`: `export_kit!` writes its exports for wasm32 only — add `export_calls_native!()` and\n   the native form of its hand-written direct links (`gf:kithost.input@^1` / `input_get`: a\n   `guest::native::DirectLink` instead of a wasm import), and the `gf_provides_*` / `gf_consumes_*` symbols.\n2. `native/gripforge-kithost-wasm` (the core): the same for its exports (`gfx_*`, the page API takes `u32` memory\n   offsets: `gf_alloc`, `gf_parity`, `gf_step`… need pointer-width variants), and `guest::take` in `kitmods.rs`.\n3. `tools/kit-modules/build.mjs`: a `--native <target>` build (one `cdylib` per kit, `panic = \"unwind\"`), the files\n   written under `native/<os>-<arch>/` and named in `kit-modules.json` (`\"native\": { \"<os>-<arch>\": … }`, which\n   `manifest::from_kit_modules` already reads).\n4. The native CI builds them per platform by content hash, like `gfnet`.\n\nThese files were being changed by the shared-zone lots while this host was written, which is why it stops here.\n\n## 10. What is not there yet\n\n- **Threads**: `thread` / `placement` are read and ignored; every module of a host runs on its thread. The plan is\n  one host per thread over one zone with the rings of module-calls.md §8 (the ring layout is already fixed).\n- **The zone as a second memory** for `.wasm` modules (multi-memory, `gf_host_caps` bit 0).\n- **Direct links native → `.wasm`**, and `.wasm` → native beyond 4 mixed scalars.\n- **The host-served zone copies for a native provider or caller** (served for `.wasm` on both sides today).\n- **The C API** for Godot, Unity, Unreal (§7), and the integration in the Bevy player.\n- **The game schema** (`gripforge.game-schema/1`, in progress with the shared zone): it is handed to the core by an\n  export of the core (`gf_schema_init(ptr, len)`), which the embedder calls with `Host::put_bytes` + `Host::call`\n  before `gf_kits_register`; nothing of it is in the host, by design.\n- **Kit-to-kit direct links and hooks through the core's function table** (announced by the shared-zone lots): a\n  `.wasm` export can be placed in another module's table by the host, since all `.wasm` modules of a host share one\n  store; the entry point is not written.\n"
 },
 {
  "id": "kit-modules",
  "title": "Kit logic modules (one wasm per kit)",
  "summary": "The game logic as one wasm per kit plus the core (kithost.core): the kithost.* interfaces, the kit façade, writing a third-party kit in Rust, building, loading, costs.",
  "source": "docs/kit-modules.md",
  "text": "# Kit logic modules — one wasm per kit (`kithost.kit@1`)\n\nHow the game logic of the kits runs on the web as **one WebAssembly module per kit** plus a **core**, linked by the\ncalls between modules ([module-calls.md](module-calls.md), `gripforge:calls@1`), and how to write a kit of your own\nin Rust on these interfaces. This is THE Rust logic of GripForge on the web (`logic: 'wasm'`, the default of every\ngame): the play page, the web export and the deployment carry nothing else (§1). Readable offline:\n`grip-forge docs kit-modules`, or the MCP tool `gripforge_docs` (topic `kit-modules`).\n\n**Start with [game-schema.md](game-schema.md)**: everything the modules of a game share (the layout of the zone and\nof an entity row, the static lists, the event types, the rights, the wake conditions, the placement) is decided\nonce at start, by the game, in its schema; this page is how the modules run on it.\n\n| Piece | Where |\n|---|---|\n| Contract: interface names, versions, function numbers, the argument codec | `native/gripforge-kitcall` (`src/lib.rs`, `src/fns_*.rs`) |\n| Schemas (`.gfi`, one per interface) | `native/gripforge-kitcall/interfaces/*.gfi` |\n| The core (`kithost.core`) | `native/gripforge-kithost-wasm` built with the feature `kit-modules` (`src/kitmods.rs`); its side of the calls: `native/gripforge-kithost/src/kitcall/` |\n| The kit side: a façade of the kit host | `native/gripforge-kit-guest` |\n| Build: one cdylib per kit, hashes, manifest | `tools/kit-modules/build.mjs` → `kit-modules.json` |\n| Loading in the page | `native/gripforge-runtime/web/kithost-wasm.mjs` (`loadKitHostWasm(null, { kitModules })`) |\n| Parity, bench | `qa/kithost-wasm-parity-check.mjs --kit-modules <dir>`, `qa/kithost-wasm-bench.mjs --sides wasm,kits --kit-modules <dir>` |\n| Merging a game's kit modules into one wasm at export (§8) | `tools/kit-modules/merge.mjs` (+ `merge.test.mjs`), `GF_KIT_MODULES_MERGE` of `tools/web-export/build.mjs` |\n\n## 1. The model\n\n```\n                 page (input, audio, saves, the Bevy player)\n                    │  gf_step, gf_frame_wire, gf_apply … (unchanged)\n             ┌──────▼───────────────────────────┐\n             │ kithost.core                      │  owns the world: entities, state, zones, objectives, timers,\n             │  provides kithost.world@1 …       │  bus, triggers, services registry, Rapier physics, input,\n             │  game.engine (the engine contract)│  assets, platform; schedules the ticks; mods applied here\n             └──┬──────────────▲─────────────────┘\n   kithost.kit@1│ hooks         │ kithost.world@1, kithost.state@1 … (calls)\n     ┌──────────▼───┐   ┌───────┴──────┐   ┌──────────────┐\n     │ ai.navigation │   │ combat.core  │   │ ui.menu      │   one .wasm per kit, its own memory\n     └───────────────┘   └──────────────┘   └──────────────┘\n```\n\n- **The core is a module like the others.** It owns the world and provides versioned interfaces (§3). It mounts the\n  kits of the game in the lock's order and drives the fixed-step loop exactly as the single kit host does: same\n  order of hooks, same bus rounds, same saves. Each kit module is, for the core, a `KitModule` whose hooks are calls\n  (`RemoteKit`, `native/gripforge-kithost/src/kitcall/mod.rs`).\n- **A kit is compiled from the same source.** `native/gripforge-kithost/src/kits/<kit>.rs` compiles unchanged\n  against the façade of `gripforge-kit-guest`, which gives the same paths (`crate::host::{Kx, KitModule}`,\n  `crate::entities::Pos`, `crate::bus::GameEvent`, `crate::ports::…`) where every field and method of `Host` / `Kx`\n  either is local to the module or calls the core.\n- **Calls between kits** (`kx.call(\"ai.navigation\", \"plan\", args)`) go through the core's service registry: kit A →\n  core (`kithost.services@1`) → kit B (`kithost.kit@1` `call`). One path, the same for every kit, whoever wrote it.\n- **One mechanism, two paths.** A call is a synchronous call of the bridge (`gf_bridge`, path (b) of\n  module-calls.md): the arguments are copied into the target's memory, the answer copied back. The hot scalar reads\n  are direct links (path (a), a wasm-to-wasm call): today the input reads (`gf:kithost.input@^1` / `input_get`, the\n  action name resolved to a number once); the others follow (§7).\n- **Memories are separate.** A kit never sees the world's memory: what it reads is a copy (§4). A kit that traps is\n  left out (its hooks are logged as failed), the core and the other kits go on.\n- **Only the game's kits are loaded.** The page reads `kit-modules.json`, declares the core and the kits of the\n  game's lock, and loads those files only.\n- **The kit modules are the Rust logic, everywhere** (decided by the owner on 2026-10-12): `?logic=wasm`,\n  `?logic=kits` and `project.logic: 'wasm'` all mean the core and one module per kit of the game. No page, export\n  or deployment loads or ships a kit host with every kit in it (`gripforge_kithost_wasm.wasm`): that build only\n  remains as the **parity reference** of the tests, built in CI. Its speed (§6, §7) is no longer a criterion.\n- **A module is not supposed to be missing.** The page never switches to another logic in silence. The manifest\n  not served, the module of one of the game's kits absent from it, a file that does not arrive (network, HTTP\n  status) or is not the one the manifest names (size, hash), a module of a version the game's lock does not accept\n  (it must be `^` the locked version: same major, not older), a refusal at link (`… was compiled against …`): each\n  is an **error that names the kit, its version and the cause**, shown by the page as its loading error and\n  written to the console (`KitLogicUnavailable`, `apps/web/src/lib/gamekits/wasm-host.ts`). The loader's own\n  message keeps its form: `kit modules not loaded: <id>: <reason>; <id>: <reason>`.\n- **The TypeScript KitHost plays by itself in one documented case**: a game that installs a kit which really has\n  no Rust logic (`wasmLogicSupport`, `packages/gamekits/src/native.ts`: a kit absent from `rust-kits.generated.ts`)\n  runs wholly in TypeScript, and the console, the CLI and the MCP name the kit. `?logic=ts` (or\n  `project.logic: 'ts'`) is the explicit way to play the TypeScript logic.\n- **A game's kit modules can be merged into one wasm at export** (§8): an option, never the default — one file,\n  the smallest download.\n\n## 2. Contracts and versions\n\nThree levels, as in module-calls.md §10:\n\n1. the calls ABI (`gripforge:calls@1`), frozen, grows at the end;\n2. **the core interfaces** (`kithost.world@1.1.0` …) and **the kit interface** (`kithost.kit@1.0.0`), owned by\n   GripForge, each with a `.gfi` schema of stable function numbers;\n3. what kits serve each other (`ai.navigation` `plan`…): the kit's own API (docs: `grip-forge kit api <id>`),\n   carried by `kithost.services@1` / `kithost.kit@1` `call` as values.\n\nA kit module carries its contracts in its custom section `gripforge.calls`: `provides kithost.kit@1.0.0` and\n`consumes kithost.world@^1.0` … The host checks them at link time against what the core declares\n(`provides: ['kithost.world@1.0.0', …]` in the manifest): a kit compiled against `world@1.0` runs with a core that\nprovides `world@1.3` (rebuilt alone, nothing else recompiled); one compiled against `1.3` is refused cleanly by a\n`1.0` core. A minor version only **adds** functions with new numbers; nothing is renumbered, renamed, retyped or\nremoved within a major.\n\nFunction numbers are unique across the interfaces of the core (the bridge gives the callee a number, not an\ninterface): interface `n` owns `n << 8 ..= n << 8 | 0xff`.\n\n| # | Interface | What |\n|---|---|---|\n| 0 | `kithost.kit@1` | the hooks of a kit, called by the core: `info`, `services_for`, `validate`, `mount`, `drop`, `setup`, `ready`, `teardown`, `update`, `late_update`, `update_idle`, `on_event`, `on_timer`, `action`, `condition`, `spawn`, `call`, `save`, `load`, `scene_enter`, `scene_exit`, `component`, `on_var`, `callback`, `step_start`, `step_update`, `step_event`, `rng` |\n| 1 | `kithost.world@1` | entities, components, tags, transforms, spawn / destroy, references, positions, player scopes |\n| 2 | `kithost.state@1` | vars (define, get, set, inc, guard, bind), phase, snapshot |\n| 3 | `kithost.zones@1` | zones (add, remove, get, list, contains) |\n| 4 | `kithost.objectives@1` | missions and steps |\n| 5 | `kithost.physics@1` | the physics port (Rapier in the core): bodies, characters, rays, overlaps |\n| 6 | `kithost.services@1` | the kit's config, log, the bus (emit, on, off), timers, triggers (actions, conditions, rules), services (`has`, `call`, callbacks, `invoke`), spawn factories, decisions, deferred work, animations |\n| 7 | `kithost.input@1` | the input actions (pressed, just pressed, axes, devices, virtual input, capture, rebinding) |\n| 8 | `kithost.assets@1` | the asset port (bound slots, variants, urls, data files) |\n| 9 | `kithost.platform@1` | platform (clock, locale, target), save stores, audio, display, pointer |\n\nThe exact functions and their types: `native/gripforge-kitcall/interfaces/<name>.gfi`.\n\n**Encoding.** Parameters one after the other: scalars little-endian at their size, `bool` one byte, `string` a u32\nbyte count then UTF-8, `value` a tagged value (tags 0–7 of gripforge-wire v1: null, false, true, integer (zigzag\nLEB128), float (f64), string, array, object in order; an integer of the JSON model stays an integer and a float stays\na float, so `3` and `3.0` are not confused), `value?` a value or the byte `0xFF` (absent). No JSON text.\n\n**Every hook** starts with the context (48 bytes): `inst u32` (which host), `kit u32` (its slot), `tick u64`,\n`frame u64`, `elapsed f64`, `fixed_dt f64`, `services_gen u32`, `config_gen u32`. The clock is therefore read\nwithout a call; the two generations tell the module when what it cached changed.\n\n## 3. Writing a kit module in Rust\n\n**A kit of your own, outside GripForge** — built alone, added to a game without recompiling the core or the other\nkits: the step-by-step guide is [kit-third-party.md](kit-third-party.md) (`grip-forge docs kit-third-party`), with a\nworked example (`examples/kit-third-party`), the commands that declare such a kit in a game (`gripforge kit\nadd|verify|list|remove`, MCP `gripforge_third_party_kit_*`: source, SHA-256 and version frozen in the lock) and the tools\n`tools/kit-modules/add-kit.mjs` and `try-kit.mjs`. A game that declares one is played on the kit modules by itself\n(no `?logic=kits`), and the web export ships its module (`tools/web-export/build.mjs`).\n\nA kit is a `KitModule` (the trait of `native/gripforge-kithost/src/kit.rs`). The same file runs inside the single\nkit host and as its own module.\n\n```rust\n// src/kits/my_counter.rs — `my.counter`: counts the events of a topic into a var.\nuse crate::bus::GameEvent;\nuse crate::host::{KitModule, Kx};\nuse serde_json::{json, Value as Json};\nuse std::rc::Rc;\n\nstruct Counter;\nstruct State { seen: u32 }\n\nimpl KitModule for Counter {\n    fn id(&self) -> &'static str { \"my.counter\" }\n    fn services(&self) -> &'static [&'static str] { &[\"my.counter\"] }\n    fn setup(&self, kx: &mut Kx) {\n        kx.put(State { seen: 0 });                       // local to the module: no call\n        let topic = kx.config()[\"topic\"].as_str().unwrap_or(\"enemy.killed\").to_string();\n        kx.define_var(\"my.count\", \"number\", \"Count\", None, Some(json!(0))); // kithost.services@1\n        kx.on(&topic, \"count\");                          // kithost.services@1 (bus)\n    }\n    fn on_event(&self, kx: &mut Kx, _tag: &str, _ev: &GameEvent) {\n        kx.data::<State>().seen += 1;\n        let n = kx.data::<State>().seen;\n        kx.set_num(\"my.count\", n as f64);                // one call\n    }\n    fn call(&self, kx: &mut Kx, _cap: &str, method: &str, _args: &[Json]) -> Result<Json, String> {\n        match method {\n            \"count\" => Ok(json!(kx.data::<State>().seen)),\n            _ => Err(format!(\"my.counter has no {method}\")),\n        }\n    }\n}\n\npub fn module() -> Rc<dyn KitModule> { Rc::new(Counter) }\n```\n\nAs its own module, a crate whose root gives the kit the paths of the kit host and exports it:\n\n```toml\n# Cargo.toml\n[package]\nname = \"kit-my-counter\"\nversion = \"1.0.0\"\nedition = \"2021\"\n[lib]\ncrate-type = [\"cdylib\"]\n[dependencies]\ngripforge-kit-guest = { path = \"<gripforge>/native/gripforge-kit-guest\" }\nserde_json = { version = \"1\", features = [\"preserve_order\", \"float_roundtrip\"] }\n```\n\n```rust\n// src/lib.rs\npub use gripforge_kit_guest::{bus, cfg, entities, expr, host, js, kit, objectives, ports, rng, schema, shared,\n    state, timers, triggers, wire, zones};\npub mod kits { pub mod my_counter; }                     // the kit file(s)\ngripforge_kit_guest::export_kit!(kits::my_counter::module, \"1.0.0\");\n```\n\n`cargo build --release --target wasm32-unknown-unknown` gives `kit_my_counter.wasm`. `export_kit!` writes the\nexports of the calls contract (`gf_alloc`, `gf_on_bridge`, `gf_calls_init`…), the hooks of `kithost.kit@1`, and the\ncontracts section. The kits of GripForge are built this way by `tools/kit-modules/build.mjs` (it generates one such\ncrate per file of `src/kits`, builds them in one cargo run, hashes them and writes the manifest).\n\n**Declaring it in a game.** The manifest the page reads (`kit-modules.json`):\n\n```json\n{ \"schema\": \"gripforge.kit-modules/1\", \"contract\": \"kithost.kit@1.0.0\",\n  \"core\": { \"name\": \"kithost.core\", \"version\": \"1.0.0\", \"wasm\": \"kithost.core.<hash>.wasm\",\n            \"provides\": [\"kithost.world@1.0.0\", \"…\"] },\n  \"kits\": { \"my.counter\": { \"version\": \"1.0.0\", \"wasm\": \"kit.my.counter.<hash>.wasm\", \"bytes\": 81234, \"hash\": \"<hash>\" } } }\n```\n\nThe kit is mounted when the game's lock lists it (`lock.order`, `installed`), like any kit; its config comes from\nthe project. A third-party kit is loaded only if the game declares it (`project.thirdPartyKits`: source, SHA-256,\nmanifest; `gripforge kit add`, [kit-third-party.md](kit-third-party.md) §3).\n\n### What is local, what is a call\n\n| In the kit | Cost |\n|---|---|\n| `kx.kit_id()`, `kx.config()`, `kx.project()`, `kx.data_collection()`, `kx.rng()`, `kx.put()` / `kx.data()` / `kx.host_state()`, `kx.elapsed()`, `kx.tick()`, `kx.frame()`, `kx.dt()` | local (the config is read again only when the core says it changed; the rng is forked by the core at mount, then the module's) |\n| `kx.host.has_service(cap)` | one call per capability per change of the service table, then local |\n| `kx.input().pressed(a)`, `just_pressed`, `released`, `axis`, `axis_over`, `presses` | a direct link (wasm to wasm) |\n| `entities.has(id)`, `entities.transform(id)`, `entities.component(id, name)` when it is absent or a scalar, `acting_player()`, `player_scopes.push` / `pop`, `set_anim`, `get_var(path)` when it is absent or a scalar, `state.phase`, `set_var` / `set_num` of a number, a boolean, null or a short string, `has_service` | a direct link (§7.1): no string crosses, nothing is copied |\n| `kx.call(capability, method, args)` to a capability another kit module serves | two calls (kit → core → kit); the core relays the bytes without decoding them |\n| reads that return a reference: `entities.get(id)`, `entities.component(id, name)`, `get_var(path)`, `entities.all()`, `query(q)` … | one call, the copy kept in the module until the next hook (a reference stays valid as long as Rust lets you hold it) |\n| `entities.get_mut(id)` | one call to read; the entity is written back when the guard is dropped |\n| every other method (`emit`, `set_var`, `spawn`, `physics().raycast(…)`, `input().just_pressed(…)` …) | one call |\n\nA bridge call costs about 1 µs plus the encoding and decoding of its values (§6: a whole entity is several\nmicroseconds). Prefer what the API already batches (one `query` rather than many `get`), read a component rather\nthan the entity, keep in `kx.data` what you derive, and read a value once per hook. `input().pressed(…)` and the\nother input reads are direct links: a few nanoseconds.\n\n**Per-tick hooks.** `export_kit!(module, version, hooks)` takes the mask of the per-tick hooks the kit implements\n(1 `update`, 2 `late_update`, 4 `update_idle`): the core does not call the others. Without it every hook is called.\n`tools/kit-modules/build.mjs` reads it from the kit's files (`fn update(` …).\n\n### Re-entrance\n\nA kit may call the core, which may call another kit, which may call the core again, or even call back the first\nkit (a callback, a service it serves): the core and the kit modules are declared `reentrant`, the calls host allows\nthese nested synchronous calls for them. A hook runs to its end before its caller goes on, as in the single kit host.\nRust's borrow rules already forbid holding a reference read from the world across a call that could change it.\n\n## 4. What the façade guarantees\n\n- **Same behaviour** as the kit compiled inside the single kit host: the parity fixtures\n  (`native/gripforge-kithost/tests/fixtures`, written from the TypeScript kit host) are replayed on the kit modules\n  by `qa/kithost-wasm-parity-check.mjs --kit-modules <dir>` with the same rules.\n- **Copies, not shared memory.** What a kit reads is a copy made at the call; nothing of the world lives in the\n  kit's memory between two hooks (the cache is dropped at every entry).\n- **game.engine stays in the core**: it is the engine contract the host applies itself (mods before mount, scenes,\n  the components of the other kits, reactions that edit their config).\n\n## 5. Building and loading\n\n```\nnode tools/kit-modules/build.mjs --out <dir> [--kits fx_hit_flash,ui_menu] [--jobs 3]\n```\n\nbuilds the core and the kit modules (opt-level s, whole-program LTO), each named with its content hash (`kit.<id>.<hash>.wasm`): a kit rebuilt\nalone changes only its own file and its line of the manifest.\n\nIn the page (what `loadWasmLogic` of `apps/web/src/lib/gamekits/wasm-host.ts` does for every game in Rust logic,\nwith a `fetch` that checks each file against the manifest):\n\n```js\nimport { loadKitHostWasm } from './kithost-wasm.mjs';\nconst logic = await loadKitHostWasm(null, { kitModules: { manifest: 'kit-modules/kit-modules.json', kits: lock.order } });\nconst host = logic.create({ project, lock, seed });   // the same host API whatever the delivery\n```\n\n`loadKitHostWasm(bytes)` — one wasm given as bytes — remains for the parity tests (the kit host with every kit in\nit) and for a merged module (§8); nothing in the page gives it a file of its own.\n\n**The web export** (`tools/web-export/build.mjs`) ships, beside the player, the loader and its files\n(`kithost-wasm.mjs`, `wire.mjs`, `module-calls.mjs`, `kit-events.mjs`, `game-schema*.mjs`) and `kit-modules/`: a\nmanifest of the game's own, the core and one wasm per kit of the game. The modules come from `GF_KIT_MODULES=<dir>`\n(the folder the command above wrote), else from `kit-modules/` of the player package. Without them, or when a kit\nof the game has no module there (or one of a version its lock refuses), **the export fails** and names the kits and\nthe command to build them; a game in TypeScript logic (`\"logic\": \"ts\"`, or a kit without a Rust port) is exported\nwithout them. Tests: `node --test tools/web-export/logic-files.test.mjs`.\n\n`logic.calls` is the calls host (`trace()`, `stats`), `logic.counts(reset)` the calls per interface.\n\n## 6. Measurements (2026-10-12, the dungeon: 36 kits + game.engine)\n\nSame Rust source on both sides; the single wasm is `gripforge_kithost_wasm.wasm` (every kit inside).\n\n**Parity.** `qa/kithost-wasm-parity-check.mjs`: single wasm 721 identical, kit modules 721 identical (4 fixtures on\nRapier apart and 139 that need the native test kits on both sides, 0 differ). After 1 800 frames of the bench the\ntwo end in the same state (hero at the same position bit for bit, 149 / 149 vars equal).\n\n**Logic per frame** — Node (`qa/kithost-wasm-bench.mjs --sides wasm,kits`, 1 800 frames, main machine, load ≈ 4):\n\n| step | `step` ms / frame | bridge calls / frame | direct calls / frame |\n|---|---|---|---|\n| single wasm | 0.44 – 0.52 | — | — |\n| kit modules, first version | 2.64 | 259 | 0 |\n| + per-tick hook mask (the core skips `update` / `late_update` / `update_idle` a kit does not implement) | 2.29 | 216 | 0 |\n| + input reads by direct link (`gf:kithost.input@^1` `input_get`, interned action numbers) | 2.25 | 184 | 57 |\n| + kit modules at opt-level s, whole-program LTO | 1.70 – 1.90 | 184 | 57 |\n\nBridge calls per frame by interface (last line): hooks `kithost.kit` 55, `world` 63, `services` 26, `state` 23,\n`input` 12, `physics` 3, `platform` 1. The frame the page reads (`gf_frame`) costs the same on both (0.24 – 0.30 ms).\n\n**In the page** — the dungeon export under the Bevy player, Chrome on the NVIDIA RTX A500 of the second machine\n(`qa/export-fps-check.mjs`, WebGPU, 20 s, machine load 0.2 – 2.2 noted at each run, two runs each):\n\n| | frames / s | p95 frame | logic `step` ms / frame | page part ms / frame |\n|---|---|---|---|---|\n| single wasm (`?logic=wasm`) | 59.8 | 16.7 ms | 1.21 – 1.23 | 0.35 – 0.36 |\n| kit modules (`?logic=kits`) | 59.7 | 16.7 – 16.8 ms | 2.69 – 2.70 | 0.29 |\n\nBoth hold the display rate; the kit modules cost 1.5 ms more logic per frame (×2.2). Calls per frame in the page:\nhooks 109, `world` 64, `services` 48, `state` 25, `input` 12, `platform` 4, `physics` 4, direct 57 (the page has\nmore events per frame than the bench: pointer, HUD).\n\n**Download for this game.**\n\n| | files | bytes | gzip -9 |\n|---|---|---|---|\n| single wasm | 1 | 20.7 MB | 5.84 MB |\n| core + 36 kits, opt-level 3 / thin LTO (first version) | 37 | 21.4 MB | 6.88 MB |\n| core + 36 kits, opt-level s / whole-program LTO | 37 | 14.3 MB | 5.12 MB |\n\nThe 160 kit modules: 41.7 MB in all (16.4 MB gzip), median 231 KB, from 97 KB (`fps.network`) to 695 KB\n(`fps.tactical`); the core 4.4 MB (1.2 MB gzip). They were 70.2 MB (23.1 MB gzip) at opt-level 3 / thin LTO. Every\nkit module carries its own copy of the value model (`serde_json::Value`, which the kit sources use everywhere), the\nallocator and the façade: about 100 KB of floor.\n\n**Which kits cost** (calls to the core per frame in the bench, before the direct input reads):\n\n| kit | hooks / frame | calls to the core / frame | bytes copied / frame |\n|---|---|---|---|\n| `character.top_down` | 2 | 39 | 2 722 |\n| `combat.core` | 10 | 22 | 2 004 |\n| `input.scheme` | 3 | 21 | 3 748 |\n| `coop.session` | 1 | 18 | 1 498 |\n| `input.actions` | 11 | 15 | 1 198 |\n| `economy.money` | 1 | 12 | 2 344 |\n| `weapons.loadout` | 1 | 11 | 1 017 |\n| the 29 others | 1 – 4 each | 0 – 6 each | < 2 000 each |\n\n**Where the time goes** (CPU profile of the bench, names kept, per frame): kit modules 1.07 ms — allocator 0.17,\ndecoding values (`Reader::value`, keys, UTF-8, the maps of `serde_json`) 0.25, hashing 0.07, the entry of a hook\n0.06, the rest the kits' own code; core 1.15 ms — of which the frame 0.26, input lookups 0.16, encoding entities and\nvalues 0.15, allocator 0.12, queries 0.09; JavaScript of the calls host 0.19 ms. The bridge itself is not the cost:\nthe copies of values are (whole entities read to test one field, the 1.4 KB of input specs read 4 times per frame),\nand the 55 hooks per frame.\n\nThese figures were why the kit modules started as an option. They no longer decide anything: since 2026-10-12 the\nkit modules are the only Rust logic a page plays (§1), and the single wasm of this section is only the reference\nthe measurements and the parity checks compare to.\n\n## 7. The shared zone, the direct links and what they measure\n\nThe plan decided by the owner on 2026-10-12 — the five steps below — is built (§7.1 – §7.8). Since then the kit\nmodules are **the** logic of GripForge (§1): the ratio to the single kit host wasm is no longer a condition of\nanything, it is how the cost of the cut is followed.\n\n**Measured**, the dungeon (36 kits), `qa/kithost-wasm-bench.mjs --interleave` on the second machine, 5 runs of\n1 800 frames: the ratio of `step` to the single wasm's played in the same process, the median run and the range.\n\n| | kit modules / single wasm | merged / single wasm | bridge calls / frame | hooks / frame |\n|---|---|---|---|---|\n| master `6a3b2ef66`, before the plan | × 3.56 (3.53 – 3.64) | × 3.09 | 184 | 55 |\n| steps 1 and 2: direct links for the simple accesses, names as numbers (§7.1) | × 3.54 (3.52 – 3.72) | × 3.12 | 137 | 55 |\n| + kit → kit service calls relayed by the core | × 3.41 (3.28 – 3.51) | — | 137 | 55 |\n| step 3 alone: inputs and state read in the zone (§7.4) | × 3.08 (2.95 – 3.11) | × 2.63 | 125 | 55 |\n| step 4 alone: entity copies kept by revision (§7.5) | × 2.63 (2.60 – 2.74) | × 2.29 | 114 | 55 |\n| step 5 alone: the event queue (§7.6; the bench has 0.17 event per frame) | × 3.39 (3.38 – 3.48) | × 3.01 | 137 | 55 |\n| **the five steps together** (master `38267fa10`) | **× 2.31** (2.27 – 2.37) | **× 1.97** (1.92 – 2.00) | 102 | 55 |\n| + kit → kit service calls by direct link (§7.7) | × 2.32 (2.22 – 2.32) | × 1.98 | 50 | 29 |\n| + kit modules built at opt-level 3 instead of s (a trial: §6, the hot kits) | × 2.06 (1.99 – 2.47) | — | 50 | 29 |\n\nIn absolute terms the best run of a session gives 0.38 – 0.48 ms for the single wasm and 0.75 – 1.10 ms for the kit\nmodules, depending on the minute (the machines of the day change speed with their load: only ratios of one run\ncompare).\n\n**What the measures say.** The plan expected 1.05 ms of gain from the number of calls and the size of what they\ncopy. Cutting the calls by four (184 → 50 by the bridge) and the hooks by two gave a third of that, and two steps\ngave nothing at all: the transport is not the cost. A profile on a calm machine (load 0.4) puts a frame at 506 µs\nin the kits, 431 µs in the core and 100 µs in JavaScript, and **in the single wasm the kits' own code is under\n25 µs per frame**: everything a kit module burns is the façade — and it is spread thin, no function of a kit\nweighs more than 4 µs: allocations (about a quarter), clones and drops of `serde_json::Value` and their maps, the\ndecoding of values, the entry of a hook. That is the work that goes on: values borrowed instead of cloned, configs\ndecoded once, an allocator by size classes, hooks entered without JavaScript, kits not woken when they have nothing\nto do.\n\nThe plan as it was written, for the record:\n\n| # | Step | What | Expected gain | Measured |\n|---|---|---|---|---|\n| 1 | Numeric ids | names resolved to numbers once; no string crosses on the hot path | 0.10 ms | none (§7.1) |\n| 2 | Direct links for simple accesses | `world`, `state`, `services` as wasm-to-wasm calls | 0.15 ms | none (§7.1) |\n| 3 | Published inputs and state | read in the zone without a call | 0.15 ms | × 3.54 → × 3.08 (§7.4) |\n| 4 | Hot components, batches | entity copies kept by revision, deltas, static query lists, typed accesses | 0.40 ms | × 3.41 → × 2.63 (§7.5) |\n| 5 | Event queue | events written once in the zone, a kit woken once for consecutive deliveries | 0.25 ms | none in the bench, − 7 % at 50 events per frame (§7.6) |\n\nRules to keep, written here so the next lot starts from them:\n\n- **Order of events = the bus of today** (`native/gripforge-kithost/src/bus.rs`, `Host::flush`): events are queued\n  in emission order (`seq`), delivered at the flush of the tick by rounds, handlers by priority then subscription\n  order, events emitted during a round go to the next round. The ring must give exactly that order (publication\n  order within the tick, delivery at the next round), or the parity fixtures differ. An unknown type or an\n  incompatible version is a clear error at link time. The tracer shows events too: emitter, type, size, subscribers.\n- **Fixed layout only for declared types.** A component without a declared layout stays a value read by a call.\n- **Without multi-memory** (every Rust module today: module-calls.md §2) a kit cannot map the zone: it reaches it\n  through the generated accessors below (direct links apart, inlined loads and stores when merged).\n- **The zone grows** (offsets stay valid, views are made again: module-calls.md §6).\n- **A kit on a Worker** reads a snapshot per frame and posts its writes (no write in place across threads).\n- **The kit source.** The kits use `serde_json::Value` as their value type everywhere (configs, components,\n  payloads); nothing of the calls is JSON text (the codec is binary), but the type stays in every kit module until\n  the kits are ported to typed components — a change of the kit sources, kit by kit, with the parity.\n\n### 7.1 Built: direct links for the simple accesses, names as numbers (steps 1 and 2)\n\n`kithost.world`, `kithost.state` and `kithost.services` are at **1.1**: functions added at the end, nothing\nrenumbered (a kit built against 1.0 runs unchanged, by the bridge). The kit side is\n`native/gripforge-kit-guest/src/direct.rs`, the core side `native/gripforge-kithost/src/kitcall/direct.rs`, the\nexports `gfx_*` in `native/gripforge-kithost-wasm/src/kitmods.rs`, the schemas the `direct` lines of the `.gfi` files.\n\n| Import (`gf:kithost.<interface>@^1.1`) | What | Replaces the bridge call |\n|---|---|---|\n| world `w_has(id)` | is there such an entity | `has` |\n| world `w_transform(id)` | 1 and x, y, z, yaw in the registers | `transform` |\n| world `w_component(id, component)` | the kind of the component; a scalar in the registers | `component`, when absent or a scalar |\n| world `w_acting_player()`, `w_scope_push(id)`, `w_scope_pop()` | the co-op player scopes | `acting_player`, `scope_push`, `scope_pop` |\n| world `w_set_anim(id, clip)` | the looping clip of an entity | `set_anim` |\n| state `st_get(path)`, `st_phase()` | the kind of the var / the phase; the scalar in the registers | `get` when absent or a scalar, `phase` |\n| state `st_set_f64`, `st_set_i64`, `st_set_flag`, `st_set_str` `(path, …)` | the same `set_var` (guard, bindings) for a float, an integer, a boolean or null, a short string | `set_var` of a scalar |\n| services `sv_has(capability)` | is the capability served | `has_service` |\n| services `reg_f64(i)`, `reg_u64(i)` | register `i` of the last direct answer | — |\n\n**No string crosses on these calls**, and nothing is allocated or copied on either side:\n\n- **Atoms.** A name of the game's vocabulary — a component, a var path, a capability, a clip — is a number the core\n  gives once (`kithost.services` `atom`, one bridge call per name and module at its first use) and both sides keep\n  for the life of the process. The input actions were already numbers (`kithost.input` `intern`).\n- **Packed ids.** An entity id travels in two `u64` (its bytes, zero padded: ids are `e<number>`, 16 bytes cover\n  them). Entity ids are not atoms on purpose: a game spawns them without end, a table of them would only grow.\n  An id that does not fit takes the bridge.\n- **Kinds and registers.** A read answers a kind — 0 absent, 1 null, 2 false, 3 true, 4 integer, 5 float, 6 other,\n  7 a string of at most 16 bytes — and the scalar is read from the core's registers by `reg_f64` / `reg_u64`\n  (an integer stays an integer and a float a float, as in the codec). Kind 6 (an object, an array, a long string):\n  the façade makes the bridge call of 1.0, which answers the same value.\n\nA direct link is a transport: each one runs, on the kit that runs, the very method the bridge function runs\n(`set_var` through a direct link still goes through the guard of another kit and tells the bindings). The façade\nfalls back to the bridge whenever the link cannot carry the call, so the two paths are interchangeable, and the\nparity fixtures replay both.\n\n**Kit → kit service calls are relayed.** `kx.call(\"combat.health\", \"health\", [id])` is two calls, kit → core\n(`kithost.services` `call`) → kit (`kithost.kit` `call`), and both carry the same bytes (`capability, method,\nvalues`). When the provider is a kit module the core now forwards the bytes as they came and the answer as it is\n(`kitcall::relay_call`): it decodes and encodes nothing, and runs the provider through the same `with_kit` as\nbefore (bindings drained before and after).\n\n**What is still a string on the hot path**, and why: the registries of the core (entities by id, vars by path,\ncomponents by name) are keyed by strings, as in the single kit host, which pays the same lookups; an atom saves the\ncrossing, the copy and the allocation, not the core's own hash. Keying the core by numbers is a change of the kit\nhost itself (both builds), not of the calls.\n\n**Measured** (the dungeon). The machines of the day change speed from one minute to the next (load, frequency), so\nthe bench has a mode that holds on them: `--interleave` plays frame *f* of every side before frame *f + 1*, and the\nfigure to read is the **ratio of `step` to the single wasm's in the same process** (5 runs of 1 800 frames on the\nsecond machine, load 3.5 – 4.9; the median run, and the range of the runs):\n\n| | `step` / single wasm | merged / single wasm | bridge calls / frame | direct calls / frame |\n|---|---|---|---|---|\n| kit modules, master `6a3b2ef66` | × 3.56 (3.51 – 3.71) | × 3.09 (3.05 – 3.14) | 184 | 57 |\n| + direct links and atoms (steps 1 and 2) | × 3.54 (3.52 – 3.72) | × 3.12 (3.04 – 3.18) | 137 | 116 |\n| + kit → kit service calls relayed | × 3.41 (3.28 – 3.51) | — | 137 | 116 |\n\n(Interleaving costs both sides their warm caches: the ratios are higher than those of §6 and §8, measured one side\nafter the other. In absolute terms the best run gave 0.39 – 0.61 ms for the single wasm and 1.33 – 2.16 ms for the\nkit modules, depending on the minute.)\n\n**Steps 1 and 2 gain nothing that can be measured** (0.5 %, inside the ± 3 % of the runs), where the plan expected\n0.25 ms: 47 bridge calls per frame became direct calls (`world` 63 → 39, `state` 23 → 0), but they were the cheap\nones — a `has`, a scalar `get`, a `set_var`, 1.5 – 2.5 µs each in the trace, with almost nothing to encode. The\nrelay of the service calls gains 4 %. What weighs is elsewhere, and the CPU profile of this build says where (rough\nshares of the wasm time of a frame, taken on a loaded machine): the allocator 25 %, decoding values 15 %\n(`Reader::value`, keys, UTF-8), the maps of JSON objects 10 %, SipHash of the façade's caches 10 %,\n`Query::matches` 7 % (`first(tag player)` asked ten times per frame scans every entity), the JavaScript of the bridge\n5 %. That is the whole player entity (365 bytes) read 19 times per frame, the input specs (1.4 KB) 4 times, and 26\nservice calls with their two hook entries (an empty hook costs 2 – 4 µs) — the matter of steps 3 to 5.\n\nThe bench prints the calls by function (`--fns`: `gf_kits_fn_counts`, direct links from `0x1000`), the median `step`\n(the mean takes every preemption of a loaded machine) and, with `--interleave`, the ratios.\n\n### 7.2 One memory for every module? (the evaluation of 2026-10-12; built since for the trusted kits: §9)\n\n> **Since then** variant (a) below was built for GripForge's own, trusted kits — §9 « Common memory ». The recipe\n> works on stable Rust 1.97.1 (`-Z build-std` through `RUSTC_BOOTSTRAP`, no Emscripten ABI needed: the host reads\n> `dylink.0` itself). What the table says it costs still holds — no isolation, one compiler for both sides — which is\n> why it is a mode **per kit**, never for a third-party kit. The zone of §7.3 is kept: it is what a kit in its own\n> memory, a Worker and a third party read.\n\nThe owner's question: would **one linear memory imported by the core and every kit as its memory 0** lift the\n\"Rust sees one memory\" limit and give reads and writes of the world in place? Evaluated on paper on 2026-10-12, with\nthe toolchain checked (Rust 1.97, its `rust-lld`: `--import-memory`, `--global-base`, `--no-stack-first`,\n`--experimental-pic`, `--emit-relocs` are all there). The decision that followed: the shared zone stays **plain\nbuffers with a fixed layout and generated accessors** — each module keeps its memory and its allocator.\n\n| Variant | Feasible today | What it would give | What it breaks |\n|---|---|---|---|\n| (a) Position-independent kits (`-C relocation-model=pic`, `dylink.0`, `__memory_base` / `__table_base`, one allocator exported by the core) | Not on stable: `wasm32-unknown-unknown` ships a non-PIC `std`, so it needs nightly `-Z build-std` and the Emscripten dynamic-linking ABI, which Rust does not target there | the single wasm's speed (references instead of copies) with one file per kit | isolation (a kit writes anywhere), and the contract: sharing Rust values needs the same compiler and the same crate versions on both sides |\n| (b) Link at export from relocatable objects (`wasm-ld`) | Yes (it is how the single wasm is built); §8 \"link, not merge\" | the single wasm's speed and size, with only the game's kits | no binary contract for third parties (Rust objects link only with the same compiler and the same build of the core): a kit is rebuilt for each release |\n| (c) One memory cut in regions, each kit linked at its own base (`--import-memory --global-base=N --no-stack-first`; `dlmalloc` takes its heap with `memory.grow`, which works on a shared memory) | Yes for GripForge's own kits (the build gives the bases); a third-party kit needs its base at **its** build, so a registry of bases, or `--emit-relocs` and a rebase tool at export | by itself nothing: the calls still encode and decode. The gain only comes with pointers passed across (strings, then whole values), i.e. with the layout of Rust types shared between two builds | isolation; any pointer passed is a contract on a layout Rust does not promise (`String`, `Vec`, `serde_json::Value`) unless every shared structure is `repr(C)` — which is the fixed-layout zone again, without the copies |\n\nIn short: the copies are not the cost (§8: merging removes them from JavaScript and gains 5 – 12 %), the encoding,\ndecoding and allocation of `serde_json::Value` are. One memory removes them only if the kits read the core's Rust\nvalues in place, which ties every kit to the core's compiler and crate versions and gives up the isolation between\nmodules. Fixed-layout buffers keep both, and cost one accessor call per read.\n### 7.3 Built: the zone (the base of steps 3 – 5)\n\n**One zone, fixed buffers.** The zone is one block cut into buffers whose places are fixed **for the play**: the\ngame schema gives the sizes and the offsets ([game-schema.md](game-schema.md), `zone`), the core lays the zone out\nfrom it before the game starts (`gf_schema_init`). 4 MiB at start by default; when the last buffer (`regions`) is\nfull the zone doubles, up to the ceiling of the schema: **offsets never move**, only the size in the directory\nchanges (the address in the core's memory may move: nothing keeps it). The table below is the layout without a\nschema (the defaults). Every\nmodule keeps its own memory and its own allocator. It lives in the core's memory, so\nthe core reads and writes it in place. A kit never sees an address, only **offsets in the zone**. The layout in bytes\nis the contract `native/gripforge-kitcall/src/zone.rs` (documented there field by field):\n\n| at | what |\n|---|---|\n| `0x000000` | directory, 256 bytes: `GFZ1` u32, layout version u32 (`major << 16 \\| minor`, 1.0), size u32, count u32, then per buffer `id u32, offset u32, size u32, 0 u32` |\n| `0x000100` | buffer 1 `INPUT` (`0x2f00` bytes): `rev u32, spec_rev u32, glob_rev u32, capacity u32`, 16 reserved bytes, then 256 records of 32 bytes, one per interned action: `rev u32, flags u32 (1 pressed, 2 just pressed, 4 released), presses u32, 0 u32, axis_over(a, 0) f64, axis_over(a, +inf) f64` |\n| `0x003000` | buffer 2 `STATE` (`0x1000` bytes): `rev u32` (the revision of the vars and the phase) |\n| `0x004000` | buffer 3 `EVENTS` (`0x3c000` bytes): the event queue (step 5) |\n| `0x040000` | buffer 4 `WORLD` (`0xc0000` bytes): the hot arrays of the world (step 4) |\n| `0x100000` | buffer 5 `REGIONS` (to the end of the zone): `used u32` then blocks given on demand — `zone_region(len)` (8-byte aligned, zeroed), given back with `zone_region_free(offset)`; `zone_tick_region(len)` gives a block that lives until the next tick (an arena the core empties when the tick changes). The allocator's records are in the core, not in the zone |\n\nA reader finds a buffer by its id in the directory once at load (`zone::buffers()`); a later layout may move or grow a\nbuffer without breaking a module built today.\n\n**The accessors of a kit** (`native/gripforge-kit-guest/src/zone.rs`, interface `kithost.zone@1`, direct links only):\n`zone_read_u8 / u16 / u32 / u64 / f32 / f64(offset)`, `zone_write_…(offset, value)`, `zone_copy(offset, &mut [u8])`\n(zone → module), `zone_copy_in(offset, &[u8])` (module → zone), `zone_region(len)`, `zone_region_free(offset)`,\n`zone_tick_region(len)`. Out of bounds a read answers 0, a\nwrite does nothing, a copy answers false: a kit cannot reach the rest of the core's memory through them.\n\nA Rust module cannot name a second memory, so the same imports (`gf:kithost.zone@^1` / `zone_read_u32` …) are wired\ntwo ways:\n\n- **kit modules loaded apart**: direct links to the core's exports `gfx_zone_*`\n  (`native/gripforge-kithost-wasm/src/kitmods_zone.rs`), a wasm-to-wasm call each; the two copies are made by the\n  calls host, which sees both memories (`ModuleCallHost.zoneCopy`, with the core's `gfx_zone_base` / `gfx_zone_size`);\n- **merged at export** (§8): `merge.mjs` generates them as glue — a bounds test and a `load` / `store` in the core's\n  memory at the zone's base, a `memory.copy` between the two memories for the copies — which `wasm-opt` inlines in the\n  kits: a read of the zone is then a load.\n\nThe core's side is `native/gripforge-kithost/src/kitcall/zone.rs` (`read_*`, `write_*`, `copy_in`, `copy_out`,\n`region`, in place).\n\n### 7.4 Built: inputs and state read in the zone (step 3)\n\nThe inputs are not constant during a frame (a kit captures them, sets the gate, a tick latches them), so a blind copy\nonce per frame would break the parity. They are published **by revision** instead:\n\n- the core's `InputActions` and `GameState` carry revisions (numbers never reused, unique across the hosts of a\n  core): `rev` (what an action reads), `spec_rev` (specs, sticks, owners), `glob_rev` (device, capture, gate, list of\n  actions), and the state's `rev` (vars and phase). They are written in the zone at every write and at every entry of\n  a kit module (the zone then speaks of the host that runs). `tick_begin` changes `rev` only when an action really\n  changed: with a key held, the records stay valid from one frame to the next;\n- **an action** is a 32-byte record of the `INPUT` buffer. The first read under a revision asks the core to fill it\n  (`in_fill(action)`, one direct call for the six reads: pressed, just pressed, released, presses, the two axis\n  reads); every later read by any kit is a read of the zone. In the dungeon the kits make 57 input reads per frame;\n- **specs, sticks and globals** (`specs()` is 1.4 KB, asked 4 times per frame by 3 kits): each kit keeps what it\n  decoded while `spec_rev` / `glob_rev` hold — no call and no decoding until the bindings, the device, the capture or\n  the gate change. When they do, the first kit asks the core, which also writes the answer in the zone (a block of\n  `REGIONS` named in the lists of the `INPUT` buffer); the other kits copy it out (`zone_copy`);\n- **the state**: the copies of vars a kit read live from one entry to the next while the state's `rev` holds (before,\n  they were dropped at every entry). Scalars are read by direct links (step 2).\n\nNothing changes in the kit sources: `kx.input()` and `host.state` of the façade read the zone\n(`native/gripforge-kit-guest/src/ports/input.rs`, `src/state.rs`).\n\n**Measured** (the dungeon, Node bench on the second machine, candidates interleaved, 5 runs of 1 800 frames; `step`\nagainst the single wasm played frame by frame in the same process):\n\n| | calls per frame (bridge + direct) | kit modules / single wasm | merged / single wasm |\n|---|---|---|---|\n| master | 184 + 57 | ×3.55 (3.41 – 3.61) | ×3.09 (2.96 – 3.16) |\n| steps 1 and 2 | 137 + 117 | ×3.54 (3.42 – 3.65) | ×3.12 (3.03 – 3.16) |\n| + the zone and step 3 | 125 + 60 | ×3.08 (2.95 – 3.11) | ×2.63 (2.57 – 2.66) |\n\nBest run: 1.59 → 1.39 ms per frame for the kit modules, 1.41 → 1.21 ms merged (single wasm 0.47): 0.20 ms per frame.\nThe 12 `kithost.input` bridge calls per frame are gone (specs 4, globals 6, sticks 2) and the 57 direct input reads\nbecame 0.5 `in_fill` per frame plus reads of the zone. Same final state in every mode. Parity: kit modules apart and\nthe dungeon merged, 0 differ.\n\n### 7.5 Built: entity copies kept by revision (step 4)\n\nWhat costs in step 4 is the same entity read again and again (the dungeon's player, 365 bytes, 19 times per frame):\nevery write and every entry of a hook dropped what the module had read. The copies are now **kept from one hook to\nthe next** and the core sends **only what changed**.\n\n- **The core** gives every entity a revision and the world an epoch (`native/gripforge-kithost/src/entities.rs`,\n  `Rev`): values of one clock, moved by every change — `set` and `set_transform` mark one component, `tag` /\n  `untag` the tags, `get_mut` (anything may change) the whole entity, creating, destroying and loading the list.\n  All changes go through the methods of `Entities`, so none is missed.\n- **A kit module** keeps the entities it read with their revision (`native/gripforge-kit-guest/src/hot.rs`,\n  `entities.rs`). Each read first reads the world's epoch by a **direct link** (`gf:kithost.world@^1` /\n  `hot_epoch`, a wasm-to-wasm call). Same epoch as when the copy was checked: the copy is the entity, **no call**.\n  The epoch moved: one call tells the core the revision held and gets a **delta** — unchanged (1 byte), the\n  components changed since (their values only), or the whole entity (first read, or after a `get_mut` of the core).\n- **Queries** (`first`, `query`, `by_tag`, `player`): the answer is kept for the epoch; at a new epoch one call\n  (`first_if`, `query_if`) carries the ids and revisions of the last answer as hints and returns one delta per\n  entity, in the order of the world: \"every entity with this tag\" in one call, nothing encoded for what the module\n  has.\n- **`get_mut`** copies the kept entity; when the guard drops, what differs is written back as changes (`patch`: the\n  components set, the tags), nothing when nothing differs, the whole entity (`put`) when a list of changes cannot\n  say it (a component removed, the kind, the owner or the references changed). When the core answers that nothing\n  else changed in the world meanwhile, the module's copies stay current: no read after the write.\n- **Same behaviour**: the order of a query is the world's; a write reaches the core at once, as before, and the\n  next read sees it (the epoch moved). A component alone (`component(id, name)` of an entity the module does not\n  hold), `has` and `transform` are kept for the epoch they were read at.\n- **Memory safety**: nothing a kit holds a reference to is freed or changed from a `&self` method — a copy that\n  must change while it may be referenced is replaced, the old one freed at the next `&mut self` (a write, an entry).\n- **Contract**: `kithost.world@1` functions `0x80`–`0x84` (`get_if`, `first_if`, `query_if`, `patch`, `epoch`;\n  `native/gripforge-kitcall/src/fns_hot.rs`, `interfaces/world.gfi`) and the direct link `hot_epoch`: a minor of\n  `kithost.world`. The functions of 1.0 are unchanged (a kit built against 1.0 keeps running).\n\nMeasured on the dungeon (Node bench, 1 800 frames, same machine and load for both): `kithost.world` bridge calls\n63.3 → 32.3 per frame (the 19 reads of the player: 7 small deltas), bytes copied by the bridge 24 168 → 16 028 per\nframe, `step` 2.33 → 1.92 ms (single wasm 0.53 – 0.60 in the same runs), 56 direct reads of the epoch per frame.\nParity: 721 identical apart and merged. A kit module weighs about 12 KB more.\n\n**Not built: typed hot arrays (position, health, tags as id sets) in the `WORLD` buffer of the zone.** The kits read\ncomponents as `serde_json::Value` and the value must be the one the core holds, bit for bit (`{\"x\":0}` is an\ninteger, `{\"x\":0.0}` a float; a transform may carry more keys than x, y, z, yaw): a typed row cannot give that value\nback, so it cannot replace a value read without porting the kits to typed components (§7, \"The kit source\"). What\na typed row can serve unchanged — `has`, `transform`, tag tests — is served by the direct links of step 2. Left for\nthe port to typed components: the rows, and queries evaluated in the module on tag sets.\n### 7.6 Built: the event queue (step 5)\n\n**The bus is unchanged; what changes is how a kit module receives its events.** The order of delivery is exactly the\nbus's (`Host::flush`): events in emission order (`seq`), delivered at the flush by rounds, handlers by priority then\nsubscription order, what is emitted during a round delivered in the next. It is frozen by a golden trace\n(`native/gripforge-kithost/tests/bus_order.rs`, `tests/fixtures/bus-order.golden.txt`: priorities, `once`, a\nsubscription made and one removed while dispatching, events emitted while dispatching, the player scope of an event,\na bounded flush), recorded on the bus before the queue; the same test replays it on kit modules that read the queue\n(`cargo test --features kitcall --test bus_order`).\n\n- **The flush is a cursor** (`Host::next_delivery` / `Host::deliver`): the same loop, asked one delivery at a time.\n- **An event is written once**, in binary, in the buffer `EVENTS` of the zone, the first time a kit module receives\n  it (`kitcall/events.rs` `event_record`): `seq u64, tick u64, time f64, topic string, source string, entity string?,\n  actor string?, payload value`. Before, every delivery built the event as a value, encoded it in the call and the\n  kit decoded it twice. Layout of the buffer (a ring of records, `len u32, kind u32, body`, 8-byte aligned; header\n  `head u32, records u32, wraps u32`): `native/gripforge-kitcall/src/events.rs`. An event that does not fit (240 KiB)\n  is delivered by the old call.\n- **One wake-up per run of deliveries.** The core wakes a kit with `kithost.kit` function `0xa0` (`KIT_EVENTS`: the\n  context, then `seq u64, event offset u32, length u32, tag string`). The kit copies the event from the zone\n  (`zone_copy`), runs the handler, then asks for its next delivery by a direct link (`gf:kithost.services@^1` /\n  `ev_next`, the core's `gfx_ev_next`, no JavaScript): the core goes on with the flush **from inside that call** —\n  it drains the state bindings as it does after and before every handler, runs the subscribers of the core that come\n  next (missions, triggers, the recorder) at their place, and when the next delivery is for the same kit writes a\n  delivery record in the queue (the context of that entry, the event, the tag) and answers its offset. When the next\n  delivery is for another kit it is put back for the flush and the answer is 0: the wake-up ends. So two handlers of\n  one kit that follow each other in the order of the bus cost one call instead of two, and nothing is reordered. A\n  kit that reads the same event under several tags decodes it once.\n- **A kit says it reads the queue** in `INFO` (`events: 1`); a kit built before (`kithost.kit@1.0`, a third party's)\n  keeps `ON_EVENT`, one call per delivery, in the same order.\n\n**What a module declares** — its entry of `kit-modules.json` (`events`), for the core, the kits of GripForge and a\nthird party's alike (`native/gripforge-runtime/web/kit-events.mjs`):\n\n```json\n\"events\": { \"emits\":   [{ \"type\": \"loot.dropped\", \"version\": \"1.2.0\", \"schema\": \"entity:u32,amount:f32,name:string\" }],\n            \"listens\": [{ \"type\": \"combat.damaged\", \"version\": \"^1\" }, { \"type\": \"input.*\" }, { \"type\": \"quest.done\", \"optional\": true }] }\n```\n\n`type` is the topic (a pattern in `listens`), `version` the version of the event contract (`major.minor.patch` for an\nemitter, a requirement `^1`, `^1.2`, `1.2.0` or none for a listener), `schema` the binary layout of the payload in\nthe queue: `value` (a tagged value: what every GripForge kit emits) or the fields in order (`bool`, `u8` … `u64`,\n`i8` … `i64`, `f32`, `f64`, `string`, `bytes`, `value`). The build writes the declarations of the GripForge kits from\n`events: { emits, listens }` of their TypeScript manifests (contract version `1.0.0`, schema `value`, what a kit\nlistens to marked `optional`: it works without the kit that emits it); a third party writes its own.\n\n**At link** (`loadKitHostWasm`, before any module is instantiated; the same check for kits apart and merged) the game\ndoes not start, and the error names the modules and the type, when: a module listens to a type **no module of the\ngame emits** (unless `optional`), the version an emitter states **does not satisfy** a listener, a listener states a\nschema that is not the emitter's, or two emitters of one type disagree on its major version or schema.\n\n```\nkit modules: events do not link:\n  acme.hud listens to the event loot.dropped@^1, but acme.loot emits loot.dropped@2.1.0 (incompatible version)\n```\n\n**The tracer shows events**: `logic.events.trace(keep)` answers the events dispatched since the last call, each\n`{ seq, tick, type, emitter, size, subscribers: [\"combat.core:spawned\", \"core:objectives\", …], version, schema }`\n(`size`: bytes of its record; `subscribers` in delivery order; `declared: false` for a type no module declared);\n`logic.events.types` is what was linked (`{ type: { version, schema, emitters, listeners } }`);\n`logic.events.stats()` counts `{ wakes, deliveries, events, bytes }`.\n\n**Measured** (2026-10-12; the unit of this lot: `step` of the kit modules ÷ `step` of the single wasm, the two\nplayed frame by frame in one process, median of 5 runs of 1 800 frames on the second machine, the candidates\ninterleaved; `qa/kithost-wasm-bench.mjs --interleave`).\n\n| the dungeon, bench | hooks / frame | kits ÷ single | merged ÷ single |\n|---|---|---|---|\n| master (`out-master`) | 55.2 | ×3.51 (3.49 – 3.57) | |\n| steps 1 – 2 + relayed service calls (`origin/rel-kit-zone`) | 55.2 | ×3.37 (3.35 – 3.42) | |\n| + the event queue | 55.2 | ×3.39 (3.38 – 3.48) | ×3.01 (2.98 – 3.06) |\n| the same two with 20 events per frame added (`--emit player.moved:20`) | 75.2 → 56.0 | ×3.38 → ×3.36 | ×2.94 |\n| … with 50 events per frame added | 105.2 → 56.0 | ×3.37 (3.32 – 3.52) → ×3.14 (3.01 – 3.19) | |\n\n**The bench of the dungeon has almost no event** — 0.17 per frame (`--ev-trace`: `player.moved` 0.16, the rest once\nin the run), against 26 `update`, 3 `late_update` and 26 service calls: the queue changes nothing there, which is\nwhat the first two lines of the table say, and the 0.25 ms the plan expected of this step was wrong for the bench\n(it counted every hook as an event). The gain shows where events are delivered: a page has about 54 more hooks per\nframe than the bench (pointer, HUD), and each event of the dungeon is heard by `audio.core` (`*`). With 50 events per\nframe the 50 wake-ups become one (`{ wakes: 1.01, deliveries: 50.2 }`) and `step` loses 7 % (about 2 µs per\ndelivery); with 20 the gain is inside the spread of the runs. Not measured in a browser in this lot.\n\n**Parity** (`qa/kithost-wasm-parity-check.mjs`): kit modules apart 721 identical, 0 differ (full run: combat 30,\nhud 32, coop 2 …, 4 on Rapier apart, 139 need the native test kits); the dungeon merged 176 identical (the 637 others\nneed kits that are not in that merged module, as before the queue). The final state of the bench is the single\nwasm's in every run (hero at the same place, 149 / 149 vars).\n\n**What is left of step 5, and why.**\n\n- *One tick call per kit that reads its events.* Not possible without changing the order: a handler runs at the\n  flush, after `late_update`, between the handlers of the other kits and of the core, and sees what they did. Moving\n  it into the kit's `update` would run it one tick later and before them. The wake-ups are grouped only where the\n  order allows it (consecutive deliveries of one kit).\n- *A kit not called when it has no subscription and no work.* True for events (a kit is woken only for a delivery of\n  its own) and for the per-tick hooks it does not implement (the hook mask). A kit that implements `update` is still\n  called every tick: whether it has work is its own code.\n- *A module publishes in the queue itself.* A kit still emits by a call (`kithost.services` `emit`), which stamps\n  `seq` at the emission among the core's own emits. Writing the record from the kit would need the core to take the\n  kit's records before each of its own emits, on every entry (calls and direct links): left for a later lot.\n- *The fixed cost of a wake-up* (2 – 4 µs for a hook that does nothing, 55 per frame in the bench) is untouched:\n  it is the bridge (JavaScript between the two modules, two `gf_alloc`, the copies of the arguments and of the\n  answer, a `BigInt` each way), not the event. The way under it: the core calling the kit's hook entry **through its\n  function table** (the host puts the kit's export there at load: a wasm-to-wasm `call_indirect`, no JavaScript),\n  the context and the arguments read in the zone, no answer buffer for the hooks that answer nothing. Kits apart and\n  merged need it both (the merge glue too): a lot of its own.\n- *A kit whose `update` has nothing to do this tick* is still called: only the kit knows. It needs the kit to say\n  so (a hint answered by `update`: \"do not call me before an event of mine or a timer\"), kit by kit, with the\n  parity — the scale (\"cost follows what works in the frame, not the number of modules loaded\") depends on it.\n- *Typed schemas* are declared and checked at link; the queue carries their payload as a value until a kit emits\n  one (no GripForge kit does: their payloads are `serde_json::Value`).\n\n### 7.5 (continued) Built: the structure version, static query lists, typed entity accesses\n\n**Structure version.** Beside its epoch the world has a *structure* value (`Entities::structure()`): it moves when\nthe list, a kind or tags change — not when a component does (a `get_mut` of the core moves it only if the kind or\nthe tags of that entity changed, checked with a hash, no allocation). A kit module reads it by a direct link\n(`hot_structure`) when the epoch moved; while it is the same, the answer of a query it asked before is the same\nentities in the same order: the module brings those copies up to date by their ids (`get_if`, or `get_many_if` for\nseveral in one call) and asks no query.\n\n**Static query lists (the core, both modes).** `Entities::query` / `first` keep, per query asked, the positions it\nselects, for the structure they were computed at: one scan per change of structure instead of one per call\n(`first(tag player)` was 10 scans of every entity per frame in the dungeon — 16 % of the single wasm's `step`).\nThe single wasm and the native host gain the same.\n\n**Typed accesses.** Methods of `host.entities` that take and return numbers, never a `serde_json::Value`, with the\n**same name and signature in the core** (`native/gripforge-kithost/src/entities.rs`) **and in the façade**\n(`native/gripforge-kit-guest/src/entities.rs`), so a kit source stays common to the single wasm, the native host\nand the kit modules. In the core they read and write the JSON component, which stays the truth (saves, the frame\nthe player reads): a typed read gives exactly what the value read gave, a typed write stores exactly what the\nvalue write stored.\n\n| Typed | Replaces | In a kit module |\n|---|---|---|\n| `transform(id) -> Option<Pos>` (already there) | `Pos::of(component(id, \"transform\"))` | the kept copy, else a direct link (4 registers) |\n| `set_pose(id, x, y, z, yaw)` (each `Option<f64>`) | `set_transform(id, &json!({ \"yaw\": num(yaw) }))` and the like — only when every field written is `num(…)` of an `f64` among x, y, z, yaw | a direct link (`hot_set_pose`): nothing built, encoded or copied |\n| `tagged(id, tag) -> bool` | `get(id).is_some_and(|e| e.has_tag(tag))` | the kept copy |\n\n**Migrating a kit** (mechanical, one kit at a time):\n\n1. In the kit's files replace the patterns of the middle column by the typed method. Do not touch a\n   `set_transform` whose patch has another key, a value that is not `num(f64)`, or comes from a variable.\n2. `cargo check` in `native/gripforge-kit-guest/check-all` (every kit against the façade) and\n   `cargo test -p gripforge-kithost --features kitcall --lib hot`.\n3. Build and replay the fixtures of that kit's family in both modes\n   (`node tools/kit-modules/build.mjs --out <dir> --kits <files>`, then\n   `node qa/kithost-wasm-parity-check.mjs --kit-modules <dir> --only <family>.`), the full 721 before the push.\n4. A pattern with no typed method yet (a health, a velocity): add the method **on both sides with the same\n   signature** and a test that it stores or reads what the JSON path did, then migrate.\n\n**Measured** (the dungeon, interleaved ratio to the single wasm built from master, 5 runs each in one launch):\n\n| | kit modules | merged |\n|---|---|---|\n| master | ×3.48 – 3.51 | ×3.09 |\n| + entity copies kept by revision (§7.4) | ×2.66 | ×2.31 |\n| + structure version (query answers kept) | ×2.60 – 2.67 | ×2.24 – 2.29 |\n| + static query lists in the core, `character.top_down` on `set_pose` / `tagged` | ×2.51 | ×2.17 |\n\nThe structure version alone gains nothing measurable (the queries it saves were already small deltas). The last\nline gains ×0.09, most of it from the static lists — which the single wasm gains too once rebuilt from this\nsource (the ratio above is against the single wasm of master). Parity 721 identical apart and merged at each line.\n\n**Where the rest is** (CPU profile of the kit modules after the structure version, per frame): the entity façade\nis about 60 µs of the 1 040 µs spent in the kits; the calls to the core 400 µs (the 26 kit-to-kit service calls\nand the input lists first), decoding their values 230 µs, the entry of a hook 105 µs, the allocator 150 µs. Typed\nentity columns can only take part of the 60.\n\n**The entity rows in the `WORLD` buffer** are built since: §7.9. The typed methods above kept their signatures\nwhen their implementation moved to the rows, and the kits that were not migrated get the same path — the façade\nrecognises a `set_transform` whose patch is numbers among x, y, z, yaw.\n\n### 7.7 Built: kit → kit service calls by direct link\n\n`kx.call(\"combat.health\", \"health\", [id])` from a kit module to a capability **another kit module** serves is a\nwasm-to-wasm call of the provider's export: no hook entered through the bridge, no JavaScript, and the core decodes\nnothing. The kit source does not change.\n\n- **Declared.** A kit's manifest entry lists what it serves (`kits[id].services`: `[{ id, version }]`, from the\n  `provides` of its manifest); the loader declares it as providing `svc.<capability>@<version>`.\n- **Linked by the host.** A kit crate imports `gf:svc.<capability>@^1` / `svc_call`, `svc_id` for each capability\n  its source names (`service_links!`; `tools/kit-modules/build.mjs` writes them from the string literals of the\n  kit's files that are capabilities of the catalogue). The calls host wires each import to the export\n  `gfx_svc_call` / `gfx_svc_id` of the kit module that provides the capability in this game. The link is\n  **optional**: no provider in the game, a provider of another major, on another thread, or built before these\n  exports — the import is a stub that answers \"not linked\" and the call takes the ordinary path, through the core.\n  Two kits that call each other are linked through a late binding. The merge (§8) does the same: an internal call,\n  or a stub.\n- **The core keeps the registry and who runs** (`native/gripforge-kithost/src/kitcall/svc.rs`). Before the call the\n  caller asks `svc_begin(capability, provider)`: the core answers whether that capability is served, in this host\n  and now, by the kit module the caller is linked to (a kit that replaced the provider at run time, a kit of the\n  core, a host service: no — the ordinary path). From there to `svc_end` the provider's calls to the core are\n  served on the provider's own `Kx`, and the bindings are drained before and after, exactly as `Host::with_kit`\n  does around `KitModule::call`.\n- **The values** are those of the codec (the same bytes as by the bridge), carried 8 bytes per call through the\n  core's words (`svc_push` / `svc_get`): the two kits do not see each other's memory, and a service call is an\n  entity id or an action name one way, a number or a small object the other — one to four words.\n- **A third-party kit** gets the same: it serves by `export_kit!` (the exports are there), and links what it calls\n  with `service_links!(name = \"capability\" in \"gf:svc.capability@^1\")` passed as the 4th argument of `export_kit!`.\n\nMeasured on the dungeon: the 26 service calls per frame (`combat.health.health` × 5, `input.actions.axis` × 4 and\n`justPressed` × 4, `combat.health.alive` × 2, `input.actions.device` × 2, `movement.dash.dashing` × 2 …) no longer\ngo through the core nor JavaScript — hooks 55 → 29 per frame, bridge calls 102 → 50 — for the same final state\nand the same parity (721 / 721, apart and merged). The ratio does not move (× 2.32 against × 2.31): see the top of\nthis section. It is the mechanism that scales — the cost of a call no longer depends on the core — and the one a\nthird party uses.\n\n### 7.8 Events notify, hooks decide: what stays changeable and stoppable\n\nTwo mechanisms, two roles, the same with kit modules (apart and merged) as in the single kit host:\n\n| | the event bus (§7.6) | the interceptable hooks (`engine.hooks`, [mods-engine.md](mods-engine.md)) |\n|---|---|---|\n| What it is | a **notification**: something happened | a **decision**: something is about to happen |\n| Who answers | nobody: every subscriber is told, in the fixed order of the bus | the taps, by priority; the asker **waits** for `{ payload, cancelled, reason, by }` |\n| Can it be changed or stopped | **no** — an event of the queue cannot be modified or cancelled by who receives it | **yes** — a tap sets the `mutable` fields, cancels when the hook is `cancellable` |\n| When | delivered at the flush of the tick, after the fact | run synchronously **before** the kit acts |\n\n**The rule.** What must be stoppable or changeable is a **hook run before the event**, never the event: a kit asks\n`engine.hooks.run(\"money.earn\", payload)`, applies what the taps left (or does nothing when cancelled), and only then\nemits `economy.transaction`. A kit that wants its decisions to be moddable declares a hook; it does not ask the\nsubscribers of an event to \"veto\" it. The queue of the zone keeps the role of the bus.\n\n**What holds with kit modules**, proved by `tools/kit-modules/hooks.test.mjs` (kits apart and merged, same answers)\nand by the 158 `hooks` / `mods` parity fixtures:\n\n1. **A kit module declares its interceptable hooks in its manifest.** The build writes those of a GripForge kit from\n   `engine.hooks` of its manifest (`kits[id].schema.hooks` of `kit-modules.json`); a third party writes `hooks` in\n   its `kit.json` (`tools/kit-modules/add-kit.mjs`). The game schema carries them (section `hooks`:\n   `{ name: { owner, mutable, cancellable, fields } }`, [game-schema.md](game-schema.md)); the core declares at start\n   the hooks of the modules its embedded manifests do not know. Two modules declaring one hook is an error at link.\n2. **Taps in data** (the `hooks` documents of the project and of the mods: `match`, `if`, `set`, `add`, `mul`, `min`,\n   `max`, `cancel`) are evaluated by game.engine, which stays in the core: same table, same order (priority\n   descending, then project before mods, then registration), whoever owns the hook.\n3. **A module taps the hook of another kit in code**: `kx.call(\"engine.hooks\", \"tap\", [hook, kx.callback(\"name\"),\n   { priority, owner, id }])`, and its `KitModule::callback` answers nothing, `{ set: { field: value }, reason }` or\n   `{ cancel: true, reason }`. The call is **synchronous**: game.engine runs the taps one after the other and enters\n   the module for each of its taps — by the kit's direct entry (`gfx_kit_hook`, hook `callback`: a wasm-to-wasm call\n   through the core's function table, the arguments and the answer as records of the queue, no JavaScript), by the\n   bridge when the kit has no direct entry (a kit built before, a tracer on). Never by the event queue. A tap may\n   run a hook itself (nested runs end innermost first).\n4. **Guard rails unchanged**: a field that is not `mutable`, a value its schema refuses, a cancel of a hook that is\n   not `cancellable` are refused and announced (`engine.hook.refused { hook, tap, field, reason }`).\n5. **The tracer says who changed or cancelled what**: `logic.hooks.trace(keep)` answers the runs since the last call,\n   `[{ hook, owner, tick, taps: [{ tap, owner, kind: \"code\" | \"data\", priority, set: [fields], refused, cancel,\n   reason }], cancelled, reason, by, payload }]` (`owner` of a tap: a kit, `project`, `mod:<id>`). A hook nobody taps\n   is not a run. `logic.events.trace()` (§7.6) shows the events that followed.\n\nWhat is not direct yet: the question itself (`engine.hooks.run` asked by a kit module) is a call to the core by the\nbridge, because game.engine is a kit of the core, not a kit module; it is synchronous like every call.\n\n### 7.9 Built: the entity rows of the zone — transforms by columns\n\n**One row per entity in the `WORLD` buffer, laid out by the game schema** ([game-schema.md](game-schema.md),\n`entity`): the fixed base — `core.id@1`, `core.position@1`, `core.rotation@1` — then every column the modules and\nthe game declared, static for every entity. Nothing else is fixed: the core itself *declares* the two columns it\nadds (`core.revision@1`, `core.shape@1`, in its entry of `kit-modules.json`), as a kit would. The layout in bytes\nis the contract `native/gripforge-kitcall/src/rows.rs` (a 64-byte header, then the rows; a row is found by the\nnumber of the entity's id — `e12` → 12 — in an open-addressed table: a few loads, no string).\n\n| Side | File | What it does |\n|---|---|---|\n| contract | `gripforge-kitcall/src/rows.rs` | the header, a row, the table (`find`, `take`, `leave`), the typed loads and stores |\n| core | `gripforge-kithost/src/kitcall/columns.rs` | lays the rows out from the schema, keeps the base equal to the `transform` component, checks the rights |\n| core | `gripforge-kithost/src/entities.rs` | every change of an entity tells the rows (`rows::changed`, `added`, `removed`, `lend`): none is missed, because every change goes through `Entities` |\n| kit | `gripforge-kit-guest/src/columns.rs` | reads and writes the rows where they are (a kit of the common memory) |\n\n- **The `transform` component stays the truth** (saves, the frame the player reads, a transform may carry more keys\n  than x, y, z, yaw); the base of the row is its mirror, written by the core at every change. An entity the core\n  handed out for any change (`get_mut`) is named in the header until it is back: its row is not read meanwhile.\n- **Reading a transform** (`entities.transform(id)`) in a kit of the common memory is four loads in the row: no\n  call. Elsewhere (a kit in its own memory, an id that is not `e<number>`) the direct link of §7.1, as before.\n- **Writing one**: `set_pose`, and `set_transform` whose patch is numbers among x, y, z, yaw as the JS model writes\n  them (the façade looks at the patch: the kit source does not change), is the direct link `hot_pose` — scalars, no\n  value built, encoded or copied. The core writes the numbers **in the transform object where it is**\n  (`Entities::set_pose_rev`): nothing is allocated when the fields are there (`tests/pose_alloc.rs`: 0 allocation in\n  300 writes). `Entities::set_transform` does the same for a patch that only gives new values to fields that are\n  there — what the physics writes after each step — so the single wasm gains it too.\n- **A copy of an entity kept by a kit is validated by its row.** `core.revision@1` is the entity's revision,\n  `core.shape@1` its last change that is *more than a move* (more than new values for x, y, z, yaw). A kit that\n  holds a copy at that revision has the entity: no call. When only the revision moved, the entity only moved: the\n  kit writes the four numbers of the base in its copy's transform — exactly, the row's flags say which of them are\n  floats and which integers (`pose_exact` / `pose_exact_into`, shared word for word by both sides) — and still no\n  call. Only a change of shape asks the core (`get_if`, a delta). Before, every move of the world (an epoch) cost\n  one call per copy read.\n- **A write of the kit itself keeps its copies.** `set` (`set_if`, `kithost.world@1.2`) and `hot_pose` answer the\n  entity's revision before and after: the kit applies its own write to its copies, which stay current, and when\n  nothing else changed in the world meanwhile it keeps everything it read.\n- **A component that is an object** (`component(id, name)` of an entity the kit holds no copy of) now keeps the\n  whole entity once, so the row validates it afterwards.\n\n**Rights per column and per module.** The schema says who reads and who writes each column (`read`, `write`, the\ngame's restrictions, each module's view). A kit asks the core once per column and mount what it may do\n(`col_info`, a direct link: offset, type, access); the façade refuses what its view does not give, and the core\nchecks the writes of the base that go through it (`hot_pose`, `set_transform`, `set` of a transform, `patch`):\n`npc.core writes column core.rotation@1: not allowed (write: vehicle.driveable)`. Limits: the write-back of a\nwhole entity (`put`) is not checked; a kit in its own memory that bypasses the façade can still store anywhere in\nthe zone (`zone_write_*`), as before this lot.\n\n**Columns of a kit or of the game.** `kx.column(id, \"game.mana@1\")`, `kx.set_column(…)`, `kx.add_column(…)`\n(`gripforge-kit-guest/src/columns.rs`; the core's twin: `kitcall::columns::read` / `write`): a scalar as one\nnumber, an `f64x3` as three, in place, under the rights above. They exist only in the zone: no GripForge kit uses\none yet (their state is JSON components — see below), and two hosts that alternate on one thread (a tool, a test)\neach start from the defaults.\n\n**Measured** (2026-10-13, common memory, the single wasm rebuilt at the same commit; second machine under\n`flock measure.lock`, load 2.1 – 3.0, 5 interleaved runs of 1800 frames, same final state 5/5; \"before\" is the\nbuild of §9.10 replayed in the same launch; allocations by `--features alloc-count`, the kits' own counter\nsubtracted — since `gf_alloc_by_kit` the count build allocates a string per kit allocation):\n\n| | calls with a value / frame | allocations per step (kits / single) | step single / kits, ms | gap | ratio (range) |\n|---|---|---|---|---|---|\n| dungeon, before | 11 | 3031 / 2428 | 0.322 / 0.611 | 0.29 | ×1.87 (1.87 – 1.91) |\n| dungeon, rows | **1.2** | 2915 / 2381 | 0.321 / 0.590 | 0.27 | ×1.83 (1.81 – 1.84) |\n| car football, before | 57 | 3527 / 2573 | 0.325 / 0.621 | 0.30 | ×1.92 (1.89 – 1.92) |\n| car football, rows | **23.5** | 3013 / 2400 | 0.329 / 0.587 | 0.26 | ×1.77 (1.76 – 1.79) |\n\n`set_transform` is no longer a call with a value in either game. What is left with a value on the car football:\n`set_if` 14.4 a frame (below), `get_if` 5.1 (`sport.ball` reads the `size` of cars whose state `vehicle.driveable`\nrewrites every frame: a change of shape), `get_many_if` 2.8 (`all()`), the contacts 1. Parity: 721 identical, 0\ndiffer.\n\n**What the object components of `vehicle.driveable` and `sport.ball` really are.** Not a position, a rotation or a\nvelocity: `vehicle.state` is `{ speed, gear, handbrake, boost, health, … }`, `vehicle.motion` `{ drifting, slip,\nboosting, throttle }`, `sport.ball` `{ v: [x, y, z] }` — the kit's own state, written as one JSON object 14 times a\nframe (`write_state` reads the object, merges, writes it back). Only the 6 `set_transform` a frame were a\ntransform. Taking those 14 off needs the kit to keep that state in **columns of its own** (declared in its\nmanifest, read and written by `kx.column`): a change of the kit source, and of what a save holds — not done here.\n\n### 7.10 Built: the physics as a module of the zone\n\n**What a kit asks of the physics is no longer a call when it is a write** (a kit of the common memory; the kit\nsource does not change: `kx.physics()` of the façade, `gripforge-kit-guest/src/ports/physics.rs`):\n\n- **a force is a state**: `apply_force` adds to the column `physics.force@1` of the entity's row (declared by the\n  core, `f64x3`), in place. Every kit that pushes a body in the tick adds to the same three numbers, each in its\n  turn; the physics takes the sum and empties the column. The sum is made in the precision the port adds in\n  (single for Rapier), so the port receives bit for bit what the calls gave it;\n- **an impulse is an event**: `apply_impulse` and `apply_torque_impulse` write a 32-byte record in the **physics\n  inbox**, a block of the zone (`rows.rs`: kind, the entity's number, three `f64`). The first force written on a\n  row also leaves a record there (\"the force of this row\"), so the physics finds what waits without a scan;\n- **the physics takes both in order** (`kitcall/physics_rows.rs` `flush`): before anything reads the physics again\n  (every call and direct link of `kithost.physics`, every call the core serves for a kit), when the kit's hook\n  ends, and before the step. So nothing is observable later than with the calls, and the order of a body's\n  impulses is the order they were asked in. A port of another kind than `null` and `rapier`, a kit in its own\n  memory, an id that is not `e<number>`, a full inbox (256 records): the call, as before — which first takes what\n  waits.\n\nThe inbox is a queue of its own beside the event queue of §7.6, not the `EVENTS` ring: that ring is written by the\ncore only (a record written by a kit there would have to be taken by the core before each of its own emits — the\nreason §7.6 gives for `emit`), and the bus is untouched: its order is frozen by `tests/bus_order.rs`, which still\npasses.\n\n**What the physics answers stays a call, by scalars and a result buffer at a fixed place**\n(`kithost.physics@1.2`, direct links, common memory): `ph_contacts` (`contact_events()` and `contacts()`: 6 words\nper contact — the two names packed, a value, a flag — in a buffer of the kit kept from one call to the next, in\nthe order of the port), `ph_move_character` (the displacement and grounded, 4 `f64` on the caller's stack),\n`ph_raycast` (7 `f64` in, 10 words out), `ph_overlap` (sphere or box; the names found, packed). A name longer than\n16 bytes, or a kit in its own memory: the call of 1.0, which answers the same.\n\n**The write phase of each column** is in the game schema ([game-schema.md](game-schema.md), `entity.phases`):\n`physics.force@1` is written by every kit during `update`, `late_update` and `events`, and by the physics alone\nduring `physics`; the base by the kits outside the physics step and by the core during it. It is what a later lot\nneeds to put the physics on its own thread (not done: today the physics takes what waits *before every read*,\nwhich a thread of its own cannot do — the phases say which reads would then see the previous step).\n\nTests: `cargo test -p gripforge-kithost --features kitcall --lib kitcall::` (`columns`: the rows follow the\ntransform, rights per column and per module with the named errors, a column added by the game, the revision\ncolumns; `physics_rows`: the forces of two kits in one tick add up in the column and the impulses keep their\norder — bit for bit the body the calls give, before and after the step, in double and in single precision — and\nthe contacts read by the fixed buffer keep the order of the port), `--test pose_alloc`, `--test bus_order`;\n`node --test native/gripforge-runtime/web/game-schema.test.mjs` (the write phases).\n\n**Measured after §7.10 and after the epoch in the zone** (same method; \"before\" replayed in each launch against the\nsingle wasm of this commit; load 1.7 – 3.2):\n\n| | calls core ↔ kit / frame (direct / with a value / hooks) | step single / kits, ms | gap | ratio (range) |\n|---|---|---|---|---|\n| dungeon, before | — / 11 / 29 | 0.322 / 0.611 | 0.29 | ×1.87 (1.87 – 1.91) |\n| dungeon, rows (§7.9) | 125.5 / 1.2 / 29.2 | 0.327 / 0.600 | 0.27 | ×1.85 (1.80 – 1.87) |\n| dungeon, + physics (§7.10) | 126.5 / 0.2 / 29.2 | 0.324 / 0.593 | 0.27 | ×1.82 (1.82 – 1.84) |\n| car football, before | — / 57 / 16 | 0.333 / 0.639 | 0.31 | ×1.92 (1.91 – 1.92) |\n| car football, rows | 194.4 / 23.5 / 16.2 | 0.329 / 0.577 | 0.25 | ×1.77 (1.75 – 1.79) |\n| car football, + physics | 190.9 / 22.5 / 16.2 | 0.328 / 0.589 | 0.26 | ×1.79 (1.78 – 1.80) |\n| car football, + epoch in the zone | 120.6 / 22.5 / 16.2 | 0.330 / 0.589 | 0.26 | ×1.80 (1.78 – 1.81) |\n| MOBA (`moba`, 36 kits, 134 entities), before | 22 035 / 3 126 / 33 | 1.976 / 6.161 | 4.19 | ×3.08 (3.08 – 3.12) |\n| MOBA, rows + physics + epoch in the zone | **718 / 44 / 33** | 1.964 / 3.282 | 1.32 | **×1.67** (1.64 – 1.68) |\n\nThe physics of §7.10 is not a speed-up (the calls it removes were cheap scalars: forces by call 5.4 → 0.9 a frame on\nthe car football, the contacts and `move_character` no longer calls with a value): inside the spread of the runs.\n**The epoch of the world is a word of the rows' header** (`rows.rs`, offset 48; the core writes it at every\nchange, a kit of the common memory loads it): `hot_epoch` was 12 479 calls a frame on the MOBA, 70 on the car\nfootball. On the MOBA — whose `combat.core` reads a component and a transform of every entity for every unit — the\nrows take `w_transform` from 2 568 calls a frame to 0 and the calls with a value from 3 126 to 44 (the copies the\nkits keep are validated by their rows instead of read again); allocations per step as the count build reports\nthem: 75 388 → 54 047 (single wasm 21 975), of which asked by the kits 50 367 → 25 642. Parity 721 identical, 0\ndiffer, at each step. Not measured: a browser, the merged export.\n\n**On the integrated base** (`rel-kit-integration` `bf3b4021f` merged in: the size-class allocator, the short entries\nof §9.11, the fixed-layout value of §9.12; \"before\" is that head's own build replayed in the same launch; single\nwasm rebuilt at the merge with the kits' toolchain; second machine under `flock measure.lock`, load 1.8 – 4.0, 3\ninterleaved runs of 1800 frames, same final state 3/3; parity 728 identical, 0 differ):\n\n| | calls core ↔ kit / frame | allocations per step (single → kits) | step single / kits, ms | gap | ratio (range) |\n|---|---|---|---|---|---|\n| MOBA, integrated head | 25 194 | 22 366 → 134 472 | 1.965 / 5.196 | 3.23 | ×2.67 (2.64 – 2.69) |\n| MOBA, + rows, physics, epoch | **796** | 21 107 → 47 439 | 1.916 / 2.572 | **0.66** | **×1.34** (1.32 – 1.35) |\n| car football, integrated head | — | 1 697 → 4 112 | 0.283 / 0.489 | 0.21 | ×1.74 (1.72 – 1.76) |\n| car football, + rows, physics, epoch | 159 | 1 524 → 3 363 | 0.280 / 0.450 | 0.17 | ×1.61 (1.60 – 1.61) |\n| dungeon, integrated head | — | 1 480 → 2 898 | 0.281 / 0.445 | 0.16 | ×1.59 (1.58 – 1.63) |\n| dungeon, + rows, physics, epoch | 104 | 1 433 → 2 731 | 0.289 / 0.446 | 0.16 | ×1.55 (1.54 – 1.57) |\n\n(Allocations as the `alloc-count` build reported them then: the counter itself allocated one string per allocation\nof a kit — the real counts are in §7.11: 24 369, 1 880 and 1 705 for the three \"after\" rows.) The dungeon does not move on this base:\nwhat the rows remove there was already cheap. **What is left on the MOBA**, not built: its entities are still\nnamed by their id string on the calls that remain (a row index would do); the scalar fields `targets_near` of\n`combat.core` reads of every entity for every unit (team, health, alive, radius) are still fields of JSON\ncomponents read from the kit's copies — as columns declared in the game schema they would be loads; an object\ncomponent the kit has no copy of is still copied whole once (lent in place as a fixed-layout view instead: §9.12);\nand the scan itself (every entity for every unit) is the kit's — a spatial query served by the core (neighbours in\na radius, filtered by team or tag, by scalars and a result buffer, in the order of the world) would replace it.\n\n### 7.11 Built: the neighbour search of the registry, service answers read in place\n\n**The allocation counters were wrong first.** `gf_alloc_by_kit` cloned the id of the running kit for *each*\nallocation a kit asked: on the MOBA, 22 771 of the \"47 439 allocations per step\" of §7.10 were the counter's own\nstrings. The counters now allocate nothing (`kitcall::with_running_kit`, lists searched by id). The base of this\nlot, counted again: **MOBA 24 369 allocations per step against 21 107 in the single wasm** (not 47 439), car\nfootball 1 880 / 1 524, dungeon 1 705 / 1 433. Who asks them, inside a kit: `qa/kit-alloc-callers.mjs` (a build\nwith `--names`) counts every allocation a kit module asks with the wasm stack that asked it — exact counts, by kit,\nby function, by the function of the kit or of the façade above it. On the MOBA: `minion.waves` ≈ 11 000 a frame\n(clones of its `Minion` records: the kit's own code, the same in the single wasm), `combat.core` `targets_near`\n5 092 (ids and teams copied per entity, the same in the single wasm), `camera.strategy` 1 271 — the whole map of\n`moba.match` decoded every frame to read its `camera` (the kit modules only).\n\n**The neighbour search** (`Entities::near(x, z, radius, conditions)`, the core's registry and the façade alike):\nevery entity with a transform within `radius` on the ground for which every condition holds — `Cond::Above\n{ component, field, min }`, `Number`, `Text`, `TextNot`, `Tag`, `NoTag` — with its distance, in the order of the\nregistry. One definition, `entity::near_one` (`src/entity.rs`, shared word for word by the core and the kit\nmodules), so both answer the same bits.\n\n- In the single wasm it is one walk of the registry: no id is looked up.\n- A kit module of the common memory asks by the **direct link `w_near(spec, out, cap)`** (`kithost.world@1.3`,\n  layout `gripforge-kitcall/src/near.rs`): the question is a block of 64-bit words on the kit's stack (x, z, radius,\n  then three words per condition, names as atoms), the answer two words per neighbour in a buffer of the kit (the\n  number of the id, as its row; the distance). Scalars both ways; the call allocates nothing. More neighbours than\n  the buffer holds: the count says how much room to ask again with. An id that is no `e<number>`: the link says\n  \"not this way\" and the façade walks the kit's own copies with the same `near_one`.\n- The core reads **positions in the entity rows** (§7.9) when the rows of the zone are that world's\n  (`columns::grounds`): an entity out of reach costs a few loads; the conditions, which read JSON components, are\n  only evaluated for the entities within the radius. Elsewhere it reads x and z of the transform.\n\n`combat.core` `targetsNear` is that search (alive: `health.hp > 0` with a numeric `max`; not of the team; within\nthe radius) followed by its own sort — the only kit source this changes. `tests/near.rs`: the search answers what\nthe walk it replaced answered, bit for bit, with and without the rows published, after moves, a transform removed,\nan entity handed out by `get_mut`.\n\n**Service answers read in place** (`Kx::call_with(capability, method, args, |answer: Val| …)`). A kit that only\nreads an answer does not rebuild it: between two kit modules of the common memory, a list or a dictionary\nanswered to a scalar call is given as a **fixed-layout block** (`fast::S_FIXED`, `kithost.mem@1.2`; §9.7) and\n`Val` reads it where it is (`get`, `at`, `as_f64`, `as_str`, `len`, `to_json` for the part the kit keeps). In the\nsingle wasm `Val` wraps the provider's value: the same source, the same accessors. `Kx::call` is unchanged for a\ncaller that keeps the value (the block is then copied once, where the codec was decoded before).\n`camera.strategy` reads `map.camera` this way: the map is no longer copied 60 times a second.\n\n**List and dictionary arguments** of a kit → kit service call are lent the same way (`Scalar::lend_block`): the\ncall stays on the scalar entry of §9.11 — on the MOBA the 93 calls a frame that still pushed words through the\ncore (`svc_begin`, `0x1028`: a position `[x, y, z]` among the arguments) are now scalar calls (465 of 465).\n\n**Smaller**: `get_mut` hands the kept copy and copies the entity at the first write (a kit that takes the guard to\nread copied the whole entity every tick); the readers of an entity row, of the state and of the event queue ask\none buffer of the zone from its own cell (`zone::world()`…) where `buffers()` copied the five.\n\n**What was already true of object components.** A kit reads a component that is an object in the copy of the\nentity it keeps, validated by the row (§7.9): nothing is rebuilt per read. What *was* rebuilt per read on this base\nwas the answer of a service — hence `call_with`.\n\n**Measured** (second machine under `flock measure.lock`, one hold per round, candidates interleaved, each against\nthe single wasm of ITS commit — the single wasm gains from `Entities::near` too; 3 rounds of 1800 frames, same\nfinal state 3/3; allocations and calls counted on the main machine, deterministic, corrected counters):\n\n| game, build | calls core ↔ kit / frame | allocations per step, single → kits | what changed |\n|---|---|---|---|\n| MOBA, base of this lot | 796 | 21 107 → 24 369 | — |\n| MOBA, + neighbour search | 864 (62 `w_near`) | 16 596 → 19 807 | `targetsNear` is one search; the single wasm gains too |\n| MOBA, + answers read in place | 864 | 16 596 → 18 569 | `camera.strategy` no longer copies the map |\n| MOBA, + arguments lent as blocks | 864 (465 service calls, all scalar) | 16 596 → **17 982** | no words pushed through the core |\n| car football, base → last | 159 | 1 524 → 1 880, then 1 524 → 1 832 | (does not call `targetsNear`) |\n| dungeon, base → last | 104 | 1 433 → 1 705, then 1 433 → 1 693 | (does not call `targetsNear`) |\n\nStep times, first series (load 2.1 – 15.6: other lots measured there; the machine at full clock speed):\n\n| game | build | step single / kits, ms | gap | ratio (range) |\n|---|---|---|---|---|\n| MOBA | base | 2.002 / 2.744 | 0.74 | ×1.38 (1.35 – 1.45) |\n| MOBA | + neighbour search | 1.522 / 2.056 | **0.53** | ×1.36 (1.35 – 1.41) |\n| car football | base → + neighbour search | 0.282 / 0.453 → 0.285 / 0.458 | 0.17 | ×1.61 → ×1.61 |\n| dungeon | base → + neighbour search | 0.283 / 0.439 → 0.283 / 0.440 | 0.16 | ×1.55 → ×1.55 |\n\nSecond series, the three steps together — **the machine was throttled** (browsers of other lots outside the lock,\nload 5.4 – 10, the processor clocked down to 0.4 – 1 GHz: a step of the single wasm took 3.3 – 5.3 ms instead of\n1.5 – 2.0). Its times in milliseconds mean nothing; the ratios, interleaved frame by frame in one process, are\nwhat it gives:\n\n| game | base | + search, + answers in place | + arguments as blocks |\n|---|---|---|---|\n| MOBA | ×1.45 (1.44 – 1.46) | ×1.34 (1.30 – 1.41) | **×1.26** (1.25 – 1.27) |\n| car football | ×1.72 (1.66 – 1.76) | — | ×1.59 (1.56 – 1.60) |\n| dungeon | ×1.63 (1.63 – 1.64) | — | ×1.60 (1.59 – 1.61) |\n\nThird series, base against the last step (each round waited for a 1-minute load under 4; load 2.6 – 4.2; a step\nof the single wasm back at its usual time) — **the numbers to keep**:\n\n| game | build | step single / kits, ms | gap | ratio (range) |\n|---|---|---|---|---|\n| MOBA | base | 2.073 / 2.856 | 0.78 | ×1.36 (1.36 – 1.38) |\n| MOBA | search + answers in place + arguments as blocks | 1.556 / 1.887 | **0.33** | **×1.20** (1.20 – 1.21) |\n| car football | base | 0.299 / 0.488 | 0.19 | ×1.63 (1.62 – 1.63) |\n| car football | last step | 0.289 / 0.443 | 0.15 | ×1.53 (1.52 – 1.53) |\n| dungeon | base | 0.286 / 0.446 | 0.16 | ×1.55 (1.53 – 1.56) |\n| dungeon | last step | 0.288 / 0.436 | 0.15 | ×1.52 (1.51 – 1.52) |\n\nAgainst the aims of this lot: MOBA allocations per step ≤ 25 000 — **17 982** (and the base was already 24 369 once\ncounted right); MOBA gap ≤ 0.3 ms — **0.33 ms, not reached** (from 0.78 in the same launch); car football and\ndungeon ≤ ×1.3 — **×1.53 and ×1.52, not reached**. A local profile of the last step, by the innermost kit on the\nstack (shares, not times): `combat.core` is now cheaper in the kit modules than in the single wasm (the rows);\nwhat is left of the MOBA's gap is `moba.lanes` (+55 % of its own time: it both makes and serves most of the 465\nservice calls a frame — `Fill::value` of the map it answers to `camera.strategy` every frame, `Kx::call`,\n`serve_scalar`), then `minion.waves`, `moba.hero`, `world.water` (a few percent each).\n\nParity: 728 identical, 0 differ at each step. Tests: `cargo test -p gripforge-kitcall` 23, the façade 15,\n`tests/near.rs` 3, `kit_fast` 3, `bus_order` 2, `pose_alloc` 1, `kitcall::` 12; `node --test tools/kit-modules`\n33 pass, 10 skipped, 1 known failure of the environment (`add-kit` wants a folder of house kits).\n\n**Tried, no gain**: the core of the kit modules is built by the repo's pinned Rust (1.95.0) while the kits and the\nsingle wasm of these measures are built by 1.97.1; the core rebuilt by 1.97.1 (`GF_CORE_TOOLCHAIN=stable`) measures\nthe same (MOBA 1.508 / 2.057 ms against 1.522 / 2.056; car football ×1.61; dungeon ×1.54 against ×1.55).\n\n**Not built, and why.**\n- *Scalar fields as columns* (team, health, alive, radius declared by their kit in its `<kit>.schema.json`, mirrored\n  by the core from the component at each change, read by `kx.column`): the search above took the per-entity reads\n  of `targets_near` off the kits altogether, which is where those fields were read in a loop; the conditions of the\n  search still read JSON for the entities in reach. The state of `vehicle.driveable` / `sport.ball` as columns of\n  their own (§7.9: 14 object writes a frame on the car football) is still the lever of that game.\n- *Entities by row number on the remaining calls*: on the MOBA the calls that still carry an id are `hot_pose` 80,\n  `w_has` 51 and `w_component` 38 a frame (a 16-byte packed id hashed by the core): a few microseconds a frame.\n- *The dungeon and the car football* do not move: their gap is no single cost — 29 and 16 hooks a frame and about a\n  hundred calls, each a few tenths of a microsecond in a dozen functions of the façade (`host::tick`,\n  `Host::enter`, `reads_stale`, `entry_from`, `Kx::call`, `serve_scalar`…), none above 2 % of the frame.\n\n## 8. Merging at export (optional): one wasm for the core and the game's kits\n\nThe kit modules stay **distributed apart** (one wasm per kit, each with its hash); when a game is exported, the core\nand the kits of that game can be **merged into one wasm** with Binaryen. Built and measured on 2026-10-12; it works\n(parity, Chrome and Firefox), it is the lightest download of the three, and it is only a little faster than the kit\nmodules loaded apart — the reason is below.\n\n```\nnode tools/kit-modules/merge.mjs --dir <kit modules dir> (--kits a.b,c.d | --bundle game.json | --all) --out <file.wasm | dir>\n     [--binaryen <bin dir>] [--no-opt] [--opt-level -O3] [--single-memory] [--keep <work dir>]\nGF_KIT_MODULES=<dir> GF_KIT_MODULES_MERGE=1 node tools/web-export/build.mjs <bundle.json> <out> <origin> <player package>\n```\n\n**Binaryen** (`wasm-merge`, `wasm-opt`, `wasm-as`, version 124 used here) is found by `--binaryen <dir>`, else\n`BINARYEN_BIN`, else the npm package `binaryen` (`node_modules/binaryen/bin`), else the `PATH`. The tool installs\nnothing; a release archive of github.com/WebAssembly/binaryen unpacked in a folder is enough. Without Binaryen the\nweb export warns and ships the kit modules one by one, as without the option.\n\n**What the merge does** (`mergeKitModules`):\n\n1. **Checks the links** as the calls host does at load: the `provides` / `consumes` lines of each binary's\n   `gripforge.calls` section against the manifest, the direct links (`gf:<interface>@<req>`) against their provider.\n   A contract that is not met stops the merge with the same message.\n2. **Rewrites the import and export sections** of every module (a binary edit, nothing else is touched): its\n   `gf_calls` imports go to a generated glue module (`gf_bridge` → `bridge_<i>`, `gf_resolve` → `resolve_<i>`), a\n   direct link `gf:kithost.input@^1` / `input_get` becomes an import of the core's `gfx_input_get`, a kit's exports\n   get a prefix of their own.\n3. **Generates the glue** (WebAssembly text, a few hundred lines): the bridge of the calls ABI written in wasm.\n   For a call from module A to module B it calls B's `gf_alloc`, copies `[name][args]` with\n   `memory.copy` **from A's memory to B's** (multi-memory), calls B's `gf_on_bridge`, calls A's `gf_alloc` and\n   copies the answer back the same way. `gf_resolve` is a table of the game's module and interface names (the\n   requirement after `@` was checked in step 1). The zone, the registers and the async path are stubs: a merged\n   module only has the bridge and the direct links, which is all the kit modules use. `gf_kits_start` runs each\n   kit's `gf_calls_init` and registers the kits in the core (what the page does after loading them apart).\n4. **`wasm-merge`** links the core, the kits and the glue: every import between them becomes an internal call.\n   **Each module keeps its own memory, its own allocator and its own table** — nothing is relocated.\n5. **Cuts the exports** down to the core's page API plus `gf_kits_start`, then **`wasm-opt -Os`** (inlining across\n   the former module borders, dead code, duplicate functions).\n\nThe result imports only `env.gf_page_call` and exports what the single kit host wasm exports: **the page loads it\nexactly as the single wasm** (`loadKitHostWasm(bytes)` calls `gf_kits_start` when it is there). In an export made\nwith `GF_KIT_MODULES_MERGE=1` the manifest names it (`\"merged\": { \"wasm\", \"bytes\", \"gzip\", \"hash\", \"memories\",\n\"kits\" }`), the per-kit files are not shipped, and the page plays it as the game's Rust logic. Merging is an option\nof the export, never its default: without the variable the export ships one wasm per kit.\n\n**Memories.** The merged module has one memory per module plus the glue's (the dungeon: 38). Multi-memory is\nverified in Chrome 146 and Firefox 157 (headless, the dungeon logic for 1 800 frames, same final state as the single\nwasm) and in Node 24. The loader tests it (`hasMultiMemory()`): an engine without it throws at load and the page\nshows that error (export with `GF_KIT_MODULES_MERGE=single`, or without the merge, for such engines). Limits to know: engines cap the memories of a module (100 in Firefox as far as we know — the 160 kits merged at\nonce, 162 memories, were only loaded in Node; a game's kits are far under), and Safari was not tested here.\n`--single-memory` (`GF_KIT_MODULES_MERGE=single`) lowers the memories to **one** with Binaryen's multi-memory\nlowering, for engines without multi-memory: every access adds its memory's offset and a memory that grows moves\nthose after it; measured a little slower and heavier (below).\n\n**What changes for a merged game**: a kit that traps stops the whole module (apart, it is left out alone); the\ntracer of the calls host sees nothing (the calls no longer pass through it; `gf_kits_counts` still counts them);\na kit cannot be replaced without merging again. A kit module calls another kit through the core's services, as\nbefore; a kit that resolves another kit **directly** gets `not_declared` (the glue only links core ↔ kit).\n\n### Measured (the dungeon, core + 36 kits, built from master `ddcb4032d`)\n\n**Parity** (`qa/kithost-wasm-parity-check.mjs`): kit modules apart 721 identical, 0 differ (master, full run);\nthe 160 kits merged into one wasm (`--all`) 721 identical, 0 differ; the dungeon's merged wasm 176 identical, 0\ndiffer (the 176 fixtures its 36 kits can play; the others need kits it does not hold), the same with\n`--single-memory`.\n\n**Download.**\n\n| | files | bytes | gzip -9 | brotli 11 |\n|---|---|---|---|---|\n| single wasm (every kit) | 1 | 21.84 MB | 5.86 MB | 3.69 MB |\n| core + 36 kits, apart | 37 | 14.35 MB | 5.12 MB | 4.05 MB |\n| merged (38 memories) | 1 | 12.61 MB | 4.58 MB | 2.13 MB |\n| merged, one memory | 1 | 13.11 MB | 4.82 MB | 2.16 MB |\n\n(MB = 10⁶ bytes. Brotli sees the copies of the shared code once they are in one file, gzip's window does not.)\n§6 counts the single wasm in MiB (20.7). The merge takes 17 s for the dungeon (wasm-merge 2 s, wasm-opt 14 s; 18 241\nfunctions before `-Os`, 13 069 after; `-O3` gives the same size) and gives the same bytes at every run.\n\n**Logic per frame**, `step` only:\n\n| | single wasm | kits apart | merged | merged, one memory |\n|---|---|---|---|---|\n| Node 24 (`qa/kithost-wasm-bench.mjs --sides wasm,kits,merged`, 1 800 frames, main machine, load ≈ 4.7) | 0.57 – 0.61 ms | 2.39 ms | 2.08 – 2.12 ms | 2.15 ms |\n| Chrome 146 headless, logic alone (second machine, load < 1.6, 3 × 1 800 frames) | 0.24 – 0.25 ms | 1.11 – 1.20 ms | 1.01 – 1.09 ms | 1.05 – 1.10 ms |\n| Firefox 157 headless, the same page | 0.26 – 0.29 ms | 1.33 – 1.41 ms | 1.21 – 1.25 ms | 1.24 – 1.27 ms |\n| The dungeon page under the Bevy player, Chrome on the NVIDIA RTX A500 (`qa/export-fps-check.mjs`, WebGPU, 20 s, load 0.0 – 2.1, two runs) | 1.21 – 1.24 ms, 59.8 frames / s | 2.69 – 2.74 ms, 59.7 | 2.55 – 2.61 ms, 59.6 – 59.7 | 2.75 – 2.78 ms, 59.4 |\n\nSame final state in every mode (hero bit for bit, 149 / 149 vars). The calls per frame are unchanged (184 by the\nbridge, 57 direct).\n\n**Why the merge gains so little** (5 % in the page and 9 – 13 % on the logic alone against the kits apart; the\nsingle wasm stays 2.1 – 4.5 times faster than the merged one). The merge removes what §6 already measured as small: the JavaScript of the calls host (0.19 ms per\nframe in the profile of §6) and the cost of crossing a module border. It keeps everything else, because\n`wasm-merge` joins modules **without relocating them**: every kit still has its own memory, its own allocator and\nits own copy of the value model, so\n\n- a call still **encodes its values in one memory, copies them, and decodes and allocates them in the other** —\n  the copy is now a `memory.copy` instead of a JavaScript `set`, the encoding and decoding (the real cost) are the\n  same code;\n- **the duplicated code is not shared**: `serde_json`, the allocator and the façade exist once per kit, and two\n  copies are not \"the same function\" for `wasm-opt` — each reads and writes its own memory, its own stack pointer\n  and its own static addresses. Inlining, duplicate function elimination and dead code remove 28 % of the\n  functions but only 7 % of the bytes.\n\n**What would give the single wasm's speed with kits distributed apart** — the calls must stop copying, which needs\n**one memory and one allocator shared by the core and the kits**:\n\n- *link, not merge*: distribute each kit as a relocatable object (the `.rlib` / `.o` of the kit crate) and link the\n  core and the game's kits at export with `wasm-ld` (shipped with Rust as `rust-lld`; no compiler is needed at\n  export). The result is the single kit host with only the game's kits: its speed, and less to download\n  than today's single wasm (not built here). The price: Rust objects only link with objects of the same compiler version and the same build of\n  the kit host crate, so a third-party kit is rebuilt for each release of the core (a build service, or the kit's\n  source in the registry) — the versioned binary contract of §2 is lost at that border;\n- *or dynamic linking in one memory*: kits built position-independent (`dylink.0` side modules) that import the\n  core's memory and allocator and pass references instead of encoded values. It keeps one file per kit, but the\n  interfaces of §2 must then be defined on shared layouts (the shared zone of §7 is the first step of that), and\n  Rust does not build such side modules for `wasm32-unknown-unknown` today.\n\nUntil then the plan of §7 is what reduces the copies; it adds to the merge (after a merge the direct links of\nstep 2 are plain calls that `wasm-opt` inlines). The merge is worth using for what it does give: one file and the\nsmallest download.\n\n## 9. Common memory (the trusted kits)\n\nA kit module in its own memory pays every exchange with the core twice: the bytes are copied into the other memory\nand the answer copied back, by the host (§1). For the kits GripForge builds itself there is a second mode, chosen\n**per kit** in `kit-modules.json`:\n\n| `kits[id].memory` | the module | its allocator | a call core ↔ kit |\n|---|---|---|---|\n| `\"own\"` (default, and the only mode of a third-party kit) | owns and exports its memory | its own | the bridge: arguments and answer copied by the host |\n| `\"common\"` | **relocatable**: imports the memory the core lives in; the host places it at load time | the core's | by **pointer**: the arguments are read where they are, the answer is a `Vec` handed over |\n\nBoth live in one game: the core tells them apart by handle and uses the bridge for the first, a table call for the\nsecond. The zone (§7.3) stays what it is for both — for a kit of the common memory its two copies are a `memcpy` in\nplace instead of a call to the host.\n\n### 9.1 What the host does (`web/module-calls.mjs`)\n\n1. **One memory.** The core built for this mode (`core.memory: \"import\"`) imports `env.memory`; the host makes that\n   `WebAssembly.Memory`. Its ceiling and start size are the game's (`project.schema.memory`, game-schema.md) within\n   the device's ceiling (four times the zone's: 1 GiB on a desktop, 128 MiB on a small phone); the stack of a kit\n   module too (`stackBytes`, 256 KiB by default; `kits[id].stackBytes` for one kit). Nothing is a constant of a\n   module. The memory is **shared** (`SharedArrayBuffer`) when the page is cross-origin isolated, the game does not\n   refuse it (`memory.shared: false`) and the folder holds the shared build (§9.4); otherwise a plain memory, the\n   same code.\n2. **One allocator.** The core exports it — `gfx_mem_alloc(size, align)`, `gfx_mem_alloc_zeroed`,\n   `gfx_mem_free(ptr, size, align)`, `gfx_mem_realloc(ptr, size, align, new_size)` (interface `kithost.mem@1`) — and\n   the kit modules of the common memory **link it directly**, wasm to wasm: it is their `#[global_allocator]`.\n3. **Placing a relocatable kit.** The host reads the module's `dylink.0` section (bytes and alignment of its static\n   data, slots of function table), asks the core's allocator a block for the data (zeroed) and one for the stack,\n   grows the **core's function table** by the module's slots, and instantiates it with `env.memory`,\n   `env.__memory_base`, `env.__table_base`, `env.__stack_pointer`, `env.__indirect_function_table`; then\n   `__wasm_apply_data_relocs` and `__wasm_call_ctors` when the module has them. The same binary can be placed several\n   times: each instance has its data, its stack and its slots (`host.commonMemory()` lists them).\n4. **Linking by pointer.** The kit's entry `gfx_mem_enter(func, args, len, out)` goes into the core's table and the\n   core is told (`gf_mem_link(handle, slot)`): from then on every hook of that kit is a `call_indirect` of the\n   core. The other way the kit imports `gf:kithost.mem@^1` / `mem_call`: the core's `gfx_mem_call`. No JavaScript\n   runs between the two, and no byte is copied: `out` receives `{ ptr, len, cap }` of a `Vec<u8>` whose ownership\n   passes to the caller (one allocator frees it).\n5. **Unloading** (`host.unload(name)`): the entry is unlinked, the table slots are emptied and kept for the next\n   module of that size, the two blocks go back to the allocator. Before that the module is told (`gf_calls_exit`,\n   written by `export_calls!`) and drops what it keeps on its heap: the allocator does not know whose a block is, so\n   only the module can. 300 load / unload cycles of the test probe leave not one byte, and the memory and the table\n   at the same size.\n6. **Errors are named, never papered over.** A kit `\"common\"` that cannot be placed stops the load with its name,\n   its version, the mode and the cause — `combat.melee@1.3.0 (memory \"common\"): the common memory has no room for\n   its stack (…)`, `… declared memory \"common\" but the binary is not relocatable`, `… built for the common memory\n   but the core (…) owns its memory`. There is no fallback to another mode: it would be another binary.\n\nWhat this mode gives up, on purpose: **isolation** (a kit of the common memory can write anywhere, and a trap in it\nunwinds through the core: the game stops, where a kit in its own memory is left out and the others go on), and the\nbinary contract of a module that owns its memory (in the common memory the contract is the structures of §9.7 and\ndocs/kit-structures.md: a layout GripForge defines, the same for any compiler). Hence: trusted kits only.\n\n**The stack of a kit** is a block of the heap, so nothing traps when it overflows. The host puts a **guard** under\nit (`stackGuardBytes`, 4 KiB by default) and fills the whole block with a mark: `host.commonMemory()` gives how deep\neach kit went (`stackUsed`), `host.checkStacks()` answers a named error for each kit that entered its guard —\n`a@1.0.0 (memory \"common\"): its stack overflowed (16384 bytes; it went 1234 bytes into its guard, nothing else was\ntouched) — raise its stackBytes` — and says when it went through it (the memory under it is then damaged: stop).\nThe parity check and the page check fail on either. Measured over the 721 fixtures: 22.7 KiB at most (of 256).\n\n**The allocator** is the core's `std` allocator (dlmalloc), reached through `gfx_mem_*`. It refuses with 0 — a\nrequest over the ceiling of the plan, or the ceiling reached — and stays usable; a refused `realloc` leaves the\nblock where it is; a kit that cannot be placed for lack of room is refused by name and leaves nothing behind.\n\n### 9.2 Building (`tools/kit-modules/build.mjs --common`)\n\n```\nnode tools/kit-modules/build.mjs --out <dir>                        # every kit in the common memory (the default)\nnode tools/kit-modules/build.mjs --out <dir> --own all              # every kit in its own memory, as before\nnode tools/kit-modules/build.mjs --out <dir> --own ui_menu,ui_hud   # those two in their own memory\nnode tools/kit-modules/build.mjs --out <dir> --common-shared        # also the build for a shared memory: §9.4\n```\n\nThe kits are built relocatable and the core is built to import its memory (`--common a,b`, the first spelling,\nbuilds only those for the common memory). `--own all` needs no `rust-src` and is what the merge at export takes. The recipe is\none constant of the tool (`RELOCATABLE`) — stable Rust 1.97.1 with the `rust-src` component — and it is the recipe of the\n**kits** only: the core is an ordinary module that imports its memory, built by the toolchain its workspace pins\n(Rust 1.95.0 today; `--core-toolchain <name>` forces another). The two sides need not share a compiler (§9.7); the\nmanifest records which one built each (`built: { core, kits }`), and every wasm written is checked against the\nstructures declarations (`tools/kit-modules/structs.mjs`: a wrong layout stops the build, naming the structure):\n\n```\nRUSTC_BOOTSTRAP=1 RUSTFLAGS=\"-C relocation-model=pic -C link-arg=--experimental-pic -C link-arg=-pie -C link-arg=--import-memory\" \\\n  cargo build --release --target wasm32-unknown-unknown -Zbuild-std=std,panic_abort\n```\n\n`std` is rebuilt position-independent once, in `<target>/pic`. The kit's **source does not change**: the generated\ncrate turns the feature `common-memory` of `gripforge-kit-guest` on and adds `gripforge_kit_guest::common_memory!()`\n(the allocator, `gfx_mem_enter`, and the two symbols `__heap_base` / `__heap_end` the allocator of `std` still\nnames). `--experimental-pic` and `-Zbuild-std` are unstable: every output is checked (`checkRelocatable`: `dylink.0`\npresent, the memory imported, nothing left for a dynamic linker) and a failure names the kit, the reason and the\nrecipe; `GF_RELOC_BUILD=1 node --test tools/kit-modules/common-memory.test.mjs` rebuilds a probe with the recipe and\nplays it — run it after a Rust update.\n\nOne thing a relocatable module cannot do: take the address of an **imported** function (the linker leaves a\n`GOT.func` symbol for a dynamic linker the host is not). `service_links!` wraps its two imports for that reason.\n\nA folder built with `--common` is **not merged** (§8): `merge.mjs` refuses it with the reason. The merge keeps to\nkit modules with their own memory.\n\n### 9.3 Measured\n\nParity (`qa/kithost-wasm-parity-check.mjs --kit-modules <dir>`, 2026-10-12): **721 identical, 0 differ** with\n`fx.hit_flash` and `combat.melee` in the common memory and the 158 others in their own; the same 721 with all 160\nkits in the common memory (deepest kit stack over the whole replay: 22.7 KiB, `quest.graph`; the check prints it and\nfails on an overflow). The 160 relocatable kits weigh 45.7 MB against 49.2 MB (no allocator of their own).\n\nStep of the dungeon (36 kits + game.engine) against the single wasm, played frame by frame in the same process\n(`qa/kithost-wasm-bench.mjs --interleave`, Node 24, second machine, load 0.2 – 1.4, 5 runs of 1800 frames, the same\nfinal state in every run):\n\n| kits of the game in the common memory | step, kits / single wasm (median; range of the runs) | best run, ms per frame |\n|---|---|---|\n| none (every kit in its own memory, same tree) | ×1.83 (1.82 – 1.85) | 0.702 |\n| `combat.melee` | ×1.84 (1.82 – 1.86) | 0.688 |\n| `combat.melee`, `combat.core` | ×1.83 (1.79 – 1.83) | 0.681 |\n| all 36 | **×1.59** (1.57 – 1.64) | 0.590 |\n\nOne or two kits do not show (inside the spread of the runs): the gain is per call that stops crossing the host, so\nit comes with the number of kits moved. With all of them the step loses 13 – 16 %. What remains above the single\nwasm is the codec (values written on one side, read on the other) and the façade's caches, not the transport.\nNot measured: the page in a browser (the bench is Node), the shared-memory build's speed, and memory use over a\nlong game.\n\n### 9.4 A memory shared between threads\n\n`--common-shared` builds the core and the kits of the common memory a second time with `-C\ntarget-feature=+atomics,+bulk-memory,+mutable-globals` (std rebuilt once more, in `<target>/pic-atomics`) and\n`--shared-memory --max-memory=…`; the manifest names both builds (`wasm` and `shared: { wasm }`, for the core and for\neach kit). At load the host picks the shared set when the page may share memory (`crossOriginIsolated`; Node may),\nthe game does not refuse it and the set is complete — otherwise the plain set. One code path: the memory is the\nonly difference (`new WebAssembly.Memory({ initial, maximum, shared: true })`; a shared memory must declare its\nceiling, so the binaries carry 4 GiB and the host's plan stays under it). The page side reads a shared memory as\nit reads a plain one, except that bytes are copied before `TextDecoder` (browsers refuse shared bytes).\n\nVerified (2026-10-12, Rust 1.97.1, Node 24): the core and `fx.hit_flash` + `combat.melee` built this way load in a\n`SharedArrayBuffer` and replay their fixtures identically, as does the plain set of the same folder; a Worker handed\nthe `Memory` object writes a word of the zone that the main thread reads back through the core (and, on the test\nbinaries, instantiates a relocatable module on that memory and reads in place a string made on the main thread).\n\n**How the allocator is protected between threads** (read in the source, `library/std/src/sys/alloc/wasm.rs` of the\ntoolchain that builds the shared set, 1.97.1): with `target_feature = \"atomics\"` every `alloc`, `dealloc` and\n`realloc` of the global dlmalloc takes one global lock, `static LOCKED: AtomicI32`, by spinning on\n`LOCKED.swap(1, Acquire)` — never `memory.atomic.wait`, which the main thread of a browser may not execute — and\nreleases it with `swap(0, Release)`. Without atomics the lock is a no-op (one thread). So the plain build has no\nlock and the shared build has std's; nothing of it is GripForge's code. Checked by a load test: the main thread and\ntwo Workers (each a second instance of the owner on the same memory) run 458 000 allocations, resizes and frees at\nonce — blocks of 1 byte to 128 KiB filled with a pattern of their own and checked before every resize and free,\n11 000 of them freed by another thread than the one that allocated them — without one wrong byte, on the test\nowner and on `kithost.core` (1.7 s each).\n\n**Kit code on a Worker.** A game places a kit module of the common memory on a Worker (`kitModules.placement: {\n'<kit>': 'worker' }`, the `placement` of module-calls.md §8). On a shared memory the main thread takes a stack\n(1 MiB, `threadStackBytes`) and a block for thread-locals from the allocator and hands them to the Worker with the\n`Memory` and the compiled core; the Worker's calls host instantiates **its own instance of the core on that\nmemory** (`joinCommonMemory`: `__stack_pointer` and `__wasm_init_tls` set first — the shared core exports them —,\nthen `gf_mem_thread()`, which makes that instance read the owner thread's zone, whose address the owner publishes\nin plain statics), places the relocatable kit there exactly as on the main thread (same allocator, a function\ntable of the thread), and serves the calls posted to it over the rings of the calls zone. `calls.post(kit,\nfunction, bytes)` posts such a call from the page. Verified on real kits: `combat.melee` on a Worker answers\n`mem.zone_words` — a function every kit of the common memory exposes: read words of the zone, add to each in place\n— on four columns the main thread wrote through the core, and the main thread reads the sums back, while\n`fx.hit_flash` replays its fixtures on the main thread in the same memory.\n\n**Fallback.** When the memory is not shared (the page is not cross-origin isolated, the game refused it, or the\nfolder has no shared build) the same kit stays on the main thread — `calls.threadFallbacks` names it with the\nreason — and the same call gives the same answer. Same test, both ways.\n\nWhat this does **not** do yet:\n\n- a kit on a Worker only serves posted calls: its hooks (`update`, events…) need the world, which lives in the\n  core on the main thread. Running a kit's tick on a Worker needs the world's columns in the zone (the next lot);\n- the zone may grow and move on the main thread while a Worker reads it: nothing orders the two yet;\n- the core's start function runs on the Worker before its own stack is set (it only checks the memory-initialised\n  flag; the same order as wasm-bindgen's threads);\n- a Worker's stack and thread-local block are given back when the host closes; what its kits placed is not.\n\nWhat was true before this step, for the record: the allocator of `std` built with\natomics is locked, so two threads may allocate, but a second thread needs its own instance of the core on the same\nmemory, hence its own stack and thread-local block (done above); a function table is per thread, so the kit's entry\nis linked again there; and a relocatable kit keeps its thread-locals in its data block (it exports no\n`__tls_base`), so a thread places its own copy of the kit. The runtime workspace pins Rust 1.95 without `rust-src`: the shared core is\nbuilt with the toolchain of the kit crates (`GF_SHARED_TOOLCHAIN`) — std rebuilt with atomics needs `rust-src` —\nwhich is fine across the two: only the structures of the contract and one allocator cross (§9.7).\n\n### 9.5 Tests\n\n`node --test tools/kit-modules/common-memory.test.mjs` — 21 tests.\n\n**13 always run (the CI runs them)**, on frozen binaries (`fixtures/common-memory/prebuilt`: an owner and a probe,\neach built plain and for a shared memory, and the probe built with its own memory; `fixtures/common-memory/build.mjs`\nrebuilds them):\n\n- the binaries read (`dylink.0`, the memory import) and `checkRelocatable`'s refusals;\n- one module at two addresses with separate states, a pointer made by one read by the other, a `Vec` freed by its\n  receiver, a module with its own memory in the same host, unload and load again;\n- every named error (not relocatable, relocatable declared `own`, no owner, an owner that does not import its\n  memory, no room);\n- the plan (defaults by device, the game's overrides, the schema's `memory` section, the fingerprint);\n- the structures contract: a module built against another major (or a later minor) than the owner, a structure at\n  another version or laid out differently, a module without a table — each refused by name, expected and found\n  (§9.7); the tool's check of a binary against the declarations;\n- a shared memory, with a Worker that reads a pointer in place;\n- a module placed on a Worker and called from the main thread, and its fallback on a plain memory;\n- **the allocator**: alloc / free / realloc from 1 byte to 4 MiB at alignments 1 to 64, patterns checked, no two\n  live blocks overlapping, contents kept by a resize, 20 000 random operations — on the plain and on the shared\n  build (2 tests); 300 load / unload cycles without growth; the limits (a request over the ceiling, the ceiling\n  reached, a module refused for lack of room, a kit stack that overflows into its guard: named, the other module\n  and a witness block intact); three threads at once, 150 000 operations each (`GF_ALLOC_STRESS_OPS` for a long run).\n\n**8 need what the CI does not build**: `GF_RELOC_BUILD=1` rebuilds the probes with the recipe (cargo with\n`rust-src`) and plays them; `GF_KIT_MODULES=<dir built with --common [--common-shared]>` runs seven tests on real\nkits (common and own memory in one game with the same traces, one kit at two addresses, the named refusal of a\ncore that owns its memory, the shared memory with a Worker on the zone, a kit on a Worker, the core's allocator\nunder three threads).\n\n`node qa/kit-common-page-check.mjs --kit-modules <dir> --bundle <game.json> [--compare <dir>]` plays a game through\nthe page's own loader (`loadWasmLogic` of apps/web, `?logic=kits`) outside a browser: the plan of the memory must be\nthe game's (the page gives `project` at load), no console warning, no stack overflow, the same final state as the\ncompared folder. The dungeon with its 36 kits in the common memory (2026-10-12, Node 24, main machine, load ≈ 2,\n1800 frames, not interleaved): loaded in 121 ms, 31.9 MiB of common memory, deepest kit stack 7.2 KiB, step mean\n0.68 ms against 0.83 with the kits in their own memory, final state identical. Not done in a browser: the second\nmachine's graphical session was closed that night.\n\n### 9.6 Not done\n\n- The **native host** (native/gripforge-modhost) does not know this mode: it needs the same four steps (one memory\n  handed to the core and the kits, `dylink.0`, the two blocks, the table) with its engine's API, or — for kits as\n  shared libraries — nothing at all, since a process already has one memory and one allocator.\n- The kit → kit service calls (§7.7) still push their words through the core's registers: between two kits of the\n  common memory they could hand a pointer as the core ↔ kit calls do.\n- Lists and dictionaries cross as fixed-layout blocks (§9.7), but a kit still receives its hook arguments and the\n  answers of the core as `serde_json::Value` — the type its source is written against — so each block a kit keeps is\n  copied once into one (§9.10 counts them). Reading without that copy needs kit APIs that hand out views.\n- One stack per kit module (a block): thousands of modules would rather run on the caller's stack (the core's\n  `__stack_pointer` given to every kit), which the host can do with the same binaries.\n- At unload a module drops what the calls side keeps on its heap (`gf_calls_exit`: the test probe leaves 0 bytes over\n  300 cycles); what a kit's façade keeps in its thread-locals (caches, instances) is not dropped yet. A stack\n  overflow is found after the fact, not trapped.\n- A real page in a browser with the common memory (WebGPU machine): only the page's loader was played, in Node.\n\n### 9.7 The fixed-layout value (what crosses between modules of the common memory)\n\nIn its own memory a kit receives every value as bytes: the core writes it out, the kit parses it. In the common\nmemory the bytes of a list or of a dictionary are not written into the message: the message carries **the address\nof the value**, and the value has a **layout GripForge defines** — fixed, versioned, the same whatever compiler or\nlanguage built the module. It is the model of a `.so` / `.dll`: what two modules share in one address space is\ndeclared field by field, not left to what one compiler made of its own types.\n\n(The first version of this step, 2026-10-13, passed `serde_json::Value` as itself and guarded it with a fingerprint\nof the compiler and of the crates the type is made of. It was sound but it forced every module to be built by the\nsame compiler at the same crate versions. It is gone: no Rust type crosses any more.)\n\n**The layout** (contract `gripforge-kitcall`, `src/fixed.rs`; structures version 1.0; every integer little-endian;\nan *address* is 64 bits wide whatever the address space, so the layout is the same in wasm32, wasm64 and a native\nprocess):\n\n`FixedValue` — 16 bytes, aligned on 8:\n\n| at | type | field |\n|---|---|---|\n| 0 | u8 | `tag`: 0 null, 1 bool, 2 integer (i64), 3 unsigned integer (u64 above the i64 range), 4 float (f64), 5 text, 6 list, 7 dictionary |\n| 1 | 3 bytes | reserved, 0 |\n| 4 | u32 | `len`: bytes of a text, items of a list, pairs of a dictionary; 0 for the others |\n| 8 | u64 | `data`: 0 / 1 for a bool, the integer, the bits of the float, or the **address** of the bytes (text), of `len` × `FixedValue` (list), of `len` × `FixedPair` (dictionary) |\n\n`FixedPair` — 32 bytes, aligned on 8: `key` u64 (address of the key's UTF-8 bytes) at 0, `key_len` u32 at 8, 4\nreserved bytes, `value` (`FixedValue`) at 16.\n\n`FixedBlock` — the header of a value that travels, 16 bytes followed by the root value: `magic` u32 `GFV1`\n(`0x31564647`) at 0, `version` u32 (`major << 16 | minor` of the structures) at 4, `size` u32 (bytes of the whole\nblock) at 8, 4 reserved bytes, `root` (`FixedValue`) at 16. Everything the root reaches lies **inside the block**\n(first the items and pairs, then the bytes of the texts and keys): one value is one allocation.\n\n**What a value means** — exactly what `serde_json` holds with `preserve_order` and `float_roundtrip`, which is what\nthe kits and the core compute with:\n\n- an integer and a float are two different values (`3` is not `3.0`): tag 2 is every integer that fits an i64, tag\n  3 the unsigned ones above it, tag 4 an f64 by its bits (`-0.0` stays `-0.0`; a float is never NaN nor infinite —\n  a reader that finds one reads null, as the JSON text would);\n- a text is UTF-8, not terminated, any length (0: the address is not read);\n- the pairs of a dictionary are **in insertion order**. A writer never writes the same key twice; a reader that\n  finds one keeps the place of the first and the value of the last (what inserting them in order gives).\n\n**Who owns what** (the one allocator is the core's — `gf:kithost.mem@^1` `mem_alloc` / `mem_free` — so any module\nmay free what another allocated):\n\n1. **The writer allocates** the block (`mem_alloc(size, 8)`) and fills it. A block is never changed afterwards.\n2. **The message owns it.** A message — the arguments of a call, or its answer — carries the tag `0xFD` and the\n   64-bit address of the block where a `value` is expected. The block goes with the message: to the callee for\n   arguments, back to the caller for an answer.\n3. **The reader reads it in place** (`fixed::View`: tag, numbers, `&str`, items, pairs by key — no parsing, no\n   copy), for as long as it holds the message, then **frees it** (`mem_free(address, size, 8)`). In Rust that is\n   `fixed::Owned`, which frees when dropped. A message is read once; one that nobody reads leaks its blocks (an\n   error path), nothing worse.\n4. **Keeping is copying.** A module that keeps a value after the call copies what it keeps into its own\n   representation — for a Rust kit, `serde_json::Value` (`View::to_json`), which is what `Reader::value` does for\n   every argument a kit's hook receives as `&Value`. Nothing of a block is referenced after it is freed.\n5. **Lending** (a module hands the address of a `FixedValue` it keeps owning, valid until a stated event) uses the\n   same layout without the header. Nothing lends yet; the rule is here so that the first one that does needs no\n   new structure.\n\nScalars, texts and empty containers stay inline in the message (the encoding of the calls, `.gfi`: a tag, then\nthe number or the bytes): a block for them would cost an allocation to save nothing. That encoding is bytes\ndefined by GripForge too — nothing in a message depends on a compiler.\n\n**Which traversals use it:**\n\n| traversal | lists and dictionaries | who frees the block |\n|---|---|---|\n| core → kit, the arguments of a hook (update, events delivered by call, actions, conditions, `call`…) | fixed-layout block | the kit, once read |\n| core → kit, the answer to a call of the kit (entities, components, state, config, data, input specs, zones…) | fixed-layout block | the kit |\n| kit → core, the arguments of a call | fixed-layout block | the core |\n| kit → core, the answer of a hook (`call`, `save`, `callback`, `step_*`, `spawn`, `validate`…) | fixed-layout block | the core |\n| kit → kit service by direct link (§7.7), when the core says both are in the common memory | fixed-layout block, both ways | the provider (arguments), the caller (answer) |\n| a call relayed by the core between two kits of the common memory | the caller's block, untouched | the provider / the caller |\n| events through the zone, the published input lists, entity deltas kept by revision (read by several kits, or kept) | written out (the encoding) | — |\n| a kit in its own memory, a kit on a Worker | written out | — |\n\nA reader accepts the tag `0xFD` only when its writer is known to be in the same memory: the core for a call that\ncame through `gfx_mem_call` and for the answer of a hook it entered through its function table; a kit for what\ncame through `gfx_mem_enter` and for the answers of `mem_call`; two kits when `svc_begin` said so. Elsewhere the tag\nis refused (`a fixed-layout value in a message that may not carry one`). A call between a kit of the common memory\nand one in its own memory is read and written out again by the core.\n\n**What is checked at load** — the version of the contract, not the compiler. The core and every kit carry a custom\nsection `gripforge.structs`, written by the contract crate itself from the `repr(C)` types the compiler laid out\n(`gripforge_kitcall::layout::TABLE`): the structures version, then for each structure its name, number, version,\nsize, alignment and the offset and size of every field. `ModuleCallHost.checkStructs` compares a kit of the common\nmemory with the owner before anything of it is placed:\n\n- the major of the structures version must be the owner's, and the kit's minor not above it —\n  `combat.melee@1.3.0 (memory \"common\"): structures contract 2.0, the owner (kithost.core) provides 1.0 — a kit\n  built against another major of gripforge-kitcall cannot share its memory; rebuild it against this core's contract`;\n- each structure both declare must have the same version and the same layout —\n  `… structure FixedValue@1.0: field data at 8 (8 bytes) expected, found at 12 (4 bytes)`;\n- once instantiated, `gf_layout()` (a number the compiler folds from the same table) must be the owner's.\n\nThe last two cannot fail for two modules built from the same contract by any compiler — `repr(C)` is the platform's\nC layout — and are there to catch a hand-written module, or a compiler that would not follow it. **Nothing about\nthe compiler is compared**: a kit built by another version of Rust, at other crate versions, at another\noptimisation level — or, later, in another language that fills the same structures — loads in the common memory.\n\nProved (2026-10-13): the core built by Rust 1.95.0 (the pin of the runtime workspace) with the 160 kits built\nrelocatable by Rust 1.97.1 — see §9.10. `tools/kit-modules/build.mjs` no longer forces one toolchain on both.\n\nTests: `cargo test -p gripforge-kitcall` (round trips with `serde_json::Value` — integer and float limits, empty\nand long UTF-8 texts, deep nesting, the order of keys, duplicate keys in a hand-made block —, the layouts pinned by\nconstant assertions, reading in place, the refusal of a reader outside the memory, of a block cut short or of\nanother version); `common-memory.test.mjs` (the refusals of `checkStructs` by name on frozen binaries; on real\nkits: the same table in the core and a kit, blocks passed, a kit of another contract major refused by name);\nand — on a folder whose core and kits come out of two compilers, which is what the build makes by default — the two\nbinaries named by their `rustc` commits, one memory, the fixtures identical).\n\n### 9.8 Measured after values are passed as themselves, and what is left\n\n*(History: this section measures the first version of §9.7 — `serde_json::Value` passed as itself under a compiler\nfingerprint — which the fixed-layout value replaced. Its numbers and its profile are what led there; the measures of\nthe fixed-layout value are in §9.10.)*\n\nParity (2026-10-13): **721 identical, 0 differ** with the 160 kits in the common memory (the default build) and\nvalues passed as themselves; the third-party tests pass with a kit in its own memory beside them.\n\nThe dungeon against the single wasm, same method as §9.3 (second machine, load 0.1 – 1.1, 5 interleaved runs of 1800\nframes, the same final state in every run):\n\n| build | step, kits / single wasm (median; range) | best run, ms per frame |\n|---|---|---|\n| every kit in its own memory | ×1.83 (1.82 – 1.86) | 0.692 |\n| the 36 kits in the common memory, values still written out (§9.3) | ×1.60 (1.57 – 1.61) | 0.588 |\n| the same with values passed as themselves | ×1.62 (1.61 – 1.63) | 0.595 |\n\n**Passing the values gained nothing here** (inside the spread, if anything a hair slower), and the counts say why:\non this base a frame of the dungeon makes 181 calls between the core and the kits, of which **137 are direct links\nthat carry scalars** (the work of §7), 29 are hooks and 14 are calls with a value — the core passes **10 values a\nframe**. What was encoded and parsed had already been taken off the frame; and a value passed to a reader that\nkeeps it is still one copy (a clone into a box instead of a parse into a value: the same allocations). The\nmechanism is what the next steps need — the fingerprint is what allows a kit to read the core's values **in place**,\nwith no copy at all — but by itself it is not a speed-up, and nothing more should be expected of it on this scene.\n\nWhere the step goes now (a CPU profile with names, 6000 frames, Node, main machine under load 4 — the shares\nmatter, not the microseconds): the kits 372 µs a frame, spread thin (the largest, `character.top_down`, 37 µs), the\ncore 592 µs (of which its allocator ≈ 105 µs, the frame written for the player ≈ 130 µs, Rapier ≈ 45 µs). In the\nkits and at their border, by size:\n\n1. **copies of values inside the kits** ≈ 33 µs (`IndexMap` buckets and `Vec<Value>` cloned: the façade's copies of\n   entities and components, which a kit of the single wasm reads in place) — removed by lending the core's value\n   instead of handing a copy, which is what the fingerprint now makes sound;\n2. **entering a hook** ≈ 40 µs for 29 hooks (`host::entry` 24, `Host::enter` 9, `gfx_mem_enter` 8): the context\n   decoded and the façade's caches checked at each entry;\n3. **kit → kit service calls** ≈ 25 µs for 26 calls (`gfx_svc_call`, `Kx::call`, `svc::begin`, the words pushed\n   through the core): still written out and parsed on both sides;\n4. the façade's bookkeeping (`reads_stale`, `direct::atom`, a table cloned) ≈ 20 µs.\n\n### 9.9 Where the gap to the single wasm is (differential profile, 2026-10-13)\n\nSame toolchain and profile on both sides this time (the single wasm rebuilt at the same commit with Rust 1.97.1,\nprofile `kithost-wasm`: the reference used until here was an older build, 14 % slower — every ratio above is that\nmuch too kind to the kits). Second machine, load 0.1 – 0.5.\n\n| game | kits | entities | calls core ↔ kit per frame (direct scalar / hooks / with a value) | step single | step kits | gap | ratio (interleaved, 5 runs) |\n|---|---|---|---|---|---|---|---|\n| dungeon | 36 | 163 | 181 (137 / 29 / 14) | 0.321 ms | 0.591 ms | 0.27 ms | ×1.84 (1.80 – 1.89) |\n| car football (`arena_car`: 3 v 3, bots) | 24 | 19 | 374 (231 / 16 / 126, of which physics 66, world 55) | 0.333 ms | 0.952 ms | 0.62 ms | ×2.88 (2.84 – 2.88) |\n\nThe gap is **not a fixed cost per kit** (fewer kits, a larger gap): it follows the calls — 1.6 µs of wasm time per\ncall in both games (292 µs / 181 and 585 µs / 374 in the profiles below) — and most of all the calls that carry a\nvalue. Allocations per step (`--features alloc-count`, `GF_CORE_FEATURES=alloc-count`): dungeon 2428 in the single\nwasm, 3056 with kits (+26 %); car football 2573 against 8796 (×3.4).\n\nSelf time by family of functions (V8 CPU profile, names kept, 6000 frames, µs per frame; single → kits):\n\n| family | dungeon | car football |\n|---|---|---|\n| the façade (`gripforge-kit-guest`: caches, revisions, entering) | 0 → 112 | 0 → 134 |\n| allocator | 48 → 89 | 60 → 217 |\n| border: hook entry, `svc`, transport | 0 → 54 | 0 → 35 |\n| codec (`Reader` / `Writer`) | 0 → 37 | 0 → 110 |\n| the core serving kit calls | 0 → 13 | 0 → 31 |\n| values (clone, drop, index, maps) | 69 → 67 | 67 → 106 |\n| hashing | 36 → 43 | 34 → 62 |\n| the logic itself (host + kits) | 77 → 86 | 73 → 108 |\n| physics engine | 56 → 67 | 43 → 56 |\n| the frame written for the player, memcpy | 84 → 93 | 24 → 29 |\n| **total wasm** | **371 → 663 (+292)** | **303 → 888 (+585)** |\n\nOne-factor trials on the dungeon (interleaved ratio against the old reference): every kit at opt-level 3 instead\nof `s` ×1.62 → ×1.57 (−3 %, +22 % of bytes). Not isolated: the cost of position-independent code (it is inside « the\nlogic itself »: +9 and +35 µs, with the opt level and the duplicated generic code), and the step by phase (the\nprofile is by function family, sampled, not by counters at the phase boundaries).\n\n### 9.10 Acting on it: the physics port by scalars, and the whole list kept\n\nThree things were done on the calls that carry a value (commits `cb5c1ebc9`, `826453140`; parity 721 identical, 0 differ, after each):\n\n- **`kithost.physics@1.1` and `kithost.platform@1.1`, direct links.** What a kit asks of the physics many times a\n  tick — `has_body`, `body`, `set_body`, `set_position`, `apply_impulse` / `apply_force` / `apply_torque_impulse`,\n  `mass`, `grounded`, `has_character`, `character_grounded` — and the date (`now`) are wasm-to-wasm calls of\n  scalars: the entity id packed in two `u64`, vectors as three `f64`, and the state of a body as **14 `f64` at an\n  address the caller names** (position 3, rotation 4, linear velocity 3, angular velocity 3, sleeping), read and\n  written in place — hence for kits of the common memory; a kit in its own memory, or an id longer than 16 bytes,\n  takes the call as before. The kits' source does not change (`PhysicsPort` of the façade tries the link first).\n  What stays a call: adding and removing bodies, the character controller's move, ray casts and overlaps, contacts.\n- **`entities.all()` no longer copies the world.** The allocation count by function (`gf_alloc_by_fn`, feature\n  `alloc-count`) showed where the car football's allocations came from: `all()`, 3.6 calls a frame, **1671\n  allocations a call** — 6000 of the 8800 a frame — because the façade read the whole list again, every entity\n  copied, each time the world had changed (in the single wasm `all()` copies nothing). The façade now keeps that\n  list and, while the structure of the world is the same, asks only what changed in each entity since the revision\n  it holds (`get_many_if`) and applies it in place.\n\n| car football (`arena_car`) | before | physics by scalars | + the list kept | + deltas written out | single wasm |\n|---|---|---|---|---|---|\n| calls with a value per frame (physics / world / platform) | 126 (66 / 55 / 5) | 57 (1 / 55 / 0) | 57 (1 / 55 / 0) | 57 | — |\n| allocations per step | 8796 | 8676 | 3716 | **3440** | 2573 |\n| step single / kits, ms (second machine, best run) | 0.333 / 0.958 | 0.334 / 0.941 | 0.332 / 0.622 | 0.330 / 0.619 | — |\n| gap, ms per frame | 0.62 | 0.61 | 0.29 | 0.29 | — |\n| ratio (interleaved, 5 runs; range) | ×2.88 (2.87 – 2.90) | ×2.82 (2.78 – 2.86) | **×1.89** (1.86 – 1.90) | ×1.87 (1.87 – 1.91) | 1 |\n\n(Second machine under `flock measure.lock`, load 0.2 – 1.9 for the first two columns, 2.3 – 3.3 for the last two:\nother measures ran there; the ratios are interleaved frame by frame.)\n\n- **The deltas of an entity are written out, even to a kit of the common memory** (the third step): the reader brings\n  its copy up to date in place (`Reader::value_into` reuses the map, the keys and the buffers it holds: nothing is\n  allocated when the shape is the same), where a value passed as itself (§9.7) is a whole new copy that replaces the\n  old one. Passing was the more expensive way here: `get_many_if` went from 350 allocations a frame to none.\n\nOn the dungeon nothing of this weighs (3 physics calls a frame, no `all()`): ×1.84 before, then ×1.85, ×1.84 and\n×1.83 after each step; 3056 → 3050 allocations per step, 14 → 11 calls with a value.\n\nThe physics calls were numerous but cheap (strings and numbers, no value): moving them changed little by itself.\nThe allocations were one function. What is left with a value on this game is the world's: components read and\nwritten as objects (`component` 19 a frame, `set` 14, `set_transform` 6, the deltas 18) — the object itself, which\nthe in-place reading of values (another lot) is for.\n\n### 9.11 Short entries: per-tick hooks and scalar service calls (2026-10-13)\n\nWhat §9.9 calls « border: hook entry, `svc`, transport » is paid at every tick by every kit, whatever the kit does.\nBetween modules of the common memory it is now a call through the function table with scalars and addresses\n(`native/gripforge-kitcall/src/fast.rs`: `repr(C)` types with fixed-size fields, nothing that depends on how the\ncompiler lays out a Rust type).\n\n**Resolved once, when the kit module is registered.** A kit module of the common memory names two of its functions\nin its `INFO` (`tick`, `svc`: their indices in the function table — the table of the common memory is one, so the\nindex a kit gives is the function for the core and for the other kits). The core keeps them as function pointers\nin its `RemoteKit` (`set_fast`), only for a kit module the host linked by pointer (`gf_mem_link`); unlinked, they\nare dropped. A kit module in its own memory, on a Worker, or built before this: no short entry, the general one —\nboth kinds live in one game, as before. No lookup by handle or by name at a call, and no JavaScript (there was\nnone since §9.1).\n\n**Per-tick hooks** (`update`, `late_update`, `update_idle`; `fast::Tick(func, ctx, dt)`). The context is a struct\npassed by address (`HookCtx`) where the general entry writes eight varints into a buffer it allocates and the kit\nreads them back; the kit finds its instance without a search (the last one entered is kept), calls the hook and\nanswers a status — no answer buffer. Around the call the core does what it always did: the kit is the one that\nruns (its calls to the core are served on its `Kx`), the zone speaks of this host. A status other than 0 means\nnothing ran (no such instance): the core takes the general entry, which reports it as before. The other hooks\n(`setup`, `on_event`, `action`, `save`…) keep the general entry: they carry values and do not run every tick.\n\n**Kit → kit service calls with scalar arguments** (`fast::Service`). `kx.call(capability, method, args)` to a\ncapability another kit module of the common memory serves, when every argument is null, a boolean, a number or a\nstring (at most 6): the caller asks the core `mem_svc_open(capability, provider)` (`kithost.mem@1.1`) — the same\nquestion as `svc_begin` (§7.7: is the capability served, in this host and now, by the kit module the caller is\nlinked to), the same care (the bindings drained before and after, the provider's own `Kx` running until\n`svc_end`) — and gets the provider's scalar entry and the address of its context. It calls that function with\nthe names of the capability and of the method by address (no atom looked up), and the arguments as 24-byte\nscalars: numbers and booleans by value, strings by address — the provider reads them where the caller holds\nthem, for the time of the call. Nothing is written in the codec, no word goes through the core, no `Vec` is made.\nThe answer is a scalar by value, or a string given away (one allocator); a **free value** (an object, an array)\ncomes back as its bytes of the codec, given away — the format of values is not this section's business. A free\nvalue among the arguments, or more than 6: the words of §7.7, unchanged. Numbers keep the kind the codec gives\nthem (an integer that fits an `i64` stays one, anything else is an `f64`), so `as_u64()` answers the same by\neither path. What the core resolves for a capability (who serves it, its entry) is kept by capability and is\nvalid for one state of the host's services (`services_gen`) and of the short entries: a kit that replaces the\nprovider, a module unlinked, and the next call asks again.\n\n**An interceptable decision nobody intercepts.** `Host::decide(hook, payload)` (the `decide` of\ndocs/mods-engine.md: the hooks a tap of a kit, of the project or of a mod may change or cancel) reads\ngame.engine's table of taps first. No tap for this hook: the answer of the pipeline for an empty list —\n`{ ok: true, payload, cancelled: false, reason: null, by: null, notes: [] }` — is made from the payload itself:\nno service call, no entry into game.engine, no copy of the payload. The table is read at each decision, so a tap\nadded while the game runs (in code, or a document of the `hooks` collection a reaction adds) is asked at the very\nnext one; with a tap, the pipeline is the one of before — same order (priority, layer, registration), same\nrights (`mutable`, `cancellable`, a refusal said on the bus). Another kit that took `engine.hooks` over: the full\npath, always.\n\n**Turned off for a test or a measure**: the core's `gf_mem_fast(0)` (`kitcall::set_fast`) sends every hook and\nevery service call back to the general entry — the same game, tick for tick, with the same binaries\n(`qa/kithost-wasm-bench.mjs --sides wasm,kits-general,kits`).\n\nTests: `cargo test -p gripforge-kitcall` (a scalar means what the codec means, kinds of numbers included);\n`cargo test -p gripforge-kithost --features kitcall --test kit_fast` (two kit modules played in process: the same\ntrace and state by the short and by the general entries, the same answers of 21 service calls — scalars, a free\nvalue back, an error —, who runs while a provider serves, the entry not opened to a provider that does not serve\nthe capability, unlinked, or switched off); `cargo test -p gripforge-kithost game_engine` (an untapped hook\nanswers the same by the short path, key order included; a tap added while playing is asked at the next decision;\norder, `mutable`, `cancellable`, refusals; a tap in data); `tools/kit-modules/common-memory.test.mjs` with\n`GF_KIT_MODULES` (real kits: the same traces with the short entries on and off, the same hooks counted, the same\nnumber of service calls — by the scalar entry, direct link 41, where the general one counts 40).\n\nMeasured (second machine, load 0.8 – 2.2, Node 24, 5 runs × 1800 frames interleaved frame by frame with the single\nwasm rebuilt at the same commit with the kits' toolchain; same final state 5 / 5 everywhere, parity 721 / 721).\nBefore = the kit modules of §9.9 (this work without the physics port of §9.10, so that only the entries differ):\n\n| game | hooks / kit → kit service calls per frame (of which by the scalar entry) | step single | step kits before | step kits after | ratio before → after |\n|---|---|---|---|---|---|\n| dungeon | 29 / 26 (25) | 0.317 – 0.325 ms | 0.592 – 0.610 ms | **0.519 – 0.536 ms** | ×1.86 (1.82 – 1.86) → **×1.63** (1.62 – 1.66) |\n| car football (`arena_car`) | 16 / 21 (15: 6 carry a free value) | 0.331 – 0.334 ms | 0.950 – 0.964 ms | **0.915 – 0.942 ms** | ×2.87 (2.86 – 2.88) → **×2.77** (2.75 – 2.82) |\n\nThe same binaries with the short entries off (`kits-general`), played in one process with the two others: dungeon\n0.595 – 0.624 ms against 0.479 – 0.488 with them on, car football 0.929 – 0.942 against 0.862 – 0.870 (a process of\nthree sides: its times do not compare with the table's, only with each other).\n\nSelf time by family (the profile of §9.9 again: names kept, 6000 frames, µs per frame; before → after):\n\n| family | dungeon | car football |\n|---|---|---|\n| border: hook entry, `svc`, transport | 54 → 35 | 35 → 29 |\n| codec (`Reader` / `Writer`) | 37 → 22 | 110 → 97 |\n| the façade | 112 → 103 | 134 → 130 |\n| allocator | 89 → 83 | 217 → 213 |\n| **total wasm** | **663 → 598** | **888 → 872** |\n\nWhat is left in the border of the dungeon (35 µs): the short entry itself with what the compiler folded into it\n(`host::tick` 10), `Host::enter` of the façade (6: the reads kept from before are dropped at every entry), the\nscalar service entry (3.6), the core's side (`RemoteKit::tick`, `update`: 4), and the general entry for what still\ntakes it (events, 1 service call a frame: 8).\n\n**Cumulated with §9.10** (rebased on `640e5fa67`: the physics port by scalars, `entities.all()` kept, the deltas\nwritten). Second machine, load 2.2 – 3.8, 3 rounds × 1800 frames, each build interleaved two by two with the single\nwasm rebuilt at the commit of the cumulated build; medians of the rounds, ratio with its range; same final state in\nevery run. « §9.10 alone » is the cumulated build with `gf_mem_fast(0)`; « §9.11 alone » is this work on the commit\nof §9.9.\n\n| game | build | step single | step kits | gap | ratio |\n|---|---|---|---|---|---|\n| dungeon | start (§9.9) | 0.326 ms | 0.602 ms | 0.276 ms | ×1.85 (1.83 – 1.87) |\n| | §9.10 alone | 0.321 | 0.605 | 0.284 | ×1.87 (1.84 – 1.89) |\n| | §9.11 alone | 0.327 | 0.532 | 0.205 | ×1.63 (1.63 – 1.66) |\n| | both | 0.322 | **0.529** | **0.207** | **×1.64** (1.64 – 1.64) |\n| car football | start (§9.9) | 0.338 | 0.981 | 0.643 | ×2.90 (2.85 – 2.92) |\n| | §9.10 alone | 0.331 | 0.623 | 0.292 | ×1.89 (1.88 – 1.89) |\n| | §9.11 alone | 0.334 | 0.924 | 0.590 | ×2.76 (2.74 – 2.78) |\n| | both | 0.333 | **0.586** | **0.253** | **×1.76** (1.73 – 1.77) |\n\nThe two add up: the dungeon gains nothing from §9.10 and 0.07 ms from the entries; the car football gains 0.35 ms\nfrom §9.10 and 0.04 more from the entries. What is left, by family (profile of the cumulated build, 6000 frames,\nµs per frame; single wasm of §9.9 → kits):\n\n| family | dungeon | car football |\n|---|---|---|\n| the façade (`gripforge-kit-guest`) | 0 → 104 | 0 → 100 |\n| allocator | 48 → 81 | 60 → 102 |\n| values (clone, drop, index, maps) | 69 → 65 | 67 → 71 |\n| the logic itself (host + kits) | 77 → 85 | 73 → 98 |\n| codec (`Reader` / `Writer`) | 0 → 23 | 0 → 48 |\n| border: hook entry, `svc`, transport | 0 → 36 | 0 → 27 |\n| hashing | 36 → 42 | 34 → 43 |\n| the core serving kit calls | 0 → 12 | 0 → 17 |\n| physics engine | 56 → 67 | 43 → 56 |\n| the frame written for the player | 80 → 90 | 22 → 27 |\n| **total wasm** | **371 → 610** | **303 → 594** |\n\nThe façade is now the first cost of both games, then the allocator.\n\n**The MOBA** (preset `moba`: 36 kits, 134 entities after 1800 frames, minions that look for targets every tick) is\nthe heaviest game there is, and the one where the modules cost most. One round on the second machine (load 1.4 –\n1.8, 1800 frames interleaved with the single wasm of the cumulated commit; the other rounds waited behind a lock\nheld 35 minutes by another measure and are not in this table):\n\n| build | step single | step kits | gap | ratio |\n|---|---|---|---|---|\n| integration `955294799` (the physics port of §9.10 in part, a size-class allocator in the core, none of the rest) | 2.05 ms | 5.24 ms | 3.19 ms | ×2.56 |\n| `640e5fa67` (§9.10 complete, the core's allocator of `std`) | 2.07 | 6.21 | 4.13 | ×3.00 |\n| cumulated, short entries off | 2.05 | 6.17 | 4.12 | ×3.01 |\n| cumulated (§9.10 + §9.11) | 2.04 | **5.76** | **3.72** | **×2.82** |\n\nThe short entries take 0.41 ms off (the game makes 354 scalar service calls a frame, 84 more with a free value, 33\nhooks). The integration branch is 1 ms ahead of `640e5fa67` on this game: what it has and this branch has not is\nits allocator (not isolated here; `alloc-count` does not build on it — two global allocators).\n\nCalls per frame (the same on the three builds): 22 695, of which direct links 19 890 — `hot_epoch` 11 308,\n`w_component` 5 285, `w_transform` 2 325, `w_has` 363, service calls 438 — and calls with a value 2 771, of which\n`world.component` (`0x103`, a component that is an object) 2 640. Allocations per step (`alloc-count`): 23 234 in the\nsingle wasm, 75 388 with kits at `640e5fa67`, 72 376 cumulated (3.7 MB asked per step against 1.3).\n\nWhere it goes (profile with names of the cumulated build, 3000 frames — the game is heavier at the end: 14.8 ms a\nstep —, taken on the main machine at load 0.8 – 1.5 because of that lock: shares, not absolute times; µs per\nframe): the façade 3 636, allocator 2 983, codec 1 629, values 1 476, the core serving the calls 1 278, hashing\n1 225, the kits' own code 1 099, the core's own 1 024, border (entries, `svc`) 422. By module: the core 8 129,\n`combat.core` 4 131, `minion.waves` 1 151, `moba.lanes` 849, every other kit under 180. One loop is most of it:\n`combat.core` `targets_near` reads a component and a transform of every entity for every unit that looks for a\ntarget. Per read: the façade hashes the component's name (`direct::atom` 287) and asks the world's epoch by a call\n(`hot_epoch`: 11 308 calls), `Entities::component` + `current` + `AtEpoch::component` 1 533; the core hashes the\nentity's id with SipHash (`hash_one` 508 + `Hasher::write` 346), looks the component up by name (`IndexMap::\nget_index_of` 366, `Entities::get` 379), and for an object clones it for the kit (`Bucket::clone` 299, then\n`malloc` 1 123, `free` 680, `dealloc` 498). The cost follows the number of reads (units × entities), not the\nnumber of entities alone: the dungeon has more entities (163) and 10 world calls with a value a frame.\n\nNot in the entries (2.7 % of the profile). What would remove it, in the world's façade (another lot): the epoch\nread in the zone instead of asked 11 308 times; the atom of a component kept at the call site instead of hashed\nat each read; entities addressed by a number (slot + generation) instead of a string hashed twice; an object\ncomponent lent in place instead of cloned (the 2 640 calls and most of the 49 000 allocations a step more than\nthe single wasm); and the allocator of the integration branch kept at the merge.\n\nNot done: the hooks that carry values (`on_event` by the queue is already one wake-up per run of deliveries; `on_var`,\n`action`, `condition`, `callback` are encoded), service calls with free values (waiting for the format of values),\n`Host::enter` of the façade (what a kit read before is dropped at every entry: it goes with reading the core's values in\nplace), and a way for a kit to ask « is this hook tapped? » before it builds the payload (`Kx::decide` takes the\npayload already built: the short path saves the call and the copies, not the construction).\n\n### 9.12 The fixed-layout value, measured (2026-10-13)\n\n*Measured on the branch of the fixed-layout value alone, before it was joined with §9.10 and §9.11. Where this\nsection says `all()` reads through the copies kept by revision, the code that is kept is the list of §9.10\n(brought up to date in place); the rest stands.*\n\n**Two compilers, one memory.** The default build now takes the core from the toolchain its workspace pins (Rust\n1.95.0, commit `59807616e`) and the 160 kits, relocatable, from the active one (Rust 1.97.1, commit `8bab26f4f`).\nThey load in one memory and `qa/kithost-wasm-parity-check.mjs --kit-modules <dir>` answers **721 identical, 0\ndiffer** (deepest kit stack 22.8 KiB, `quest.graph`). The test `real kits: the core and the kits come out of two\ndifferent compilers…` of `common-memory.test.mjs` replays it on any folder built that way: it reads the `rustc`\ncommit each binary kept, checks they differ, checks both carry the declared structures table, and plays the\nfixtures. (Rust 1.95.0 has no `rust-src` here, so the *kits* could not be the 1.95 side: the relocatable recipe\nrebuilds `std`. The core does not need it.) The 41 kits of the two games below weigh 14.1 MB against 13.5 MB at\n`65f113c0f` (+4 %: the writer and the reader of blocks, the table); the 160 kits, 49.1 MB.\n\n**Speed.** Same method as §9.3 and §9.9 — second machine, 5 interleaved runs of 1800 frames, the kit modules against\nthe single wasm **rebuilt at the same commit with the same toolchain (1.97.1) as the core of the measured folder**,\nthe same final state in every run; the machine was shared with other measures (load 0.4 – 2.7, one at a time under a\nlock). \"Before\" is `65f113c0f` (values passed as themselves, §9.8), \"after\" this branch:\n\n| game | before | after | allocations per step, before → after (single wasm) |\n|---|---|---|---|\n| the dungeon (36 kits) | ×1.85 (1.84 – 1.86), 0.596 ms | ×1.86 (1.84 – 1.87), 0.603 ms | 3056 → 3015 (2428) |\n| `arena_car` (24 kits) | ×2.90 (2.88 – 2.92), 0.966 ms | **×2.49** (2.48 – 2.53), 0.837 ms | 8796 → 5543 (2573) |\n\nThe dungeon does not move: it passes 17 blocks a frame. `arena_car` loses 13 % of its step, and that needs the\nwhole story, because the layout alone made it *slower*:\n\n1. With only the fixed-layout value in place (and entities and events read in place) `arena_car` went from ×2.90 to\n   **×3.23** (0.952 → 1.092 ms) while its allocations fell (8796 → 8028). The profile named it: `sport.ball` 115 →\n   209 µs a frame, the kits' share of the conversions 45 → 99 µs. That kit asks for every entity three times a\n   frame (`entities.all()`: 57 entities). Before, the core cloned each and the kit *took* the Rust value — no work\n   on the kit's side; with a layout no compiler owns, the kit has to **build** its `serde_json` values from the\n   block (allocations, and one hash per key of every map). That is the price of the stable layout wherever a kit\n   keeps what it is sent.\n2. So `all()` stopped sending entities: it is now the query that filters nothing, read through the copies the façade\n   keeps by revision (§7.5) — only what changed since the last read crosses, an unchanged entity is one clone of the\n   copy the kit already has. That gave ×2.49 and 5543 allocations. Nothing of it depends on a compiler either.\n\n**What a kit still copies** (`gf_fixed_stats`, exported by every module of the common memory; 600 frames):\n\n| game | blocks the kits receive per frame | copied whole into a value the kit keeps | written over a copy it had (no allocation when the shape is the same) | read in place |\n|---|---|---|---|---|\n| the dungeon | 17 | 10 (`character.top_down` 4, `combat.core` 2, five kits 1) | 7 | 0 |\n| `arena_car` | 66 | 20 (`vehicle.driveable` 16, three kits 1 – 2) | 46 | 0 |\n\nand the core copies 0.2 (the dungeon) and 18 (`arena_car`: the arguments of the physics port, which the direct\nscalar links of the next lot remove). \"Read in place\" is 0 on these two games after step 2 — the in-place readers\n(an event from a hook, a list of entities from `query` without the kept copies) serve the paths these games no\nlonger take. **The copies that remain are the answers a kit's source receives as an owned `serde_json::Value`**\n(`component`, `get`, a service's answer): as long as a kit's source is written against that type, a value it is\nhanded is a copy. Removing them means kit APIs that hand out a view (`fixed::View`) — a change of the kits'\nsources, kit by kit, starting with the ones named above.\n\n**By family of functions** (the profile of §9.9: V8 CPU profile with names, 6000 frames, self time in µs per frame,\nsecond machine, one run each — not interleaved, so a few percent of drift between two columns is the machine):\n\n| family | the dungeon, before → after | `arena_car`, before → layout alone → after |\n|---|---|---|\n| total wasm | 667 → 709 | 905 → 1019 → **801** |\n| conversions (`gripforge-kitcall`: writer, reader, blocks) | 41 → 46 | 109 → 152 → 69 |\n| allocator | 88 → 91 | 214 → 231 → 184 |\n| values (clone, drop, index, maps) | 66 → 70 | 120 → 134 → 85 |\n| hashing | 44 → 45 | 64 → 74 → 45 |\n| façade + border (the entry of a hook moved from one to the other with its name) | 166 → 179 | 168 → 167 → 198 |\n| core: serving the kits' calls | 13 → 14 | 33 → 31 → 17 |\n\nOn the dungeon the profile run of \"after\" was 4 – 5 % slower in every family, the untouched ones too (the frame\nwritten for the player 87 → 91, the physics engine 68 → 72): the interleaved runs above are the comparison, and\nthey say unchanged. On `arena_car` the conversions, the allocator, the values and the hashing all fall, and the\nfaçade grows by 30 µs — the clones of the kept copies and their revision checks are counted there: the next thing\nto remove (a list of entities handed out without cloning the ones that did not change).\n\n**Not measured**: a browser page; the speed of the shared-memory build (it was rebuilt and its tests replayed —\n`common-memory.test.mjs` 22 / 22 with `GF_RELOC_BUILD=1` on a folder with two kits in the common memory, plain and\nshared, and one in its own — but not benched); memory over a long game.\n\n## 10. Other paths\n\n- **Native**: the same kit modules as `.so` / `.dll` / `.dylib` with the same `gf_*` exports, loaded by a native\n  calls host (module-calls.md §14).\n"
 },
 {
  "id": "kit-structures",
  "title": "Memory structures of the kit modules",
  "summary": "Every structure modules share in memory, in one page: the fixed-layout value (FixedValue, FixedPair, FixedBlock), Bytes, Ctx, the records of the shared zone — who owns each, who reads and writes it, its version and its layout byte by byte; what a module in another language must do.",
  "source": "docs/kit-structures.md",
  "text": "# Memory structures of the kit modules\n\n<!-- Generated by tools/kit-modules/structs.mjs from native/gripforge-kitcall/structs.json — do not edit: run `node tools/kit-modules/structs.mjs --write`. -->\n\nStructures contract **1.0** — every structure that modules of a game read or write in memory they\nshare (the common memory of the kit modules, the shared zone), in one place: who owns it, who reads and writes it,\nhow long it is valid, and its layout byte by byte.\n\n- **A layout GripForge defines.** Nothing here depends on a compiler or on a language: integers are little-endian,\n  a field lies at the next multiple of its alignment (the C layout rules), an *address* in a `Fixed*` structure is\n  64 bits wide whatever the address space. A kit written in any language that fills these bytes is a valid peer.\n- **Versioned.** The contract has a version (`major.minor`), and so has each structure. A structure added, or a\n  field added in reserved bytes: a minor. A size, an offset or a meaning changed: a major.\n- **Declared by each module.** Every kit module and the core carry the table of these structures as their own\n  compiler laid them out (custom section `gripforge.structs`); the build checks it against this page's source\n  (sizes and offsets are computed by the tool, then compared with the binary), and writes in the manifest of each\n  module the contract it was checked against and its role (`kit-modules.json`: `structs`, the layouts and who reads or\n  writes each; `core.structs` / `kits.<id>.structs`, the role of the module).\n- **Checked at load.** A kit of the common memory whose contract major is not the core's — or whose minor is\n  later — is refused by name, with what was expected and what was found. The compiler is never compared.\n\nHow values travel with these structures, and the ownership rules in full: [kit-modules.md §9.7](kit-modules.md).\nThe shared zone: [kit-modules.md §7](kit-modules.md). The game schema that sizes it: [game-schema.md](game-schema.md).\n\n## Index\n\n| structure | n° | version | bytes | align | the core | a kit |\n|---|---|---|---|---|---|---|\n| [`FixedValue`](#fixedvalue) | 1 | 1.0 | 16 | 8 | reads and writes | reads and writes |\n| [`FixedPair`](#fixedpair) | 2 | 1.0 | 32 | 8 | reads and writes | reads and writes |\n| [`FixedBlock`](#fixedblock) | 3 | 1.0 | 32 | 8 | reads and writes | reads and writes |\n| [`Bytes`](#bytes) | 4 | 1.0 | 12 | 4 | reads and writes | reads and writes |\n| [`Ctx`](#ctx) | 5 | 1.0 | 48 | 8 | writes | reads |\n| [`ZoneBuffer`](#zonebuffer) | 16 | 1.0 | 16 | 4 | writes | reads |\n| [`ZoneDirectory`](#zonedirectory) | 17 | 1.0 | 256 | 8 | writes | reads |\n| [`ZoneInputHeader`](#zoneinputheader) | 18 | 1.0 | 32 | 8 | writes | reads |\n| [`ZoneInputRecord`](#zoneinputrecord) | 19 | 1.0 | 32 | 8 | writes | reads |\n| [`ZoneInputList`](#zoneinputlist) | 20 | 1.0 | 16 | 4 | writes | reads |\n| [`ZoneStateHeader`](#zonestateheader) | 21 | 1.0 | 4 | 4 | writes | reads |\n| [`ZoneEventsHeader`](#zoneeventsheader) | 22 | 1.0 | 32 | 8 | writes | reads |\n| [`ZoneEventRecord`](#zoneeventrecord) | 23 | 1.0 | 8 | 8 | writes | reads |\n| [`ZoneRegionsHeader`](#zoneregionsheader) | 24 | 1.0 | 8 | 8 | writes | reads |\n\n## FixedValue\n\nOne value of free shape, read in place: a tag, a length and 8 bytes of data — the number itself, or the address of the bytes of a text, of the items of a list, of the pairs of a dictionary. Same meaning as a JSON value that keeps integers apart from floats and the order of its keys.\n\n- **Version** 1.0 · number 1 · 16 bytes, aligned on 8 · `repr(C)`\n- **Owner**: the module that wrote the block it lies in (until the block is handed over with a message).\n- **The core** reads and writes it; **a kit** reads and writes it.\n- **Where**: inside a FixedBlock (or lent by its owner).\n- **Valid**: as long as its block.\n\n| at | bytes | type | field | meaning |\n|---|---|---|---|---|\n| 0 | 1 | `u8` | `tag` | 0 null, 1 bool, 2 integer (i64), 3 unsigned integer (u64 above the i64 range), 4 float (f64), 5 text, 6 list, 7 dictionary |\n| 1 | 3 | `u8[3]` | `reserved` | 0 |\n| 4 | 4 | `u32` | `len` | bytes of a text, items of a list, pairs of a dictionary; 0 for the others |\n| 8 | 8 | `u64` | `data` | 0 or 1 (bool), the integer, the bits of the float, or the address of the text bytes / of len FixedValue / of len FixedPair |\n\n## FixedPair\n\nOne pair of a dictionary. The pairs of a dictionary are contiguous, in insertion order; a reader that finds the same key twice keeps the place of the first and the value of the last.\n\n- **Version** 1.0 · number 2 · 32 bytes, aligned on 8 · `repr(C)`\n- **Owner**: as FixedValue.\n- **The core** reads and writes it; **a kit** reads and writes it.\n- **Where**: inside a FixedBlock.\n- **Valid**: as long as its block.\n\n| at | bytes | type | field | meaning |\n|---|---|---|---|---|\n| 0 | 8 | `u64` | `key` | address of the UTF-8 bytes of the key (not terminated) |\n| 8 | 4 | `u32` | `key_len` | bytes of the key |\n| 12 | 4 | `u32` | `reserved` | 0 |\n| 16 | 16 | `FixedValue` | `value` | the value of the key |\n\n## FixedBlock\n\nThe header of a value that travels between two modules of the common memory: ONE allocation of the one allocator (alignment 8) that holds the root and everything it reaches — first the items and pairs, then the bytes of the texts and keys. A message carries its address after the tag 0xFD where a value is expected.\n\n- **Version** 1.0 · number 3 · 32 bytes, aligned on 8 · `repr(C)`\n- **Owner**: the writer allocates it (mem_alloc(size, 8)); the message owns it; the reader of the message reads it in place, copies what it keeps and frees it (mem_free(address, size, 8)).\n- **The core** reads and writes it; **a kit** reads and writes it.\n- **Where**: a block of the one allocator (kithost.mem@1).\n- **Valid**: from the write to the read of the message that carries it; never changed in between.\n\n| at | bytes | type | field | meaning |\n|---|---|---|---|---|\n| 0 | 4 | `u32` | `magic` | GFV1 (0x31564647) |\n| 4 | 4 | `u32` | `version` | structures version of the writer, major << 16 | minor (a reader refuses another major) |\n| 8 | 4 | `u32` | `size` | bytes of the whole block: what is given back to the allocator |\n| 12 | 4 | `u32` | `reserved` | 0 |\n| 16 | 16 | `FixedValue` | `root` | the value |\n\n## Bytes\n\nA buffer of bytes handed from one module of the common memory to another with its capacity: the answer of a call by pointer (mem_call, gfx_mem_enter). Addresses are 32 bits: the common memory is a wasm32 memory.\n\n- **Version** 1.0 · number 4 · 12 bytes, aligned on 4 · `repr(C)`\n- **Owner**: the callee allocates it; the caller owns it once the call returns and frees it (mem_free(ptr, cap, 1)); cap 0: nothing was allocated.\n- **The core** reads and writes it; **a kit** reads and writes it.\n- **Where**: written by the callee where the caller said (out).\n- **Valid**: the call.\n\n| at | bytes | type | field | meaning |\n|---|---|---|---|---|\n| 0 | 4 | `u32` | `ptr` | address of the bytes |\n| 4 | 4 | `u32` | `len` | bytes in use |\n| 8 | 4 | `u32` | `cap` | bytes allocated (what is given back to the allocator) |\n\n## Ctx\n\nWhat the core tells a kit at every entry (the first 48 bytes of the arguments of a hook, and of a delivery record of the event queue): which host instance and kit slot, the clock, and the generations of what the kit may cache.\n\n- **Version** 1.0 · number 5 · 48 bytes, aligned on 8 · `repr(C)`\n- **Owner**: the core writes it in the message of the call; the kit reads it.\n- **The core** writes it; **a kit** reads it.\n- **Where**: the first bytes of the arguments of every hook of kithost.kit@1 (not aligned in the message: copy it out).\n- **Valid**: the call.\n\n| at | bytes | type | field | meaning |\n|---|---|---|---|---|\n| 0 | 4 | `u32` | `inst` | the host instance (one per game running) |\n| 4 | 4 | `u32` | `kit` | the slot of the kit in that host |\n| 8 | 8 | `u64` | `tick` | simulation ticks so far |\n| 16 | 8 | `u64` | `frame` | frames so far |\n| 24 | 8 | `f64` | `elapsed` | seconds of game time |\n| 32 | 8 | `f64` | `fixed_dt` | seconds of one tick |\n| 40 | 4 | `u32` | `services_gen` | bumped when the table of served capabilities changes |\n| 44 | 4 | `u32` | `config_gen` | bumped when the core changes a kit config after mount |\n\n## ZoneBuffer\n\nOne entry of the directory of the zone.\n\n- **Version** 1.0 · number 16 · 16 bytes, aligned on 4 · a record at a fixed place (bytes, not a type of the language)\n- **Owner**: the core (it writes the zone in place; a kit reads it through the accessors of kithost.zone@1, or in place in the common memory).\n- **The core** writes it; **a kit** reads it.\n- **Where**: ZoneDirectory.entries.\n- **Valid**: the game.\n\n| at | bytes | type | field | meaning |\n|---|---|---|---|---|\n| 0 | 4 | `u32` | `id` | 1 INPUT, 2 STATE, 3 EVENTS, 4 WORLD, 5 REGIONS |\n| 4 | 4 | `u32` | `offset` | from the start of the zone |\n| 8 | 4 | `u32` | `size` | bytes |\n| 12 | 4 | `u32` | `reserved` | 0 |\n\n## ZoneDirectory\n\nThe start of the shared zone: where each buffer is. A reader finds a buffer by its id, once at load; a later layout may move or grow a buffer.\n\n- **Version** 1.0 · number 17 · 256 bytes, aligned on 8 · a record at a fixed place (bytes, not a type of the language)\n- **Owner**: the core (it writes the zone in place; a kit reads it through the accessors of kithost.zone@1, or in place in the common memory).\n- **The core** writes it; **a kit** reads it.\n- **Where**: offset 0 of the shared zone.\n- **Valid**: the game; size changes when the zone grows.\n\n| at | bytes | type | field | meaning |\n|---|---|---|---|---|\n| 0 | 4 | `u32` | `magic` | GFZ1 (0x315A4647) |\n| 4 | 4 | `u32` | `version` | layout version of the zone, major << 16 | minor |\n| 8 | 4 | `u32` | `size` | bytes of the zone now (it grows in REGIONS, the last buffer) |\n| 12 | 4 | `u32` | `buffers` | number of entries that follow |\n| 16 | 240 | `ZoneBuffer[15]` | `entries` | the buffers, in id order |\n\n## ZoneInputHeader\n\nThe start of the INPUT buffer: the revisions a kit compares before it trusts what it read, then one ZoneInputRecord per action number, then 4 ZoneInputList.\n\n- **Version** 1.0 · number 18 · 32 bytes, aligned on 8 · a record at a fixed place (bytes, not a type of the language)\n- **Owner**: the core (it writes the zone in place; a kit reads it through the accessors of kithost.zone@1, or in place in the common memory).\n- **The core** writes it; **a kit** reads it.\n- **Where**: offset 0 of the buffer INPUT (id 1).\n- **Valid**: rewritten by the core whenever the inputs change.\n\n| at | bytes | type | field | meaning |\n|---|---|---|---|---|\n| 0 | 4 | `u32` | `rev` | revision of what the actions read (never 0 once a host runs) |\n| 4 | 4 | `u32` | `spec_rev` | revision of the specs, sticks and owners (bindings) |\n| 8 | 4 | `u32` | `glob_rev` | revision of the device, the capture, the gate and the list of actions |\n| 12 | 4 | `u32` | `capacity` | records that follow (input.actions of the game schema; 256 by default) |\n| 16 | 16 | `u8[16]` | `reserved` | 0 |\n\n## ZoneInputRecord\n\nOne input action as read now. Filled by the core the first time the action is read under a revision, then read by every kit without a call until the inputs change.\n\n- **Version** 1.0 · number 19 · 32 bytes, aligned on 8 · a record at a fixed place (bytes, not a type of the language)\n- **Owner**: the core (it writes the zone in place; a kit reads it through the accessors of kithost.zone@1, or in place in the common memory).\n- **The core** writes it; **a kit** reads it.\n- **Where**: INPUT + 32 + 32 × action number.\n- **Valid**: while rev equals the header rev.\n\n| at | bytes | type | field | meaning |\n|---|---|---|---|---|\n| 0 | 4 | `u32` | `rev` | the header rev it was written for: valid only while equal to it |\n| 4 | 4 | `u32` | `flags` | 1 pressed, 2 just pressed, 4 released |\n| 8 | 4 | `u32` | `presses` | presses this tick |\n| 12 | 4 | `u32` | `reserved` | 0 |\n| 16 | 8 | `f64` | `axis` | axis_over(action, 0) |\n| 24 | 8 | `f64` | `axis_inf` | axis_over(action, +inf) |\n\n## ZoneInputList\n\nA list the core published for the specs revision (specs(false), specs(true), sticks(false), sticks(true)): the bytes of the answer of kithost.input@1 specs / sticks, in a block of REGIONS.\n\n- **Version** 1.0 · number 20 · 16 bytes, aligned on 4 · a record at a fixed place (bytes, not a type of the language)\n- **Owner**: the core (it writes the zone in place; a kit reads it through the accessors of kithost.zone@1, or in place in the common memory).\n- **The core** writes it; **a kit** reads it.\n- **Where**: INPUT + 32 + 32 × capacity + 16 × list number.\n- **Valid**: while rev equals the header spec_rev.\n\n| at | bytes | type | field | meaning |\n|---|---|---|---|---|\n| 0 | 4 | `u32` | `rev` | the spec_rev it was written for: valid only while equal to the header spec_rev |\n| 4 | 4 | `u32` | `offset` | of the bytes, in the zone |\n| 8 | 4 | `u32` | `len` | bytes of the list |\n| 12 | 4 | `u32` | `capacity` | bytes of the block |\n\n## ZoneStateHeader\n\nThe start of the STATE buffer.\n\n- **Version** 1.0 · number 21 · 4 bytes, aligned on 4 · a record at a fixed place (bytes, not a type of the language)\n- **Owner**: the core (it writes the zone in place; a kit reads it through the accessors of kithost.zone@1, or in place in the common memory).\n- **The core** writes it; **a kit** reads it.\n- **Where**: offset 0 of the buffer STATE (id 2).\n- **Valid**: the game.\n\n| at | bytes | type | field | meaning |\n|---|---|---|---|---|\n| 0 | 4 | `u32` | `rev` | revision of the game state (vars and phase): changes at every write |\n\n## ZoneEventsHeader\n\nThe start of the EVENTS buffer (the event queue, a ring): the records follow.\n\n- **Version** 1.0 · number 22 · 32 bytes, aligned on 8 · a record at a fixed place (bytes, not a type of the language)\n- **Owner**: the core (it writes the zone in place; a kit reads it through the accessors of kithost.zone@1, or in place in the common memory).\n- **The core** writes it; **a kit** reads it.\n- **Where**: offset 0 of the buffer EVENTS (id 3).\n- **Valid**: the game.\n\n| at | bytes | type | field | meaning |\n|---|---|---|---|---|\n| 0 | 4 | `u32` | `head` | where the next record is written (≥ 32, 8-byte aligned) |\n| 4 | 4 | `u32` | `records` | records written so far (wraps) |\n| 8 | 4 | `u32` | `wraps` | times the queue went back to its start |\n| 12 | 20 | `u8[20]` | `reserved` | 0 |\n\n## ZoneEventRecord\n\nThe header of one record of the event queue; the body follows (an event or a delivery, in the encoding of the calls), padded to 8 bytes.\n\n- **Version** 1.0 · number 23 · 8 bytes, aligned on 8 · a record at a fixed place (bytes, not a type of the language)\n- **Owner**: the core (it writes the zone in place; a kit reads it through the accessors of kithost.zone@1, or in place in the common memory).\n- **The core** writes it; **a kit** reads it.\n- **Where**: EVENTS, from offset 32.\n- **Valid**: until the queue wraps over it: a reader copies the body when it is given its offset, never later.\n\n| at | bytes | type | field | meaning |\n|---|---|---|---|---|\n| 0 | 4 | `u32` | `len` | bytes of the body |\n| 4 | 4 | `u32` | `kind` | 1 event, 2 delivery |\n\n## ZoneRegionsHeader\n\nThe start of the REGIONS buffer (blocks of the zone given on demand: region, region_free, tick_region).\n\n- **Version** 1.0 · number 24 · 8 bytes, aligned on 8 · a record at a fixed place (bytes, not a type of the language)\n- **Owner**: the core (it writes the zone in place; a kit reads it through the accessors of kithost.zone@1, or in place in the common memory).\n- **The core** writes it; **a kit** reads it.\n- **Where**: offset 0 of the buffer REGIONS (id 5).\n- **Valid**: the game.\n\n| at | bytes | type | field | meaning |\n|---|---|---|---|---|\n| 0 | 4 | `u32` | `used` | bytes in use (information) |\n| 4 | 4 | `u32` | `reserved` | 0 |\n\n## Blocks of words (no structure number: plain `u64` words, little-endian)\n\nTwo direct links of the common memory carry their question and their answer as 64-bit words in the caller's own\nmemory, read and written in place by the core:\n\n- **The neighbour search `w_near(spec, out, cap)`** (`kithost.world@1.3`, `gripforge-kitcall/src/near.rs`).\n  `spec`: words 0–2 `x`, `z`, `radius` (`f64` bits); word 3 the number of conditions (≤ 8); then 3 words per\n  condition — the kind in the low half of the first (1 above, 2 number, 3 text, 4 text-not, 5 tag, 6 no-tag) and\n  the atom of the component or tag in its high half, the atom of the field or of the compared string, the number\n  (`f64` bits). `out`: 2 words per neighbour — the number of the entity's id (`e12` → 12) and its distance (`f64`\n  bits) — in the order of the registry. Answer: the count (more than `cap`: nothing more is written, ask again),\n  `0xffffffff`: not answered this way.\n- **A scalar service call** (`fast::ServiceCall`, `fast::Scalar` — 24 bytes: `kind u32`, `len u32`, `bits u64`,\n  `cap u64`). Kind 7 (`S_FIXED`, `kithost.mem@1.2`): `bits` is the address of a [`FixedBlock`](#fixedblock) that\n  holds a list or a dictionary — **lent** as an argument (the caller frees it after the call; the provider reads or\n  copies it), **given away** as the answer (the caller reads it in place, `Kx::call_with`, then frees it with the\n  common allocator).\n\n## For a module in another language\n\nWhat a module of the common memory needs, whatever built it:\n\n1. import the memory, and the one allocator (`gf:kithost.mem@^1`: `mem_alloc(size, align)`, `mem_free(ptr, size, align)`);\n2. carry the custom section `gripforge.structs` (magic `GFST`, the contract version, then each structure: name on 24\n   bytes, number, version, size, alignment, number of fields, and per field its name on 16 bytes, offset and size —\n   all u32 little-endian) and export `gf_layout()`, the 64-bit FNV-1a of those bytes;\n3. read a `FixedBlock` whose address a message carries (tag `0xFD` then the address on 8 bytes) in place, copy what\n   it keeps, then free the block: `mem_free(address, block.size, 8)`;\n4. write a value it passes as ONE block: `mem_alloc(size, 8)`, the header, the root, the items and pairs, then the\n   bytes of the texts — every address inside the block — and never touch it again once the message is sent.\n"
 },
 {
  "id": "kit-third-party",
  "title": "Writing a third-party kit (step by step)",
  "summary": "A kit of game logic of your own, in Rust, built alone and played with the GripForge kits without recompiling anything: crate, kit.json, declaring it in a game (gripforge kit add|verify|list|remove, gripforge_third_party_kit_*: source, sha256, lock), try-kit, web export, what the page says, versions, limits.",
  "source": "docs/kit-third-party.md",
  "text": "# Writing a third-party kit — a kit logic module of your own, step by step\n\nA **third-party kit** is a kit of game logic that is not one of GripForge's: you write it in Rust, you compile it\n**alone** into one `.wasm`, and a game plays it together with GripForge's kits. Neither the core nor any other kit is\nrecompiled, and the binary keeps working when the core gains functions. This page is the whole path — create,\ncompile, declare, verify, export, play — and can be followed without reading the code of the core. Readable\noffline: `gripforge docs kit-third-party`, or the MCP tool `gripforge_docs` (topic `kit-third-party`). The commands\n`gripforge kit add|verify|list|remove` and the MCP tools `gripforge_third_party_kit_*` of §3 and §4: from CLI 0.3.39 /\nMCP 0.1.55 (`gripforge --version`; `gripforge update`). `gripforge` is the command of the CLI everywhere in this page\n(`grip-forge` is an older alias of the same command); `node <gripforge>/tools/…` is a tool of the checkout, not of the CLI. The model behind it (the core, the interfaces, the costs):\ntopic `kit-modules`.\n\n**Use the existing kits first.** A game is made by picking GripForge's kits and adapting them (config, mods, hooks\nof `game.engine`): MCP `gripforge_gamekit_search`, `gripforge kit api <id>`, and the topic `third-party` (mods,\npresentation modules). Write a kit of your own only for a rule no kit has\nand no mod of `game.engine` can express — and make it small, on top of the others (listen to their events, call\ntheir services), as the example does.\n\nThe worked example of this page is in the repository: **`examples/kit-third-party`** (`acme.streak`). It listens to\nan event of `collect.tokens`, reads and writes a component on the player, and calls a service of `economy.money`.\n\n| Step | What | Command |\n|---|---|---|\n| 1 | Create the crate | three files: `Cargo.toml`, `src/lib.rs`, `kit.json` |\n| 2 | Compile it alone | `cargo build --release --target wasm32-unknown-unknown` |\n| 3 | Declare it in the game | `gripforge kit add <game> --wasm <kit.wasm> --manifest kit.json` (MCP: `gripforge_third_party_kit_add`) |\n| 4 | Verify, list, remove | `gripforge kit verify <game>`, `kit list`, `kit remove` (MCP: `…_verify`, `…_list`, `…_remove`) |\n| 5 | Try it without a browser | `node tools/kit-modules/try-kit.mjs --dir <kit modules> --game game.json --script script.json` |\n| 6 | Export the game and play it in a page | `node tools/web-export/build.mjs game.json <out> <origin> <player package>`, then `npm run dev` |\n\n**The rule: a third-party module is loaded only when the game declares it.** The declaration names where the module\ncomes from and its SHA-256; the lock of the game freezes the version and that fingerprint; the export and the page\nrefuse a binary that is not the declared one.\n\n## 0. What you need\n\n- A checkout of GripForge (the kit compiles against `native/gripforge-kit-guest`, a path dependency; `<gripforge>`\n  below is that checkout).\n- Rust 1.95 or later with the target: `rustup target add wasm32-unknown-unknown`.\n- Node 24.\n- The GripForge CLI (`gripforge`, 0.3.39 or later) or the MCP client `@gripforgeai/mcp` (0.1.55 or later) for the\n  declaration (§3, §4). Neither needs a login for these commands: they work on the files of the game.\n- A **game**: a file `game.json` (`{ \"project\": …, \"lock\": … }`), or the folder that holds it. An exported web game\n  (`gripforge game-export <gkp_id> <folder>`) is such a folder; `examples/kit-third-party/game.json` is such a file.\n- A **folder of kit modules**: the core and the GripForge kits your game uses, each as a `.wasm`, with\n  `kit-modules.json`. An exported web game has one when its player package has them (`runtime-rust/kit-modules/`),\n  a player package too (`kit-modules/`). To build one yourself, with only the kits you need\n  (file names are the kit ids with `_` for `.`):\n\n  ```\n  node <gripforge>/tools/kit-modules/build.mjs --out <dir> --kits collect_tokens,economy_money --jobs 3\n  ```\n\n  This is the only time the core and GripForge's kits are compiled. Adding your kit later recompiles none of them.\n\n## 1. Create the crate\n\n```\nmy-kit/\n  Cargo.toml\n  kit.json          the kit's manifest: what it provides and consumes\n  src/lib.rs        the kit\n```\n\n**`Cargo.toml`** — a `cdylib`, one dependency on the kit side of the interfaces, a workspace of its own:\n\n```toml\n[package]\nname = \"kit-acme-streak\"          # the output is kit_acme_streak.wasm\nversion = \"1.0.0\"\nedition = \"2021\"\n\n[lib]\ncrate-type = [\"cdylib\"]\n\n[dependencies]\ngripforge-kit-guest = { path = \"<gripforge>/native/gripforge-kit-guest\" }\nserde_json = { version = \"1\", features = [\"preserve_order\", \"float_roundtrip\"] }\n\n[workspace]\n\n[profile.release]\nopt-level = \"s\"\nlto = \"fat\"\ncodegen-units = 1\nstrip = true\npanic = \"abort\"\n```\n\nKeep the two `serde_json` features: they are the value model of the core (`3` and `3.0` stay distinct, the keys keep\ntheir order).\n\n**`src/lib.rs`** — a kit is a type that implements `KitModule`, exported with `export_kit!`. A module is stateless:\nwhat it keeps between hooks goes in `kx.put(…)` and is read back with `kx.data::<T>()`.\n\n```rust\nuse gripforge_kit_guest::bus::GameEvent;\nuse gripforge_kit_guest::host::{KitModule, Kx};\nuse gripforge_kit_guest::shared::current_player;\nuse serde_json::{json, Value as Json};\nuse std::rc::Rc;\n\nstruct Streak;\nstruct Settings { every: u64, bonus: f64 }\n\nimpl KitModule for Streak {\n    fn id(&self) -> &'static str { \"acme.streak\" }                       // the id the game declares\n    fn services(&self) -> &'static [&'static str] { &[\"acme.streak\"] }   // what it serves to the other kits\n\n    fn setup(&self, kx: &mut Kx) {\n        let cfg = kx.config().clone();                                   // its `config` in the project\n        kx.put(Settings { every: cfg[\"every\"].as_u64().unwrap_or(3), bonus: cfg[\"bonus\"].as_f64().unwrap_or(25.0) });\n        kx.define_var(\"streak.count\", \"number\", \"Streak\", None, Some(json!(0)));\n        kx.on(\"tokens.collected\", \"collected\");                          // an event of collect.tokens\n    }\n\n    fn on_event(&self, kx: &mut Kx, tag: &str, ev: &GameEvent) {\n        if tag != \"collected\" { return; }\n        let Some(player) = current_player(kx.host) else { return };\n        // Read a component, write it back.\n        let count = kx.host.entities.component(&player, \"streak\").and_then(|c| c[\"count\"].as_u64()).unwrap_or(0) + 1;\n        kx.host.entities.set(&player, \"streak\", json!({ \"count\": count, \"kind\": ev.payload[\"kind\"] }));\n        kx.set_num(\"streak.count\", count as f64);\n        let (every, bonus) = { let s = kx.data::<Settings>(); (s.every, s.bonus) };\n        if count % every == 0 && kx.host.has_service(\"economy.money\") {\n            // A service of another kit.\n            let balance = kx.call(\"economy.money\", \"add\", &[json!(bonus), json!(\"streak\")]).ok();\n            kx.emit(\"streak.bonus\", json!({ \"count\": count, \"bonus\": bonus, \"balance\": balance }));\n        }\n    }\n\n    fn call(&self, kx: &mut Kx, _capability: &str, method: &str, _args: &[Json]) -> Result<Json, String> {\n        match method {\n            \"count\" => Ok(json!(current_player(kx.host)\n                .and_then(|p| kx.host.entities.component(&p, \"streak\").and_then(|c| c[\"count\"].as_u64()))\n                .unwrap_or(0))),\n            _ => Err(format!(\"acme.streak has no method {method}\")),\n        }\n    }\n}\n\nfn module() -> Rc<dyn KitModule> { Rc::new(Streak) }\n\n// (module, version, per-tick hooks): 1 = update, 2 = late_update, 4 = update_idle, added up. 0: never called on a\n// tick. Leave the third argument out and every per-tick hook is called (correct, only slower).\ngripforge_kit_guest::export_kit!(module, env!(\"CARGO_PKG_VERSION\"), 0);   // the version of Cargo.toml\n```\n\nThe complete file with comments: `examples/kit-third-party/src/lib.rs`.\n\n**`kit.json`** — the manifest: what the binary provides and consumes, as `name@semver`.\n\n```json\n{\n  \"schema\": \"gripforge.kit-module/1\",\n  \"id\": \"acme.streak\",\n  \"version\": \"1.0.0\",\n  \"provides\": [\"kithost.kit@1.1.0\"],\n  \"consumes\": [\"kithost.world@^1.3\", \"kithost.state@^1.1\", \"kithost.zones@^1.0\", \"kithost.objectives@^1.0\",\n               \"kithost.physics@^1.0\", \"kithost.services@^1.1\", \"kithost.input@^1.1\", \"kithost.assets@^1.0\",\n               \"kithost.platform@^1.0\", \"kithost.zone@^1.0\"],\n  \"services\": [\"acme.streak@1.0.0\"],\n  \"requires\": [\"collect.tokens@^1.1\"],\n  \"optional\": [\"economy.money@^1\"]\n}\n```\n\n- `id`: dotted, lowercase, **under a prefix of your own** (`acme.…`); never the id of a GripForge kit. It is the id\n  `fn id()` returns and the one the game declares.\n- `provides` / `consumes`: copy the two lists above as they are (their order does not matter). They are what `export_kit!` writes in the binary\n  (its custom section `gripforge.calls`); `gripforge kit add` (§3) compares them with the binary and tells you the difference.\n- `services`: the capabilities of `fn services()`, with the version of their API. That version is the one of the\n  service, not of the kit: it stays `1.0.0` while you only fix the kit, gets a new minor when you add a method.\n- `requires`: the kits your kit cannot work without (it listens to them, calls them without a test). `optional`: the\n  kits it uses only when the game has them (`kx.host.has_service(…)` first). The requirement is matched against the\n  **kit** version of `<dir>/kit-modules.json` (`economy.money` 1.3.0), not the version of the service API that\n  `kit api` prints (1.2.0).\n\n### The API of a kit (`Kx`)\n\nEverything goes through the `kx: &mut Kx` each hook receives. The ones you need most:\n\n| You want to | Call |\n|---|---|\n| read your config, a data collection of the project | `kx.config()`, `kx.data_collection(\"token_kinds\")`, `kx.project()` |\n| keep state between hooks | `kx.put(value)` once in `setup`, then `kx.data::<T>()` — a `&mut T`: `kx.data::<Local>().ticks += 1` |\n| the clock, random numbers | `kx.elapsed()` (seconds of game time), `kx.tick()`, `kx.dt()` (a fixed tick: 1/60 s), `kx.rng()` (deterministic, forked per kit) |\n| listen to an event | `kx.on(\"topic\", \"tag\")` in `setup` (`\"family.*\"` and `\"*\"` work) → `fn on_event(&self, kx: &mut Kx, tag: &str, ev: &GameEvent)`; `ev.topic`, `ev.payload` (a `serde_json::Value`: `ev.payload[\"amount\"].as_f64()`, `ev.payload[\"kind\"].as_str()`), `ev.entity`, `ev.source` |\n| emit an event | `kx.emit(\"topic\", json!({ … }))` |\n| a var (shown by HUDs, saved) | `kx.define_var(path, \"number\" \\| \"string\" \\| \"boolean\", label, format, Some(default))` (`format`: `None`, or a display hint such as `Some(\"money\")`), `kx.get_var(path)`, `kx.set_var(path, value)`, `kx.set_num(path, n)`, `kx.bind_var(path, \"tag\")` → `fn on_var(&self, kx: &mut Kx, tag: &str, path: &str, value: Option<&Json>, prev: Option<&Json>)` |\n| the player in scope | `current_player(kx.host)` → `Option<String>` (its entity id) |\n| read an entity | `kx.host.entities.get(id)` (`.kind`, `.tags`, `.has_tag(t)`, `.component(name)`), `kx.host.entities.component(id, name)`, `kx.host.entities.transform(id)` (`Pos { x, y, z, yaw }`) |\n| find entities | `kx.host.entities.by_tag(\"enemy\")`, `kx.host.entities.query(&Query { kind, all, any, none })`, `kx.host.entities.player()` |\n| write an entity | `kx.host.entities.set(id, component, value)`, `kx.host.entities.set_transform(id, &json!({ \"x\": 1.0 }))`, `kx.host.entities.tag(id, &[\"hidden\"])`, `untag` |\n| create, destroy | `kx.create_entity(kind, &tags, Some(&components))` → id, `kx.host.destroy_entity(id)` |\n| call another kit | `kx.host.has_service(\"economy.money\")`, `kx.call(\"economy.money\", \"add\", &[json!(25)])` → `Result<Json, String>` |\n| serve the others | `fn services()` + `fn call(&self, kx: &mut Kx, capability: &str, method: &str, args: &[Json]) -> Result<Json, String>` |\n| a timer | `kx.after(0.5, \"tag\", Json::Null)`, `kx.every(0.5, \"tag\", json!({ … }))` (seconds of game time; the data is a `serde_json::Value`) → `fn on_timer(&self, kx: &mut Kx, tag: &str, data: &Json)` |\n| a trigger verb usable from the project's data | `kx.register_action(\"verb\")` → `fn action(&self, kx: &mut Kx, verb: &str, args: &Json, ev: Option<&GameEvent>)`, `kx.register_condition(\"verb\")` → `fn condition(…same…) -> bool` |\n| every tick | `fn update(&self, kx: &mut Kx, dt: f64)`, `fn late_update(&self, kx: &mut Kx, dt: f64)` — **and** their bits in the mask of `export_kit!` (the mask lives only there, not in `kit.json`: a kit with `fn update` and the mask 0 is never ticked) |\n| input, physics | `kx.input().pressed(\"jump\")`, `kx.input().axis(\"move_x\")`, `kx.physics().raycast(…)` |\n| save and load | `fn save(&self, kx: &mut Kx) -> Option<Json>`, `fn load(&self, kx: &mut Kx, data: &Json)` (components and vars are already saved by the core) |\n| log | `kx.log(\"warn\", \"message\")` (shown by `try-kit`) |\n\nThe other hooks (`ready`, `teardown`, `spawn`, `scene_enter`, `component`, mission steps…) and the cost of each call\nare in the topic `kit-modules` §3. **Which events a kit emits, which services it serves, with which arguments**:\n`gripforge kit api <kit-id> --section events,services`, or the MCP tool `gripforge_gamekit_api`.\n\nRules that save time:\n\n- A read returns a **copy** (`component`, `get`, `get_var`): change it, then write it back with `set` / `set_var`.\n- Do not hold a reference read from the world across a call that writes (`emit`, `set`, `call`): Rust refuses it;\n  clone what you need first (`let cfg = kx.config().clone();`).\n- An event emitted in a hook is delivered **after** the hook, in the next round of the same tick.\n- A kit that panics is left out (its hooks are logged as failed); the game goes on without it.\n\n## 2. Compile it alone\n\n```\ncd my-kit\ncargo build --release --target wasm32-unknown-unknown\n```\n\nThe output is `target/wasm32-unknown-unknown/release/kit_<name>.wasm` (under `$CARGO_TARGET_DIR/` when that\nvariable is set; about 120 KB for the example). Only your\ncrate and its dependencies are compiled: a few seconds.\n\n## 3. Declare it in the game\n\n```\ngripforge kit add <game> --wasm target/wasm32-unknown-unknown/release/kit_acme_streak.wasm --manifest kit.json \\\n          --config '{\"every\":3,\"bonus\":25}'\n```\n\n`<game>` is the `game.json` of the game or the folder that holds it. `--wasm` and `--manifest` are files or\n`http(s)://` URLs; `--wasm` is the output of your last build (cargo keeps the same file name from one version to the\nnext: build, then add). With the MCP client the same is the tool `gripforge_third_party_kit_add { game, wasm, manifest,\nconfig? }` (absolute paths). The command:\n\n1. **checks** the kit — and writes nothing when a check fails (exit code 1, one problem per line):\n   - the binary is a kit module (`export_kit!`) and `provides` / `consumes` of `kit.json` are what it declares\n     (the binary carries neither its id nor its version: **the `id` of `kit.json` must be the one `fn id()` returns**\n     and its `version` the one of `Cargo.toml` — nothing can compare them for you yet, §8);\n   - when the game has kit modules beside it (`<game folder>/runtime-rust/kit-modules/`, `<game folder>/kit-modules/`,\n     or `--modules <dir>`): the core provides every interface the kit consumes, the kits it `requires` have a module\n     at a matching version, its id is not the id of a GripForge kit;\n   - the kits it `requires` are installed in the game;\n2. **copies** the module beside the game as `third-party-kits/<id>-<version>.wasm` (a URL is not copied: it stays the\n   source), and, when the game has kit modules, puts it there too (`kit.<id>.<hash>.wasm`, one line in\n   `kit-modules.json`; no other file changes, nothing is recompiled);\n3. **writes the declaration** in `game.json`:\n\n```json\n{ \"project\": {\n    \"installed\": [ { \"id\": \"game.engine\", \"…\": \"…\" }, { \"id\": \"economy.money\", \"…\": \"…\" }, { \"id\": \"collect.tokens\", \"…\": \"…\" },\n      { \"id\": \"acme.streak\", \"version\": \"1.0.0\", \"enabled\": true, \"config\": { \"every\": 3, \"bonus\": 25 } } ],\n    \"thirdPartyKits\": [\n      { \"id\": \"acme.streak\", \"version\": \"1.0.0\",\n        \"source\": \"./third-party-kits/acme.streak-1.0.0.wasm\",\n        \"sha256\": \"182e2229…6999\", \"bytes\": 120516,\n        \"manifest\": { \"…the kit.json…\": \"\" } } ] },\n  \"lock\": { \"order\": [\"game.engine\", \"economy.money\", \"collect.tokens\", \"acme.streak\"],\n            \"kits\": { \"acme.streak\": { \"version\": \"1.0.0\", \"enabled\": true } },\n            \"thirdParty\": { \"acme.streak\": { \"version\": \"1.0.0\", \"sha256\": \"182e2229…6999\", \"bytes\": 120516 } } } }\n```\n\n- `project.thirdPartyKits[]`: where the module comes from (`source`: a path relative to the game file, or a URL),\n  its SHA-256 and its manifest. **This is what makes the kit loadable**: an id in `installed` that is neither a\n  GripForge kit nor declared here is refused by the export.\n- `project.installed[]`: the kit's entry, as for any kit; `config` is what `kx.config()` returns. Change the config\n  by editing it there (or pass `--config` again). The command also writes `\"source\": \"user\"` (who installed the\n  kit — not the `source` of the declaration) and `\"installedAt\"` in that entry, as for any kit.\n- `lock.order`: the mount order. A new kit goes **last**, after the kits whose services it calls during `setup`;\n  move it by hand if another kit must mount after it. Events and calls made later do not depend on the order.\n- `lock.thirdParty`: the version and the SHA-256 the lock froze.\n\nRun the command again after each build of your kit: the kit is replaced (config and place kept, version and SHA-256\nmoved everywhere). `--check` checks and writes nothing. `--json` prints the report.\n\n| Message of `kit add` | What to do |\n|---|---|\n| `…: no such game file. A game is a game.json …` | give the path of the `game.json` or of its folder |\n| `the kit binary: not a WebAssembly module …` / `the binary does not export gf_alloc…` / `has no \"gripforge.calls\" section` | the crate is not a `cdylib`, lacks `export_kit!`, or was built for another target |\n| `kit.json \"consumes\" is not what the binary declares: add …; remove …` | make the list of `kit.json` the one the message gives |\n| `the kit consumes kithost.world@^1.0, the core provides kithost.world@2.0.0: another major version` | rebuild the kit against the `gripforge-kit-guest` of that core |\n| `… the core is older than the interface the kit was built against` | update the kit modules of the game, or build against the older `gripforge-kit-guest` |\n| `required kit collect.tokens@^1.1 has no kit module here` | the kit modules of the game lack that kit: install it in the game and export again (or build it, §0) |\n| `acme.streak: requires collect.tokens@^1.1, which the game does not install` | install that kit in the game first, or drop it from `requires` |\n| `\"…\" is the id of a GripForge kit` / `is already a kit of these kit modules (a GripForge kit)` | choose an id under your own prefix |\n| `warning: this game has no kit modules beside it …` | not an error: the kit was checked against its manifest only; pass `--modules <folder of kit modules>` to check it against a core now, the export checks it in any case (§6) |\n\nA game written before these commands (the kit only in `installed` and `lock.order`, by hand) is brought up to date\nby the same `gripforge kit add`: its entry is adopted, config and place kept.\n\n## 4. Verify, list, remove\n\n```\ngripforge kit verify <game> [kit-id]      # exit code 2 when a kit does not verify\ngripforge kit list <game>\ngripforge kit remove <game> <kit-id>\n```\n\nMCP: `gripforge_third_party_kit_verify { game, id? }`, `gripforge_third_party_kit_list { game }`,\n`gripforge_third_party_kit_remove { game, id }`.\n\n`list` prints, per kit: version, SHA-256, source, its place in `lock.order`, its config, what it requires and serves.\n\n`verify` reads each module again **from its source** and compares: the bytes with the SHA-256 the game declares and\nits lock froze; the manifest with the binary; the version in the declaration, in `installed`, in `lock.kits`, in\n`lock.thirdParty` and in the kit modules of the game. Run it after fetching a game, after editing `game.json` by\nhand, and before an export.\n\n```\nThird-party kits of /games/streak/game.json\n  ok   acme.streak@1.0.0  sha256 182e22290fd2b7ae…  ./third-party-kits/acme.streak-1.0.0.wasm\n```\n\n| Message of `kit verify` | Cause |\n|---|---|\n| `the module at … has sha256 …, the game declares …: it is not the binary that was declared` | the file (or what the URL serves) changed since `kit add`: add it again to accept the new binary, or restore the old one |\n| `the lock froze version 0.9.0, the project declares 1.0.0` (or `sha256`) | `game.json` was edited by hand on one side only: `kit add` again |\n| `installed at 1.0.1, declared at 1.0.0` | the version of the `installed` entry was changed by hand: it follows the declaration |\n| `the lock does not freeze it` | the declaration was written by hand: `kit add` |\n| `not in lock.order — it is never mounted` | add its id to `lock.order` |\n| `the kit module is version …, the game declares …` / `the kit module kit.<id>.<hash>.wasm has sha256 …, the game declares …` | the kit modules (`runtime-rust/kit-modules/`) hold another build of the kit, or its file changed: `kit add` again (it replaces the module) |\n| `the module cannot be read: … no such file` / `HTTP 404` | the source is gone: the game cannot be exported; `kit add` from where the module is now |\n\n`remove` deletes the declaration, the `installed` entry, the lock lines, the copy under `third-party-kits/` and the\nkit module. It removes third-party kits only.\n\n## 5. Try it without a browser\n\n```\nnode <gripforge>/tools/kit-modules/try-kit.mjs --dir <dir> --game game.json --script script.json\n```\n\nplays the game on the kit modules exactly as the page does (same loader, same core), then prints what happened:\n\n```\nmounted (4): game.engine [core], economy.money, collect.tokens, acme.streak [third-party]\ncollect.tokens.collect(\"row.3\") → true\nacme.streak.count() → 3\neconomy.money.balance() → 125\nevents (16): entity.spawned ×8, entity.despawned ×3, tokens.collected ×3, economy.transaction, streak.bonus\nvars: {\"economy.money\":125,\"tokens.coin\":3,\"streak.count\":3, …}\nplayer e1: {\"transform\":{…},\"economy.money\":{\"balance\":125},\"streak\":{\"count\":3,\"best\":3,\"kind\":\"coin\"}}\n```\n\n`script.json` is an array of operations (`examples/kit-third-party/script.json`): `{ \"op\": \"step\", \"ticks\": 10 }`,\n`{ \"op\": \"create\", \"kind\": \"player\", \"tags\": [\"player\"], \"components\": { \"transform\": { \"x\": 0, \"y\": 0, \"z\": 0 } } }`,\n`{ \"op\": \"move\", \"entity\": \"e1\", \"to\": { \"x\": 1, \"y\": 0, \"z\": 0 } }`,\n`{ \"op\": \"call\", \"service\": \"…\", \"method\": \"…\", \"args\": [] }`, `{ \"op\": \"emit\", \"topic\": \"…\", \"payload\": {} }`,\n`{ \"op\": \"set\", \"path\": \"…\", \"value\": … }`, `{ \"op\": \"key\", \"code\": \"KeyW\", \"down\": true }`. Without `--script` it\ncreates a player and plays `--frames` ticks. A tick is 1/60 s of game time. The output also has a line `calls:` (how\nmany hooks the core called and how many calls it served, by interface: the cost of the kits). An event emitted by a\n`call` or an `emit` of the script is delivered when the game steps: put a `step` after it before you read what it\ncaused (the example does). The text output counts the events by topic; **their payloads** are in `--json` (the whole\nreport as JSON: `events[]` with `topic`, `payload`, `source`; also `kits`, `results`, `logs`, `vars`, `calls`); the exit code is 1 when a\nkit of the lock did not mount or an operation failed.\n\n| What you see | Cause |\n|---|---|\n| `NOT MOUNTED: acme.streak (no kit module in the folder …)` and `log warn: kit acme.streak has no native module; skipped` | the kit is not in this folder: `gripforge kit add` on a game that has kit modules, or `add-kit.mjs` on the folder (or the id of `kit.json` is not the id of the game) |\n| `the kit modules did not link: … was compiled against kithost.world@^1.0; the game provides kithost.world@2.0.0` | the binary and the core are of different majors: rebuild the kit |\n| `… is in project.installed but not in lock.order` | add the id to `lock.order` |\n| `game.engine is in lock.order but not in project.installed` | add its entry to `installed`: every id of `lock.order` has one, `game.engine` included |\n| your kit is mounted but nothing happens | the event has another topic or payload than you think (`gripforge kit api <kit>`; the line `events` lists every topic that was emitted), or the service is not served (`has_service`) because that kit is missing or mounted later |\n| `<kit>.<method> is not served by <kit>` / `acme.streak has no method …` | the method name (they are the names of the TypeScript API: `canAfford`, not `can_afford`) |\n\n`try-kit` is a tool of the checkout (`node <gripforge>/tools/…`), not a command of the CLI. `<dir>` is a folder of kit modules **that holds your kit**: the `runtime-rust/kit-modules/` of the game folder after\n`gripforge kit add` (§3 puts the module there), or a folder you built (§0) to which you add the kit with\n`node <gripforge>/tools/kit-modules/add-kit.mjs --dir <dir> --wasm <kit.wasm> --manifest kit.json` (the same checks\nas `kit add`, on the folder alone).\n\nA test of your own can do the same in a few lines (`tools/kit-modules/third-party.test.mjs` is the model):\n\n```js\nimport { readFileSync } from 'node:fs';\nimport { loadKitHostWasm } from '<gripforge>/native/gripforge-runtime/web/kithost-wasm.mjs';\nconst manifest = JSON.parse(readFileSync(`${dir}/kit-modules.json`, 'utf8'));\nconst logic = await loadKitHostWasm(null, { kitModules: { manifest, kits: game.lock.order, fetch: async (f) => readFileSync(`${dir}/${f}`) } });\nconst host = logic.create({ project: game.project, lock: game.lock, seed: 1, hud: false });\nhost.apply({ op: 'create', kind: 'player', tags: ['player'], components: { transform: { x: 0, y: 0, z: 0, yaw: 0 } } });\nhost.step(1 / 60);\nhost.services.get('acme.streak').count();      // a service, as the page calls it\nhost.state.snapshot();                          // the vars\nhost.entities.player().components.get('streak');\n```\n\n## 6. Export the game and play it in a page\n\n**A game folder that already has its kit modules** (an exported web game with `runtime-rust/kit-modules/`): after\n`gripforge kit add <folder> …` it is ready — `npm run dev` in the folder, open the address it prints.\n\n**From a game file**, the web export builds that folder:\n\n```\nGF_KIT_MODULES=<kit modules dir> node <gripforge>/tools/web-export/build.mjs game.json <out> http://127.0.0.1:1 <player package>\ncd <out> && npm run dev          # http://127.0.0.1:5173\n```\n\n- The paths can be given from anywhere: a declared `source` such as `./third-party-kits/…` is read **relative to\n  the game file**, not to the current folder.\n- The export brings the project up to date first, as the site does when it opens a project (it prints what it did:\n  `updated …: asset.preload 1.0.0 (added) …`): GripForge's kits may be added, moved to their latest version and\n  ordered again in `lock.order`. The third-party kits are put back after them, in the order they had.\n- `<player package>`: the web package of the Bevy player (`native/gripforge-runtime/dist/web`, or the folder a site\n  serves as `/runtime-rust/`). `GF_KIT_MODULES`: a folder of kit modules with the core and the GripForge kits of the\n  game (§0); not needed when the player package has `kit-modules/`. `<out>` must be empty. The third argument is\n  the origin the assets of the game are fetched from (any address when the game has none).\n- The export reads each declared module from its `source`, refuses it when its SHA-256 is not the declared one,\n  checks it against the core and the kits of **this** export, and ships it as a kit module with the core and the\n  GripForge kits of the game (`<out>/runtime-rust/kit-modules/`) and as `<out>/third-party-kits/` (so\n  `gripforge kit verify <out>` works on the exported game). A third-party kit has no TypeScript runtime and no view:\n  nothing else is built for it.\n- `GF_KIT_MODULES_MERGE=1` merges the core, the GripForge kits and yours into one wasm (topic `kit-modules` §8).\n\n**The page plays it like any kit.** The kit modules are the Rust logic of every game (`?logic=wasm` and\n`?logic=kits` mean the same): the page loads the core and the kits of the game's lock — yours with them — and\nnothing else. The console says it:\n\n```\n[gripforge] kit logic modules: the core and 5 kits (third-party: acme.streak)\n```\n\nBefore a module is compiled the page compares it with the declaration: the version of `kit-modules.json` with the\ndeclared and locked one, and the SHA-256 of the bytes with the declared one. There is no other wasm behind the kit\nmodules: when something does not fit, **the game does not start** and the page shows the error, naming the kit, its\nversion and the cause (topic `kit-modules` §1). It never plays the game without your kit in silence.\n\n| What the page says | Cause |\n|---|---|\n| `acme.streak: … its module has sha256 …, the game declares … (not the binary that was declared)` | the module served is not the declared one: export again, or `gripforge kit add` then `kit verify` |\n| `acme.streak: the kit module is version 1.1.0, the game declares 1.0.0` | `kit-modules.json` and `game.json` are of two different builds |\n| `acme.streak: … was compiled against kithost.world@^2.0; the game provides kithost.world@1.0.0` | the kit and the core are of different majors: rebuild the kit, export again |\n| `kit-modules/kit-modules.json: the manifest of the kit modules was not read (HTTP 404)` | the folder served has no kit modules: export with `GF_KIT_MODULES` (or a player package that has them) |\n| `acme.streak@1.0.0: no module in the kits package` | the kit modules do not hold the kit: `gripforge kit add` on this folder, or export again |\n| `This game runs on the TypeScript KitHost (logic ts), WITHOUT its third-party kit …` | the page was opened with `?logic=ts`, or the project asks for `logic: \"ts\"` (a red line at the top of the page) |\n\nThe export refuses, with the reason, a game it could only ship broken:\n\n| Message of the export | What to do |\n|---|---|\n| `acme.streak: installed, but it is neither a GripForge kit nor a declared third-party kit` | `gripforge kit add` (the kit was written in `installed` by hand) |\n| `Third-party kit acme.streak@1.0.0: the module at … has sha256 …, the game declares …` | `gripforge kit verify`, then add the right binary again |\n| `Third-party kit acme.streak: its module … is missing` | the `source` is relative to the game file: export from where the game file and `third-party-kits/` are |\n| `… cannot be exported with the JavaScript renderer` | pass the player package (fourth argument): a kit module runs under the Bevy player |\n| `… the project asks for logic \"ts\"` | remove `\"logic\": \"ts\"` from the project (or `gripforge game-logic <gkp_id> --logic wasm`) |\n| `… <kit> has no Rust module, so this game runs on the TypeScript KitHost` | a GripForge kit of the game is not ported to Rust yet: the game cannot have a third-party kit until it is |\n| `The Rust logic of the game needs the kit logic modules, and … kit-modules.json is missing` | set `GF_KIT_MODULES`, or use a player package that has `kit-modules/` |\n| `The kit logic modules of … do not serve this game — <kit>: no module` | a kit of the game has no module in that folder: build the kit modules again from the sources of the game's kits |\n| `Third-party kit … cannot be exported with these kit modules (core …): …` | the lines that follow are the checks of §3 against the core of the export |\n\n## 7. Versions: what stays compatible\n\n- Your binary names what it was built against: `consumes kithost.world@^1.0`. A core that provides `world@1.4.0`\n  accepts it; a core at `2.0.0` refuses it at load with a message. **Within a major an interface only grows at the\n  end**: a function keeps its number, its name and its types, new ones get new numbers. So a kit built today keeps\n  running on later cores of the same major without being rebuilt.\n- This is tested in GripForge's CI: a binary of the example **frozen** at the interfaces 1.0\n  (`examples/kit-third-party/prebuilt/`, with the `kit.json` it was built with) is played against the core of each commit, and the schemas of the\n  interfaces are compared with their 1.0 snapshot (`node tools/kit-modules/interfaces.mjs --against\n  examples/kit-third-party/prebuilt/interfaces-1.0.json`).\n- Your own versions: bump `version` in `Cargo.toml` (which `export_kit!` reads) and in `kit.json` together, build,\n  then `gripforge kit add` again: it moves the version and the SHA-256 in the declaration, `installed` and the lock.\n  The lock is what a game is checked against: the export and the page refuse a module of another version or with\n  other bytes than the lock froze. The services you serve to other kits follow the same rule: add methods, never change one.\n\n## 7b. Changing and stopping what another kit decides: interceptable hooks\n\n**An event cannot be modified or cancelled.** The bus notifies after the fact, every subscriber in a fixed order.\nWhat a kit lets others change or stop is an **interceptable hook** of game.engine (`engine.hooks`, topic\n`mods-engine`): a decision the kit asks **before** it acts, and waits for. If you want to change a decision of\nanother kit, tap its hook; if you want your own decisions to be changeable, declare a hook and run it before you\nact (then emit your event). Worked example: `examples/kit-third-party-hooks` (`acme.tax`), played by\n`tools/kit-modules/hooks.test.mjs`.\n\n**Tap the hook of another kit, in code.** The hooks of a kit are in its API (`grip-forge kit api economy.money`):\nname, payload, which fields are `mutable`, whether it is `cancellable`.\n\n```rust\nfn setup(&self, kx: &mut Kx) {\n    // priority: higher runs first, among the taps in code and the taps in data of the game and its mods.\n    let opts = json!({ \"priority\": 0, \"owner\": \"acme.tax\", \"id\": \"acme.tax.earn\" });\n    let _ = kx.call(\"engine.hooks\", \"tap\", &[json!(\"money.earn\"), kx.callback(\"earn\"), opts]);\n}\n\n/// Called synchronously each time economy.money is about to credit: args[0] is the payload as the taps before\n/// left it. Answer nothing (Json::Null), `{ set }` on mutable fields, or `{ cancel }` on a cancellable hook.\nfn callback(&self, kx: &mut Kx, name: &str, args: &[Json]) -> Result<Json, String> {\n    let amount = args[0][\"amount\"].as_f64().unwrap_or(0.0);\n    if amount > 500.0 {\n        return Ok(json!({ \"cancel\": true, \"reason\": \"over_cap\" }));\n    }\n    Ok(json!({ \"set\": { \"amount\": amount * 0.8 }, \"reason\": \"tax\" }))\n}\n```\n\nA field that is not `mutable`, a value its schema refuses or a cancel of a hook that is not `cancellable` is\nrefused and announced (`engine.hook.refused`); the game can also refuse a hook to mods (`mods.deny.hooks`).\n\n**Declare a hook of your own**, in `kit.json` — the game schema then carries it, and a game, a mod or another module\ntaps it like any hook:\n\n```json\n\"hooks\": { \"tax.rate\": { \"mutable\": [\"rate\"], \"cancellable\": false,\n                         \"fields\": { \"rate\": { \"type\": \"number\", \"minimum\": 0, \"maximum\": 1 } } } }\n```\n\n```rust\nlet asked = kx.call(\"engine.hooks\", \"run\", &[json!(\"tax.rate\"), json!({ \"amount\": amount, \"rate\": rate })])?;\nif asked[\"cancelled\"] == json!(true) { return Ok(Json::Null); }      // only when the hook is cancellable\nlet rate = asked[\"payload\"][\"rate\"].as_f64().unwrap_or(rate);        // what the taps left\n// … act, THEN notify:\nkx.emit(\"tax.taken\", json!({ \"amount\": amount, \"rate\": rate }));\n```\n\n**See who did what**: `logic.hooks.trace()` in the page or in a test lists every run — the taps in order, the\nfields each one set, who cancelled and why.\n\n## 8. Limits today\n\n- **Kit modules only.** A third-party kit exists only as its own module (or merged with the others at export), which\n  is how every game is played in Rust logic; the TypeScript KitHost cannot play it. What it means for you: the game\n  needs kit modules for every kit it installs, so every GripForge kit of the game must have a Rust module\n  (`gripforge game-logic <gkp_id>` says when one has not).\n- **The declaration lives in the game file.** A project kept on the GripForge site does not store third-party kits\n  yet: the kit search, the kit pickers, the site's validation and its own export button know GripForge's kits only.\n  Declare the kit in an exported game folder or in a game file (§3), and export from there (§6).\n- **The binary carries neither its id nor its version.** What is compared is `kit.json`, the declaration, the lock\n  and `kit-modules.json`; the SHA-256 ties them to the bytes. Keep `fn id()` / `Cargo.toml` and `kit.json` in step\n  yourself: a `kit.json` with another id than `fn id()` passes `kit add`; play the game with `try-kit` (§5) after\n  each add — its line `mounted` must name your kit.\n- **Updating an exported game from the site** (`gripforge game-export <gkp_id> <folder>` again) knows GripForge's\n  kits only: it reports `game.json` and the kit modules as edited locally. After it, `gripforge kit verify <folder>`,\n  and `gripforge kit add` again if the kit no longer verifies (its module is still in `third-party-kits/`).\n- **Logic only.** A kit module computes; what is drawn comes from the presentation modules of the player\n  (`gripforge docs porting`). Your kit shows itself through vars (HUD), components and events that existing\n  views already read.\n- **Rust, from a checkout.** The kit side (`gripforge-kit-guest`) is a path dependency of the repository; it is not\n  published as a package, and there is no binding for another language.\n- **Cost.** A kit module pays for each call to the core (about a microsecond plus the copy of the values): read once\n  per hook, prefer one `query` to many `get`, set the per-tick mask (topic `kit-modules` §3 and §6).\n"
 },
 {
  "id": "abi",
  "title": "The presentation ABI (gripforge:present@1)",
  "summary": "present.wit, the engine-neutral contract for a host (Bevy, Godot, Unity, Unreal), and the rules of present_abi.rs.",
  "source": "native/gripforge-runtime/format/present.wit",
  "text": "# present.wit — gripforge:present@1\n\n```wit\n// gripforge:present@1 — the presentation ABI of the kit modules, described in WIT.\n//\n// Today a module is a core WebAssembly module (wasm32-unknown-unknown, no import) and its payloads are postcard\n// bytes of the Rust types of `format/src/present_abi.rs` (the reference: field order = encoding order). This\n// file is the engine-neutral description of the same contract, kept in step with it, so a host can be written\n// from it (Bevy today; Godot, Unity, Unreal later) and so the modules can move to the component model when the\n// browsers run it without glue. The core exports map 1:1 on the `module` interface:\n//\n//   gf_abi() -> u32                      abi-version\n//   gf_alloc(len: u32) -> u32            (memory management of the core form: the host writes the input there)\n//   gf_needs() -> u64 (ptr<<32 | len)    needs   -> module-info\n//   gf_init(ptr, len) -> u64             init    (init)      -> frame-out\n//   gf_frame(ptr, len) -> u64            frame   (frame-in)  -> frame-out\n//\n// Conventions: right handed, Y up, metres, seconds (glTF). Quaternions x, y, z, w. Colours linear RGBA, except the\n// UI (sRGB as CSS). Ids chosen by the module, one space per kind. Compatibility: v1 is frozen; every command is\n// encoded on its own (a host skips and reports one it does not know); evolutions are appended variants only.\n// Level of this description: v1.2 (gf_abi() still answers 1; v1.1 and v1.2 are appended variants, marked in\n// present_abi.rs). Readable offline: `grip-forge docs abi`, MCP `gripforge_docs { topic: \"abi\" }`.\n//\n// ── Writing a host that is not Bevy (Godot, Unity, Unreal, a custom engine) ──────────────────────────────────\n// The Bevy host is player/src/module_host.rs (+ module_host/*.rs, one file per family); this is what any host does:\n//  1. Load. Instantiate the .wasm with NO import (browser WebAssembly, wasmtime / wasmi / Wasm3 natively). Call\n//     gf_abi() (refuse anything but 1), then gf_needs(): decode `module-info` (postcard; field order = the order\n//     below) and add its needs to what you ask of the kit host (the TypeScript KitHost on the web, gripforge-kithost\n//     natively): components, views of services (polled every N snapshots, or on events, or a grid around the\n//     player), event topics, data collections, commands it may send, shared keys, settings.\n//  2. Init. Build `init`: the kit's config (JSON text), the declared collections, the slots bound in the project,\n//     and `host-info` { engine: \"godot\" | \"unity\" | \"unreal\" | …, backend: \"vulkan\" | \"d3d12\" | \"metal\" | \"webgl2\"…,\n//     caps }. Write it with gf_alloc, call gf_init, apply the commands it answers.\n//  3. Each frame. Build `frame-in` with the DELTAS of what the module declared since its previous frame (port\n//     InputTracker of present_abi.rs: entities that appeared or whose declared components changed, gone ids,\n//     changed views / vars / shared / settings as JSON text or none when removed, new events with their seq, the\n//     clip each entity plays, answers to earlier commands in `results`). Call gf_frame; decode each element of\n//     `frame-out.cmds` ON ITS OWN: one that fails to decode or that you do not implement is skipped and answered\n//     with a `refused` result next frame (index + reason) — never fail the frame.\n//  4. Map the families to the engine (see the table below): meshes (positions, normals, uvs, colours, u32\n//     triangles), the glTF metallic-roughness material (std-material is the baseline every host must reproduce;\n//     material-wgsl is optional: translate it with naga to GLSL / HLSL / SPIR-V / MSL, or draw its `fallback`\n//     std-material and report it), a node tree with local transforms (parent: world, a node, a kit entity, a named\n//     node or bone of its model, the camera), skeleton overrides and two-bone IK, lights, CPU particles, ribbons,\n//     projected decals, a retained UI tree (or ui.webui: the HUD as web UI), a camera pose / mode / shake, full\n//     screen passes, sounds (through the audio kit), pick shapes.\n//  5. Requests to the kit host: kit-call (capability.method + JSON args, optional reply key → a `reply` result),\n//     kit-emit (an event), read-config (→ a `config` result), share (a key other modules may read). Only what the\n//     module declared in needs.commands / needs.shared is accepted.\n//  6. Isolation. Ids are per module (key = module index + id). A module that traps is disabled and reported; the\n//     others go on. Free every resource of a module when it is unloaded.\n// Caps (host-info.caps) — what the host draws beyond the baseline; announce only what you really do:\n//   bit 0 wgsl-material · 1 post-pass · 2 shadows · 3 hdr · 4 audio · 5 ui · 6 bones · 7 decals · 8 float-textures\n//   · 9 texture-arrays · 10 wgsl-surface · 11 scene-depth · 12 web-ui (React fragments: the web only)\n//   · 13 render-targets.\n// A host is checked with the module traces: every module has tests/<name>.player.json (snapshots) and\n// <name>.trace (the commands, one per line); replay the snapshots through your host's InputTracker port and\n// compare what you send each module with what the SDK harness sends (sdk/src/harness.rs).\npackage gripforge:present@1.0.0;\n\ninterface types {\n    type vec2 = tuple<f32, f32>;\n    type vec3 = tuple<f32, f32, f32>;\n    type quat = tuple<f32, f32, f32, f32>;\n    type rgba = tuple<f32, f32, f32, f32>;\n\n    record xf { t: vec3, r: quat, s: vec3 }\n\n    variant parent {\n        world,\n        node(u32),\n        entity(string),\n        entity-node(tuple<string, string>),   // entity, named node or bone of its model\n        camera,\n        camera-position,\n    }\n\n    // ---- what a module declares (gf_needs) --------------------------------------------------------------\n    record view-decl { name: string, service: string, method: string, args-json: string, on: list<string>,\n                       every: u32, grid: option<tuple<f64, f64>> }\n    record needs-decl { components: list<string>, views: list<view-decl>, events: list<string>,\n                        data: list<string>, commands: list<string>, shared: list<string>, settings: list<string> }\n    record module-info { abi: u32, kit: string, version: string, needs: needs-decl }\n\n    // ---- what the host gives ----------------------------------------------------------------------------\n    record host-info { engine: string, backend: string, caps: u32 }\n    record init { abi: u32, kit: string, config-json: string, data: list<tuple<string, string>>,\n                  assets: list<tuple<string, string>>, kits: list<string>, generic-json: string,\n                  model-slots: list<string>, texture-slots: list<string>, host: host-info }\n    record camera-state { position: vec3, rotation: quat, fov-y: f32, viewport: vec2, view-proj: list<f32>, mode: string }\n    record stage { exposure: f32, composed: bool, cinematic: bool, title: bool, hud-hidden: bool }\n    record event-in { topic: string, payload-json: string, entity: option<string>, seq: u64 }\n    record entity-delta { id: string, kind: string, tags: list<string>, transform: xf,\n                          model: option<tuple<string, option<string>>>, components: list<tuple<string, option<string>>> }\n    record clip-in { state: option<string>, clip: string, looped: bool, speed: f32, sequence: f64, duration: f32,\n                     time: f32, matched: string }\n    // host-result: refused, shader, bound, reply, loaded, bounds, picked, slot, model, texels, skeleton\n    // (see `HostResult` in present_abi.rs)\n    record frame-in { frame: u64, tick: u64, phase: string, time: f64, dt: f32, step: f32, camera: camera-state,\n                      player: option<xf>, stage: stage, views: list<tuple<string, option<string>>>,\n                      events: list<event-in>, entities: list<entity-delta>, gone: list<string>,\n                      vars: list<tuple<string, option<string>>>, results: list<list<u8>>,\n                      clips: list<tuple<string, option<clip-in>>>, shared: list<tuple<string, option<string>>>,\n                      settings: list<tuple<string, option<string>>>, ext: list<list<u8>> }\n\n    // ---- what the module answers --------------------------------------------------------------------------\n    enum blend-kind { opaque, mask, blend, add, multiply, alpha-to-coverage }\n    record std-material { base-color: rgba, base-texture: option<u32>, emissive: vec3, emissive-texture: option<u32>,\n                          metallic: f32, roughness: f32, normal-texture: option<u32>, unlit: bool,\n                          blend: blend-kind, mask-cutoff: f32, double-sided: bool, depth-write: option<bool>,\n                          depth-test: bool, order: f32, tone-mapped: bool, vertex-colors: bool, fog: bool, layers: bool }\n    record node-flags { visible: bool, cast-shadows: bool, receive-shadows: bool, no-cull: bool, billboard: bool, layer: u8 }\n\n    // The command families (`Cmd` in present_abi.rs, each encoded on its own):\n    //   mesh       mesh-create, mesh-update (attribute range), mesh-free\n    //   texture    texture-create (2D / array, mips, formats incl. float, sampler), texture-slot, texture-free\n    //   material   material-std, material-wgsl (gf_shade | gf_surface, gf_displace), material-params, material-free\n    //   node       node-spawn, node-look, transforms, visible, attach, despawn, node-bind, node-flags\n    //   instancing instances, model-instances, watch-slot\n    //   entity     entity-look, entity-look-clear, entity-offset, entity-linger, entity-clips, claim\n    //   skeleton   bone-override, ik-two-bone, bone-clear, watch-skeleton\n    //   light      light (point, spot, directional, hemisphere)\n    //   scene      scene (fog, sky rotation, sun, ambient, exposure, emissive gain, clear), environment,\n    //              surface-layer, surface-params\n    //   fx         emitter, emitter-burst, emitter-active, emitter-free, trail, ribbon, decal, ground-ring\n    //   ui         ui-tree (resolved themed nodes), ui-free\n    //   camera     camera-pose, camera-mode, camera-shake, camera-release\n    //   post       post-pass (gf_post), post-params, post-free\n    //   audio      audio-play, audio-stop\n    //   pick       pick-parts, watch-bounds, watch-model, read-texture\n    //   kit host   kit-call, kit-emit, share, read-config (v1.2)\n    //   diagnostic log, undrawn\n    // Appended in v1.1: shader (prepared WGSL + optional GLSL ES 3.0 + digest), entity-anim, node-clips, node-child,\n    //   texture-slot-sampled, material-tweak, entity-clips-fade, ambient-flash.\n    // Appended in v1.2: node-mesh-own, node-material, node-texture, node-release, claim-occupants, read-config,\n    //   ui-web, ui-props, ui-web-free, render-target, ui-image, ui-shader, entity-material, model-spawn,\n    //   material-options, material-clearcoat, ui-gradient, scene-set (a key of the scene owned by world.lighting).\n    // How the Bevy host groups them (one file each under player/src/module_host/): mesh.rs (mesh, texture slots),\n    //   material.rs (materials, shaders, textures), node.rs (node, instancing, entity materials, model-spawn, claims),\n    //   scene.rs (light, scene, environment, surface layers, scene-set), fx.rs, ui.rs, skeleton.rs (skeleton,\n    //   entity looks / clips / offsets), camera_post_audio.rs (camera, post, render targets, audio, pick).\n    //   kit-call / kit-emit / read-config / share / log / undrawn are handled by the host itself.\n    record frame-out { cmds: list<list<u8>> }\n}\n\n// The WGSL dialect of a module (material-wgsl, post-pass, surface-layer): plain WGSL functions, no `#import`,\n// no binding, no storage, no compute, nothing WebGPU only. The host prepends what it provides and declares the\n// bindings itself; it validates the result with naga and, for the web, its GLSL ES 3.0 translation (WebGL2):\n//   struct GfIn { uv, uv1: vec2<f32>; position, local, normal: vec3<f32>; color: vec4<f32>; view: vec3<f32>; time: f32 }\n//   struct GfSurface { base_color: vec4<f32>, emissive: vec3<f32>, metallic: f32, roughness: f32, normal: vec3<f32>, occlusion: f32 }\n//   fn gf_param(i: u32) -> vec4<f32>;  fn gf_tex(i: u32, uv: vec2<f32>) -> vec4<f32>;\n//   fn gf_tex_layer(i: u32, uv: vec2<f32>, layer: i32) -> vec4<f32>;  fn gf_time() -> f32;\n//   module writes: gf_shade(GfIn) -> vec4 | gf_surface(GfIn, GfSurface) -> GfSurface, optional gf_displace(GfIn) -> vec3\n//   (gf_displace also runs in the shadow and depth passes); post: gf_post(uv, color) -> vec4 with gf_scene, gf_depth,\n//   gf_world_from_clip, gf_eye; surface layer: gf_layer(GfIn, GfSurface) -> GfSurface.\n// Lighting, fog and tone mapping are the host's.\n\ninterface module {\n    use types.{module-info, init, frame-in, frame-out};\n    abi-version: func() -> u32;\n    needs: func() -> module-info;\n    init: func(input: init) -> frame-out;\n    frame: func(input: frame-in) -> frame-out;\n}\n\nworld present-module {\n    export module;\n}\n```\n\n## present_abi.rs (the reference)\n\n`gripforge:present@1` — the presentation ABI between a player (any engine) and a kit presentation module.\n\nA module is a WebAssembly instance (`wasm32-unknown-unknown`, no import) that turns what the kit host says\n(the part of the snapshot it declared in its needs) into **commands**: meshes, materials, nodes, transforms,\nbones, lights, particles, trails, decals, UI, camera, post passes, audio, claims, pick shapes and requests to\nthe kit host. It draws nothing itself and knows no engine: the same `.wasm` is run by the Bevy player (WebGPU\nand WebGL2, natively under wasmtime) and later by a Godot, Unity or Unreal host. The description in WIT is\n`format/present.wit`; the recipe of a module is `modules/PORTING.md`.\n\n### Exports of a module (all `u32`/`u64`, little endian linear memory, export `memory`)\n- `gf_abi() -> u32`: [`ABI_VERSION`].\n- `gf_alloc(len: u32) -> u32`: a buffer of `len` bytes the host writes an input into. Owned by the module,\n  freed by it after the call it was passed to.\n- `gf_needs() -> u64`: `(ptr << 32) | len` of a postcard [`ModuleInfo`] (kit, version, needs).\n- `gf_init(ptr: u32, len: u32) -> u64`: takes a postcard [`Init`], returns a postcard [`FrameOut`].\n- `gf_frame(ptr: u32, len: u32) -> u64`: takes a postcard [`FrameIn`], returns a postcard [`FrameOut`].\n\nAn answer stays valid until the next call into the module. A module that traps is disabled by the host and\nreported (`kithost.undrawn`); the others go on.\n\n### Conventions (engine neutral)\n- Right handed, Y up, metres, seconds; the axes and units of glTF. A quaternion is `[x, y, z, w]`.\n- Colours are **linear** RGBA floats (`srgb()` of the SDK converts); emissive is a linear radiance multiplier\n  (`[1, 1, 1]` adds the colour as it is). `tone_mapped: false` asks for a colour shown as written (the\n  `toneMapped: false` of the web): the host undoes its tone curve.\n- Ids (`MeshId`, `MaterialId`, `NodeId`…) are chosen by the module, one space per kind, any `u32`. Creating\n  an id that exists replaces it.\n- Entities of the kit host are named by their id (`String`); a named node of their model by\n  [`Parent::EntityNode`] (`gf_door`, `gf_wheel_fl`, a bone).\n\n### Compatibility\nv1 is frozen. Every command is encoded on its own ([`FrameOut::cmds`] holds the bytes of each one): a host\nthat does not know a command skips it and reports it ([`HostResult::Refused`]), the others apply. Evolutions\nare **appended** variants of [`Cmd`], [`HostResult`] or [`Ext`] — never a field added to an existing struct\n(postcard has no optional field). Asked of the architect of the ABI, upward compatible only.\n\n### What a host must implement (Bevy today; Godot, Unity, Unreal later)\n1. Load the `.wasm` (browser `WebAssembly.instantiate`, wasmtime/wasmi, …), call `gf_abi` and `gf_needs`, add\n   the needs to what it asks of the kit host.\n2. Each frame, build the [`FrameIn`] of each module with [`InputTracker`] (or its port), call `gf_frame` and\n   apply the commands in order. The resources of a module are its own: freed when it is unloaded.\n3. Map each command to the engine: a mesh (positions, normals, uvs, colours, u32 triangles), a PBR material\n   (metallic-roughness, the glTF one) or an unlit one, a node tree with local transforms, a skeleton override,\n   lights, a CPU particle emitter, ribbons, projected decals, a retained UI tree, a camera, a fullscreen pass,\n   sounds. [`StdMaterial`] is the baseline every engine reproduces; `WgslMaterial`/`PostPass` are an option: a\n   host without WGSL translates it (naga → GLSL/HLSL/SPIR-V/MSL) or draws `fallback` and reports it.\n4. Validate WGSL before use (naga, and for the web its GLSL ES 3.0 output: the WebGL2 path is mandatory).\n   No compute, no storage buffer or texture is ever accepted from a module.\n"
 },
 {
  "id": "modding",
  "title": "Modding contract (mods.engine)",
  "summary": "The extension and modding contract of game.engine: hooks, registries, moddable keys, the gripforge.mod/1 format, applying mods.",
  "source": "docs/en/mods-engine.md",
  "text": "> English translation of [../mods-engine.md](../mods-engine.md) (French, the reference). Kept in step by hand.\n> Terms used here (kit, hook, tap, scene, archetype, port, parity fixture…) are defined in the [glossary](../glossary.md).\n\n# mods.engine — the extension and modding contract of `game.engine`\n\n> Design and status document. Language: French for the prose in the reference text, English for code and\n> identifiers.\n>\n> \"mods.engine\" is the **name of a layer of `game.engine`**, not a kit of the catalogue: the contract, the services\n> `engine.hooks` and `engine.mods`, the collections `hooks` and `mods`, the format `gripforge.mod/1`. It comes with\n> the **contract `game.engine@1.2.0`**. This document extends `docs/game-engine.md` and `docs/game-engine-contract.md`;\n> it does not replace them.\n>\n> **Status** (branch `bevy-mod-int`, 2026-10-10): the base is built and proven in parity on the **web and Rust**;\n> **the catalogue is migrated**: 145 kits out of 152 follow the contract (296 hooks declared in 108 kits,\n> `moddable` declared by 147), 7 remain as exceptions (the four `legacy.*` kits outside the contract, `game.engine`,\n> `world.district`, `world.trails`: §8). **707 parity fixtures identical** in TypeScript and in Rust, including 109\n> `hooks` fixtures and 35 `mods` fixtures. For Godot, Unity and Unreal: mods are applied at delivery time, and hook\n> execution is **described (§6), not written**: all hooks of the kits delivered to those engines are declared\n> `targets: ['web', 'rust']`. What is checked and what is not: §12; what the batches ask of the core for\n> `game.engine` 1.3: §9.5.\n\n---\n\n## 0 · On one page\n\n**The owner's request.** Kits must be generic, modular and configurable. Games must be moddable. The two go\ntogether: for a game to be moddable, each kit must expose its decisions, its settings and its data; and a kit that\nexposes them is a kit that a game can bend to its needs **without recoding it or making a local copy of it**. That\nis the double role.\n\n**The first user is not the player, it is the game.** The same extension points serve three levels, from most to\nleast trusted:\n\n| Level | Who | Through what | Trust |\n|---|---|---|---|\n| **Project** | the game's creator, the AI agents that assemble it | its data: kit config, collections, `gripforge.script/1` scripts, `hooks` documents | that of the project (validated by schema, as today) |\n| **Game code** | the creator, outside the hosted page (`docs/game-engine.md` §10) | `engine.hooks.tap(...)`, `declare(...)`, verbs, components, services | trusted code, where code is already allowed |\n| **Mod** | a player | a `gripforge.mod/1` package: exactly what the project level can do, packaged, versioned, applied on top | **none**: untrusted data, limited to what the kits declare moddable and to what the game allows |\n\nSo a mod has **no power of its own**: it cannot do anything that the project could not do with its own data.\nDesigning the project level means designing the mod.\n\n**What `game.engine` 1.2 adds, once, for all kits:**\n\n1. **Interceptable hooks** (`engine.hooks`): a kit declares its decisions (`engine.hooks` in its manifest) and\n   submits them before applying them; the game, its code or a mod can change the fields declared mutable, or\n   cancel the decision, in a deterministic order (§4.3).\n2. **Declaring what can be overridden** (`engine.moddable`): which config keys, which collections, which live\n   settings a mod is allowed to touch. Nothing is moddable by default (§4.6).\n3. **The mod layer** (`engine.mods`, `applyMods`): a mod is applied **before the kits are mounted**, entirely or\n   not at all, with a report of what is refused and why (§3).\n4. **The check**: `qa/gamekits-mods-contract-check.mjs` checks the contract on every kit; the kits not yet migrated\n   are in a dated exception list that must empty batch by batch (§5, §8, §9).\n\n**What is not added.** No existing mechanism is duplicated: events and their schema, verbs, components, services,\ncollections, config and live settings enter the contract **as they are** (§4). No mod code is executed (§3.6).\n\n---\n\n## 1 · What we take from a classic modding platform\n\nSources: the documentation of a classic, widely used modding platform for a sandbox game and of its newer fork\n(*Concepts › Events*, *Concepts › Registries*, *Getting Started › Mod Files*, *Data Maps*, *Global Loot Modifiers*,\n*Capabilities*, *Data Attachments*, *Configuration*), the documentation of an older major version of the original\nplatform, the game's community wiki for data packs, the documentation of a code-patching library, and the report of a malware incident that spread through mods. The first\nthree pages of the newer fork were reread on 2026-10-09 for this table (priorities and order,\n`ICancellableEvent` / `receiveCanceled`, `TriState`, parallel mod bus; `DeferredRegister`, `RegisterEvent`, data\npack registries; the mod metadata file (`mods.toml`): `type` `required / optional / incompatible / discouraged`,\n`versionRange`, `ordering`, `side`); the rest comes from knowledge of these documentations, not reread that day.\nThe basic difference: a mod on that platform is **trusted Java code** installed by the player on their own machine;\na GripForge mod is **untrusted data** applied to a hosted game that is exported to five targets. So everything\nmust stay declarative, validated, deterministic and portable.\n\n| Concept in the classic platform (and its fork) | What it is | Here | Why |\n|---|---|---|---|\n| **Event bus with priorities** (`@SubscribeEvent`, `EventPriority` `HIGHEST…LOWEST`, registration order at equal priority) | Mods listen to what the game announces | **Taken as is**: the host bus already uses decreasing priority then subscription order, deterministic (`runtime/bus.ts`). Events stay **past facts**. | Exists, ported to the five targets. |\n| **Cancellable events** (`@Cancelable`, `ICancellableEvent`, `receiveCanceled`) | A listener prevents the action | **Adapted**: this is the **hook** (§4.3), separate from the bus. A cancellation stops the chain; no `receiveCanceled` in v1. | On the host bus, events are queued and dispatched at the end of the tick: you cannot cancel a decision already taken. A hook is synchronous, at the moment of the decision. |\n| **Events with a result** (`Event.Result` `ALLOW / DEFAULT / DENY` in the original; in the fork a `TriState` or a `Result` enum specific to each event, with its setters) | A listener changes the outcome | **Adapted**: the hook's `mutable` fields, typed by schema. The fork carries the result per event rather than through a generic type: same choice. | A named, bounded field can be validated; a generic tri-state cannot. |\n| **Two buses** (mod bus for the life cycle, game bus for gameplay) | Separate loading from play | **Rejected**: a mod has no executed life cycle. | No mod code. |\n| **Registries and deferred registration** (`namespace:path`, `DeferredRegister`, `RegisterEvent`, frozen registries) | Every object has an identifier, registered at a precise phase, before anyone reads | **Taken in spirit**: the registry exists (`engine.content`: archetypes, claimed components, kit collections). \"Deferred registration\" becomes: **mods are applied before mounting**, then the content is frozen for the game session. | Same guarantee (nobody reads a half-filled registry), without a phase to program. |\n| **`modid:name` namespace** | No collision between mods | **Adapted**: a document added by a mod whose id is already taken is **refused** (`id_taken`); the origin of every added document is tracked (`engine.mods.originOf`). Prefixing with the mod id is recommended, not enforced (decision §11). | Content ids are `[a-z][a-z0-9_]*` on five targets; changing their form would break games. |\n| **Data-driven registries** (datapack registries) | Content that exists only as files | **Taken**: this is the whole content model of `game.engine`. | — |\n| **Missing entries** (`MissingMappingsEvent`: `IGNORE / WARN / FAIL / REMAP`; aliases in the fork) | Load a saved world after a mod was removed | **Adapted**: the save records the applied mods; on load with other mods, `engine.mods.changed { missing, added, changed }` is emitted and the game loads what still exists (§3.5). No `REMAP` in v1. | Never block a game; remapping needs a renaming table per mod. |\n| **Life cycle** (constructor, registries, a common setup event, messages between mods, a load-complete event, parallel dispatch) | The loading phases of a mod | **Reduced to four steps without code**: read, order, apply, mount (§3.3). No IMC (inter-mod messages): a mod talks to another by patching its documents. | No code, so no phases to orchestrate and no parallelism. |\n| **Metadata** (`mods.toml`: `modId`, `version`, `displayName`, `[[dependencies]]` with `type`, `versionRange`, `ordering`, `side`) | Identity, dependencies, order | **Taken**: `id`, `version`, `name`, `description`, `author`, `requires` (kits and version ranges), `depends` (`mod`, `version`, `optional`), `conflicts` (= `type: incompatible`) (§3.1). `ordering: BEFORE`, `type: discouraged` and `side` rejected. | A single ordering direction is enough and sorts without surprises; there is no client / server side in a data mod. |\n| **Load order** (topological sort, ties by discovery order, cycle = error) | Determinism | **Taken**: stable topological sort, ties broken by the order the game wants, then document order; a cycle refuses the mods in the cycle (§3.3). | — |\n| **Missing or incompatible dependency** (load error, the game does not start) | Loading safety | **Adapted**: the mod is **refused**, the game starts without it, the report says why. | `game.engine` rule: an error drops one piece, never the game (`docs/game-engine.md` §1.2). |\n| **Typed config per mod** (`ModConfigSpec`, `defineInRange`, `CLIENT / COMMON / SERVER`, correction of invalid values, `Reloading`) | Validated settings, some synchronised, some live | **Taken**: this is `configSchema` + `defaults` (validated, bounded) and the live settings `<capability>.settings`. An invalid value coming from a mod **refuses the mod** (no silent correction). `CLIENT / SERVER` types: see \"separation\" below. | Already exists. Silent correction would hide an error in untrusted content. |\n| **Capabilities attached to objects** (`Capability`, `AttachCapabilitiesEvent`; then `BlockCapability` + data attachments in the fork) | Graft data and behaviours onto other people's objects | **Exists**: archetype components (`engine.components`, `registerComponent`) for data, `provides / requires` capabilities for services. A mod can **put** existing components on its archetypes; it cannot **define** new ones (that would need code). | The fork separated capability lookup from attached data; that is already the components / services split here. |\n| **Data packs and resource packs** (a pack metadata file, namespaces, the last pack wins per file, tags merge unless `replace`, invalid file ignored, `mod_loaded` conditions, global loot modifiers with priority, data maps with `replace / remove`) | Content without code | **This is exactly v1.** Taken: override per document, explicit merging (`set / append / update / remove`), priorities on modifiers (hooks), `mod_enabled` condition. Adapted: a mod applies **entirely or not at all** (the classic platform skips file by file). | A half-applied mod is the worst state for a player and for a save. |\n| **Client / server separation** (`Dist`, logical sides, channel negotiation on connection) | Do not run client code on the server; refuse an incompatible client | **Reduced**: a mod is gameplay data, so \"common\". In multiplayer, all peers must play the same modded project: the fingerprint of the list of applied mods goes into the handshake (to do, §9 batch M-N). Purely local settings (graphics, keys) are not mods. | No code to isolate; what remains is the need for agreement between peers. |\n| **Mixins, coremods, access transformers** (`@Inject`, `@Redirect`, `@Overwrite`, priorities, conflicts) | Change the game's code where no event exists | **Rejected.** What we lose: the ability to change a behaviour that no kit planned to expose. What it would cost: running third-party code (five languages, five engines), conflicts between mods that cannot be arbitrated, fragility at every kit version, and no provable parity. The answer here is the opposite: **if a point is missing, we add it to the kit** (that is the QA check and the migration). | The platform itself presents `@Overwrite` as fragile; the security is that of native code (Fractureiser, 2023: compromised mods stole credentials and tokens). |\n\n---\n\n## 2 · The three levels, and what each one is allowed to do\n\n| Mechanism | Project | Game code | Mod |\n|---|---|---|---|\n| Config of a kit | any key of `configSchema` | same | only the keys of `engine.moddable.config`, unless the game refuses |\n| Documents of a collection | any declared collection | same | only the collections of `engine.moddable.collections`: add, patch, remove |\n| Archetypes, instances, scenes, scripts | yes | yes | yes (collections `archetypes`, `scenes`, `scripts` of `game.engine`) |\n| Rules and scripts plugged into events | yes | yes | yes |\n| Hooks: data taps (`hooks`) | yes | yes | yes, except hooks refused by the game (`mods.deny.hooks`) |\n| Hooks: code taps (`engine.hooks.tap`) | — | yes | **no** |\n| Declaring a hook, a verb, a component, a service | — | yes (`declare`, `registerAction`, `registerComponent`, `provide`) | **no** |\n| Live settings (`<capability>.settings`) | yes (`world.bindings`, verb `call`) | yes | through its rules, on the keys of `engine.moddable.settings` |\n| Code modules (`code_modules`), local kit copies (`overlays`) | yes | yes | **never** |\n| The mods themselves (`mods`) | installs, orders, disables, forbids | — | **never** (a mod does not change the list of mods) |\n\n**Relation to the local kit copy.** The product rule stays: an agent may modify a kit for a project (local copy:\nconfig, code, runtime), and a modified kit is no longer updated automatically. The contract makes this copy\n**rarely necessary**. Instruction for agents and tools: *to adapt a kit to a game, first use its extension points\n(config, documents, rules on its events, taps on its hooks); recode or copy the kit only as a last resort, with a\none-line justification.* Three cases, taken from the reference kit `trade.shop`, where a local copy was needed until\nnow and where data is enough:\n\n| What the game needs | Before | Now |\n|---|---|---|\n| Half price once the quest is handed in | copy the runtime, read the quest variable in it | a `hooks` document: `{ \"hook\": \"shop.buy\", \"if\": [{ \"var\": \"story.lantern_found\", \"op\": \"==\", \"value\": true }], \"mul\": { \"price\": 0.5 } }` |\n| A quest item cannot be sold back | copy the runtime, add a test | `{ \"hook\": \"shop.sell\", \"match\": { \"item\": \"cellar_key\" }, \"cancel\": true, \"reason\": \"quest_item\" }` |\n| Merchant closed at night | copy the runtime, or disable the interaction with a fragile script | `{ \"hook\": \"shop.open\", \"if\": [{ \"var\": \"world.night\", \"op\": \"==\", \"value\": true }], \"cancel\": true, \"reason\": \"closed\" }` |\n\nThese three documents are played in the fixture `game.engine.village_hooks` (§7).\n\n---\n\n## 3 · A mod\n\n### 3.1 The format (`gripforge.mod/1`)\n\nA document of the `mods` collection of `game.engine`. Schema: `MOD_SCHEMA` (`kits/game.engine/mods.ts`).\n\n```json\n{\n  \"schema\": \"gripforge.mod/1\",\n  \"id\": \"golden_village\", \"name\": \"Golden village\", \"version\": \"1.0.0\", \"author\": \"…\", \"description\": \"…\",\n  \"enabled\": true,\n  \"requires\": { \"game.engine\": \"^1.2\", \"trade.shop\": \"^1.1\" },\n  \"depends\": [{ \"mod\": \"base_pack\", \"version\": \"^1\", \"optional\": false }],\n  \"conflicts\": [\"other_mod\"],\n  \"config\": { \"trade.shop\": { \"buyRate\": 0.8 } },\n  \"data\": {\n    \"archetypes\": { \"add\": [{ \"id\": \"gv_fountain\", \"kind\": \"prop\", \"components\": { \"interactable\": { \"label\": \"gv.wish\" } } }] },\n    \"scenes\":     { \"patch\": [{ \"id\": \"village\", \"append\": { \"instances\": [{ \"id\": \"gv_fountain_1\", \"archetype\": \"gv_fountain\", \"at\": [1, 0, 1] }] } }] },\n    \"shops\":      { \"patch\": [{ \"id\": \"peddler\", \"update\": { \"offers\": [{ \"match\": { \"item\": \"lantern\" }, \"set\": { \"price\": 20 } }] } }] },\n    \"scripts\":    { \"add\": [{ \"id\": \"gv_receipt\", \"rules\": [{ \"when\": { \"event\": \"shop.bought\" }, \"then\": [{ \"inc_var\": { \"path\": \"gv.purchases\" } }] }] }] },\n    \"hooks\":      { \"add\": [{ \"id\": \"gv_tax\", \"hook\": \"shop.buy\", \"priority\": -10, \"add\": { \"price\": 1 } }] }\n  }\n}\n```\n\n- **Identity**: `id` (`[a-z][a-z0-9_]*`, unique in the project), `version` (`x.y.z`).\n- **Compatibility**: `requires` — kit id → version range (`*`, `1.2.3`, `^1`, `^1.2`, `~1.2`, `>=`, `>`, `<=`,\n  `<`, several separated by spaces; the same subset in Rust). `game.engine` appears there like any other kit: it is\n  the contract version.\n- **Dependencies**: `depends` (another mod, its version range, `optional`), `conflicts`.\n- **Config overrides**: `config.<kit>.<key>`; an object merges key by key, anything else replaces.\n- **Content**: `data.<collection>` with three operations, applied in this order:\n  - `remove: [ids]` — removes documents (a missing id: warning);\n  - `patch: [{ id, set?, remove?, update?, append? }]` — changes an existing document (missing: refusal):\n    `set` merges keys (`id` is never rewritten); `remove: { \"<path>\": [values] }` removes from an array the\n    elements equal to a value or that carry all of its keys; `update: { \"<path>\": [{ match, set }] }` changes the\n    array elements that carry `match`; `append: { \"<path>\": [elements] }` adds to an array (an element whose `id`\n    already exists replaces it). A path is a sequence of object keys separated by dots;\n  - `add: [documents]` — adds (an id already taken: refusal, \"patch it instead\").\n- **Rules, scripts, wiring**: these are documents like any other (`scripts`, `hooks`, `triggers` when the kit that\n  owns them declares them moddable).\n- **Assets**: in v1 a mod **points to** assets the game already has (slots, `content:<id>`, Library ids).\n  Shipping files inside a mod is an open decision (§11): it is a matter of storage, moderation and size, not an\n  engine problem.\n\n### 3.2 Where a mod is stored, who puts it there\n\nProposal (the decisions are in §11):\n\n- **The creator** puts mods in the project's `mods` collection (through `PATCH …/data` like any content, so through\n  the MCP server and the CLI). It is also the way to ship **variants** of a game (a hard mode, a seasonal event)\n  without duplicating the project.\n- **Players**: the application merges the mods the player enabled into the project document **that it hands to\n  the host**; the host does not know where they come from, it applies them all with the same function. So the engine\n  needs to know nothing about storage. Where they are offered (a gallery per game, an imported file) and who\n  moderates them: owner decisions.\n- **The game's policy** (`config.mods` of `game.engine`) belongs to the creator: `enabled` (no mods),\n  `disabled` (mods installed but not applied), `order`, `deny: { kits, collections, hooks }` (what the mods of this\n  game do not touch, among what the kits declare moddable).\n\n### 3.3 Loading: read, order, apply, mount\n\n`applyMods(project, manifestOf)` (`mods.ts`, pure; `mods.rs` in Rust):\n\n1. **Read.** Each `mods` document is validated against `MOD_SCHEMA`. Invalid, duplicated, or beyond 64 mods:\n   refused.\n2. **Set aside the disabled ones** (`enabled: false`, `mods.disabled`, `mods.enabled: false`): status `disabled`.\n3. **Order.** The order the game wants (`mods.order`) first, then document order; a mod always comes after the mods\n   it depends on. A cycle refuses the mods in the cycle.\n4. **Apply**, mod by mod, on a working copy: compatibility (`requires`), dependencies, conflicts, then `config`,\n   then `data`. Each touched config is validated against the kit's `configSchema`, each touched document against\n   its collection's schema. **A single error refuses the whole mod**; the working copy is then thrown away and the\n   next mod starts from the previous state.\n5. **Mount.** The host mounts the resulting project. It carries a `mods` section (`gripforge.mods/1`): applied\n   mods in order, status and problems of each mod, origin of each added document.\n\nA project **without a `mods` document** is returned as is, the same object: nothing changes for existing games.\n\n**Readable refusals.** Each problem carries `level`, `code`, `path`, `message`:\n`schema_invalid`, `too_many`, `duplicate_mod`, `kit_missing`, `kit_incompatible`, `dependency_missing`,\n`dependency_incompatible`, `dependency_cycle`, `conflict`, `denied`, `kit_unknown`, `config_not_moddable`,\n`config_invalid`, `collection_unknown`, `collection_not_moddable`, `doc_missing`, `doc_invalid`, `id_taken`,\n`path_invalid`, `hook_unknown` (warning). Real example (fixture `village_modded`): *\"its kit does not declare items\nmoddable\"*, *\"made for trade.shop ^2, the game has 1.1.0\"*.\n\n### 3.4 Enabling and disabling\n\nMods are applied **at mount time**. Enabling or disabling a mod means remounting the game with another list: there\nis no switch during a game session in v1 (a mod changes documents that the kits have already read). This is the\nchoice made by the data packs of the classic platform (`/reload` reloads everything). So `engine.mods` is read-only\nat run time: `list()`, `applied()`, `has(id)`, `originOf(collection, id)`; the script condition `mod_enabled` lets\ncontent adapt to the presence of a mod.\n\n### 3.5 Saves\n\n- The `game.engine` save section records `mods: [{ id, version }]` when there are any (a game without engine\n  content then saves only `{ v, mods }`).\n- On load, if the list differs: `engine.mods.changed { missing, added, changed }`, then loading continues. The\n  engine already ignores instances, scripts and scenes that no longer exist; the sections of the other kits are\n  reloaded as they are (a kit that keeps state per document must tolerate a document that disappeared: this is a\n  review criterion, §5).\n- The lock hash (`lockHashOf`) does not change: a `compatibility: strict` save does not break when a mod is added.\n  Do we need the reverse (refuse a save made with other mods)? Decision §11.\n\n### 3.6 Security\n\nA mod comes from a player: **untrusted content**.\n\n- **No code.** A mod contains only schema-validated data. The only \"behaviours\" are rules of the trigger DSL and\n  hook taps (equalities, DSL conditions, five numeric operations). No loops, no free expressions, no access outside\n  the game state.\n- **Allow-list, on two levels.** A mod touches only what a kit declares in `engine.moddable`, minus what the game\n  refuses (`mods.deny`). The `mods` and `code_modules` collections are forbidden, hard-coded. A kit that is not\n  migrated is not moddable at all: the security check **is** the migration.\n- **Bounded hooks.** A tap writes only the hook's `mutable` fields, with a value that matches the field's schema\n  (`price: min 0`); otherwise the write is dropped and `engine.hook.refused` reports it.\n- **Limits**: 64 mods per project, 2,000 documents per operation, 256 KB per mod (to be enforced by the server on\n  write), 16 conditions per tap.\n- **What still needs watching** (review, not the engine): a mod can make a game unplayable or misleading within the\n  limits of what is moddable (a price of zero, an offensive text). That is moderation, and the reason why the game\n  has a policy (`deny`) and an activation list.\n- **Texts**: a mod writes `i18n.text` keys or plain text in the fields the schemas allow; no HTML is interpreted by\n  the kits' views (this must stay true: a review criterion for `view` kits).\n\n**Second step, not done: sandboxed mod code.** It would be the same decision as \"game code on the hosted page\",\nrefused for now by the owner (`docs/game-engine.md` §16, decision 4). Possible form: a WebAssembly module with no\nimports beyond a hooks API (no clock, no network, no DOM), with a bounded instruction budget, deterministic, the\nsame binary on the web and in Rust. Risks: three engines that would have to embed a WASM interpreter; a cost per\nhook call; parity to prove for each mod; the attack surface of an interpreter; moderating binaries. What we lose\nwithout it: the behaviours that no kit exposes — and the answer is still to expose the point in the kit.\n\n---\n\n## 4 · The extension contract required of every kit\n\nA **closed** list of the kinds of extension points. For each one: how a kit declares it, how it is checked, how it\nis documented (the building-block catalogue `gripforge_game_engine blocks` reads the manifests: every declaration\nshows up there without writing anything more).\n\n| # | Kind | Declaration in the manifest | Mechanism | New in 1.2? |\n|---|---|---|---|---|\n| 1 | Emitted events | `events.emits[]`: `topic`, `payload` (schema), `description` | host bus | no — the **schema becomes mandatory** |\n| 2 | Listened events | `events.listens[]` | host bus | no — the **declaration becomes checked** |\n| 3 | Interceptable hooks | `engine.hooks.<name>`: `payload`, `mutable[]`, `cancellable`, `description`, `targets?` | `engine.hooks` | **yes** |\n| 4 | Verbs and conditions | `engine.verbs.<name>` (+ `extensions`) | `ctx.triggers`, `engine.scripts` | no |\n| 5 | Config | `configSchema`, `defaults`, `configRules` | project config | no |\n| 6 | Overridable and live-tunable | `engine.moddable`: `config[]`, `collections[]`, `settings[]` | mod layer; `<capability>.settings` | **yes** (the declaration) |\n| 7 | Data collections | `data[]` (schema), `engine.sceneCollections`, `runtime.core.defaultData` | `project.data` | no |\n| 8 | Archetype components | `engine.components.<name>` | `engine.content.registerComponent` | no |\n| 9 | Services | `provides[]`, `requires[]` | `ctx.services` | no |\n\n### 4.1 Emitted events\n\nEvery significant action of a kit emits an event **declared with the schema of its payload**\n(`events.emits[].payload`, a `GkSchema` object). An event is a done fact: you react to it (rules, scripts, other\nkits), you do not change it. No event on every tick for a continuous state: use a variable (`vars`) or a read\nservice.\n\n### 4.2 Listened events\n\nEvery topic the runtime subscribes to is in `events.listens`. This is what lets the catalogue say who reacts to\nwhat, and lets a game know what it triggers when it emits a topic.\n\n### 4.3 Interceptable hooks\n\nA hook is a point where a kit **asks before deciding**.\n\n```ts\n// manifest\nengine: { hooks: {\n  'shop.buy': {\n    payload: s.obj({ shop: s.str(), item: s.str(), count: s.int({ min: 1 }), price: s.num({ min: 0 }) }),\n    mutable: ['price'], cancellable: true,\n    description: 'The player is about to buy count units for price (the total).',\n  },\n} }\n\n// runtime (web) — the same call on every target\nconst asked = ctx.services.get<EngineHooksService>('engine.hooks')?.run('shop.buy', { shop, item, count: n, price });\nif (asked?.cancelled) return refuse(shop, item, asked.reason ?? 'refused');\nconst total = asked ? asked.payload.price : price;\n```\n\n- **Who taps.** In code (`tap(hook, fn, { priority, owner })`, kits and game code) or in data (the project's `hooks`\n  documents, then those added by mods).\n- **Order, deterministic**: decreasing priority (default 0, bounded to ±1000); at equal priority, the layer (`kit`,\n  then `project`, then `mod`); then registration order (kit mount order, document order, mod application order).\n  Each tap sees the payload left by the previous ones: **the last one has the last word**, so the lowest priority\n  (like `LOWEST` in the classic platform). A game that wants the last word over its mods gives its tap a negative\n  priority, or forbids the hook (`mods.deny.hooks`).\n- **What a tap answers**: nothing, `{ set: { field: value } }`, `{ cancel: true, reason }`. Nothing else.\n- **Safeguards**: only `mutable` fields change, with a value that matches the field's schema; a hook that is not\n  `cancellable` cannot be cancelled; each violation emits `engine.hook.refused { hook, tap, field, reason }`\n  (`not_mutable`, `invalid`, `not_cancellable`) and the chain continues.\n- **Cancellation**: stops the chain; the kit receives `{ cancelled: true, reason, by }` and does what it already\n  does for a refusal (a refusal event, no effect).\n- **Without a tap**, `run` returns the payload unchanged: a migrated kit behaves exactly as before.\n- **A data tap**: `{ id, hook, priority?, match?, if?, set?, add?, mul?, min?, max?, cancel?, reason?,\n  enabled? }`. `match`: equality on payload fields; `if`: conditions of the trigger DSL (variables, zones, kits'\n  condition verbs), with the payload as the event's payload; operations in the order `set`, `add`, `mul`, `min`,\n  `max`.\n- **A hook is not an event.** The manifest validator refuses a hook that is neither cancellable nor mutable.\n- **Naming**: `<domain>.<decision>` in the infinitive (`shop.buy`, `combat.damage`, `wave.spawn`,\n  `inventory.pickup`, `game.end`), where the matching event is in the past tense (`shop.bought`).\n\n**Functions passed between kits** (`combat.damage.addModifier`, `stealth.detection.addFilter`,\n`combat.turns.registerEffect`, `machines.production.addSource`, `npc.behavior.register`…) are the ad hoc ancestor\nof this mechanism. Rule: those that **change or filter a decision** become a declared hook (the historical service\nstays, rewritten as a `tap`: no caller changes); those that **provide an implementation** (an NPC behaviour, a\nproduction source) stay service registrations — they are points of kind 9, not hooks. The audit (§8) lists them\nkit by kit (`fn_registration`).\n\n### 4.4 Verbs and conditions\n\nUnchanged: `engine.verbs` with an argument schema, `primary`, description, example. Every verb in `extensions` is\nalso declared in `engine.verbs` (checked). `game.engine` 1.2 adds the condition `mod_enabled`.\n\n### 4.5 Config\n\nUnchanged: every gameplay constant is a `configSchema` key with bounds, a default and a description. No magic\nnumbers in the runtime (the audit gives a hint per kit, review decides).\n\n### 4.6 What can be overridden, what can be tuned live\n\n```ts\nengine: { moddable: {\n  config: ['buyRate', 'buysAnything', 'restockMinutes', 'interactLabel'],   // keys of configSchema a mod may set\n  collections: ['shops'],                                                   // own collections a mod may add to, patch, remove from\n  settings: ['level'],                                                      // keys of <capability>.settings: change while the game runs\n} }\n```\n\n- A kit that has config keys or collections **states** what a mod may touch (an empty list is a valid and readable\n  answer: \"nothing\"). Do not put in `moddable.config` anything related to security, network, accounts, paths or\n  costs.\n- **Live settings** are the existing mechanism `<capability>.settings` (`KitSettingsService`: `keys`, `get`,\n  `set`, bounded values), driven by `world.bindings` or by a rule (`{ \"call\": \"world.water.settings.set\",\n  \"args\": [\"level\", 2] }`). `moddable.settings` declares which ones exist; nothing new at run time.\n\n### 4.7 Collections, components, services\n\nUnchanged (contract 1.1). Reminders that become criteria: a kit that plays default documents when the project has\nnone **declares** them (`runtime.core.defaultData`) instead of keeping them hard-coded; a kit does not read a\ncomponent claimed by another kit; a kit depends on another only through a capability.\n\n### 4.8 Who depends on `game.engine`\n\n\"Everything depends on it\": every kit has an `engine` block and `requires: ['game.engine@^1']`. Pure services\n(input, theme, network, rendering), \"independent\" until now, take the **`service` role** (added to\n`ENGINE_ROLES`): they have no hook to offer, but they declare their events, their config and what of it is\nmoddable. The resolver already adds the engine to a game where a kit requires it, first and outside the sort: the\nmount order of the other kits does not change (`docs/game-engine.md` §7.6). The `legacy.*` kits are outside the\ncontract (legacy clients, separate exit plan).\n\n### 4.9 A compiled kit follows the same contract\n\nA kit whose rules would be a **Rust module compiled into the runtime** (`native/gripforge-runtime/runtime/src/modules/`,\n`files` adapters, no TypeScript runtime and no kit-host module) is not an exception: same declarations in its\nmanifest; at run time it mounts `game.engine` in its own `gripforge-kithost` session, on the authority (mods through\n`apply_mods`, decisions asked of `engine.hooks.run`, events on the engine bus, save `gripforge.save/1`), and its\nruntime manifest (`native/gripforge-runtime/manifests/<id>.json`) names in `engine_sources` the Rust sources that\n`qa/gamekits-mods-contract-check.mjs` checks. In authoritative networking, hooks and mods are applied only on the\nauthority (the peer whose state is the reference), which announces the fingerprint of its mods to the clients. The\nonly kit of this kind, `dungeon.coop`, was removed on 12/10/2026: the dungeon is played with the kits\n(`world.rooms`, `character.top_down`, `coop.session`…) and the unified player.\n\n### 4.10 `game.engine` 1.3: what a kit and a game write in addition (§13)\n\nEverything is additive: a 1.2 kit or game has nothing to change, and without a new tap or rule the traces are the\nsame.\n\n**For a kit.**\n\n| Need | 1.3 |\n|---|---|\n| A decision of the host or of a library, without a kit context | `decide(services, hook, payload)` (`runtime/decide.ts`, `Host::decide` in Rust): the same tap table. Core hooks, declared by `game.engine`: `mission.complete` (`rewards` mutable, an object; if refused: the mission stays active, the step that had just finished is re-armed, `mission.completion.refused`) and `engine.spawn` |\n| Know that a tap cancelled, and why a field changed | `engine.hooks.decide(hook, payload)` → `{ ok, payload, cancelled, reason, by, notes: [{ tap, reason, fields }] }` (`run` keeps its 1.2 form); a historical `void` service returns `{ ok, cancelled, by, reason }` (`decisionOf`) |\n| A continuous decision | `engine.hooks.hold(hook, key, payload)`: asked once, the answer is kept for `(hook, key)` until `release(hook, key?)`; saved (`held` in the engine section, absent when nothing is held) |\n| Create an interceptable entity | `ctx.spawn.try(spec)` (Rust: `kx.spawn_try`) → `{ ok, id, cancelled, by, reason }`; if cancelled: **no id consumed**; a factory can answer \"nothing\" (`''`) → `reason: 'nothing'`. `spawn` stays as it is |\n| A published variable whose decision the kit keeps | `const set = ctx.state.guard(path, (next, prev) => value \\| undefined)` (Rust: `kx.guard_var(path, kx.callback(…))`, the kit writes through `kx.set_var`): every other write (`set_var`, `inc_var`, another kit, a fixture) goes through the guard; `null` or `undefined` refuses |\n| An ability cooldown | `AbilityPort.decide` (library `abilities/runtime.ts`): `ability.cooldown { source, ability, cooldown }` |\n| A \"nobody\" field, a union | `nullable: true` on any schema (`s.nullable(…)`), `const: null`, `oneOf` everywhere (shared TS / Rust vectors: `tests/schema_vectors.json`, `qa/gamekits-schema-vectors-check.mjs`) |\n| Built topics | `events.emits[].topic` accepts a bus pattern (`fps.tactical.*`) |\n| Know that a provider is installed before it is mounted | `ctx.services.installed(capability)` (Rust: `kx.installed(cap)`): true from the first kit's `setup` on if the resolved lockfile names an installed, active kit as the provider (or if a mounted kit serves it); host capabilities do not count. Replaces any test on another kit's id; `has` stays false until the provider is mounted |\n| A saved random draw | `ctx.rng.state()` → `{ seed, a }` to write in the kit's section, `ctx.rng.restore(state)` on `load` (`false` if invalid); the `fork`s follow; the host saves nothing more |\n| Refuse a peer that does not have the same mods | `engine.mods.fingerprint()`: `''` without mods, otherwise the hash of the canonical JSON of `[[id, version, document], …]` in application order, the same string on the web and in Rust |\n| Everything that can be plugged into a kit | `extensionPointsOf(manifest)` (pure, `kits/game.engine/points.ts`, schemas included); in game `engine.points.of(kit)` / `list()`: the compact view, with the `completeness` counters (also to be served by the MCP `gripforge_game_engine blocks` and a CLI command `points <kit>`) |\n| Be changeable in game by a reaction | `engine.moddable.live: [collections, config paths]`: the kit rereads on `engine.data.changed` / `engine.config.changed` |\n\n**For a game (and a mod): a single \"when / if / then\" language.** The conditions are those of the trigger DSL,\nextended: `{ \"field\": \"<path>\", \"op\": \"==|!=|<|<=|>|>=|in|nin|has\", \"value\": … }` on the payload of the event or\nhook, `in` / `nin` / `has` also for `var`. Wherever a rule writes a value, an object with a single key `$field`,\n`$var`, `$add`, `$sub`, `$mul`, `$div`, `$min`, `$max`, `$round` is computed (any other object stays a literal;\nwithout a value, the action is skipped). A rule has a `priority` (highest first). A chain of rules that keeps\nre-triggering itself is stopped at the 8th generation (`engine.reaction.refused`, `loop`).\n\n*Tap* (before a decision: change, cancel), taken from `game.engine.rules`:\n\n```json\n{ \"id\": \"courier_extra\", \"hook\": \"mission.complete\", \"match\": { \"mission\": \"courier\" },\n  \"patch\": { \"rewards\": { \"append\": { \"items\": [\"potion\"] }, \"set\": { \"money\": { \"$mul\": [{ \"$var\": \"difficulty\" }, 10] } } } },\n  \"reason\": \"tip\" }\n{ \"id\": \"hard_mode\", \"hook\": \"shop.buy\", \"if\": [{ \"field\": \"price\", \"op\": \">=\", \"value\": 50 }],\n  \"mul\": { \"price\": { \"$var\": \"difficulty\" } }, \"reason\": \"hard_mode\" }\n```\n\n*Reaction* (after an event: \"an event changes the data\"), taken from `game.engine.reactions_combat` — the brute\ngets stronger each time the player dies, and stays so after a reload:\n\n```json\n{ \"id\": \"grudge\", \"when\": { \"event\": \"player.died\" }, \"then\": [\n  { \"inc_var\": { \"path\": \"story.deaths\" } },\n  { \"type\": \"patch_data\", \"collection\": \"hooks\", \"id\": \"brute_buff\",\n    \"set\": { \"mul\": { \"health\": { \"$add\": [1, { \"$mul\": [{ \"$var\": \"story.deaths\" }, 0.5] }] } } } } ] }\n```\n\nReaction actions: `patch_data` / `add_data` / `remove_data` (collection declared moddable **and** `live`, document\nvalidated), `set_config` (moddable and `live` path, config validated), `set_setting` (key of `moddable.settings`,\nthrough the `<kit>.settings` service), `set_component` (declared component, value validated). Refusals:\n`engine.reaction.refused { rule, action, reason, path }`, `reason` ∈ `not_moddable`, `not_live`, `doc_missing`,\n`id_taken`, `invalid`, `kit_unknown`, `loop`. Data and config changes form a saved journal (`journal`, absent if\nempty) that is replayed on load before the other kits. `game.engine` declares its `hooks` collection live: a\nreaction adds, changes or removes a tap during play (`game.engine.reactions_mission`: the finished mission lowers\nthe rain intensity and opens a discount on the potion).\n\n**Finer mods and registries (mechanism D).** The same operations everywhere, for a project as for a mod:\n\n- collection operation `order: [ids]` (after `remove`, `patch`, `add`: the listed documents go first, the others\n  keep their order);\n- **default documents**: a mod that patches, removes or orders a collection for which the project has no document\n  is no longer refused (`doc_missing`): its operations wait (`mods.deferred`) and apply to the documents that the\n  kit declares as defaults (`runtime.core.defaultData`), which then become the project's documents (the kit must\n  declare its defaults **before** reading its collection, like `collectionOrDefault`; `enemy_ai.rs` was put back in\n  this order);\n- **config as a document**: `moddable.config` accepts a path (`fog.density`); `config.<kit>` accepts a partial\n  object where every leaf is under a moddable path; `configPatch.<kit>: { set: { \"<path>\": v }, append, update,\n  remove }` adds, removes or replaces **one element** of a config list (a list that the project does not write\n  starts from the manifest default);\n- **settings by pattern**: `moddable.settings: [\"layer.*\"]` (`settingModdable`);\n- **registries**: `engine.registries.<collection>: { of, inherit?, live?, description }`; in an `inherit`\n  registry, `{ id, extends: \"<id>\" }` inherits from an entry (keys merged, the child wins, `extends` removed,\n  missing parent or cycle: document dropped), resolved before mounting (`resolveRegistries`, after the mods).\n  `game.engine` declares `archetypes`: a game adds an interaction to an entity type without touching the kit:\n\n```json\n{ \"id\": \"talking_crate\", \"extends\": \"crate\", \"name\": \"Talking crate\", \"components\": { \"interactable\": { \"label\": \"crate.talk\" } } }\n```\n\n*Binding* (a state → a setting): `world.bindings` keeps its format; its conditions and its writes will go through\nthe same evaluator and the same guarded target as `set_setting` once the kit is wired (step 3 of the batch).\n\n---\n\n## 5 · The criteria\n\n### 5.1 Checked mechanically (`qa/gamekits-mods-contract-check.mjs`)\n\n| Rule | What is checked | Source |\n|---|---|---|\n| `engine_block` | the kit requires `game.engine@^1` and has an `engine` block | manifest |\n| `events_undeclared` | every literal topic emitted by the web runtime is in `events.emits` | manifest + source |\n| `events_no_schema` | every declared event has a payload schema | manifest |\n| `listens_undeclared` | every literal topic the runtime subscribes to is in `events.listens` | manifest + source |\n| `verbs_undeclared` | every verb in `extensions` is declared in `engine.verbs` | manifest |\n| `hooks_none` | a kit that decides (role other than `view` / `service`) and that emits events declares at least one hook | manifest |\n| `hooks_unwired` | every declared hook is run by the adapter of **each target** it announces. On the web and in Rust, the name must be **handed to a call that runs the hook**: an argument of `engine.hooks.run`, or passed on (a kit helper function, a table of hook names, a choice by condition) in a source that calls `run`; an emitted event, a variable, an input or a tag with the same name does not count (`race.pickup`, `sport.kick`). On Godot, Unity and Unreal, as long as hook execution is not ported there: the name appears in the source | manifest + sources of the five targets |\n| `moddable_none` | a kit with config or collections declares `engine.moddable` | manifest |\n| `save_none` | the web runtime of a stateful kit has `save` / `load` | source |\n| `kit_coupling` | no hard dependency: no mandatory `dependencies` line, no import of another kit's runtime, no test on the id of an installed kit. A `dependencies` line marked `optional: true` or `companion: true` **is not a coupling**: it sets a mount order or offers to install a companion; the kit works without the other one and only reaches it through a capability it tests first (`services.has`). A line to a kit of the **same family** (same id prefix: the `net.*` kits to `net.transport`) is not one either: it is the family's internal stacking, read by the resolver and the engine deliveries | manifest + source |\n\nNon-blocking hints, carried in the audit: `events_unported` (a declared topic missing from a target's source),\n`fn_registration` (functions passed between kits), `magic_numbers`, `emit_in_update` (event on every tick),\n`demo_data` (hard-coded demonstration data), `hooks_partial` (hook limited to some targets: an explicit debt, never\nhidden).\n\nThe manifest itself is validated by `validateManifest` (so by `qa/gamekits-resolve-check.mjs` on the whole\ncatalogue): name and schema of a hook, `mutable` fields that exist, hook cancellable or mutable, `moddable` keys\nthat exist in `configSchema` and `data[]`.\n\n**The exception list** `qa/gamekits-mods-contract-exceptions.json` holds, for each kit not migrated, the date it was\nadded and the rules it does not meet. The check fails if a kit misses a rule that is not listed **and** if an\nexception is no longer needed: the list can only shrink. A new kit is never added to it.\n\n### 5.2 Checked by review\n\n- **Every gameplay decision goes through a hook.** The check sees that there is at least one and that they are\n  wired; that none is missing is a judgement. A landmark: does every outcome event (`…ed`) have its hook?\n- **No hidden behaviour that data cannot drive** (a special case coded for one precise id, a behaviour that depends\n  on another kit without saying so).\n- **Constants**: the `magic_numbers` hint shows where to look.\n- **Events on every tick**, **tolerance of a save to a missing document**, **views that do not interpret HTML\n  coming from data**.\n- **Parity across targets**: a hook runs at the same moment, with the same payload, on every target; the proof is\n  the kit's scenario (§9).\n\n---\n\n## 6 · Implementation on the five targets\n\nPrinciple: **everything that can be done before run time is done before**, once, by the same TypeScript function,\nlike the compiled content of `game.engine` (`gameplay.json`, section `engine`). Only one piece remains at run time,\non each target: the hook table.\n\n| Mechanism | Web | Rust / Bevy | Godot, Unity, Unreal |\n|---|---|---|---|\n| **Load and apply the mods** | `KitHost` calls `applyInstalledMods(project)` before mounting (`runtime/host.ts`) | `Host::new` calls `mods::apply_mods` (`host.rs`); faithful port | **At delivery**, not at run time: `withMods` (`delivery/pipeline.ts`, written) applies `applyMods` to the configs and the data **before** `withEngineContent`, removes the `mods` collection from the delivered data and reports each refused mod as a plan warning (`mod_refused`). The engines receive a `gameplay.json` that is already modded: nothing to port. Web and Rust receive the data untouched (they apply at mount time). Consequence: on an exported game, changing mods = delivering again. Player mods on an exported game would require porting `applyMods` into each core (≈ 400 lines per engine): outside v1. |\n| **Config and collection overrides** | done by `applyMods` | same | same (in the delivered data) |\n| **Hook table, order, safeguards** | `runtime/web/hooks.ts` | `game_engine/hooks.rs` + `run_hook` in `game_engine.rs` | **To port** into the `game.engine` kit of each engine. Closest existing equivalent: `GfEngine.register_component(name, callable, owner)` (a callable stored by name) and `GfTriggers.evaluate` (DSL conditions). See the details below. |\n| **Code tap** | `tap(hook, fn, opts)` | `tap(hook, kx.callback(\"name\"), opts)` → `KitModule::callback` | Godot: `GfEngine.tap(hook, Callable, priority, owner)`; Unity: `IEngineHooksService.Tap(hook, Func<GfJObj, GfHookResult>, priority, owner)`; Unreal: `UGfEngineHooksService::Tap(Hook, TFunction<FGfJ(const FGfJObj&)>, Priority, Owner)` |\n| **Data tap** | `hooks` documents of the modded project | same | section `engine.hooks.taps` of `gameplay.json` (already sorted), evaluated by `GfTriggers` |\n| **Event schema** | declared; static check | same | same (the manifests are shared); `events_unported` reports a topic missing from an adapter |\n| **Validation of a field written by a tap** | `validateSchema` | `schema::validate_schema` | the cores have no schema validator: the delivery writes per field `{ type, min, max, enum }` and the port checks these four keywords (the only ones a `mutable` field is allowed to use: to be added to `validateManifest` together with the port) |\n| **`engine.mods`** (read) | service | service | section `engine.mods` of `gameplay.json`, served by `GfEngine` |\n| **Save** | `mods` in the engine section | same | same in `save` / `load` of `GfEngine` |\n\n**Porting hooks to an engine — what has to be written** (one agent per engine; files\n`packages/gamekits/src/delivery/gameplay/engines/<engine>/kits/game.engine/**`):\n\n1. Delivery (shared, TypeScript): `withEngineContent` writes `engine.hooks = { declared: { <hook>: { kit,\n   mutable, cancellable, fields } }, taps: [...] }` and `engine.mods = { applied, mods, origins }`;\n   `CompiledContent` receives these two keys (optional).\n2. Engine: `run(hook, payload) → { payload, cancelled, reason, by }`, `tap`, `untap`, `declare`, `declared`,\n   `taps`, with the sort (decreasing priority, layer, sequence), the evaluation of a data tap (`match`, `if` through\n   `GfTriggers`, `set / add / mul / min / max`, `cancel`), the three refusals and the event `engine.hook.refused`.\n   Line-by-line reference: `runtime/web/hooks.ts` (120 lines).\n3. `mod_enabled` (condition), `engine.mods.applied` on `ready`, `mods` in the save, `engine.mods.changed` on load.\n4. Proof: a scenario `qa/gameplay-engines/scenarios/engine-hooks.json` (a test kit that runs a hook, data taps, a\n   refusal, a cancellation, save) and `engine-mods.json` (a delivered modded project), `≡ web` on the engine:\n   `node qa/gameplay-engines-check.mjs --scenario=engine-hooks,engine-mods\n   --only=<engine>`. Nothing is green on an engine until this command has run.\n\nAs long as this port does not exist, a kit delivered to the three engines declares its hooks with\n`targets: ['web', 'rust']`: the manifest tells the truth, the check reports it (`hooks_partial`), and on those\nengines the kit behaves as before its migration (no tap is played there).\n\n---\n\n## 7 · What is built\n\n| Piece | Files |\n|---|---|\n| Manifest: `engine.hooks`, `engine.moddable`, `service` role, validation | `packages/gamekits/src/types.ts`, `src/manifest.ts` |\n| Mod format, application, version ranges, patches | `kits/game.engine/mods.ts`, `mods-catalog.ts` |\n| Hooks | `kits/game.engine/runtime/web/hooks.ts` |\n| Services `engine.hooks`, `engine.mods`, condition `mod_enabled`, save, events | `kits/game.engine/runtime/web/index.ts`, `contract.ts` |\n| The engine follows its own contract: hook `game.end` (change the result, or keep the game going), events `game.won` / `game.lost` declared | `kits/game.engine/manifest.ts`, `runtime/web/index.ts` (`flow.end`), `game_engine.rs` (`flow_end`) |\n| Contract 1.2.0 (manifest 1.1.0 frozen, changelog, collections `hooks` and `mods`, policy `config.mods`) | `kits/game.engine/manifest.ts`, `manifest-1.1.0.ts`, `index.ts` |\n| The host applies mods before mounting | `runtime/host.ts` (one line), `native/gripforge-kithost/src/host.rs` (one line) |\n| Rust mirror | `native/gripforge-kithost/src/kits/game_engine/{mods,hooks}.rs`, `game_engine.rs` |\n| Catalogue summary read by Rust (hooks, moddable, schemas) | `qa/rust-kithost-parity-check.mjs` (`engineManifests`), `game_engine/manifests.json` |\n| Reference kit `trade.shop` 1.1.0 (2 targets): hooks `shop.open`, `shop.buy`, `shop.sell`, `moddable` | `kits/trade.shop/**`, `native/gripforge-kithost/src/kits/trade_shop.rs` |\n| Reference kit `encounters.waves` 1.4.0 (5 targets): hook `encounter.start` (web and Rust; `targets` says so for the three engines), `moddable` | `kits/encounters.waves/**`, `native/gripforge-kithost/src/kits/encounters_waves.rs` |\n| Mods applied at delivery (Godot, Unity, Unreal) | `packages/gamekits/src/delivery/pipeline.ts` (`withMods`) |\n| Contract check and exceptions | `qa/gamekits-mods-contract-check.mjs`, `qa/gamekits-mods-contract-exceptions.json`, `package.json` (`qa:gamekits`) |\n| End-to-end proof | fixtures `native/gripforge-kithost/parity/game.engine.village_{hooks,modded,mod_disabled}.json`, example `native/gripforge-runtime/examples/kithost-village-modded/` |\n\n**The proof, in three fixtures** (the village of the `adventure` preset, plus a peddler):\n\n- `village_hooks` — **the game itself alters `trade.shop`, without a mod**: half price when the lantern is found,\n  cellar key cannot be sold, one tap that writes a non-mutable field and another that writes a value outside the\n  schema (both dropped, `engine.hook.refused`); and the engine itself: a refused give-up (`game.end` cancelled), a\n  defeat changed into `retry`.\n- `village_modded` — **mods on top**: `golden_village` (lantern price overridden, `buyRate` overridden, a fountain\n  and a bard added to the scene, a script on the kit's `shop.bought` event, a tax through a hook, a closure through\n  a cancelling hook) and `gv_addon` which depends on it (written before it, applied after it); ten mods refused or\n  disabled, each for a different reason (collection not moddable, kit too old, missing dependency, hook forbidden by\n  the game, config out of bounds and non-moddable key, missing document — half applied then **cancelled\n  entirely** —, disabled, duplicate, invalid schema, `code_modules`). Played, saved, reloaded.\n- `village_mod_disabled` — the same project, `golden_village` disabled by the game's policy (`mods.disabled`): the\n  project's prices come back, the fountain and the bard no longer exist, `gv_addon` is refused\n  (`dependency_missing`).\n\n---\n\n## 8 · Catalogue audit\n\nProduced by `node qa/gamekits-mods-contract-check.mjs` (`--audit=… --md=…` for the per-kit detail): it reads the\nmanifests and the sources of each kit. The violations are the rules of §5.1: mechanical and reliable (a rule is met\nor not). The hints (`magic_numbers`, `fn_registration`, `demo_data`, `hooks_partial`) stay heuristics carried by\nthe detailed audit, never failures.\n\n<!-- AUDIT:BEGIN -->\n**Summary as of 2026-10-11** (`node qa/gamekits-mods-contract-check.mjs`, whole catalogue): 163 kits, **157\ncompliant**, 6 as exceptions. Kits in violation, by rule: `engine_block` 4, `hooks_none` 1, `moddable_none` 4,\n`kit_coupling` 2; all other rules at 0 (`events_undeclared`, `events_no_schema`, `listens_undeclared`,\n`verbs_undeclared`, `hooks_unwired`, `save_none`).\n\nThe pre-migration audit (149 kits, 2 compliant, per-kit table and an estimate of 189.8 agent-days) is in the history\nof this file; the estimate was a heuristic, replaced by the measured durations of §9.1.\n\n| Kit in exception | Rules not met | Why |\n|---|---|---|\n| `game.engine` | `kit_coupling` | imports the terrain height of `world.terrain` to place its instances |\n| `world.district` | `kit_coupling` | `plan()` tests the id of the kit `world.streaming` (`world.district/runtime/web/index.ts:238`): the host does not expose \"a provider of this capability is installed\" before mounting (§9.5); the rest of the contract is met (hook `district.build`, `moddable`) |\n| `world.trails` | `hooks_none`, `kit_coupling`, `moddable_none` | deprecated alias of `world.tracks` (1.3.0), classified `legacy` (`presentation.legacy`, not offered in the catalogue, absent from presets), replaced by `world.tracks` when a project is opened (`replacedBy`); web target only, no Rust module. Its runtime **is** that of `world.tracks` under the old names (`createTracksRuntime`): `kit_coupling` (import of another kit's runtime) is its very definition, and `hooks_none` can only be cleared by giving it its own hooks or by lying about its role (it slows vehicles down like `world.tracks`). The check has no \"alias\" category: the exception is kept, like the `legacy.*` ones |\n| `legacy.fps_tactical`, `legacy.kart`, `legacy.rules_engine` | `engine_block`, `moddable_none` | outside the contract (legacy clients, §4.8) |\n| `legacy.royale` | `engine_block` | outside the contract |\n\n\nView kit that arrived through master (`cf4812c91`), aligned on 2026-10-11: `hud.tactical` 1.1.0, compliant — role\n`view`, no hook (it decides nothing: `document()` returns the HUD Studio v2 document from its config, `concept()` the\nreference of the game's concept), no event (nothing changes in game), saves the document; `moddable.config` limited\nto `themeId` and `document` (`conceptItem`, `conceptHash`, `studioHud` point to workspace objects and `brief` feeds a\npaid generation: not moddable). Rust mirror `native/gripforge-kithost/src/kits/hud_tactical.rs`, three parity\nfixtures (`defaults`, `document`: a malformed document sanitised identically, `mods`: one mod applied, four\nrefused). What it draws is the React view of the FPS page, on top of Three.js or Bevy.\n\nService that arrived through master (`06ce008b6`), aligned on 2026-10-11: `ai.navigation` 1.0.0, compliant — role\n`service`, requires `game.engine`; hook `navigation.plan` (`actor` nullable, `from`, `to`, body size `radius` /\n`height` / `maxSlope` / `stepHeight`, `approach`; everything except `actor` and `from` is mutable; if cancelled:\nroute `unreachable`, reason `cancelled: …`), asked before each route computation (within the per-step budget), never\non every step; event `navigation.blocked { actor, status, reason }` once per change; listens to the seven topics that\nreset the bake (the precomputed navigation grid); `moddable.config`: `cellSize`, `padding`, `ground`, `approach`,\n`smooth`, `retrySeconds`, `agent` (the budgets `maxCells`, `maxLayers`, `plansPerTick`, `sharedBakeCells` bound the\ncost: not moddable); the default body size, hard-coded in 0.2.0, becomes the `agent` key. Saves the followed paths\nand the queue (a reloaded game takes the same steps). Fixed along the way (red on master, `gamekits-s5`): a goal\ninside a body (stolen car) was never reached (`approach`, 3 m), paths in cardinal staircases slowed down the\npursuers (`smooth`). With the open-world pedestrians (base kit), `gamekits-weather` went from 10 s to more than\n15 min: a start that grazes a wall starts from its nearest node, a world with fewer than `sharedBakeCells` cells is\nbaked once, a blocked actor asks again at most every `retrySeconds`. Rust mirror\n`native/gripforge-kithost/src/kits/ai_navigation.rs` (and `npc_core.rs` follows the service when it is mounted),\nparity fixtures `ai.navigation.*`.\n\nCompliant without proof by execution: `game.cinematic` (migrated in TypeScript only, no Rust mirror, **no\nfixture**) and `fps.network` (TypeScript only, nothing moddable). All the other compliant kits have at least one\n`hooks` or `mods` fixture played in parity.\n\n| Batch | Kits migrated | Measured duration |\n|---|---|---|\n| reference kits (base) | 2 (`trade.shop`, `encounters.waves`) | — |\n| M-C · NPCs, quests, items, economy | 15 | 1 h 22 |\n| M-D · combat, weapons, enemies | 22 | 2 h |\n| M-A · interface, settings, save, services | 23 | 54 min |\n| M-E and M-G · vehicles, characters, movement | 17 | 1 h |\n| M-B · world | 27 (including `world.district`, kept as an exception for `kit_coupling`) | 1 h 03 |\n| M-F and M-H · strategy, simulation, network, rendering | 40 | 1 h 18 |\n| **Total of the batches** | **144** | **7 h 37** |\n<!-- AUDIT:END -->\n\n---\n\n## 9 · Migration plan\n\n### 9.1 What a kit costs: the measurements\n\n`trade.shop` (169 web lines, 569 Rust lines, 2 targets): 3 hooks, `moddable`, frozen manifest, changelog —\n**≈ 35 lines of TypeScript and ≈ 40 lines of Rust**, plus the fixture. The cost is proportional to the number of\ndecisions and to the number of targets, not to the size of the kit.\n\n**Real durations of the batches** (one agent coordinating sub-agents that write in parallel, a single remote\nexecution at a time; web and Rust, fixtures and parity included): M-C, 15 kits in 1 h 22; M-D, 22 kits in 2 h;\nM-A, 23 kits in 54 min; M-E and M-G, 17 kits in 1 h; M-B, 27 kits in 1 h 03; M-F and M-H, 40 kits in 1 h 18. That\nis **2 to 5.5 minutes per kit**, 144 kits in 7 h 37 of batches: the heuristic of the initial audit (189.8 agent-days\nfor 147 kits) overestimated by more than two orders of magnitude. What stays heavy is not the writing: it is running\nthe engines (batch M-0, §6), where each hook has to be placed and each scenario replayed on Godot, Unity and\nUnreal.\n\n### 9.2 Order\n\n0. **M-0 · engine base on Godot, Unity, Unreal** (§6): three agents, one per engine, plus the shared delivery.\n   **Blocking** for removing `targets: ['web','rust']` from the hooks of five-target kits; not blocking for\n   migrating the manifest and the web and Rust runtimes of the kits.\n1. **Batches M-A to M-H**, in parallel, same families as batches A-H of `docs/game-engine.md` §14.3 (an agent\n   already knows its family).\n2. **M-N · multiplayer**: mod fingerprint in the handshake (`net.*`, `coop.session`, `fps.network`).\n3. **Integration**: one agent, sequential (shared files, `CATALOG_VERSION`, docs, CLI policy, MCP).\n\n### 9.3 The batches\n\nEach batch owns, for its kits: `packages/gamekits/src/kits/<kit>/**` (manifest, frozen manifest, `runtime/web`,\n`docs.ts`), `native/gripforge-kithost/src/kits/<kit>.rs` (+ folder) and its fixtures\n`native/gripforge-kithost/parity/<kit>.*.json`, `packages/gamekits/src/delivery/gameplay/engines/{godot,unity,\nunreal}/kits/<kit>/**`, its scenarios `qa/gameplay-engines/scenarios/<kit>-*.json`, and **its lines** of\n`qa/gamekits-mods-contract-exceptions.json` (removed, never added).\n\n| Batch | Kits | Expected hooks (examples) |\n|---|---|---|\n| **M-A · interface, settings, save** | `hud.*`, `ui.*`, `settings.graphics`, `save.persistence`, `input.*`, `photo.mode`, `lore.journal` | role `view` / `service`: events, `moddable`, no hook except `save.write`, `save.load` |\n| **M-B · world** | `world.*`, `travel.worlds`, `launch.pad` | `world.enter`, `weather.change`, `daynight.phase`, `access.pass`; live settings declared |\n| **M-C · NPCs, quests, items, economy** | `spawn.system`, `npc.*`, `interaction.system`, `mission.system`, `quest.graph`, `inventory.*`, `storage.containers`, `economy.money`, `trade.shop` (done), `craft.recipes`, `faction.system`, `collect.tokens`, `game.endings` | `inventory.pickup`, `inventory.give`, `money.spend`, `craft.make`, `mission.start`, `mission.complete`, `dialogue.choose`, `interaction.use`, `spawn.entity`, `game.end` |\n| **M-D · combat, weapons, enemies** | `combat.*`, `weapons.loadout`, `upgrades.boons`, `enemy.*`, `encounters.waves`, `defense.*`, `hazard.traps`, `stealth.*`, `fx.*`, `progression.levels` | `combat.damage` (absorbs `addModifier`; **first kit of the batch**: planned as the third reference kit, left to the batch because a version bump of `combat.core` regenerates the parity traces of almost all the other batches in progress), `combat.death`, `ability.cast`, `wave.spawn`, `wave.start`, `stealth.detect` (absorbs `addFilter`), `boon.offer`, `level.up` |\n| **M-E · vehicles and living world** | `vehicle.*`, `traffic.system`, `wanted.police`, `race.kart`, `mount.ride`, `sport.ball` | `vehicle.enter`, `vehicle.damage`, `wanted.raise`, `race.finish` |\n| **M-F · arenas, lanes, tactics, strategy** | `moba.*`, `minion.waves`, `fps.*`, `rts.*`, `units.command`, `camera.strategy`, `party.rounds`, `cards.deck`, `run.map` | `minion.spawn`, `hero.respawn`, `match.end`, `round.start`, `card.play`, `unit.order`, `production.queue` |\n| **M-G · characters and movement** | `character.*`, `movement.*`, `light.flashlight` | `character.jump`, `character.respawn`, `dash.start`, `traversal.climb` |\n| **M-H · simulation and cross-cutting services** | `life.*`, `farming.crops`, `fishing.rod`, `survival.needs`, `horror.sanity`, `machines.production`, `automation.logistics`, `resource.*`, `research.samples`, `build.*`, `custom.paint`, `audio.core`, `i18n.text`, `ui.theme`, `render.*`, `asset.meta`, `physics.port` | `crop.harvest`, `fish.catch`, `need.decay`, `machine.produce` (keeps `addSource` as a service), `build.place`, `resource.extract` |\n\n**Typical work for a kit**, in order: (1) `requires game.engine@^1` and an `engine` block if missing (`service`\nrole for a pure service); (2) declare all emitted events with their schema, all listened topics; (3) one hook per\ndecision, run on web and Rust (and on the engines once M-0 is done); the `add<Thing>(fn)` services that change a\ndecision rewritten as taps of the hook, signature unchanged; (4) `engine.moddable`; (5) constants moved up into\nconfig; demonstration data declared through `defaultData`; `save` / `load`; (6) minor version, frozen manifest,\nchangelog; (7) remove its lines from the exceptions.\n\n**End criterion of a batch**: `node qa/gamekits-mods-contract-check.mjs` green with no exception for its kits;\n`node qa/rust-kithost-parity-check.mjs`: existing fixtures of its kits identical (without a tap nothing changes) +\none `<kit>.hooks` fixture per kit; for the kits delivered to the engines:\n`node qa/gameplay-engines-check.mjs --no-engines --with-engine --scenario=<its scenarios>` identical to before,\nthen `--only=godot,unity,unreal` on a `<kit>-hooks` scenario.\n\n**Shared files**: the list in `docs/game-engine.md` §14.3 applies as is, plus\n`qa/gamekits-mods-contract-check.mjs` and the kithost core. A need of the contract (a tap keyword, a declaration\nfield) is a **request** to the owner of `game.engine`, for 1.3.\n\n### 9.4 What must be carried over to every target, what can wait\n\n| | Web | Rust | Godot / Unity / Unreal |\n|---|---|---|---|\n| Manifest declarations | shared | shared (summary regenerated) | shared |\n| Mods applied | done | done | at delivery (`withMods` in `pipeline.ts`): **no engine code** |\n| Hooks run | done | done | M-0 then each batch |\n| Events with the same schema | at each batch | at each batch (parity) | at each batch (the `≡ web` scenarios already prove it for existing events) |\n| Can stay specific to web and Rust at first | — | — | hook execution (the kits keep their default behaviour there, stated in the manifest through `targets`); player mods on an exported game |\n\n### 9.5 Requests to the core for `game.engine` 1.3\n\nGaps in the contract found by the batches while migrating the kits. **None is handled here**: each one is a design\ndecision for the core. The kits concerned worked around the gap without bending the contract, and say so in their\n`docs.ts`.\n\n**Hooks and taps**\n\n1. **Mission completion out of reach of a hook**: it is decided in `runtime/objectives.ts`, the host core, not in a\n   kit; no kit can submit it.\n2. **Continuous hook asked again after a cancellation**: a hook placed on a condition that stays true (a zone, a\n   threshold) is asked again on every tick once cancelled; a shared \"refused until the condition drops\" is missing\n   (today each kit keeps its own memory of the refusal).\n3. **Tap priority bounded to ±1000**: a kit that turns its old modifiers into taps runs out of ranges.\n4. **A tap's `match` limited to equality** (no comparison, no membership in a list).\n5. **Non-scalar mutable field**: a tap only writes numbers, strings, booleans; not a list (a card offer, a composite\n   reward) nor an object.\n6. **Nullable field**: the schema subset has no `null`; a \"nobody\" field is declared as `''` (`world.elements`\n   declares `into` as `s.str()` while its value is `null`).\n7. **A tap's reason cannot be carried**: the `reason` of a cancellation reaches the kit, not the reason of a change;\n   a kit cannot tell the player why a price changed.\n8. **A `void` service that does not report cancellation**: a historical API without a return value (kept as a\n   wrapper around a hook) cannot tell its caller that the decision was cancelled.\n9. **A direct write to a variable that bypasses a hook**: `state.set` on a variable that a kit publishes goes around\n   the hook that owns its decision.\n10. **`save.write` cancelled after `save()` has answered true**: the service's answer comes before the decision.\n11. **Dynamic operands** of a tap (`mul` by a variable) and `receiveCanceled`: already noted in §12.\n12. **Decisions taken in a pure model** (combustion, freezing in `world.elements`): not interceptable without\n    bringing `engine.hooks` into the model.\n\n**Entities**\n\n13. **Entity factories that bypass the spawn hooks**: a kit that creates its entities through another kit's factory\n    (`adopt`, a service's `spawn`) does not go through the first kit's spawn hook; and **a cancelled spawn uses up an\n    entity id** (the following ids differ depending on whether a tap cancels or not).\n14. **`combat.death` does not cover the player's death outside the pipeline** (a fall, a respawn decided by the\n    controller).\n15. **Cooldowns of `combat.abilities`**: out of reach of a hook (they live in the abilities package).\n\n**Mods and overridable data**\n\n16. **A mod cannot patch the default documents** (`runtime.core.defaultData`): they do not exist in `project.data`\n    when `applyMods` runs.\n17. **`moddable.config` limited to the first level**: an object key is open or closed as a whole.\n18. **A mod replaces a config list as a whole** (no adding or removing one element, unlike collection\n    documents).\n19. **Static `moddable.settings`** while some kits have dynamic setting keys (`world.scenery`,\n    `world.lighting`).\n20. **Random generator with no exposed state**: `ctx.rng` is not saved; a kit that draws at random does not resume\n    its sequence after a reload.\n21. **Mod fingerprint in the network handshake** (batch M-N, §9.2): `net.*`, `coop.session`, `fps.network` have\n    nothing moddable as long as it does not exist.\n\n**Declarations and checks**\n\n22. **Wildcard in a declared topic**: since the integration, `events.listens` accepts a bus pattern (`*`, `fps.*`:\n    `audio.core`, `fps.arsenal`); **`events.emits` does not accept it**, and a kit that emits built topics\n    (`fps.tactical`, `shared-net-runtime.ts`) stays invisible to the static check.\n23. **\"A provider of this capability is installed\" before mounting**: the host does not expose it\n    (`runtime/host.ts:284`), hence the id test in `world.district` (the only `kit_coupling` exception of a migrated\n    kit) and the one in `input.pointer_lock` on `input.actions`.\n24. **A `service` role that decides**: `coop.session` is attached as a service but takes real decisions (downed,\n    revive, respawn) left without a hook, because they are arbitrated by the network authority. Filled by\n    `coop.session` 1.4: the authority runs `coop.down` (`seconds`; if cancelled: out of the game at once),\n    `coop.revive` (`health`; if cancelled: the progress falls back to 0) and `coop.bleedout` (a continuous decision,\n    `hold` per player, released on revive; if cancelled: the player stays down), web and Rust.\n\n**Kit defects seen during the migration** — fixed since then on both sides with parity (finishing batch of\n2026-10-10, one fixture per defect): `world.vision` 1.1.1 saves `rechargeAt` (`world.vision.recharge`);\n`world.weather` 1.5.1 saves the `intensity` setting once moved (`world.weather.setting`); `world.platforms` 1.6.1\nnow emits `course.door` only once per approach for a door without a course (`world.platforms.dead_door`);\n`mount.ride` 1.1.1 releases the mount whose rider was destroyed (`mount.ride.rider_gone`); `world.rooms` 1.6.1 no\nlonger declares `boon.acquired` as listened (no subscription, on any target: `world.rooms.boon_event`).\n\n**Left as is**: `minion.waves`: `chaseDistance` never makes the minions give up the chase, unlike `docs.ts:51-52`\n(the minions oscillate; fixing it changes the game: owner decision). `world.elements`: `elements.burnt.into` is\n`null` and stays declared as `s.str()` (point 6: the schema subset has neither a `null` type nor `const: null`,\n`schema/validate.ts` refuses a `const` that is not a string, a number or a boolean).\n\n**Fixed in the host** (web and Rust, fixture `host.load_clock`): `KitHost.load` restores the clock (`tick`,\n`elapsed`) **before** the state, the entities, the mission and the kits' `load` (`runtime/save.ts`, `restoreClock`;\n`native/gripforge-kithost/src/host.rs`, `Host::load`). A kit that resets a deadline with `ctx.time.elapsed +\nremaining` in its `load` gets the right clock, and the events emitted during a load carry the time of the save. Two\nkits change behaviour without changing code: `world.vision` 1.1.2 (a recharged beacon keeps its remaining time;\ntrace `world.vision.recharge`: `until` 5.03 instead of 4.48) and `hazard.traps` 1.1.1 (a press goes back to where\nit was in its cycle as soon as the game loads, entity and collider). `rechargeAt` in `world.vision`, saved in\nabsolute game time, stays correct. The Godot, Unity and Unreal hosts have their own loading: to review in the\nengines batch (M-0).\n\n---\n\n## 10 · CLI, MCP, agents\n\n**Nothing is changed in `packages/grip-forge`** (any change requires a release). To change there, in one go: the\npolicy (`src/game-policy.ts`) and `templates/SKILL.md` receive the instruction of §2 (\"extension points first,\nlocal copy as a last resort with a one-line justification\"); `game-check` reads the mods report; commands\n`mod list | validate | install | enable | disable | new`.\n\n**MCP**: since mods and taps are documents of `game.engine` collections, the existing tools already cover them\nwithout change: `gripforge_game_content put / get / list / remove / validate` with `kind: hooks` or `kind: mods`\n(`PATCH …/data` validates against `HOOK_TAP_SCHEMA` and `MOD_SCHEMA`). What agents must also be able to do,\n**described, not added** (the tool descriptions are shared files: `packages/mcp-client/src/gamekit-tools.ts`,\n`apps/web/src/lib/mcp-server.ts`):\n\n| Need | Proposed tool | What it calls |\n|---|---|---|\n| List a game's mods and their status | `gripforge_game_mods list` | `applyInstalledMods(doc)` → section `mods` |\n| Validate a mod before putting it in | `gripforge_game_mods validate { mod }` | `applyMods` on a copy with this mod added → its problems |\n| Install, enable, disable, order | `gripforge_game_mods install / enable / disable / order` | `PATCH …/data` (`mods`) and `mods` config of `game.engine` |\n| Create a mod from a difference | `gripforge_game_mods create { from, to }` | difference between two project states → `config` / `data` (to be written) |\n| See a kit's extension points | `gripforge_game_engine blocks` (existing) | add the manifests' `hooks` and `moddable` to it |\n| Content report | `gripforge_game_engine report` (existing) | attach the mods report to it |\n\n**Equivalent rules elsewhere, to update at integration (listed, not changed)**:\n`docs/gamekits.md` § \"Adding a kit\" (rules 1 to 8); `docs/game-engine.md` §13 (rules for writing a kit);\n`docs/game-engine-contract.md` (contract 1.x: add 1.2 to it); `docs/bevy-kit-port.md` (convention for passed\nfunctions: a tap is a `kx.callback`); `packages/grip-forge/src/game-policy.ts` and `templates/SKILL.md`;\n`packages/mcp-client/src/gamekit-tools.ts` and `apps/web/src/lib/mcp-server.ts` (descriptions of the Game Kits\ntools, including the one for local copies); `apps/web/src/lib/game-creation/development-tools.ts` (tools of the\ncreation agents); `apps/web/src/lib/gamekits/engine.ts` (report and building-block catalogue served to agents).\n\n---\n\n## 11 · Decisions that belong to the owner\n\n| # | Question | Recommendation |\n|---|---|---|\n| 1 | A separate `mods.engine` kit? | **No.** No strong reason found: the layer only makes sense inside the engine (it applies before mounting, so before any kit) and every kit must be able to rely on it. |\n| 2 | Can players mod, or only the creator? | The creator first (variants, seasons, balancing: useful right away, no new risk). Players later, **per game and by the creator's decision** (`mods.enabled`), once moderation is decided. |\n| 3 | Where are player mods stored and offered? | A server-side collection attached to the game, mods private by default, public after the creator's approval. The engine does not depend on it (§3.2). |\n| 4 | Can a mod ship assets? | Not in v1: it points to assets of the game or of the Library. Later: references to items in the player's Library, never free files. |\n| 5 | A save made with other mods: load or refuse? | **Load and warn** (`engine.mods.changed`), as built. A per-game option `mods.saves: strict` later. |\n| 6 | Mandatory `<mod>_` prefix for added ids? | Recommended only. Refusal on collision is enough, and the origin is tracked. |\n| 7 | Order at equal priority between the game and its mods | The mod has the last word (built); the game keeps control through a lower priority or `mods.deny`. To be reversed if the owner prefers that the game always has the last word. |\n| 8 | Switching mods during a game session | No in v1 (remount). |\n| 9 | Sandboxed mod code (second step) | Not now; same decision as game code on the hosted page. |\n| 10 | Player mods on an **exported** game (Godot, Unity, Unreal) | Not in v1: the creator's mods are baked in at delivery. |\n| 11 | `legacy.*` outside the contract? | Yes (permanent exceptions marked `legacy`). |\n| 12 | Should all \"pure service\" kits require `game.engine`? | Yes, that is the reading of \"everything depends on it\"; `service` role. Cost: one manifest line per kit, and a legacy game that updates such a kit receives the engine (transparent). |\n| 13 | Multiplayer: peers agreeing on mods | Fingerprint of the applied list in the handshake; connection refused if it differs. |\n\n---\n\n## 12 · Status, limits, what is not checked\n\n### Checked after integrating the batches (run on 2026-10-10 on the test machine, branch `bevy-mod-int`)\n\n| Command | Result |\n|---|---|\n| `pnpm --filter @gripforge/gamekits typecheck`, `pnpm --filter @gripforge/web typecheck` | green |\n| `node qa/gamekits-mods-contract-check.mjs` (whole catalogue) | **145 / 152 compliant**, 7 exceptions (§8), 0 failures; `hooks_unwired` requires a call that runs the hook |\n| `node qa/rust-kithost-parity-check.mjs` | **707 fixtures identical in TypeScript and Rust** (109 `hooks`, 35 `mods`); the traces of `coop.session.host`, `coop.session.mods` and `units.command.orders` are stable from one regeneration to the next (`volatile` option) |\n| `cargo test --locked` (player workspace: format, kithost, moba, player, runtime, cli) | green, including `schema::tests::catalogue_patterns_match_like_v8` (27 catalogue patterns replayed against V8's verdicts), `mods::tests::base_config_of_a_kit_without_moddable_key`, 293 tests of `gripforge-player` |\n| `cargo fmt --all --check`, `rustfmt --check --edition 2021` on `src/kits/**` | green |\n| `run-test` of the six `kithost-*` examples | `ok: true`, deterministic |\n| `node qa/run-collected.mjs` (the `qa/gamekits-*` and `batch-*` checks without browser or engine) | see the integration report: the checks that were already red on `master` stay red (`batch-d-engine-check`, `gamekits-audit-check`, `gamekits-locomotion-check`, `gamekits-mcp-check`, `gamekits-nameplates-check`, `gamekits-playtest-check`, `render-lod-check`) |\n\n**Not proven by execution**: `game.cinematic` (no Rust mirror, no fixture); `fps.network` (TypeScript only);\neverything that touches Godot, Unity and Unreal (no engine started: the `≡ web` scenarios of the migrated kits were\nnot replayed, and `combat.duel` now saves its match on the web and in Rust only — the `combat-duel-engine` scenario\nmust be reviewed on the engines); the game page (no browser).\n\n### Checked on the base (run on 2026-10-09 on the test machine, branch `bevy-mods`)\n\n\n| Command | Result |\n|---|---|\n| `pnpm --filter @gripforge/gamekits build` (typecheck included) | green |\n| `node qa/gamekits-resolve-check.mjs` (validates all manifests) | 25 checks |\n| `node qa/gamekits-engine-check.mjs` (including the modded delivery to Godot, Unity, Unreal: plan only) | 27 passed |\n| `node qa/gamekits-delivery-check.mjs`, `qa/gamekits-blocks-check.mjs` | 22 and 14 passed |\n| `node qa/gamekits-mods-contract-check.mjs` | 2 / 149 compliant, 147 exceptions, 1642 assertions, 0 failures; rerun without `--write-exceptions`: identical |\n| `node qa/rust-kithost-parity-check.mjs` (the whole ported catalogue) | **252 fixtures, 15,239 frames, 12,082 events identical in TypeScript and Rust**, including `game.engine.village_hooks` (47 frames), `village_modded` (51), `village_mod_disabled` (50), the existing fixtures of `trade.shop` (3) and of `encounters.waves` (4) unchanged in how they play out |\n| `cargo test --locked -p gripforge-kithost` | all green (including `mods::tests::ranges`, `patches`) |\n| `cargo fmt --all --check`, `rustfmt --check --edition 2021` on `src/kits/**` | green |\n| `run-test examples/kithost-village-modded/game.json` (preset `adventure` + `trade.shop`, 24 kits) | `ok: true`, 10 expectations, deterministic; `kithost-village` and `kithost-village-full` still `ok: true` |\n\n`qa/gamekits-audit-check.mjs` fails on this branch with \"preset tower_defense has no genre in completeness.ts\": no\nfile of this batch touches presets or genres; not compared with the base.\n\n### Run on the engines (2026-10-09 and 10, test machine, branch `bevy-engines`)\n\nThe modded delivery is proven **in game** on the engines, for what is applied at delivery. The harness\n(`qa/gameplay-engines-check.mjs`) hands an engine a scenario whose data carries `mods` the way a project reaches\nit: through `planDelivery` (so `withMods` then `withEngineContent`), configs and collections already modded, with no\n`mods` collection. The web reference keeps the scenario as written (its host applies the mods at mount time): both\nmust give the same trace.\n\n| Scenario | What it proves |\n|---|---|\n| `engine-village` | the village without mods (the reference from before the mod layer) |\n| `engine-village-mods` | `game.engine` collections: an added archetype, an instance added to the scene through `patch.append`, an added script (the fountain can be used, its state and its variable change); a disabled mod not applied; a refused mod (`code_modules`) reported as `mod_refused` in the plan and without effect |\n| `encounters-waves-engine-mods` | **config** override of a kit (`encounters.waves.startDelay` 0.5 → 0.2: all waves come 0.3 s earlier) and **patch of a collection** of a kit other than the engine (`encounters`: the ambush becomes a `wretch`) |\n| `engine-village-mods-hook`, `encounters-waves-engine-mods-hook` | a data tap on `game.end` (`set result`) and on `encounter.start` (`cancel`), hooks declared `targets: ['web', 'rust']`: the web plays them (the result becomes `legend`, the ambush does not happen); an engine does not play them and gives **the trace of the same game without these taps** (the scenario's `engineReference` key), without error |\n\nTwo scenario keys carry what batch M-0 must remove: `notOnEngines: [\"engine.mods.*\"]` (the event\n`engine.mods.applied` exists only on the web and in Rust) and `engineReference` (the engine is compared with the\nscenario without the taps). The harness fails by itself on the day a tapped hook declares the engine's target\n(\"remove engineReference\"), and when a tap changes nothing on the web (a scenario that would prove nothing). The\ndelivered project, replayed **on the web** as the engine receives it (already modded, without `mods`), also gives\nthe same trace: it is the reference for Unreal's save round trips and for Godot's second physics backend.\n\nResults: the five scenarios identical to their reference on Godot 4.7.1 (Godot Physics and Jolt), Unreal 5.8.3\n(`-game -nullrhi`, save round trips included) and in the Unity 6000.3.25f1 editor (batch mode). Unity's standalone\nLinux player crashes at start-up on the test machine, before any script: player mode is not proven there. The two\n`encounters-waves-engine-mods*` scenarios do not record the position of the ambush enemy: on Unity a `wretch` has\ntravelled 2.0 m where the web counts 2.4 m in 0.6 s (tolerance 0.3 m), a difference in `enemy.ai` unrelated to the\ndelivery.\n\n**What M-0 will find when it arrives** (seen while running, to add to the list in §6):\n\n1. The `hooks` documents (of the project and of the mods) **are in the delivered `gameplay.json`**, collection\n   `hooks`, as they are and not sorted; no engine reads them. `withEngineContent` must turn them into\n   `engine.hooks.taps` (sorted) and `engine.hooks.declared`; until then, a delivered project where a tap targets a\n   `web`/`rust` hook warns nobody: `withMods` is missing a plan warning `hook_not_on_target` (kit, hook, target).\n2. `engine.mods.applied` is not emitted and the services `engine.mods` / `engine.hooks` do not exist on the\n   engines: a script or a kit that calls them fails there. The scenarios above do not call them.\n3. The `mod_enabled` condition is not in `GfTriggers`: a mod script that uses it has not been played on an engine.\n   Since mods are applied at delivery, it can be resolved **at delivery** (a true or false constant written into\n   the compiled rule) without porting anything.\n4. The two `*-mods-hook` scenarios are the end criterion of M-0 for `game.end` (mutable field) and\n   `encounter.start` (cancellation): remove `engineReference` and `targets: ['web', 'rust']`, they must then be\n   `≡ web` directly. `engine-hooks` still has to be written (priority order between taps, refusal of a non-mutable\n   field, `engine.hook.refused`, save).\n\n### Written, not run\n\n- **Hooks on the three engines** (batch M-0): nothing is ported; see above for what is proven (the declaration\n  `targets: ['web', 'rust']` is respected: default behaviour, no error).\n- **The whole of `pnpm qa:gamekits`** and the web checks (`qa/webui-check.mjs`): not run; only the checks in the\n  table were.\n- **The game page**: no browser has mounted a modded project. The web proof is the TypeScript `KitHost` without\n  rendering (the one used for parity).\n\n### Known limits of the base\n\n- **Godot, Unity, Unreal**: the `game.engine` adapters of these targets are at contract 1.1: no hook runs there\n  (`game.end`, `encounter.start` are declared `targets: ['web', 'rust']` there), `engine.mods` and `mod_enabled` do\n  not exist there. The 1.2.0 manifest says so in its adapter notes. That is batch M-0.\n- **Delivery**: `withMods` applies the mods for Godot, Unity and Unreal (config overrides, documents added, patched,\n  removed). The `hooks` documents arrive in the delivered data but **no engine plays them** until batch M-0 is done;\n  the mods report is not delivered to the engines (only the `mod_refused` plan warnings).\n- **Rust**: the manifest read by `apply_mods` is the one of the embedded catalogue (`manifests.json`, regenerated by\n  the parity script and **committed** with this batch, because the mod layer depends on it at run time); the web\n  reads the manifest of the installed version. Same result as long as a game's kits are up to date.\n- **Web host**: `runtime/host.ts` now imports the manifest catalogue (`mods-catalog.ts`) to apply the mods; this is\n  a new dependency of the core on `kits/index.ts` (manifests only, the runtimes are still loaded on demand).\n- **Server**: the size limit of a mod and the validation on write rely on `PATCH …/data` (schema); `applyMods` is\n  not yet called by the content report served to agents.\n- **Web game page**: it hands the project to `KitHost`, which applies the project's mods; merging a player's mods\n  into this project does not exist (decisions 2 and 3).\n- **Event validation at run time**: the schema is declared and checked statically; no payload is validated in game.\n- **Static check**: `events_undeclared` and `listens_undeclared` only see topics written as literals in the web\n  runtime; a topic built dynamically escapes them. `hooks_unwired` reads each occurrence of the hook name where it\n  is (argument of `run`, handed to a helper function or to a table, or a mere topic, variable, input, tag): a hook\n  with the same name as an event is no longer considered wired, but the check is still a source reading — that a\n  hook is called at the right moment is proven by parity.\n- **Schema patterns**: Rust has its own pattern engine (`schema.rs`), proven against V8 on all the catalogue's\n  patterns (`tests/patterns.json`, 27 patterns); a pattern outside the common subset (lookahead or lookbehind,\n  named group, backreference, `\\b`, `\\p`) is refused at declaration by `validate.ts`, and a value submitted to such\n  a pattern is refused in Rust. A value that would make the engine backtrack forever is refused in Rust after two\n  million steps, where V8 would keep waiting.\n- **`receiveCanceled`, `REMAP`, dynamic operands in a tap** (`mul` by a variable): not done.\n- **Events without a payload**: they carry `null` on the web as in Rust since the integration (`runtime/bus.ts`).\n- **Base config and mods**: a mod is judged against a kit's config only if that kit declares a moddable key (same\n  condition on both sides: the summary read by Rust carries the schema only for those kits).\n\n---\n\n## 13 · `game.engine` 1.3: a unified design for the requests to the core\n\n> Step 1 of the batch `rel-engine13` (2026-10-10). This chapter is the **design**; what is built and proven is\n> carried over into §4, §5 and §12 as the steps go, and the table in §13.3 gives the status of each request.\n\n### 13.0 The direction\n\n**The contract does not serve only mods: it serves games first**, so that they can bend a kit to their design\nwithout recoding it. 1.2 was the first building block (hooks, `moddable`, mods). 1.3 aims at **completeness**: every\ndecision goes through the same pipeline, everything a kit can do \"by types\" is an open registry, every useful state\nchange is a declared event, and everything that can be plugged in can be listed with a single request. Equality\nrule: **everything a mod can do, the project can do** with the same operations on its own data; on top of that,\nthe project can plug its rules (scripts, verbs, conditions) into the same points.\n\nThe 24 requests of §9.5 are not handled one by one: they come down to **six mechanisms**. Mechanism C also carries\nthe owner's example, \"an event can change the data\".\n\n### 13.1 The six mechanisms\n\n**A · A single decision pipeline.** Every game decision, wherever it is taken, goes through the `engine.hooks`\ntable, and everyone receives the same typed answer.\n\n- `decide(services, hook, payload)` (`runtime/decide.ts`, `decide.rs`): the shared entry point for the **host\n  core** and the **shared libraries**, which have no kit context. Without `game.engine` or without a tap: the payload\n  unchanged. The core uses it for `mission.complete` (mission completion and its rewards, `runtime/objectives.ts`;\n  if cancelled: the mission stays active, its last step is re-armed) and `engine.spawn` (below). These core hooks are\n  declared by the manifest of `game.engine`.\n- **Shared typed result** `Decision = { ok, cancelled, by, reason, payload, notes }`: `HookOutcome` gains `ok`\n  (`!cancelled`) and `notes` (the `reason` of a tap that **changes** without cancelling: `[{ tap, reason, fields }]`,\n  empty without a tap). A historical `void` service kept as a wrapper around a hook **returns this result**\n  (`void` → a value: no caller breaks).\n- **Continuous decision**: `engine.hooks.hold(hook, key, payload)` asks only on the **rising edge** (when the\n  condition first becomes true); if cancelled, it is locked for `(hook, key)` until `release(hook, key)`, which the\n  kit calls when its condition drops. **A single rule**: the locks are saved (section of `game.engine`, key absent\n  when there are none).\n- **Guarded variable**: `ctx.state.guard(path, fn)` gives the owning kit back its direct write; every other write\n  (`state.set`, `inc`, verb `set_var`, setting) goes through `fn(next, prev)`, where the kit runs its hook and\n  returns the accepted value or refuses.\n- **Factories**: `ctx.spawn.try(spec)` runs `engine.spawn` **before** any creation (no id used up if cancelled),\n  accepts that a factory answers \"nothing\", and returns `{ ok, id, cancelled, by, reason }`. `spawn(spec)` stays as\n  it is (not intercepted) for existing callers; the check reports a kit that still calls it.\n- **Pure model**: a model receives `decide` as a parameter (default: identity); it stays pure, the decision is taken\n  outside.\n- **Abilities library**: `AbilityPort.decide?`; the controller submits `ability.cooldown` before setting a cooldown.\n\n**B · More expressive schemas, the same everywhere** (events, hooks, config, collections, mods).\n\n- `nullable: true` on any schema (`s.nullable(schema)`) and `const: null`: a \"nobody\" field can be declared.\n- Simple union: `oneOf` (existing) is allowed everywhere, including for a `mutable` field.\n- **Non-scalar mutable field**: a `mutable` field can be an object or a list; a data tap changes it through\n  `patch: { append, remove, update }`, **the same operations as on a document** (`patchDocument`), and the result\n  is validated against the field's schema.\n- **Wildcard and topic pattern**: `events.emits[].topic` accepts a bus pattern (`fps.tactical.*`) like\n  `events.listens`; the check links a built topic (template, concatenation with a literal prefix) to the declared\n  pattern, and reports a built topic that nothing covers.\n\n**C · A single \"when / if / then\" rule language: taps, reactions, bindings.** Nothing new is invented: the language\nis the host's trigger DSL (`runtime/triggers.ts`: conditions `var`, `event`, `in_zone`, `has_tag`,\n`all / any / not`, kits' condition verbs; actions `set_var`, `inc_var`, `emit`, `spawn`, kits' action verbs). 1.3\nextends it once, for its three uses:\n\n| Use | When | If | Then |\n|---|---|---|---|\n| **Tap** (`hooks` document) | before a decision (`hook`) | `match`, `if` | change the `mutable` fields, cancel |\n| **Reaction** (rule of a script or of `triggers`) | after an event (`when.event`) | `if` | change the data, emit, call a verb |\n| **Binding** (`world.bindings`) | a state changes | its conditions | write a live setting |\n\n- **Extended conditions**, the same everywhere: `{ field, op, value }` compares a field of the payload (of the event\n  or of the hook; dotted path); operators `==`, `!=`, `<`, `<=`, `>`, `>=` (existing) + `in`, `nin` (membership in\n  a list), `has` (the list contains); `in_zone` accepts a point or an entity from the payload. `match` (equality)\n  keeps its 1.2 meaning.\n- **Computed values**, without code: wherever a rule writes a value, an object with **a single key starting with\n  `$`** is an expression: `{ \"$field\": \"price\" }`, `{ \"$var\": \"story.deaths\" }`, `{ \"$add\": [a, b] }`, `$sub`,\n  `$mul`, `$div`, `$min`, `$max`, `$round`, nested (depth bounded to 8). Any other object stays a literal: 1.2 rules\n  keep their meaning. The operands of a tap's `add / mul / min / max` accept them (request 11).\n- **Reactions: an event can change the data.** New actions, all guarded by what the kit declares open (the same\n  list as `moddable` and the registries) and validated by schema:\n  `patch_data { collection, id, set?, append?, remove?, update? }` (same operations as a mod; `add_data`,\n  `remove_data` to add and remove an entry), `set_config { kit, path, value }`,\n  `set_setting { capability, key, value }`, `set_component { entity, component, value }`; `set_var`, `emit` and the\n  kits' verbs already exist. A refusal (target not open, value outside the schema, missing document) stops nothing:\n  it is logged through `engine.reaction.refused { rule, action, reason, path }`.\n- **Live data.** A kit that read its documents at mount time does not see a patch made during play. A registry or a\n  config key that can change during play is declared `live` (`engine.registries.<c>.live`,\n  `moddable.live: [paths]`): the kit rereads on `engine.data.changed { collection, id, op }` /\n  `engine.config.changed { kit, path }`. A reaction on a target that is not `live` is refused (`not_live`):\n  completeness can be measured (live registries / registries).\n- **Order, loops, save.** Decreasing priority then declaration order (like taps). A reaction that triggers the event\n  that triggers it is bounded: beyond 8 generations of events in the same tick, the rule is refused (`loop`), in a\n  deterministic way. The changes made to the data form a **journal** saved in the section of `game.engine` (key\n  absent when it is empty) and replayed on load before the kits' `load`.\n- `reason` also carried by a change (→ `notes`, mechanism A).\n- **Tap priority**: the ±1000 bound is **kept** (a mod is bounded by schema); a priority is a number, not an\n  integer: a kit that runs out of ranges uses fractions, and registration order breaks ties. Documented.\n- **`world.bindings`** keeps its format (a continuous, sampled binding); its conditions go through the same\n  evaluator and its writes through the same guarded target as `set_setting`.\n- **Rejected**: `receiveCanceled` (an observer reads `by` and `reason` from the result; a cancellation event emitted\n  by the core would change the traces of the existing `hooks` fixtures).\n\n**D · Open registries and finer mods: the same operations everywhere.** A collection is a registry; what was missing\nis uniformity.\n\n- `engine.registries.<collection>: { of, inherit?, description }` declares that a collection is the kit's **type\n  registry** (enemy types, weapon types, status types, room types, recipes…). In an `inherit` registry, a document\n  `{ id, extends: \"<id>\" }` **inherits** from an existing entry (key-by-key merge, resolved before mounting, for the\n  project as for a mod; cycle or missing parent: document refused, reported).\n- A mod's operations on a collection: `remove`, `patch`, `add` (1.2) + **`order: [ids]`** (reorder).\n- **Default documents** (`runtime.core.defaultData`): when a mod touches a moddable collection that the project does\n  not have, the working copy starts from the kit's default documents: they can be patched like the others.\n- **Config as a document**: `moddable.config` accepts a **path** (`fog.density`, `rules`); a mod writes\n  `configPatch.<kit>: { set, append, remove, update }` (same operations, paths under a moddable key): add, remove,\n  replace **one element** of a config list. `config.<kit>` (1.2) keeps its meaning.\n- **Settings with dynamic keys**: `moddable.settings` accepts a pattern (`layer.*`).\n- The default texts of `i18n.text` go through the two previous points (no mechanism of their own).\n\n**E · The host.**\n\n- `ctx.services.installed(capability)`: true from the mounting of the first kit on, if an installed and active kit\n  provides the capability (read from the manifests of the resolved project). Removes the id test in\n  `world.district` and in `input.pointer_lock`.\n- `Rng.state()` / `Rng.restore(state)`: a kit that draws at random saves its sequence in its own section (the host\n  saves nothing more: existing saves do not change).\n- `engine.mods.fingerprint()`: a stable fingerprint of the applied list (`''` without mods); the network kits put it\n  in their handshake and refuse a peer that differs.\n\n**F · Discoverability and measurement.**\n\n- `extensionPointsOf(manifest)` (pure, `kits/game.engine/points.ts`): **everything that can be plugged into a kit,\n  in one request** (hooks with mutable fields, emitted and listened events, registries, collections, config and what\n  of it is moddable, settings, verbs, conditions, components, services). Served in game by `engine.points`\n  (`list()`, `of(kit)`), to be exposed by the MCP server (`gripforge_game_engine blocks`) and the CLI.\n- Check (`qa/gamekits-mods-contract-check.mjs`), new rules: `hook_no_after` (a hook without an \"after\" event declared\n  in the same domain), `emits_dynamic` (built topic not covered by a pattern), `spawn_unhooked` (direct call of a\n  factory). At first **measured hints** in the audit, blocking once the kits are wired.\n- **Completeness indicator per kit**, in the audit: hooks / outcome events counted; declared registries /\n  collections; moddable config keys / keys.\n\n### 13.2 Compatibility and order\n\n**Nothing breaks**: 1.3 accepts everything 1.2 accepted. Everything is additive: new schema keywords, new tap, mod\nand manifest keys, extra services, a returned value where there was `void`. Without a tap or a mod, the same traces:\n`decide` returns the payload, `hold` writes nothing in the save when there is no lock, `spawn.try` creates the same\nentity with the same id, a registry without `extends` is not touched, a project without `mods` is returned as is.\nThe 708 fixtures stay identical except for version lines. The only visible change: a mod with `requires\n{ \"game.engine\": \"^1.3\" }` is refused by a game at 1.2 (intended).\n\n**Order**: (0) version 1.3.0, manifest 1.2.0 frozen; then in parallel, one sub-batch per mechanism: B (schemas),\nA (pipeline), C (rule language and reactions), D (mods and registries), E (host); F when grouping them; then the kits\nby family.\n\n### 13.3 Request → mechanism\n\n| # | Request (§9.5) | Mechanism | Kits to wire |\n|---|---|---|---|\n| 1 | Mission completion outside a hook | A · `decide`, core hook `mission.complete` | `mission.system`, `quest.graph` |\n| 2 | Continuous hook asked again | A · `hold` / `release`, saved locks | `world.access` 1.2, `world.biomes` 1.3, `world.stages` 1.5, `world.streaming` 1.5, `world.water` 1.4, `resource.extraction` 1.2, `horror.sanity` 1.2, `mount.ride` 1.2, `vehicle.driveable` 1.11, `race.kart` 1.8; not applicable: `farming.crops` (the refusal resets the dry period, that is the rule), `life.ecosystem` (refusal already saved in the colony), `moba.hero` (waiting for a cooldown, not a condition) |\n| 3 | Priority ±1000 | C · kept, fractions documented | — |\n| 4 | `match` limited to equality | C · conditions `{ field, op, value }`, `in`, `nin`, `has`, zone | — (games' taps and rules) |\n| 5 | Non-scalar mutable field | B · `mutable` object or list + `patch` | `mission.complete` (`rewards`), card and boon offers |\n| 6 | Nullable field | B · `nullable`, `const: null` | `world.elements`, `units.command`, `ui.menu`, `input.remap` |\n| 7 | Reason for a change | A / C · `notes` | `trade.shop` (why a price changed) |\n| 8 | `void` service silent about cancellation | A · typed result | `character.*` (push), `vehicle.damage` (wreck) |\n| 9 | Direct write to a guarded variable | A · `state.guard` | `wanted.police` (`wanted.level`) |\n| 10 | `save.write` cancelled after the answer | A · ask before answering | `save.persistence` |\n| 11 | Dynamic operands; `receiveCanceled` | C · expressions `$var`, `$field`, `$add`…; `receiveCanceled` **rejected** | — |\n| 12 | Decisions in a pure model | A · `decide` as a parameter of the model | `world.elements` |\n| 13 | Factories outside a hook, id used up | A · `spawn.try`, `engine.spawn` | `npc.core`, `vehicle.driveable`, `enemy.ai`, `spawn.system` |\n| 14 | Player death outside the pipeline | A · the controller goes through the `combat.core` service | `combat.core`, `character.*` |\n| 15 | Ability cooldowns | A · `AbilityPort.decide` | `combat.abilities` |\n| 16 | Default documents not patchable | D · `defaultData` in the working copy | kits with `defaultData`, `i18n.text` |\n| 17 | `moddable.config` at the first level | D · paths | `world.bindings`, kits with nested config |\n| 18 | Config list replaced as a whole | D · `configPatch` | `world.weather`, `world.atmosphere`, `world.bindings` |\n| 19 | Static `moddable.settings` | D · pattern | `world.scenery`, `world.lighting` |\n| 20 | Generator without state | E · `Rng.state` / `restore` | `combat.ranged` |\n| 21 | Mod fingerprint on the network | E · `engine.mods.fingerprint` | `net.transport` 1.3 (application identifier `app~mods.<fingerprint>` in the hello, unchanged without mods; refusal `mods`), `net.async` 1.2, `net.lobby` 1.2, `net.rollback` 1.4, `coop.session` 1.3 (`join.mods` / `hi.mods`, refusal `mods`); `net.authoritative`, `net.claim`, `net.state`, `net.physics` get it through `net.transport.open`; `fps.network`: batch `rel-fps` (translate the refusal into `mods`); dedicated server: set `transport.app` to a client's `app()` |\n| 22 | Wildcard in an emitted topic | B · pattern in `events.emits` | `input.virtualpad`, `audio.core` (`fps.arsenal`, `fps.tactical`: batch `rel-fps`) |\n| 23 | Provider installed before mounting | E · `services.installed` | `world.district`, `input.pointer_lock` |\n| 24 | `service` role that decides | A · a `service` can declare hooks | `coop.session` 1.4 (`coop.down`, `coop.revive`, `coop.bleedout` as `hold`, on the authority) |\n| — | Uniform registries, inheritance, order (owner's direction) | D · `engine.registries`, `extends`, `order` | kits with types |\n| — | \"An event can change the data\" (owner) | C · reactions: `patch_data`, `set_config`, `set_setting`, `set_component`, `live` data, loop guard, saved journal | `enemy.ai` (enemy types), `trade.shop` (prices), `world.weather` |\n| — | Complete view of what can be plugged in | F · `extensionPointsOf`, `engine.points` | all (read from the manifests) |\n\n### 13.4 What stays closed, and why\n\n| Mechanism | Stays closed | Why |\n|---|---|---|\n| A | Historical `spawn(spec)` not intercepted; decisions taken on every tick of a continuous loop | changing the return type of `spawn` would break its callers; a hook per tick is costly and does not replay identically |\n| A | Hooks on Godot, Unity, Unreal | batch M-0 (§6): 1.3 adds `hold`, `notes`, `where`, `patch`, `engine.spawn`, `mission.complete` there |\n| B | Validation of event payloads in game; free recursive schemas | cost on every emission; the subset must stay readable by the engine cores |\n| C | Free expressions, loops, `receiveCanceled` (replaced, at no cost: a kit reads `by` and `reason` from the typed result and emits its own declared refusal event, the \"after\" of the decision); reaction on a target that is not `live` | a mod does not run code; same verdicts on five targets; a kit that does not reread its documents would not see the patch |\n| D | A mod does not **define** a component, a verb or a service; no switching mods during a game session | that would need code; the kits have already read their documents |\n| E | State of the root generator not saved by the host | would change all existing saves; each kit saves its own sequence |\n| F | The completeness indicator is a source-reading heuristic | that no decision is missing remains a judgement (§5.2) |\n"
 },
 {
  "id": "game-engine-contract",
  "title": "Attaching a kit to game.engine",
  "summary": "The 1.x contract a kit follows to plug into game.engine: roles, components, verbs, hooks, moddable.",
  "source": "docs/en/game-engine-contract.md",
  "text": "> English translation of [../game-engine-contract.md](../game-engine-contract.md) (French, the reference). Kept in step by hand.\n> Terms used here (kit, hook, scene, archetype, port…) are defined in the [glossary](../glossary.md).\n\n# Attaching a kit to `game.engine` — the 1.x contract\n\n> For the agents working on the migration batches (\"lots\", docs/game-engine.md §14.3). Contract\n> **`game.engine@1.1.0`** (1.0.0 extended without breaking changes by the batches' requests, §9), frozen for the\n> batches: a new need (verb, hook, field) is a **request** to the owner of `game.engine`, never a change made inside\n> the batch. Prose in French in the reference text, code and identifiers in English.\n\nThe engine runs on the web (`packages/gamekits/src/kits/game.engine/`) and on Godot, Unity and Unreal\n(`delivery/gameplay/engines/<engine>/kits/game.engine/`), with the names given in section 5.\n\n---\n\n## 1 · Should I attach my kit?\n\nThe classification of the 83 kits is in docs/game-engine.md §7.4 (column \"Lot\", i.e. batch). The rule:\n\n- **Dependent** (`requires: ['game.engine@^1']` + an `engine` block) if the kit brings vocabulary to the content\n  (components, verbs, steps, behaviours, entity kinds, per-scene data), builds or dresses a scene, reacts to the\n  life cycle, or displays the content.\n- **Independent** (no change) if it is a pure service. It may read an engine service on demand\n  (`ctx.services.get('engine.flow')`) without requiring it.\n\n`game.engine` is always present in a new project (first entry of `BASE_KITS`). Requiring `game.engine@^1` is safe:\nthe resolver adds it if it is missing (`source: 'auto'`, listed in `added`) and mounts it **first, outside the\nsort** — the order of the other kits does not change.\n\n---\n\n## 2 · The manifest\n\n```ts\nrequires: [...existing, 'game.engine@^1'],\nengine: {\n  role: 'content',                       // 'world' | 'layer' | 'content' | 'actor' | 'view' | 'flow'\n  components?: { [name]: { schema, description, example? } },   // archetype components this kit builds\n  verbs?: { [name]: { kind: 'action' | 'condition', args, primary?, description, example? } },\n  sceneCollections?: string[],           // own collections (data[]) a scene may carry in `data`\n  sceneConfig?: string[],                // own config keys a scene may override in `layers[<kit>]`\n  world?: { collection?: string, note?: string },   // a world kit: the collection whose document a scene names\n  entityKinds?: string[],                // spawn factories this kit registers (archetype `kind`)\n},\n```\n\n`validateManifest` checks it (`qa/gamekits-resolve-check.mjs` runs it on the whole catalogue):\n\n- an `engine` block requires `requires: game.engine@^1`;\n- `role` must be a known role; names are lowercase `[a-z0-9_]` (dots allowed);\n- every component and every verb has a `schema` / `args` (a subset of GkSchema) and a `description`;\n- `primary` names one argument of the verb: `{ \"has_item\": \"key\" }` becomes `{ type: 'has_item', item: 'key' }`;\n- `sceneCollections` and `world.collection` are collections declared in the kit's `data[]`;\n- the components `transform`, `model`, `state`, `solid`, `entry`, `health`, `faction` belong to the engine or to\n  the host: a kit does not claim them.\n\n**Version.** The batch bumps the kit's **minor** version and freezes the previous manifest (`manifest-<x.y.z>.ts`,\nadded to `versions` in the kit's `index.ts`). Only the integration step bumps `CATALOG_VERSION`.\n\n**Verbs already in `extensions`.** They stay (the data validator reads them). Declaring them also in\n`engine.verbs` gives them a schema, a short form and a place in the building-block catalogue. A manifest\ndeclaration replaces the matching line of `BRIDGE_VERBS` (model.ts), which played that role until now.\n\n---\n\n## 3 · The web runtime\n\n```ts\nimport type { EngineContentService, GameEngineService } from '../../../game.engine/contract.js';\n\nsetup() {\n  // 1. Claim the components this kit builds (the engine bridge of the slice yields to the kit's handler).\n  ctx.services.get<EngineContentService>('engine.content')?.registerComponent('pickup', (entity, value, inst) => {\n    ctx.entities.set(entity, 'inventory.pickup', { item: value.item, count: value.count ?? 1 });\n  }, ctx.kitId);\n  // 2. Verbs: ctx.triggers.registerAction / registerCondition as today (declared in engine.verbs).\n},\nready() { /* every kit is set up and the start scene entered: services and factories of other kits exist */ },\nsceneEnter(scene: SceneView) { /* build / load what belongs to this scene */ },\nsceneExit(scene: SceneView) { /* release it; the engine destroys the scene's instances itself */ },\n```\n\n- **`setup()`**: `game.engine` is mounted before everyone else, so its services already exist. Call\n  `registerComponent` here. The handler receives `(entity, value, instance)` when an instance that carries the\n  component appears; `instance` is an `InstanceView` (`id`, `scene`, `archetype`, `kind`, `state`, `solid`,\n  `visible`, `talk` — 1.1: the current conversation topic, set by `talk.topic` then by `set_talk`, saved —,\n  `components`).\n- **`ready()`** (a new optional hook of `KitRuntime`): called once **all** kits have run their `setup()`, in mount\n  order. `game.engine` enters its start scene in its own `ready()`, so before the other kits' `ready()`.\n- **`sceneEnter` / `sceneExit`** (optional): called by the engine on every scene entry / exit, after the instances\n  appear / before they are destroyed. `scene.restored === true` when a load rebuilds the scene: restore, do not\n  replay the entry effects. A kit without these hooks is global (current behaviour).\n- **`SceneView`** (`runtime/types.ts`): `id`, `implicit`, `native?`, `title?`, `entry`, `entries`, `world`\n  (`{ kit, config?, doc? }`), `data` (sections of your `sceneCollections`), `layers` (your per-scene config, to\n  merge over the kit config, key by key), `audio?`, `ui?`, `instances`, `restored`, and (1.1, `sceneExit` only)\n  `next`: the id of the scene being entered, so that a world kit knows whether it stays in place.\n- **The `data` sections of a scene are lists of objects** (a bare string is dropped at compile time): to name a\n  document of the collection, write `{ \"id\": \"<doc>\" }`.\n- **Start scene before `ready()`** (1.1): `engine.scenes.pending()` returns the `SceneView` of the scene that start-up\n  is about to open (start scene and entry, instances without entities), readable from `setup()` on; `null` once the\n  game has started (read `current()`) or in transparent mode.\n- **Borrowed entity** (1.1): when the factory of a kind returns an entity that already existed (the player, which\n  the actor kit moves on entry), the engine does not remove its physics body (it only touches instances that have a\n  `solid` component) and does not destroy it on scene exit: it just forgets it.\n- **Bridges**: a component claimed by a kit (`registerComponent`) is no longer handled by the engine's bridge —\n  this includes giving a `container`'s items on interaction (1.1).\n- **Implicit scene**: a project without a `scenes` document plays the scene `main` (`implicit: true`) — and in\n  transparent mode (no engine content), the engine calls **no** hook and emits nothing. Your kit must then behave\n  **exactly** as before (rule 5 below).\n\n### Engine services (`ctx.services.get(...)`)\n\n| Capability | Interface (`kits/game.engine/contract.ts`) | Essentials |\n|---|---|---|\n| `game.engine` | `GameEngineService` | `version`, `active()`, `content`, `scenes`, `scripts`, `flow` |\n| `engine.content` | `EngineContentService` | `registerComponent`, `instances(scene?)`, `instance(id)`, `entityOf(id)`, `instanceOf(entity)`, `archetype(id)`, `state(id)`, `setState(id, patch)`, `report()`, `compiled()`, `active()` |\n| `engine.scenes` | `EngineScenesService` | `current()`, `pending()` (1.1), `list()`, `enter(scene, entry?)`, `visited()` |\n| `engine.scripts` | `EngineScriptsService` | `registerAction(name, decl, fn, kit)`, `registerCondition(…)`, `verbs()`, `rules()`, `enable(id)`, `disable(id)`, `played()` |\n| `engine.flow` | `EngineFlowService` | `phase()`, `start(scene?, entry?)`, `end(result)`, `restart()`, `result()` |\n\n### Engine events (only when the game has engine content)\n\n`engine.scene.entered { scene, entry, restored }`, `engine.scene.leaving { from, to }`, `engine.flow.title`,\n`engine.flow.ended { result }`, `engine.flow.restarted { scene }`, `engine.interact { instance, entity, by }`,\n`engine.state.changed { instance, state }`, `engine.clip`, `engine.solid`, `engine.visibility`,\n`engine.instance.spawned { instance, entity, archetype, scene }`, `engine.call.missing`. The topics `game.won`,\n`game.lost`, `world.ready` stay as they are today. With `flow.title: on` (and `ui.menu` installed), the engine\nleaves the title screen on `menu.action { action: 'play' | 'continue' }` (what `ui.menu` emits) or on\n`ui.menu.perform` (1.1). A scene's audio (`scene.audio`) goes through `audio.core` (1.1): `music` plays the playlist\nof that name, otherwise sets the music state; `ambience` plays that sound on entry and stops it on exit.\n\n### Variables\n\n`instance.<id>.<key>` (state of an instance), `quest.<id>` (`active` / `completed` / `failed` / `aborted`),\n`story.<id>` (flags declared in the engine config).\n\n---\n\n## 4 · What a script becomes\n\nA script (`gripforge.script/1`) has no runtime of its own: it is compiled into ordinary `TriggerRule`s, run by the\nhost (`GfTriggers` on the engines). For a kit, this means: **your existing verbs already work in scripts**.\nCompiled forms your verbs may meet:\n\n| Script | Compiled rule |\n|---|---|\n| `{ \"interact\": \"self\" }` (instance `door`) | `{ event: 'engine.interact', match: { instance: 'door' } }` |\n| `{ \"state\": { \"open\": false } }` | `{ var: 'instance.door.open', op: '==', value: false }` |\n| `{ \"quest\": \"q\", \"is\": \"completed\" }` | `when`: `{ event: 'mission.completed', match: { missionId: 'q' } }`; `if`: `{ var: 'quest.q', … }` |\n| `{ \"give_item\": \"key\" }` | `{ type: 'give_item', item: 'key' }` (via `primary`) |\n| `{ \"strike\": \"self\" }` (a kit verb whose `instance` argument is `self`, 1.1) | `{ type: 'strike', instance: '<id of the scope>' }` (same for `npc`; `self` outside an instance scope: `script_invalid`) |\n| `if` + `else` | a single rule, action `{ type: 'engine_if', if, then, else }` (guard evaluated once) |\n| `once: true` | `{ type: 'engine_once', group }` at the head of `then` (the rule disappears, saved) |\n\nThe engine verbs: `set_state`, `play_clip`, `set_solid`, `show`, `hide`, `enable_script`, `disable_script`,\n`load_scene`, `end_game`, `call`, `set_talk` (and the internal ones `engine_if`, `engine_once`).\n\n---\n\n## 5 · The engines\n\nThe ports exist (`delivery/gameplay/engines/<engine>/kits/game.engine/`); these names are frozen.\n\n| | Godot (`GfKit`, GDScript) | Unity (`GfKit`, C#) | Unreal (`UGfKitComponent`, C++) |\n|---|---|---|---|\n| ready | `func gf_ready() -> void` | `protected override void Ready()` | `virtual void KitReady()` + BP event \"On Kit Ready\" |\n| scene entry | `func gf_scene_enter(scene: Dictionary) -> void` | `protected override void OnGfSceneEnter(GfSceneView scene)` | `virtual void KitSceneEnter(const FGfSceneView& Scene)` + \"On Scene Enter\" |\n| scene exit | `func gf_scene_exit(scene: Dictionary) -> void` | `protected override void OnGfSceneExit(GfSceneView scene)` | `virtual void KitSceneExit(const FGfSceneView& Scene)` + \"On Scene Exit\" |\n| the engine | node `GfEngine` (`gf_order() = 0`) | component `GfEngine` (`Order = 0`, `GfEngine.Instance`) | component `UGfGameEngineComponent` (`UpdateOrder = 0`) |\n| component | `GfEngine.register_component(name, callable, kit_id())` — `callable(entity: String, value, instance: Dictionary)` | `Core.Service<IEngineContentService>(\"engine.content\").RegisterComponent(name, (entity, value, instance) => …, KitId)` | `Cast<UGfEngineContentService>(G()->GetService(TEXT(\"engine.content\")))->RegisterComponent(Name, [](const FString& Entity, const FGfJ& Value, const FGfJObj& Instance) {…}, KitId)` |\n| services | the node (`gameplay.service(\"engine.scenes\")`), methods in snake_case | `IEngineContentService`, `IEngineScenesService` (core), `IGfInvokable` (web names) | `UGfEngineContentService` (core), `Call` (web names) |\n\n`scene` / `GfSceneView.raw` / `FGfSceneView.Raw` carry the same keys as the web `SceneView` (`id`, `implicit`,\n`entry`, `entries`, `world`, `data`, `layers`, `instances`, `restored`). Empty implementations by default. The\ncompiled content arrives in the game's data file (`gameplay.json`, section `engine`, schema `gripforge.engine/1`,\ncompiled by the delivery step): the engines do not ship a compiler. A `solid` collision goes through the existing\nphysics.port node (Godot), a `BoxCollider` (Unity), a `UBoxComponent` (Unreal); `solid: { shape: \"passport\" }`\narrives with its size already resolved (`solid.size`, rules of `asset.meta`). 1.1 additions in all three ports:\n`pending` (Godot `pending()`, Unity `IEngineScenesService.Pending()`, Unreal `Call(\"pending\")`), the `next` key of\nthe exit view (Unity `GfSceneView.Next`, Unreal `FGfSceneView.Next`), `talk` in the instance view.\n\n## 6 · The batch rules\n\n1. **Touch only your own files**: `packages/gamekits/src/kits/<your kits>/**`,\n   `delivery/gameplay/engines/{godot,unity,unreal}/kits/<your kits>/**`, your scenarios\n   `qa/gameplay-engines/scenarios/<kit>-*.json`, your checks `qa/<lot>-*.mjs`.\n2. **Never a shared file** (list in docs/game-engine.md §14.3: `registry.ts`, `kits/index.ts`, `presets.ts`,\n   `capabilities.ts`, `types.ts`, `runtime/**`, `resolve.ts`, `kits/game.engine/**`, the engine cores, the generated\n   sources, `i18n.text/defaults.ts`, `docs/gamekits.md`, `docs/game-engine*.md`, the CLI policy, the MCP tools,\n   `apps/web/src/lib/gamekits/**`). A need is written, ready to paste, in the branch description, under the heading\n   **\"Integration requests\"** (\"Demandes d'intégration\").\n3. **Generated files** (`delivery/gameplay/sources.ts`, `kit-covers.generated.ts`, `abilities/generated-web.ts`,\n   `unity/settings.generated.ts`, outputs of `scripts/gen-*.mjs`): regenerate locally to check, then **revert**;\n   never committed by a batch.\n4. **Slice 1 bridges**: `interactable` (interaction.system), `npc` (npc.core), `talk` (npc.dialogue), `pickup`,\n   `container` (inventory.basic) are handled today by the engine. Batch C **claims** them (`engine.components` +\n   `registerComponent`); the kit's handler then runs before the bridge, which stays as a fallback. The `engine-*`\n   scenarios must stay identical.\n5. **Implicit scene = previous behaviour.** Proof: replay your scenarios with the engine mounted —\n   `node qa/gameplay-engines-check.mjs --with-engine --scenario=<your scenarios>` (web) and the same command on the\n   engines — must give the same traces as the replay without `--with-engine`. Add a `<kit>-engine` scenario that\n   exercises the attachment (component, per-scene data, hooks).\n6. **No paid call** in a test (`GRIPFORGE_PROVIDER_MOCK=1`), no cover generation.\n\n---\n\n## 7 · A complete migration example: `inventory.basic` (batch C)\n\nThis is **not** applied in slice 1 (no existing kit is changed there): it is the model to follow. The attachment\npath it uses (claiming a component in `setup()`, `ready()`, scene hooks, handler priority over the bridge) is\nchecked by `qa/gamekits-engine-check.mjs` (section 10) with a demonstration kit.\n\n**`kits/inventory.basic/manifest-1.0.0.ts`**: frozen copy of the current manifest (`export const manifest_1_0_0`).\n\n**`kits/inventory.basic/manifest.ts`**:\n\n```ts\nexport const manifest: GameKitManifest = {\n  // …unchanged fields…\n  version: '1.1.0',\n  requires: ['input.actions@^1', 'game.engine@^1'],\n  engine: {\n    role: 'content',\n    components: {\n      pickup: {\n        schema: s.obj({ item: s.str({ minLength: 1 }), count: s.int({ min: 1 }) }, { required: ['item'] }),\n        description: 'A pick-up of an item: interacting gives the units, the entity goes when everything fitted.',\n        example: { item: 'lantern' },\n      },\n      container: {\n        schema: s.obj({ items: s.arr(s.str()) }, { required: ['items'] }),\n        description: 'A container: interacting gives its items once (instance state looted).',\n        example: { items: ['cellar_key'] },\n      },\n    },\n    verbs: {\n      give_item: { kind: 'action', primary: 'item', args: s.obj({ item: s.str(), count: s.int({ min: 1 }) }, { required: ['item'] }), description: 'Give units of an item to the player.', example: { give_item: 'cellar_key' } },\n      take_item: { kind: 'action', primary: 'item', args: s.obj({ item: s.str(), count: s.int({ min: 1 }) }, { required: ['item'] }), description: 'Take units of an item (all or nothing).', example: { take_item: 'cellar_key' } },\n      has_item: { kind: 'condition', primary: 'item', args: s.obj({ item: s.str(), count: s.int({ min: 1 }) }, { required: ['item'] }), description: 'The player holds at least count units.', example: { has_item: 'cellar_key' } },\n    },\n  },\n  changelog: [...previous, { version: '1.1.0', date: '…', breaking: false, notes: ['Attached to game.engine: claims the pickup and container archetype components; its verbs are declared with their arguments.'] }],\n};\n```\n\n**`kits/inventory.basic/index.ts`**: `versions: { '1.0.0': manifest_1_0_0, [manifest.version]: manifest }`.\n\n**`kits/inventory.basic/runtime/web/index.ts`**, in `setup()`:\n\n```ts\nconst engine = ctx.services.get<EngineContentService>('engine.content');\nengine?.registerComponent('pickup', (entity, value) => {\n  const v = value as { item: string; count?: number };\n  ctx.entities.set(entity, PICKUP_COMPONENT, { item: v.item, count: v.count ?? 1 });   // the existing pick-up path\n}, ctx.kitId);\nengine?.registerComponent('container', (entity, value, inst) => {\n  containers.set(inst.id, (value as { items: string[] }).items);                       // given on engine.interact, once\n}, ctx.kitId);\n```\n\nplus an `engine.interact` subscription that gives the items of a container not yet looted, then\n`engine.setState(inst, { looted: true })`. Without engine content none of this runs: the `inventory-basic` trace\nstays identical (rule 5).\n\n**Ports**: `gf_inventory_basic.gd` / `GfInventoryBasic.cs` / `UGfInventoryBasicComponent` do the same in\n`gf_setup()` / `Setup()` / `KitSetup()` with `GfEngine.register_component` (names from section 5).\n\n**Batch QA**: `qa/gameplay-engines/scenarios/inventory-basic-engine.json` (a chest and a lantern as data, no\nbridge) ≡ web on the three engines; `--with-engine` on `inventory-basic` identical.\n\n**Integration requests** (example): \"remove `give_item`, `take_item`, `has_item` from `BRIDGE_VERBS` and `pickup`,\n`container` from `BRIDGE_COMPONENTS` in `kits/game.engine/model.ts` once batch C is merged\".\n\n---\n\n## 8 · Checking\n\n```bash\npnpm --filter @gripforge/gamekits build\nnode qa/gamekits-engine-check.mjs                              # the engine contract, pure\nnode qa/gamekits-resolve-check.mjs                             # every manifest, engine block included\nnode qa/gameplay-engines-check.mjs --no-engines --with-engine  # every scenario, engine mounted ≡ without\nnode qa/gameplay-engines-check.mjs --scenario=<yours> --only=godot,unity,unreal   # the engine ports\n```\n\n## 9 · Contract 1.1 (batch requests, done)\n\n| Request | Batch | Where |\n|---|---|---|\n| The title screen is left on `menu.action` (`play`, `continue`) | A §2 | web runtime and three ports |\n| `InstanceView.talk` | C §3 | `contract.ts`, web runtime, three ports |\n| Giving a `container`'s items yields to the kit that claims it | C §4 | web runtime and three ports |\n| `self` (or `true`) for the `instance` / `npc` argument of a kit verb | C §5, D §4 | compiler (`model.ts`) |\n| The `data` rows of a scene are objects (documentation) | D §5 | §3 above |\n| `next` in the `sceneExit` view | B §3.2 | `SceneView`, web runtime, three ports |\n| `engine.scenes.pending()` | F §4.3 | `contract.ts`, web runtime, three ports |\n| The borrowed player: body kept, not destroyed on exit | G §2.1, §2.2 | web runtime and three ports (saved: `borrowed`) |\n| Text of `entry_missing` | G §2.3 | `model.ts` |\n| `ui_hud_unknown` | A §6 | `model.ts` |\n| Passport resolved like `asset.meta` (slot, then Library id, project corrections); size resolved at compile time | H R1, R2 | `archetypePassport`, `passportSize` (`model.ts`), web runtime (`asset.meta` service first) |\n| `passport_missing` suggests `asset.meta` when it is missing | H R3 | `model.ts` |\n| Scene music and ambience through `audio.core` | H R4 | web runtime and three ports, `engine-flow` scenario |\n\nLeft for a later version (no batch depends on it to merge): entries provided by a world kit (B §3.1, F §4.2),\nseveral baked maps per project (B §3.3, owner of the assets), validation of `world.config` and `layers` against the\nworld kit's schema (F §4.1). Removing the `BRIDGE_VERBS` / `BRIDGE_COMPONENTS` lines taken over by the batches'\nmanifests is done at integration, once the batches are merged.\n\n## 10 · Contract 1.2: the extension layer (\"mods.engine\")\n\n`game.engine@1.2.0` adds, without breaking changes, the extension contract that **every** kit follows:\n**docs/mods-engine.md**. In short, for a kit:\n\n- `engine.hooks` (manifest): its interceptable decisions — `payload`, `mutable`, `cancellable`, `description`;\n  the runtime submits them through `ctx.services.get<EngineHooksService>('engine.hooks')?.run(name, payload)` before\n  applying them (Rust: `kx.call(\"engine.hooks\", \"run\", …)`; a code tap there is a `kx.callback`).\n- `engine.moddable` (manifest): the config keys, collections and live settings that a mod may touch.\n- role `service` for a pure service; every kit requires `game.engine@^1`.\n- New services: `engine.hooks` (`run`, `tap`, `untap`, `declare`, `declared`, `taps`), `engine.mods`\n  (`list`, `applied`, `has`, `originOf`). New engine collections: `hooks`, `mods`. Condition `mod_enabled`.\n  Events `engine.mods.applied`, `engine.mods.changed`, `engine.hook.refused`.\n- Check: `node qa/gamekits-mods-contract-check.mjs`. Godot, Unity, Unreal ports: to do (docs/mods-engine.md §6).\n\n"
 },
 {
  "id": "game-engine",
  "title": "game.engine design",
  "summary": "The engine of every game: scenes, content model, scripts, saves (design document). (French: no English translation yet.)",
  "source": "docs/game-engine.md",
  "text": "# game.engine — le moteur de chaque jeu GripForge\n\n> Document de conception **approuvé**, mis à l'état de la construction. Langue : français pour la prose, anglais\n> pour le code et les identifiants.\n>\n> **État** (branche `engine-integration`, catalogue `2026.10.02.8`, 84 kits) : la tranche 1 et le **contrat 1.1.0**\n> sont construits sur le web, Godot, Unity et Unreal — kit `game.engine`, registre de contenu, scènes, cycle de vie,\n> scripts `gripforge.script/1` compilés en règles, placement cuit (`engine.place`), outils MCP `gripforge_game_engine`\n> et `gripforge_game_content`, `added` à l'installation, retrait avec dépendants confirmé, résolution des livraisons\n> par liste, preset `adventure` — et les huit lots de migration sont intégrés (§17.5). Ce qu'un kit doit déclarer et\n> implémenter pour se rattacher : **docs/game-engine-contract.md**. Les décisions du propriétaire et les choix pris\n> sont au §16, les écarts entre la conception et la construction au §17.\n\n---\n\n## 0 · En une page\n\n**Ce qu'on change.** Aujourd'hui, créer un jeu revient à créer un projet Game Kits (`gkp_…`), y poser des kits,\npuis écrire le reste. Demain, créer un jeu revient à créer **l'instance du moteur de ce jeu** : un projet dont le\npremier kit est `game.engine`. On y **dépose** ensuite le contenu : assets, scènes, histoire, scripts\nd'interaction, interface. Le jeu évolue par son contenu, pas par une réécriture de son moteur. Il reste un jeu\ncodé : le code propre au jeu reste permis et normal (§10).\n\n**Ce que `game.engine` est réellement.** Il ne réécrit pas le moteur existant. Le `KitHost` web et les cœurs de\ngameplay Godot, Unity et Unreal fournissent déjà la boucle, le bus, les variables, les entités, les zones, les\ndéclencheurs, les objectifs, l'apparition des entités et la sauvegarde. C'est la capacité hôte `runtime.core`.\n`game.engine` fait trois choses :\n\n1. Il **nomme et versionne ce socle**. Le socle devient un kit, premier de `BASE_KITS` et monté en premier, avec\n   un contrat que les autres kits peuvent requérir (`game.engine@^1`).\n2. Il **ajoute les trois couches qui manquent** :\n   - le **registre de contenu** : archétypes, instances, validation ;\n   - les **scènes** : niveaux, entrées, chargement, cycle de vie du jeu ;\n   - les **scripts d'interaction** : une déclaration de données compilée vers les règles `triggers.rules`, déjà\n     portées sur les quatre cibles.\n3. Il **donne aux agents la structure canonique** d'un jeu : l'arborescence, le catalogue des briques, l'ordre\n   de construction et le paquet de départ. C'est la voie recommandée. Ce n'est jamais une barrière.\n\n**Première tranche.** Elle prouve le principe sur les quatre cibles :\n- un village avec un PNJ qui donne une quête, une porte fermée à clé et un coffre ;\n- entièrement en données ;\n- le même fichier de contenu donne la même trace sur web, Godot, Unity et Unreal ;\n- aucun kit existant n'est modifié ;\n- un agent peut construire ce jeu par le MCP sans écrire de code moteur (§14.1).\n\n**Rattachement des kits.**\n- 56 kits **dépendent** de `game.engine`. Ce sont ceux qui apportent du vocabulaire au contenu, construisent une\n  scène ou en affichent le contenu.\n- 27 kits sont **indépendants**. Ce sont des services purs : entrée, réglages, rendu, texte, thème, réseau,\n  physique, et les clients hérités.\n- Les jeux existants reçoivent `game.engine` automatiquement à l'ouverture, en mode transparent, sans aucun\n  changement de comportement (§7.6).\n- La migration des kits se fait par **lots parallèles**. Seule l'étape d'intégration finale touche les fichiers\n  partagés (§14.3).\n\n---\n\n## 1 · Le principe\n\n### 1.1 La demande, traduite en règles\n\n| Ce que dit le propriétaire | La règle de conception |\n|---|---|\n| « on ne crée pas le jeu, on crée le moteur du jeu » | Créer un jeu = créer un projet dont `game.engine` est le premier kit. Le reste se dépose dedans. |\n| « assets, scripts d'interaction et UI viennent s'y greffer, se construire, se déposer » | Tout ce qui n'est pas du code moteur est un **document de contenu**, déclaré, validé et indexé. Le déposer ne demande aucune modification de code. |\n| « les assets, grâce à leurs métadonnées, se déclarent et se placent » | Le passeport d'un asset (`.gfmesh.json`, servi par `asset.meta`) reçoit une section `kits.engine` : rôle, règle de placement, points d'interaction. Une instance s'en sert pour se poser et se rendre interactive (§5.6). |\n| « ce PNJ donne cette quête » | Un script d'interaction est une donnée exécutée à l'identique sur les quatre cibles (§6). |\n| « ça reste un jeu codé » | Le code propre au jeu a sa place et ses points de branchement (§10). |\n| « game.engine sera le premier module chargé » | Il est en tête de `BASE_KITS` et monté en premier, hors tri topologique (§7.6). |\n| « toute évolution viendra du contenu » | Le catalogue des briques (§8.2) et l'ordre de construction (§8.3) orientent l'agent vers le contenu d'abord. |\n\n### 1.2 Ce qu'on retient d'un projet voisin du propriétaire\n\nUn autre projet du propriétaire définit déjà le comportement de son monde par des données. Seules les idées sont\nreprises, ni le code ni les noms :\n\n1. **Poser un fichier suffit à le faire exister.** Une map est un fichier de données déposé dans un dossier.\n   Aucune inscription ailleurs. Le registre la découvre. Ici, un document déposé dans une collection de contenu\n   suffit.\n2. **Le registre ne construit rien.** Il trouve, décrit et valide, puis rend le contenu. Ce sont les\n   bâtisseurs qui construisent. Ici, `engine.content` indexe et valide. Les kits construisent.\n3. **Deux niveaux de diagnostic.**\n   - Une **erreur** veut dire « injouable » : le contenu ne se charge pas.\n   - Un **avertissement** veut dire « se chargera, mais il manquera quelque chose ».\n   - On ne promeut jamais un avertissement en erreur : un contenu en cours de fabrication reste jouable.\n   - Le rapport est disponible sans lancer de partie.\n4. **Un catalogue de données, seule source de vérité.** Le validateur et le bâtisseur lisent la même table. Une\n   sorte d'élément inconnue est refusée avant la construction, et en ajouter une demande une ligne de table, pas\n   une branche de code. Ici, chaque kit déclare dans son manifeste les composants qu'il sait bâtir. Le validateur\n   et le kit lisent cette même déclaration (§7.3).\n5. **Un asset se désigne par un identifiant, jamais par un chemin.** Le préchargement suit le contenu de la\n   scène. Ici : slot, `content:<id>` ou `lib_…`.\n6. **Ce qui ne dépend que du contenu déclaré se cuit une fois et se livre cuit**, avec une empreinte. Si\n   l'empreinte ne correspond plus, on recalcule avec un avertissement. On n'est jamais bloqué. Ici, le placement\n   des instances est cuit (§5.6).\n7. **Un seul registre d'entités** : un id, une sérialisation, un tick, une recherche spatiale. C'est déjà le\n   cas (`EntityRegistry`).\n8. **Une seule porte d'entrée pour les intentions**, qu'elles viennent du joueur, du réseau ou de l'IA. Ici,\n   c'est `input.actions` et le bus.\n\n---\n\n## 2 · Ce qui existe déjà\n\n### 2.1 Le socle est presque là\n\n| Brique | Où | Rôle pour `game.engine` |\n|---|---|---|\n| `KitHost` : pas fixe 1/60 s, montage dans l'ordre du lockfile, phases `loading / countdown / playing / paused / finished` | `packages/gamekits/src/runtime/host.ts` | La boucle et le cycle de vie bas niveau |\n| `KitContext` : `bus`, `entities`, `state`, `input`, `timers`, `zones`, `triggers`, `objectives`, `spawn`, `physics`, `assets`, `rng`, `services`, `project` | `runtime/types.ts` | Le contrat que chaque kit reçoit |\n| Capacité hôte `runtime.core`, avec `save()`, `load()`, `defer()` et `saveStore()` | `capabilities.ts` (`HOST_CAPABILITIES`), `runtime/save.ts` | La sauvegarde du jeu entier, déjà sur les quatre cibles |\n| Cœurs natifs | `delivery/gameplay/engines/godot/core` (`GfGameplay`, `GfEntity`, `GfZone`, `GfKit`, `GfTriggers`, `GfObjectives`), `unity/core/Runtime` (`GfGameplay`, `GfBus`, `GfEntities`, `GfTriggers`…), `unreal/core` (`UGfGameplaySubsystem`, `GfTriggers`, `GfObjectives`…) | Le même socle, porté ligne à ligne |\n| Fichier de données du jeu, lu au démarrage par chaque cœur | `GAMEPLAY_DATA_FILE` (`gripforge/data/gameplay.json`, `Assets/GripForge/Resources/GripForge/gameplay.json`, `Content/GripForge/Data/gameplay.json`) | **Le véhicule du contenu vers les moteurs** |\n| Langage commun conditions / actions : `var`, `event`, `in_zone`, `has_tag`, `all`, `any`, `not`, `set_var`, `inc_var`, `emit`, `spawn`, `despawn`, `notify`, `start_mission`, `complete_objective`, `fail_mission`, `teleport`, `wait`, et les verbes `{ type }` déclarés par les kits | `data/dsl.ts`, `types.ts` (`Condition`, `Action`, `TriggerRule`) | **L'exécuteur des scripts d'interaction** |\n| Verbes ajoutés par des kits (`extensions`) | `inventory.basic` (`give_item`, `take_item`, `has_item`), `economy.money`, `combat.core`, `faction.system`, `wanted.police`, `save.persistence` (`save_game`), `npc.core` (`npc_state`)… | Le vocabulaire existant des scripts |\n| Collections de données déclarées par les kits | 30 collections : `missions`, `triggers`, `npcs`, `dialogues`, `zones`, `spawns`, `items`, `rooms`, `terrain_maps`, `world_lights`, `asset_passports`… | Le contenu d'aujourd'hui, éclaté par kit |\n| Passeport de mesh : étalon, orientation, rig, landmarks, colliders, clips, sections `kits.*` | `packages/core/src/mesh-passport.ts`, kit `asset.meta` (collection `asset_passports`) | La métadonnée qui rendra un asset auto-descriptif |\n| `SceneDocument` (`purpose: 'map'`) : instances d'assets avec `role`, zones `spawn / objective / gameplay`, terrain, lumières, caméra | `packages/core/src/scene/types.ts` | Une source de scènes (import) |\n| Carte cuite du studio terrain (`terrain.bakeKit` → `.gftm` lié au slot `terrain_map`) | `world.terrain`, `apps/web/src/lib/gamekits/terrain-map.ts` | Le modèle « cuit une fois, livré » |\n| Scénarios de conformité : 70 fichiers, découverts automatiquement, trace web de référence ≡ Godot / Unity / Unreal | `qa/gameplay-engines/scenarios/*.json`, `qa/gameplay-engines-check.mjs` | La preuve de parité, sans nouveau format |\n| Mises à jour automatiques à l'ouverture, copies locales, tâches d'agent | `autoupdate.ts`, `overlay.ts`, `doc.tasks` | Le mécanisme de migration des jeux vivants |\n| Résolveur : `requires` → index de capacités → `DEFAULT_PROVIDERS` ; fournisseurs ajoutés avec `source: 'auto'` | `resolve.ts` | L'installation automatique des dépendances |\n| `ui.webui` : une page HTML / JS au-dessus du jeu, une seule API de page, sur les quatre sorties | `kits/ui.webui` | L'hôte des interfaces propres au jeu |\n\n### 2.2 Ce qui manque\n\n1. **Pas de scène.** Le `KitHost` n'a qu'une partie, sans niveau. Chaque kit de monde est son propre chargeur de\n   niveau, avec sa propre collection :\n   - `rooms` / `runs`, `platform_courses`, `race_tracks`, `tactical_maps`, `terrain_maps`, `zones` du quartier ;\n   - aucune entrée de scène ;\n   - aucun changement de niveau ;\n   - aucun « où commence le joueur » commun.\n2. **Pas de registre de contenu.** Les collections sont validées une à une (`PATCH …/data`). Rien ne dit « voici\n   tout le contenu du jeu, et voici ce qui manque ».\n3. **Un asset ne se dépose pas seul.** Un modèle n'entre dans le jeu que par un slot de kit. Un coffre, une\n   porte ou un tonneau n'ont aucun kit qui les fasse apparaître. `spawn.system` n'a des fabriques que pour\n   `player`, `npc` et `vehicle`.\n4. **« Ce PNJ donne cette quête » demande trois collections câblées à la main.** Il faut un dialogue\n   (`dialogues`, avec un choix `then: [{ start_mission }]`), une mission (`missions`) et souvent un déclencheur\n   (`triggers`). Le champ `giver.npc` du schéma de mission existe, mais le runtime ne gère que `giver.zone`\n   (`mission.system/runtime/web/index.ts`, `giverGated`).\n5. **Les règles sont globales.** Une `TriggerRule` ne connaît pas « soi-même ». Une porte ne peut pas dire\n   « quand on *m'*interagit, *je* m'ouvre », et aucun état par instance n'est sauvé avec elle.\n6. **Pas de cycle de vie de jeu.** On a des phases (`loading…finished`), mais pas de suite\n   « titre → scène de départ → transitions → fin → rejouer ».\n7. **Les vues web sont codées en dur dans `apps/web`.** Ce sont `render/*.ts` (26 fichiers par genre) et\n   `components/gamekits/*Hud.tsx`. Un kit ne déclare pas ses vues.\n8. **Le code propre au jeu n'a pas de place dans la page de jeu hébergée.** Les fichiers d'une copie locale sont\n   stockés mais « not executed in the browser ». Sur les moteurs, la consigne actuelle est « drop the kit nodes\n   in your main scene » : la scène principale appartient à l'utilisateur.\n9. **Le mot « moteur » est déjà pris.** L'ancien outil MCP `gripforge_kit` dit « A game kit IS an engine »\n   (document GameRules des kits Library hérités). Il faudra lever l'ambiguïté (§15).\n\n---\n\n## 3 · `game.engine` : définition\n\n### 3.1 Identité\n\n```ts\n{\n  schema: 'gripforge.gamekit/1',\n  id: 'game.engine',\n  name: 'Game engine',\n  version: '1.0.0',\n  requires: ['runtime.core@^1'],          // l'hôte, sur les quatre cibles\n  provides: [\n    { id: 'game.engine',    version: '1.0.0' },  // le contrat, la version que les kits requièrent\n    { id: 'engine.flow',    version: '1.0.0' },  // cycle de vie du jeu\n    { id: 'engine.content', version: '1.0.0' },  // registre de contenu, composants, validation\n    { id: 'engine.scenes',  version: '1.0.0' },  // scènes, entrées, chargement\n    { id: 'engine.scripts', version: '1.0.0' },  // scripts d'interaction, registre des verbes\n  ],\n  data: [\n    { kind: 'archetype', collection: 'archetypes', schema: ARCHETYPE_SCHEMA },\n    { kind: 'scene',     collection: 'scenes',     schema: SCENE_SCHEMA },\n    { kind: 'script',    collection: 'scripts',    schema: SCRIPT_SCHEMA },\n    { kind: 'code',      collection: 'code_modules', schema: CODE_MODULE_SCHEMA },  // §10\n  ],\n  configSchema: {\n    startScene: '…',          // id de scène ; vide = la première, ou la scène implicite\n    flow: { title: 'auto|on|off', endOn: '[conditions de victoire / défaite]' },\n    placement: 'baked|runtime',\n    debug: false,\n  },\n  adapters: [webNative(), ...gameplayAdapters('game.engine')],\n}\n```\n\n- **`BASE_KITS`** devient `['game.engine', 'ui.menu', 'input.remap', 'settings.graphics', 'ui.prompts',\n  'ui.endscreen', 'save.persistence', 'audio.core', 'i18n.text', 'ui.theme']`.\n- **Un preset hérité** (client dédié, `legacy.*`) ne reçoit pas les kits de base aujourd'hui. Il ne reçoit pas\n  non plus `game.engine`.\n- **Mode transparent.** Sans document `archetypes`, `scenes` ni `scripts`, `game.engine` ne crée aucune entité,\n  n'ajoute aucune règle et n'émet aucun événement de plus qu'aujourd'hui. Il expose seulement ses services. C'est\n  ce qui permet de l'ajouter aux jeux vivants (§7.6).\n\n### 3.2 Ce qu'il possède, ce qui reste aux kits\n\n| Domaine | `game.engine` possède | Reste aux kits |\n|---|---|---|\n| Boucle | Rien de neuf. Le `KitHost` et les cœurs natifs gardent le pas fixe. `game.engine` est leur visage versionné (§3.7). | — |\n| Cycle de vie du jeu | `engine.flow` : `boot → title? → scene(start) → playing ⇄ paused → scene(x)… → ended(result) → restart`. Événements `engine.flow.*`. | L'écran titre et la pause (`ui.menu`), l'écran de fin (`ui.endscreen`) |\n| Scènes | `engine.scenes` : document de scène, entrées, chargement et déchargement, scène implicite, crochets `sceneEnter` / `sceneExit` vers les kits | La **construction du monde** d'une scène (`world.*`, `moba.lanes`, `fps.tactical`) |\n| Contenu | `engine.content` : index, archétypes, instances, composants revendiqués par les kits, placement, rapport erreurs / avertissements | Le **sens** de chaque composant (un `npc` est bâti par `npc.core`, un `interactable` par `interaction.system`) |\n| Bus et variables | Les règles de nommage (§3.5) et le catalogue des sujets et variables, calculé depuis les manifestes. Le bus reste celui de l'hôte. | Leurs sujets et leurs variables |\n| Scripts | `engine.scripts` : le format, la compilation vers `TriggerRule`, le registre des verbes avec leurs schémas, l'état par instance | Les **verbes métier** (`give_item`, `damage`, `start_dialogue`…) |\n| Histoire | Rien en propre. L'index relie quêtes, dialogues et PNJ. | `mission.system` (quêtes), `npc.dialogue` (dialogues), `npc.core` (PNJ) |\n| Interface | Les déclarations par scène : quel HUD, quels panneaux (§5.5) | Les vues (`hud.*`, `ui.*`, `ui.webui`) |\n| Sauvegarde | Sa section `kits['game.engine']` : scène courante, scènes visitées, état des instances, scripts `once` déjà joués. Rien d'autre à écrire : `runtime.core.save()` inclut déjà le `save()` de chaque kit. | Les emplacements, l'interface et les déclencheurs d'autosave (`save.persistence`) |\n\n### 3.3 Le cycle de vie (`engine.flow`)\n\n```\nboot ── content indexed, kits mounted (lock order, game.engine first)\n  │\n  ├─ flow.title = on|auto(with ui.menu) ──► title  (ui.menu shows its title screen)\n  │                                          │ ui.menu.perform {action:'play'|'continue'}\n  ▼                                          ▼\nscene.enter(startScene, entry) ──► playing ⇄ paused (host phases, unchanged)\n  │      load_scene / door to another scene\n  ├────► scene.exit(a) → scene.enter(b, entry)\n  │\n  └─ endOn condition | game.won | game.lost ──► ended(result) ──► ui.endscreen\n                                                    │ restart\n                                                    └──► scene.enter(startScene)\n```\n\n- **Les phases de l'hôte ne changent pas.** `engine.flow` les pilote. Il ne les remplace pas.\n- **Événements émis** : `engine.flow.title`, `engine.scene.leaving {from, to}`, `engine.scene.entered {scene,\n  entry}`, `engine.flow.ended {result}`, `engine.flow.restarted`. Les sujets existants `game.won`,\n  `game.lost` et `world.ready` sont conservés.\n- **Sans `ui.menu`**, ou avec `flow.title: off`, le jeu entre directement dans la scène de départ, comme\n  aujourd'hui.\n\n### 3.4 Le registre de contenu (`engine.content`)\n\n- **Index.** Au montage, et côté serveur à chaque écriture, l'index rassemble :\n  - les archétypes, les scènes et leurs instances, les scripts ;\n  - les documents des collections que les kits marquent comme contenu (`missions`, `dialogues`, `npcs`,\n    `items`…) ;\n  - les liaisons et les passeports.\n\n  Chaque entrée porte `{ kind, id, source: 'engine'|<kit id>, scene?, refs: [...] }`. Les références croisées\n  sont résolues : instance → archétype, script → instance, dialogue → quête, quête → PNJ.\n- **Rapport.** Un rapport `{ errors, warnings, stats }`, avec les deux niveaux du §1.2.\n  - Exemples d'erreur : une instance d'un archétype inconnu ; un composant que personne ne revendique ; une\n    scène de départ absente ; un script qui vise une instance inexistante ; un verbe inconnu **et** non déclaré\n    par un module de code (§10).\n  - Exemples d'avertissement : un asset sans passeport ; un placement cuit périmé ; un kit attendu par un\n    composant mais non installé ; un texte qui n'est pas une clé `i18n.text`.\n- **Une erreur ne refuse jamais une écriture**, sauf un document invalide pour son schéma. C'est déjà le\n  comportement de `PATCH …/data`. Le jeu se charge avec le contenu sain. Le contenu en erreur est écarté et cité\n  dans le rapport.\n- **Composants.** Un kit revendique un nom de composant d'archétype :\n\n  ```ts\n  engine.content.registerComponent('interactable', handler, 'interaction.system')\n  ```\n\n  Le gestionnaire reçoit l'entité créée et la valeur du composant, puis il bâtit (§7.3). Les noms gérés par\n  l'hôte (`transform`, `model`, `health`, `faction`) restent à l'hôte.\n\n### 3.5 Bus et variables : règles de nommage\n\n- Sujets : `<domaine>.<événement>`. Ceux du moteur sont `engine.*`, ceux de l'hôte restent ceux de\n  `RUNTIME_TOPICS`.\n- Variables : `<kit ou domaine>.<chemin>`. Celles de l'histoire sont `story.<id>`, celles d'une instance sont\n  `instance.<id>.<clé>`. Une variable `story.*` est déclarée par le contenu (§5.4).\n- Le catalogue des sujets et variables est **calculé** depuis les manifestes (`events`, `vars`) et le contenu.\n  Il n'est jamais écrit à la main (§8.2).\n\n### 3.6 Sauvegarde\n\n- `game.engine` implémente `save()` / `load()` comme n'importe quel kit :\n\n  ```json\n  { \"scene\": \"village\", \"entry\": \"start\", \"visited\": [\"village\"], \"instances\": { \"door_cellar\": { \"state\": { \"open\": true }, \"solid\": false } }, \"once\": [\"s_chest#0\"] }\n  ```\n\n- **Scène courante au chargement.** Si le jeu est sauvé dans la scène B, un chargement la reconstruit d'abord.\n  Il appelle `sceneEnter(B)` sans rejouer les scripts d'entrée, puis il hydrate entités et variables. C'est\n  l'ordre `runtime.core.defer` déjà utilisé par `save.persistence`.\n- **Anciennes sauvegardes.** Une sauvegarde `gripforge.slot/1` ou `/2` sans section `game.engine` se charge dans\n  la scène implicite (§5.3), avec `migrated: true`. Les enregistrements réels\n  `qa/save-slots/legacy-1.0.0.json` doivent toujours reprendre leur partie.\n\n### 3.7 Un jeu codé à la main utilise les pièces à la carte\n\nUn jeu qui n'adopte pas le modèle de contenu (pas d'archétype, de scène ni de script) garde `game.engine`, en\nmode transparent. Il s'en sert pièce par pièce, depuis son propre code :\n\n| Pièce | Web (`ctx.services`) | Godot | Unity | Unreal |\n|---|---|---|---|---|\n| Cycle de vie | `engine.flow.start(scene?)`, `.end('won')`, `.restart()`, `on('engine.flow.*')` | `GfEngine.flow_start()`… | `GfEngine.Flow.Start()`… | `UGfEngineSubsystem::FlowStart()`… |\n| Registre d'entités | `ctx.entities` (inchangé) | `GfGameplay.register(node, kind, tags)` (inchangé) | `GfEntities` | `UGfEntityComponent` |\n| Bus et variables | `ctx.bus`, `ctx.state` | `GfGameplay.emit / on / set_var` | `GfBus`, `GfState` | `UGfGameplaySubsystem` |\n| Sauvegarde | `runtime.core.save()` via `save.persistence` | `GfGameplay.save_game()` | `GfSave` | `GfSaveStore` |\n| Scènes | Facultatif. `engine.scenes.enter('b')` change de scène même si la scène est « native » (§5.3). | Une scène `.tscn` faite à la main est une scène native | Une scène `.unity` | Un niveau `.umap` |\n\nRien n'oblige à passer du code au contenu. Le rapport de contenu d'un jeu codé à la main reste simplement vide.\n\n### 3.8 Installation, dépendance, retrait\n\n**Installation.**\n- `game.engine` est un kit par défaut, en tête de `BASE_KITS`.\n- Un kit qui en dépend le déclare dans `requires: ['game.engine@^1']`. Installer ce kit installe `game.engine`\n  s'il manque : c'est le résolveur actuel (`source: 'auto'`, §9.3).\n- Il n'existe aucune règle « non retirable ».\n\n**Jamais de retrait implicite.**\n- Aucun chemin ne retire `game.engine` par effet de bord.\n- `prune` ne l'élague jamais, même s'il est marqué `auto`.\n- Un `configure enabled:false` sur lui demande la même confirmation qu'un retrait.\n- Un agent qui « fait le ménage » ne le touche pas. La politique CLI le dit (§8.5).\n\n**Retrait explicite.** Il suit la règle commune à tous les kits (§9.3) :\n1. la demande montre la liste des kits dépendants ;\n2. la confirmation retire le kit **et** ses dépendants ensemble ;\n3. le projet garde une trace `doc.removed['game.engine'] = { at, by, reason }`, pour que la migration\n   automatique (§7.6) ne le réinstalle pas. Installer plus tard un kit qui le requiert le ramène normalement et\n   efface la trace.\n\n---\n\n## 4 · Ce qu'est le contenu\n\n| Sorte | Collection | Schéma | Qui le lit à l'exécution | D'où il vient |\n|---|---|---|---|---|\n| Asset | `bindings` (slots) + `asset_passports` | passeport `gfmesh` | moteur de rendu de chaque cible, `asset.meta`, `game.engine` (placement) | Library, studios, génération |\n| Archétype | `archetypes` | `gripforge.archetype/1` | `game.engine` + les kits qui revendiquent ses composants | agent, studios (§12) |\n| Scène | `scenes` | `gripforge.scene/1` | `game.engine` + le kit monde de la scène + les kits de couche | agent, import Scene Studio, carte du studio terrain, plan `gripforge_level`, éditeur natif |\n| Quête | `missions` | `gripforge.mission/1` (inchangé) | `mission.system` | agent |\n| Dialogue | `dialogues` | schéma de `npc.dialogue` (inchangé) | `npc.dialogue` | agent |\n| PNJ (fiche) | `npcs` | `gripforge.npc/1` (inchangé) | `npc.core` | agent |\n| Objet d'inventaire | `items` | schéma de `inventory.basic` | `inventory.basic` | agent |\n| Script d'interaction | `scripts` | `gripforge.script/1` | `game.engine` → `triggers.rules` | agent |\n| Règle globale | `triggers` | `TriggerRule` (inchangé) | l'hôte | agent (reste valable) |\n| Texte | `translations` | `i18n.text` | `i18n.text` | agent |\n| Apparence de l'interface | config `ui.theme` | — | kits d'interface | agent |\n| Panneau propre au jeu | section `ui` de la scène + page `ui.webui` | §5.5 | `ui.webui`, `hud.*` | agent, code |\n| Module de code | `code_modules` | §10 | `game.engine` (validation, catalogue) | agent |\n\n**Toutes ces sortes restent dans `doc.data`**, la structure de projet existante. Aucun nouveau stockage. Les\ncollections de `game.engine` sont des collections comme les autres, validées par `PATCH …/data`, et livrées aux\nmoteurs dans le même `gameplay.json`.\n\n---\n\n## 5 · Le modèle de contenu\n\n### 5.1 Comment un contenu se déclare et se dépose\n\n```\nput (MCP / API / studio)\n  └─ sanitize + schema of the declaring kit   (existing PATCH …/data; only a document invalid for its schema is refused)\n       └─ index + cross refs + report         (engine.content, pure TS, also run server side)\n            └─ placement bake                 (compute service job when it reads a file, §5.6)\n                 └─ bundle (web) / gameplay.json + bound binaries (engines)\n                      └─ runtime: game.engine mounts first, scene.enter → instances → component handlers → scripts compiled\n```\n\nDéposer un contenu ne touche aucun code. Un document peut arriver dans n'importe quel ordre : une référence encore\nabsente donne un avertissement, puis disparaît quand la cible arrive.\n\n### 5.2 Archétypes et composants\n\nUn archétype est un gabarit d'entité, un « préfabriqué » déclaré en données.\n\n```json\n{\n  \"schema\": \"gripforge.archetype/1\",\n  \"id\": \"chest_wood\",\n  \"kind\": \"prop\",\n  \"name\": \"content.chest_wood.name\",\n  \"asset\": { \"item\": \"lib_7Qk…\" },\n  \"tags\": [\"container\"],\n  \"components\": {\n    \"solid\":        { \"shape\": \"passport\" },\n    \"interactable\": { \"label\": \"content.chest_wood.open\", \"action\": \"interact\" },\n    \"state\":        { \"opened\": false }\n  }\n}\n```\n\n- **`kind`** choisit la fabrique d'apparition (`spawn.system`) : `player`, `npc` et `vehicle` existent.\n  `game.engine` ajoute `prop`, une entité posée, sans comportement propre, qui porte des composants. Un module de\n  code peut enregistrer d'autres sortes (§10).\n- **`asset`** désigne l'apparence :\n  - `{ \"slot\": \"npc_elder\" }` vise un slot existant ;\n  - `{ \"item\": \"lib_…\" }` vise un item Library. Le moteur le lie alors automatiquement au slot `content:<id\n    d'archétype>`. Les bundles et les livraisons signent et téléchargent ce slot comme les autres, sans\n    nouvelle mécanique.\n- **`components`** : chaque nom est **revendiqué** par un kit. Exemples :\n  - `npc` → `npc.core`, avec `{ \"doc\": \"npc_elder\" }` qui renvoie à la fiche existante ;\n  - `talk` → `npc.dialogue` ;\n  - `interactable` → `interaction.system` ;\n  - `container`, `pickup` → `inventory.basic` ;\n  - `vehicle` → `vehicle.driveable` ;\n  - `enemy` → `enemy.ai` ;\n  - `health`, `faction` → l'hôte.\n\n  `game.engine` gère lui-même `state` (§6.4), `solid` (collision depuis le passeport ou une boîte), `model` et\n  `entry`.\n- **Composant non revendiqué.** C'est une **erreur** du rapport si aucun kit installé ne déclare ce composant,\n  sinon un **avertissement** si le kit qui le déclare existe au catalogue mais n'est pas installé. La réponse\n  `next` propose alors `gripforge_gamekit_install`.\n- **Les fiches existantes restent la source.** Un archétype `npc` renvoie à la fiche `npcs`, il ne la recopie\n  pas. Les collections `npcs`, `enemies`, `weapons`… restent ce qu'elles sont. Un archétype les **place** dans\n  une scène.\n\n### 5.3 Scènes\n\n```json\n{\n  \"schema\": \"gripforge.scene/1\",\n  \"id\": \"village\",\n  \"title\": \"content.scene.village\",\n  \"world\": { \"kit\": \"world.terrain\", \"config\": { \"size\": 160, \"seed\": 7, \"climate\": \"temperate\" } },\n  \"entries\": [ { \"id\": \"start\", \"at\": [0, 0, 0], \"yaw\": 0 }, { \"id\": \"from_cellar\", \"at\": [11, 0, -1], \"yaw\": 3.14 } ],\n  \"instances\": [\n    { \"id\": \"elder\",       \"archetype\": \"elder\",     \"at\": [4, 0, 6],   \"yaw\": 3.1, \"place\": \"ground\" },\n    { \"id\": \"door_cellar\", \"archetype\": \"door_wood\", \"at\": [12, 0, -3], \"yaw\": 1.57, \"place\": \"ground\" },\n    { \"id\": \"chest_1\",     \"archetype\": \"chest_wood\",\"at\": [-8, 0, 9],  \"place\": \"ground\",\n      \"set\": { \"container\": { \"items\": [\"cellar_key\"] } } }\n  ],\n  \"zones\": [ { \"id\": \"z_square\", \"shape\": \"sphere\", \"center\": [0, 0, 0], \"radius\": 10 } ],\n  \"data\":  { \"spawns\": [], \"npcs\": [] },\n  \"layers\": { \"world.lighting\": { \"preset\": \"golden_hour\" }, \"world.weather\": { \"mode\": \"clear\" } },\n  \"audio\": { \"music\": \"village\", \"ambience\": \"birds\" },\n  \"ui\":    { \"hud\": \"hud.open_world\", \"panels\": [] },\n  \"scripts\": [\"s_elder\", \"s_cellar_door\", \"s_chest\"]\n}\n```\n\n- **`world`** nomme le kit qui bâtit le sol et sa config pour cette scène, ou un document de sa collection, par\n  exemple `{ \"kit\": \"world.rooms\", \"doc\": \"run_crypt\" }` ou `{ \"kit\": \"world.terrain\", \"doc\": \"tm_…\" }`. Les\n  collections de niveau des kits (`rooms`, `race_tracks`, `platform_courses`, `terrain_maps`…) restent leur\n  format. La scène les **désigne**.\n- **`instances`** : un archétype, une position, un placement et des surcharges (`set`, fusion composant par\n  composant).\n- **`data`** : les sections des collections qu'un kit déclare « par scène » (§7.3), par exemple des `spawns`\n  ou des `npcs` qui n'existent que dans cette scène.\n- **`layers`** : la config par scène des kits de couche. On fusionne la config du kit puis celle de la scène,\n  clé par clé.\n- **Scène implicite.** Si `scenes` est vide, le moteur synthétise `{ id: 'main', implicit: true }`. Les kits\n  lisent alors leurs collections globales comme aujourd'hui. **Tout jeu existant est donc déjà un jeu à une\n  scène.**\n- **Scène native.** Sur un moteur, une scène faite à la main dans l'éditeur, avec des `GfEntity` posés, est\n  aussi une scène. Le document se réduit à `{ \"id\": \"crypt\", \"native\": \"res://levels/crypt.tscn\" }`, et les\n  instances sont les nœuds trouvés. Le registre de contenu les indexe en lecture seule.\n- **Sources d'une scène.**\n  1. Écrite par l'agent (`gripforge_game_content put`).\n  2. Importée d'une **carte du Scene Studio** (`SceneDocument`, `purpose: 'map'`) par\n     `gripforge_game_scene import`. Une instance d'asset avec `role` devient une instance. Une `SceneZone` donne\n     une entrée (`spawn`), une zone d'objectif (`objective`) ou une zone (`gameplay`). Un `SceneTerrain` donne un\n     monde `world.terrain` (cuisson existante `terrain.bakeKit`). Les lumières deviennent la couche\n     `world.lighting`.\n  3. Une **carte du studio terrain**, par le `PUT …/terrain-map` existant.\n  4. Le plan de `gripforge_level` : salles en mètres, chemin critique, apparitions. Il devient une scène\n     `world.rooms` avec ses entrées et ses apparitions.\n\n### 5.4 Histoire\n\n- **Quêtes = missions.** Le schéma `gripforge.mission/1` reste inchangé. Dans le vocabulaire des agents, on dit\n  « quête ». Dans les données, on garde `missions`.\n- **Dialogues** : `npc.dialogue`, inchangé. Un choix porte déjà `then: [actions]`.\n- **Drapeaux d'histoire** : des variables `story.<id>` déclarées dans la config de `game.engine`\n  (`story: { \"lantern_found\": false }`). Elles sont sauvées avec l'état du jeu. Les scripts les lisent avec\n  `{ \"var\": \"story.lantern_found\" … }`.\n- **`giver.npc`** sera enfin servi. Le lot C (§14.3) fait apparaître le repère de quête au-dessus du PNJ\n  donneur. D'ici là, le sucre `gives` du §6.2 compile le même effet.\n\n### 5.5 Interface déclarée\n\nL'interface reste dans les kits. Le contenu en **choisit** les morceaux, scène par scène :\n- `ui.hud` : le kit de HUD actif dans la scène. Un village sans combat n'affiche pas la barre de vie.\n- `ui.panels` : des panneaux propres au jeu, servis par `ui.webui` :\n\n  ```json\n  { \"id\": \"journal\", \"page\": \"webui/journal.html\", \"bind\": [\"story.*\", \"mission.*\"], \"open\": { \"action\": \"journal\" } }\n  ```\n\n- Les textes sont des clés `i18n.text`. L'apparence passe par `ui.theme`. Les touches viennent de `labelFor`.\n  Ce sont les règles existantes de la politique.\n- La déclaration des vues par les kits eux-mêmes (le sujet de la branche `gamekits-web-views`, absente) relève de\n  la phase 5. Tant qu'elle n'existe pas, la page de jeu garde ses composants codés en dur.\n\n### 5.6 Des assets qui se décrivent et se placent\n\nLe passeport est déjà « la monnaie » des studios (`docs/architecture-studios-outils.md` §3). `game.engine` y\najoute sa section, comme `render.lod` a `kits.lod` :\n\n```json\n\"kits\": {\n  \"engine\": {\n    \"role\": \"container\",\n    \"archetype\": \"chest_wood\",\n    \"placement\": { \"snap\": \"ground\", \"align\": \"upright\", \"footprint\": [1.1, 0.7], \"clearance\": 0.2 },\n    \"interaction\": { \"point\": \"lid_handle\", \"radius\": 1.6, \"verb\": \"open\" },\n    \"solid\": \"colliders.physics\",\n    \"clips\": { \"open\": \"Chest_Open\", \"close\": \"Chest_Close\" }\n  }\n}\n```\n\n**D'où vient chaque valeur.**\n\n| Valeur | Source |\n|---|---|\n| `footprint` | `etalon.size` (taille réelle) |\n| `align` et la face avant | `orientation` (`front`, `up`) |\n| `interaction.point` | un `landmark` (poignée, gond) |\n| `solid` | les `colliders` de rôle `physics` |\n| `clips` | `anim.clips` (`kind`) |\n| `role` et `archetype` | Proposés par une étape `ai` facultative d'un outil de studio, puis confirmés à la main. Ils peuvent manquer sans rien casser (§12). |\n\n**Effet.**\n- Un asset dont le passeport porte `kits.engine` peut être **déposé** directement :\n\n  ```json\n  gripforge_game_content { \"action\": \"place\", \"scene\": \"village\", \"asset\": \"lib_…\", \"at\": [-8, 0, 9] }\n  ```\n\n- Le moteur choisit l'archétype indiqué, ou en crée un depuis le rôle (`content:<lib id>`).\n- Il pose l'objet selon `snap`, l'oriente avec `orientation` et le rend solide avec ses colliders.\n- Si le rôle l'indique, il le rend interactif au bon point.\n\n**Placement cuit.** C'est le principe 6 du §1.2.\n- Le placement est résolu **à l'écriture**, pas à l'exécution : poser sur le sol, aligner, vérifier\n  l'emprise.\n- Il est écrit dans l'instance : `resolved: { p, yaw, basis }`, où `basis` est l'empreinte du monde et du\n  passeport.\n- Les quatre cibles lisent la même valeur cuite, ce qui évite les écarts de lancer de rayon entre moteurs.\n- Si `basis` ne correspond plus (monde modifié), la cible résout elle-même et le rapport émet un avertissement.\n  On n'est jamais bloqué.\n- La résolution qui lit un fichier (hauteurs d'une carte `.gftm`, maillage) est un **travail du service de\n  calcul** (`engine.place`, règles du `CLAUDE.md`). Le web garde le cache, le service rend des nombres.\n\n---\n\n**Lecture.** `kits.engine` est une section de passeport comme `kits.lod` : `asset.meta` la sert telle quelle\n(`section(ref, 'engine')`, corrections du projet fusionnées clé par clé) sans en connaître le schéma, qui appartient\nà `game.engine`. Le moteur ne requiert pas `asset.meta` ; il lit `asset_passports` à la demande avec la même\nrésolution (`assetMetaTable`, slot puis id Library). Sans `asset.meta`, seuls les documents écrits par le projet\nexistent : les passeports de la Bibliothèque voyagent avec lui.\n\n## 6 · Scripts d'interaction\n\n### 6.1 Le format\n\n```json\n{\n  \"schema\": \"gripforge.script/1\",\n  \"id\": \"s_cellar_door\",\n  \"on\": \"door_cellar\",\n  \"rules\": [\n    {\n      \"when\": { \"interact\": \"self\" },\n      \"if\":   [ { \"has_item\": \"cellar_key\" } ],\n      \"then\": [ { \"set_state\": { \"open\": true } }, { \"play_clip\": \"open\" }, { \"set_solid\": false }, { \"take_item\": \"cellar_key\" } ],\n      \"else\": [ { \"notify\": \"content.door.locked\" } ],\n      \"once\": true\n    }\n  ]\n}\n```\n\n- **`on`** donne la portée du script :\n  - une instance (`door_cellar`) ;\n  - un archétype (`archetype:door_wood` : chaque porte de ce modèle) ;\n  - une scène (`scene:village`) ;\n  - rien, pour un script global.\n- **`when`** reçoit les conditions existantes (`event`, `var`, `in_zone`, `has_tag`, `all`, `any`, `not`,\n  verbes de kits) et quelques **sucres** :\n\n  | Sucre | Se compile en |\n  |---|---|\n  | `{ \"interact\": \"self\" }` | `{ event: 'engine.interact', match: { instance: <id de l'instance> } }` (§17.2, point 1) |\n  | `{ \"enter\": \"z_square\" }` / `{ \"leave\": … }` | `zone.entered` / `zone.exited` |\n  | `{ \"scene\": \"entered\" }` | `engine.scene.entered` de la scène portante |\n  | `{ \"talked\": \"elder\", \"topic\": \"thanks\" }` | les événements de `npc.dialogue` |\n  | `{ \"quest\": \"q_lantern\", \"is\": \"completed\" }` | `mission.completed` (ou état de `mission.run`) |\n  | `{ \"state\": { \"open\": true } }` | état de l'instance (§6.4) |\n\n- **`if` / `then` / `else`** : actions existantes, verbes des kits, verbes du moteur (§6.3).\n- **`once`** joue la règle une seule fois par partie. C'est sauvé. (`if` + `else` : une seule règle, garde\n  évaluée une fois, §17.2 points 2 et 3.)\n\n### 6.2 Une seule machine : la compilation\n\n**Le format n'a pas de runtime propre.** Une fonction TypeScript pure (`compileScripts(content) →\nTriggerRule[]`) le transforme en règles `triggers.rules` ordinaires :\n- `self` est remplacé par l'id d'entité de l'instance ;\n- `else` devient une seconde règle sous `not` ;\n- `once` devient `once: true` plus la mémoire de `game.engine` ;\n- un sucre devient sa condition de base.\n\nLes règles compilées sont écrites dans `gameplay.json` pour les moteurs. Le web les compile au montage avec le\nmême code.\n\n**Conséquence : quasiment rien de neuf à porter par moteur.**\n- `GfTriggers` (Godot), `GfTriggers` (Unity) et `GfTriggers` (Unreal) exécutent déjà ces règles à l'identique,\n  avec des scénarios de conformité qui le prouvent.\n- Le port de `game.engine` se limite à la lecture du contenu, à l'apparition des instances, aux verbes du\n  moteur et à l'état des instances.\n\n**Sucre `gives`.** Un archétype ou une instance peut porter :\n\n```json\n\"gives\": { \"quest\": \"q_lantern\", \"offer\": \"d_elder_offer\", \"thanks\": \"d_elder_thanks\" }\n```\n\nIl se compile en :\n- un dialogue d'offre dont le choix « accepter » fait `start_mission` ;\n- un dialogue de remerciement quand la quête est finie ;\n- un repère au-dessus du PNJ tant que la quête est disponible.\n\nC'est exactement « ce PNJ donne cette quête », en une ligne, sur les kits existants.\n\n### 6.3 Les verbes\n\n| Verbe | Fourni par | Remarque |\n|---|---|---|\n| `set_var`, `inc_var`, `emit`, `spawn`, `despawn`, `notify`, `start_mission`, `complete_objective`, `fail_mission`, `teleport`, `wait` | hôte (existants) | inchangés |\n| `give_item`, `take_item`, `has_item` | `inventory.basic` (existants) | |\n| `add_money`, `spend_money`, `money_at_least` | `economy.money` (existants) | |\n| `damage`, `heal`, `apply_status`, `health_below` | `combat.core` (existants) | |\n| `adjust_reputation`, `reputation_at_least` | `faction.system` (existants) | |\n| `set_wanted`, `wanted_at_least` | `wanted.police` (existants) | |\n| `save_game` | `save.persistence` (existant) | |\n| `npc_state` | `npc.core` (existant) | |\n| `set_state`, `play_clip`, `set_solid`, `show`, `hide`, `enable_script`, `disable_script`, `load_scene`, `end_game` | **`game.engine`** (nouveaux) | Le minimum pour portes, coffres, leviers, transitions |\n| `start_dialogue` | **`npc.dialogue`** (nouveau, lot C) | Appelle le service `dialogue.lines.say` |\n| `call` | **`game.engine`** | `{ \"call\": \"mygame.unlock_secret\", \"args\": {} }` vers un service enregistré par du code du jeu (§10) |\n\n**Le registre des verbes passe par `engine.scripts`.**\n- Il prend un nom, un schéma d'arguments et un kit propriétaire. C'est ce qui alimente le catalogue des briques\n  (§8.2) et la validation.\n- `ctx.triggers.registerAction` / `registerCondition` restent des alias.\n- Les verbes déjà listés dans `extensions` sont repris automatiquement.\n\n### 6.4 État par instance et sauvegarde\n\n- Le composant `state` d'une instance est une table plate de valeurs JSON, définie dans l'archétype et surchargée\n  par l'instance.\n- `set_state` l'écrit. La condition `state` le lit.\n- La variable `instance.<id>.<clé>` le reflète, ce qui permet de l'afficher ou de le lier au HUD.\n- Il est sauvé deux fois, ce qui est voulu :\n  - dans les composants de l'entité, par la sérialisation existante ;\n  - dans la section `game.engine`, pour les instances des scènes non chargées.\n- **Les états qui changent l'apparence ou la collision** (`open` → clip `open` joué jusqu'à la fin, `solid`\n  retiré) sont **rejoués au chargement**. Une porte ouverte se recharge ouverte, sans revoir son animation.\n\n### 6.5 Les trois exemples demandés\n\n**« Ce PNJ donne cette quête »**\n\n```json\n{ \"schema\": \"gripforge.archetype/1\", \"id\": \"elder\", \"kind\": \"npc\", \"asset\": { \"slot\": \"npc_elder\" },\n  \"components\": { \"npc\": { \"doc\": \"npc_elder\" }, \"talk\": { \"topics\": [\"greet\"] } },\n  \"gives\": { \"quest\": \"q_lantern\", \"offer\": \"d_elder_offer\", \"thanks\": \"d_elder_thanks\" } }\n```\n\n```json\n{ \"id\": \"d_elder_offer\", \"npc\": \"npc_elder\", \"topic\": \"greet\",\n  \"lines\": [\"dlg.elder.offer.1\", \"dlg.elder.offer.2\"],\n  \"choices\": [ { \"id\": \"yes\", \"text\": \"dlg.elder.offer.yes\", \"then\": [ { \"start_mission\": \"q_lantern\" } ] },\n               { \"id\": \"no\",  \"text\": \"dlg.elder.offer.no\" } ] }\n```\n\n**« Cette porte s'ouvre quand… »** : le script `s_cellar_door` du §6.1.\n\n**« Ce coffre donne un objet, une fois »**\n\n```json\n{ \"schema\": \"gripforge.script/1\", \"id\": \"s_chest\", \"on\": \"chest_1\",\n  \"rules\": [ { \"when\": { \"interact\": \"self\" }, \"if\": [ { \"state\": { \"opened\": false } } ],\n               \"then\": [ { \"set_state\": { \"opened\": true } }, { \"play_clip\": \"open\" },\n                         { \"give_item\": \"cellar_key\" }, { \"notify\": \"content.chest.key_found\" } ],\n               \"once\": true } ] }\n```\n\n### 6.6 Relation avec les kits existants : construire dessus\n\n| Kit | Décision | Pourquoi |\n|---|---|---|\n| `mission.system` (`missions`, `triggers`, `mission.run`, `triggers.rules`) | **Réutilisé**, inchangé dans la tranche 1 | Les quêtes restent des missions. Les scripts compilés sont des `triggers`. |\n| Moteur de déclencheurs de l'hôte (`runtime/triggers.ts`, `GfTriggers`×3) | **Réutilisé** : l'exécuteur unique | Déjà porté et conforme sur les quatre cibles |\n| `npc.dialogue` | **Réutilisé**. Lot C : verbe `start_dialogue`, composant `talk` | Les dialogues et leurs choix `then` sont déjà des actions |\n| `interaction.system` | **Enveloppé**. Le moteur l'appelle par `interaction.use.register` (tranche 1), puis le kit revendique `interactable` (lot C) | Il garde la proximité, l'invite et la touche (`labelFor`) |\n| `npc.core` | **Réutilisé**. `kind: 'npc'` existe déjà. Lot C : composant `npc`, données par scène | |\n| `inventory.basic` | **Réutilisé**. Lot C : composants `container` et `pickup` | Ses verbes existent déjà |\n| `spawn.system` | **Réutilisé**. `game.engine` ajoute la fabrique `prop` | |\n\n**Rien n'est absorbé.**\n- `triggers.rules` est fourni aujourd'hui par `mission.system`, alors que l'exécuteur est dans l'hôte. Le\n  fournisseur pourrait devenir `game.engine` en phase 3 : c'est une question au propriétaire (§16).\n\n### 6.7 Parité des quatre cibles\n\nC'est la méthode des kits existants :\n1. Le modèle est écrit en TypeScript : la compilation des scripts, l'index et le rapport sont **purs**.\n2. Le petit runtime de `game.engine` est porté : `gf_engine.gd`, `GfEngine.cs`, `UGfEngineSubsystem`.\n3. Des scénarios de conformité (`qa/gameplay-engines/scenarios/engine-*.json`) comparent la trace web à chaque\n   moteur.\n\nLe format de scénario couvre déjà le besoin : `install`, `data` avec les collections `archetypes`, `scenes`,\n`scripts`, et les étapes `input`, `step`, `save`, `load` et `snapshot`.\n\n---\n\n## 7 · Le rattachement des kits\n\n### 7.1 La règle\n\n- **Le moteur compose les kits par leurs services. Un kit utilise le moteur quand il prend part à la\n  construction du jeu.**\n- `game.engine` est toujours présent dans un projet Game Kits. Un kit peut donc le requérir librement : il n'y a\n  aucun « mode sans moteur » à prouver.\n- La catégorie « indépendant » ne signifie pas « doit marcher sans `game.engine` ». Elle signifie « n'en\n  **utilise** rien ».\n\n### 7.2 Le critère\n\nUn kit est **dépendant** (`requires: ['game.engine@^1']`) s'il remplit au moins une de ces conditions :\n- (a) il apporte du **vocabulaire au contenu** : composants d'archétype, verbes de script, types d'étape de quête,\n  comportements de PNJ, sortes d'entités, sections de scène ;\n- (b) il **bâtit ou habille une scène** : monde, couche ;\n- (c) il **réagit au cycle de vie** du jeu ou des scènes : entrée, sortie, fin, rejouer ;\n- (d) il **affiche le contenu** du jeu : quête courante, repères des instances, carte de la scène.\n\nUn kit est **indépendant** (aucun changement, aucun `requires`) s'il est un **service pur** :\n- il ne lit ni ne déclare aucun contenu de jeu ;\n- il n'a besoin d'aucune scène ;\n- il a du sens hors d'une partie : réglages joueur, entrée, rendu, texte, thème, transport, physique, effets\n  réagissant à des événements, client hérité.\n\nUn indépendant **peut** lire un service du moteur à la demande (`ctx.services.get('engine.flow')`), comme on lit\n`ui.theme` aujourd'hui, sans le requérir.\n\n**Cas limites tranchés.**\n\n| Kit | Décision | Raison |\n|---|---|---|\n| `save.persistence` | **Dépendant** | Le `location` d'un emplacement est le titre de la scène courante. L'autosave sur changement de scène écoute `engine.scene.entered`. « Continuer » rouvre la scène sauvée par `engine.flow`. |\n| `ui.menu` | **Indépendant** | C'est la coquille du joueur : titre et options existent avant toute scène. Il émet `ui.menu.perform {action}`. C'est `game.engine` qui l'écoute, pas l'inverse. |\n| `ui.endscreen` | **Dépendant** | Le récapitulatif lit le parcours tenu par le moteur (temps par scène, quêtes finies). « Rejouer » appelle `engine.flow.restart()`, qui recharge la scène de départ au lieu de remettre seulement la phase à zéro. |\n| `fx.hit_flash`, `fx.ability_vfx` | **Indépendants** | Présentation pure, déclenchée par `combat.damaged` ou une capacité. Ni contenu, ni scène. |\n| `hud.open_world`, `hud.action`, `hud.minimap`, `hud.moba` | **Dépendants** | Ils montrent la quête courante, les repères des instances, les limites et le titre de la scène. La scène choisit quel HUD est actif (§5.5). |\n| `ui.prompts` | **Indépendant** | Il n'affiche que des invites de touches. Le contexte « interagir » vient de `interaction.system`. |\n| `asset.meta` | **Indépendant** | Service de données. `game.engine` ne le requiert pas : il lit la collection `asset_passports` à la demande (taille de `solid: passport`, résolue à la compilation et, sur le web, par le service quand il est là ; `kits.engine` à l'écriture, cuisson et `place`), avec les règles de fusion d'`asset.meta` (`assetMetaTable`). Les passeports de la Bibliothèque ne sont livrés qu'avec `asset.meta` installé. |\n| `audio.core` | **Indépendant** | La musique et l'ambiance par scène sont posées par `game.engine`, qui appelle le service `audio.core` (section `audio` de la scène). |\n| `input.actions` | **Indépendant** | C'est la porte d'entrée des intentions, utile sans moteur de contenu. |\n\n### 7.3 Le contrat d'un kit dépendant\n\n**1. Manifeste.**\n\n```ts\nrequires: [..., 'game.engine@^1'],\nengine: {\n  role: 'world' | 'layer' | 'content' | 'actor' | 'view' | 'flow',\n  components?: { [name]: { schema, description } },            // claimed archetype components\n  sceneCollections?: string[],                                  // own collections a scene may carry in `data`\n  sceneConfig?: string[],                                       // config keys a scene may override in `layers`\n  world?: { collection?: string },                              // a world kit: the document a scene names\n  entityKinds?: string[],                                       // spawn factories it registers\n}\n```\n\n- `extensions` (verbes, étapes, comportements) reste valable. `game.engine` le lit.\n- Tout est **déclaratif** : le validateur et le catalogue des briques s'en servent sans exécuter le kit.\n\n**2. Runtime.** `KitRuntime` reçoit des crochets **facultatifs** :\n\n```ts\nsceneEnter?(scene: SceneView): void   // build / load what belongs to this scene\nsceneExit?(scene: SceneView): void    // release it (entities of the scene are destroyed by the engine)\n```\n\n- Un kit sans crochets reste global : il traverse les changements de scène sans rien faire, ce qui est le\n  comportement actuel.\n- Les gestionnaires de composants s'enregistrent au `setup()` par\n  `ctx.services.get('engine.content').registerComponent(...)`.\n\n**3. Moteurs.** Les mêmes crochets existent dans `GfKit` :\n- Godot : `gf_scene_enter(scene)` / `gf_scene_exit(scene)` ;\n- Unity : `OnGfSceneEnter` / `OnGfSceneExit` ;\n- Unreal : `OnGfSceneEnter` / `OnGfSceneExit`.\n\nIls ont des implémentations vides par défaut.\n\n**4. Comportement constant en scène implicite.** Avec la seule scène implicite, un kit dépendant doit produire\n**exactement** la trace d'avant. Ses scénarios de conformité, rejoués avec `game.engine`, en sont la preuve.\n\n### 7.4 Classement des 83 kits\n\n**Rôles des dépendants.**\n- `world` : bâtit le monde d'une scène.\n- `layer` : habille une scène.\n- `content` : apporte composants, verbes, étapes ou données de scène.\n- `actor` : place le joueur ou des acteurs aux entrées.\n- `view` : affiche le contenu.\n- `flow` : cycle de vie et sauvegarde.\n\n**Lots** : voir §14.3.\n\n| Kit | Classe | Ce qu'il apporte au moteur | Ce qui change dans le kit | Lot |\n|---|---|---|---|---|\n| `game.engine` | moteur | — | nouveau | T1 |\n| `world.terrain` | dépendant · world | monde d'une scène (`doc` = `terrain_maps`, ou config) | `sceneEnter` reconstruit le terrain de la scène ; entrées depuis les points d'apparition de la carte cuite : reste à faire (contrat suivant) | B |\n| `world.streaming` | dépendant · layer | segments du monde de la scène courante | remise à zéro des segments sur changement de scène | B |\n| `world.city_block` | dépendant · world | sol, routes et zones d'une scène | `sceneEnter` ; zones par défaut comme entrées : reste à faire (contrat suivant) | B |\n| `world.district` | dépendant · world | idem (`zones`, bâtiments) | idem | B |\n| `world.rooms` | dépendant · world | une course de salles est une scène (`doc` = `runs`) | `sceneEnter` ; portes vers `load_scene` possibles | B |\n| `world.platforms` | dépendant · world | parcours (`platform_courses`) | `sceneEnter` ; points de reprise comme entrées : reste à faire (contrat suivant) | B |\n| `world.racetrack` | dépendant · world | circuit (`race_tracks`) | `sceneEnter` ; grille de départ comme entrées : reste à faire (contrat suivant) | B |\n| `world.lighting` | dépendant · layer | `layers['world.lighting']`, `world_lights` par scène | `sceneConfig` + `sceneCollections` | B |\n| `world.weather` | dépendant · layer | météo par scène, `warmth_sources` | idem | B |\n| `world.water` | dépendant · layer | `water_bodies` par scène | idem | B |\n| `world.fluids` | dépendant · layer | `fluid_surfaces` par scène | idem ; état des surfaces par scène dans sa sauvegarde | B |\n| `world.tracks` | dépendant · layer | traces par scène | état par scène | B |\n| `world.scenery` | dépendant · layer | habillage du sol de la scène | `sceneEnter` (graine par scène) | B |\n| `world.elements` | dépendant · content | composant `material` (bois, métal…), `element_climates` par scène | revendique `material` ; climats par scène | B |\n| `spawn.system` | dépendant · content | `spawns` par scène ; fabriques de sortes | `sceneCollections: ['spawns']` ; despawn à la sortie | C |\n| `npc.core` | dépendant · content | composant `npc` ; `npcs` par scène | revendique `npc` ; `sceneCollections` | C |\n| `ai.navigation` | dépendant · service | chemins de la scène (géométrie de collision du port physique, sol `world.ground`) | écoute `engine.scene.entered` / `engine.scene.leaving` (cuisson remise à zéro) ; hook `navigation.plan` (but, gabarit, approche ; annulable), event `navigation.blocked` ; moddable `cellSize`, `padding`, `ground`, `approach`, `smooth`, `retrySeconds`, `agent` ; chemins suivis sauvés | C |\n| `npc.dialogue` | dépendant · content | composant `talk` ; verbe `start_dialogue` ; condition `talked` | revendique `talk` (gestionnaire : PNJ et sujet de `InstanceView.talk`) ; nouvelle action `start_dialogue` | C |\n| `npc.pedestrian` | dépendant · layer | foule ambiante de la scène | `sceneConfig` : `count`, `fleeRadius` ; `sceneEnter` / `sceneExit` | E |\n| `interaction.system` | dépendant · content | composant `interactable` | revendique le composant (le moteur cesse d'appeler `register` lui-même) | C |\n| `mission.system` | dépendant · content | quêtes ; étapes ; `giver.npc` servi ; repères par scène | `giver.npc` ; repères limités à la scène ; zones de scène | C |\n| `inventory.basic` | dépendant · content | composants `container`, `pickup` | revendique les composants | C |\n| `encounters.waves` | dépendant · content | rencontres d'une scène (`data.encounters`), points `encounter_spawn` | `sceneCollections: ['encounters']` ; `sceneEnter` / `sceneExit` ; verbe `start_encounter` | D |\n| `faction.system` | dépendant · content | composant `faction` étendu (relations par archétype) | déclare son vocabulaire | C |\n| `economy.money` | dépendant · content | verbes existants avec schémas | verbes enregistrés via `engine.scripts` | C |\n| `character.third_person` | dépendant · actor | joueur posé à l'entrée de scène ; l'instance `player` d'une scène est le joueur | `sceneEnter` (entrée, pas au chargement ni en voiture) ; fabrique `player` qui prête le personnage vivant | G |\n| `character.top_down` | dépendant · actor | idem | idem | G |\n| `character.platformer` | dépendant · actor | idem (la reprise de parcours reste à `world.platforms`, lot B) | idem ; fabrique `player` seulement avec du contenu moteur | G |\n| `movement.dash` | dépendant · content | composant `dash` sur l'archétype du joueur (distance, durée, charges, recharge, invulnérabilité, délai) | revendique `dash` ; réglage gardé sur l'entité (`dash.tuning`) | G |\n| `movement.traversal` | dépendant · content | composant `traversal` (interrupteurs, endurance) sur l'archétype du joueur ; composant `climbable: false` sur toute instance | revendique les deux ; lâche la paroi à la sortie de scène | G |\n| `combat.core` | dépendant · content | composant `combat` (vie, équipe, statuts d'une instance) ; verbes `damage`, `heal`, `apply_status`, `health_below` (argument `instance`) | revendique `combat` ; verbes déclarés | D |\n| `combat.melee` | dépendant · content | composant `melee` (la frappe d'une instance) ; verbe `strike` | revendique `melee` ; verbe `strike` | D |\n| `combat.ranged` | dépendant · content | composant `ranged` (dégâts de l'arme d'une instance) ; verbes `fire`, `reload` | revendique `ranged` ; verbes | D |\n| `combat.projectiles` | dépendant · content | verbe `projectile.launch` avec schéma (argument `instance`) | verbe déclaré | D |\n| `combat.abilities` | dépendant · content | composant `abilities` (ressources de départ) ; verbe `use_ability` | revendique `abilities` ; verbe | D |\n| `combat.duel` | dépendant · world | l'arène est une scène ; combattants aux entrées first / second | `sceneEnter` ; manifeste rattaché à l'intégration (ports moteur de `game.engine` livrés) | F |\n| `weapons.loadout` | dépendant · content | composant `loadout` (arme de l'instance joueur) ; verbe `equip_weapon` | revendique `loadout` ; verbe | D |\n| `upgrades.boons` | dépendant · content | offres comme récompenses du contenu | verbes `offer_boon`, `grant_boon`, condition `has_boon` | D |\n| `enemy.ai` | dépendant · content | sorte `enemy` ; composant `enemy { def }` | fabrique `enemy` (contenu moteur seulement) ; revendique `enemy` | D |\n| `enemy.boss` | dépendant · content | composant `boss { doc }` sur une instance ennemie | revendique `boss` | D |\n| `vehicle.driveable` | dépendant · content | sorte `vehicle` ; composant `vehicle` (santé, boost de départ) | revendique `vehicle` ; `entityKinds: ['vehicle']` (pas de `sceneCollections` : les apparitions sont les instances ou les `spawns`) | E |\n| `vehicle.enter_exit` | dépendant · content | composant `seat` (`owned`, `access`) | revendique `seat` | E |\n| `vehicle.doors` | dépendant · content | composant `doors` ; verbe `set_door` ; portières dans l'état d'instance (`door_fl` … `door_rr`) | revendique `doors` ; verbe | E |\n| `vehicle.damage` | dépendant · content | composant `damage_model` (`health`, `collisionScale`, `explode`) | revendique `damage_model` | E |\n| `traffic.system` | dépendant · layer | trafic ambiant de la scène | `sceneConfig` : `density`, `speed`, `obeySignals` ; `sceneEnter` / `sceneExit` | E |\n| `wanted.police` | dépendant · content | verbes `set_wanted`, `wanted_at_least` ; zones de police = zones de scène étiquetées `police` | verbes déclarés ; `sceneConfig` : `heat`, `spawnPerLevel`, `decaySeconds` ; `sceneEnter` / `sceneExit` | E |\n| `race.kart` | dépendant · actor | course de la scène (la grille reste celle du circuit de `world.racetrack`) | `sceneConfig` : `countdown`, `difficulty` ; `sceneEnter` / `sceneExit` | E |\n| `moba.lanes` | dépendant · world | carte de voies = scène ; entrées `blue` / `red` = apparitions | monde de la scène de départ ; une scène suivante ne change pas de carte | F |\n| `moba.hero` | dépendant · actor | héros posé au point d'apparition de son équipe | `sceneEnter` d'une scène de voies : ordres et rappel annulés, mana rendue | F |\n| `minion.waves` | dépendant · content | `minion_routes` par scène | `sceneCollections: ['minion_routes']` ; `sceneEnter` (vagues remises à zéro) / `sceneExit` (sbires retirés) | F |\n| `fps.tactical` | dépendant · world | `tactical_maps` = scène | `sceneEnter`, monde sauvé ; manifeste rattaché à l'intégration ; sites et apparitions comme entrées : reste à faire (contrat suivant) | F |\n| `hud.open_world` | dépendant · view | quête courante (repères `quest_available` de la scène), titre de scène | `sceneEnter` : HUD actif si `ui.hud` le nomme ou est absent ; `sceneConfig: ['show']` ; `hud.bind.markers()`, `hud.active`, `hud.scene`, `hud.markers` | A |\n| `hud.action` | dépendant · view | salle de la scène, titre | `sceneEnter` : HUD par scène, `sceneConfig: ['show']`, une scène = une salle (toast des portes) | A |\n| `hud.minimap` | dépendant · view | composant `map_marker`, `minimap_layers` par scène, repères de quête | revendique `map_marker` ; `sceneCollections: ['minimap_layers']` ; `sceneConfig` : visible, mode, orientation, shape, zoom, range | A |\n| `hud.tactical` | dépendant · view | — (un HUD pour toute la partie) | aucun : `document()` lit la config (document HUD Studio v2, `themeId`), sauvé ; moddable `themeId`, `document` ; pas de scène, pas de hook (aucune décision) | A |\n| `hud.moba` | dépendant · view | HUD de la scène de voies | `sceneConfig: ['show']` ; `ui.hud` d'une autre interface masque tout | F |\n| `ui.endscreen` | dépendant · flow | fin du flux (`engine.flow.ended`), récapitulatif lieux / quêtes, rejouer | Rejouer → `engine.flow.restart()` ; `engine.flow.restarted` remet le compte à zéro | A |\n| `save.persistence` | dépendant · flow | lieu = titre de scène, autosave sur changement de scène, verbe `save_game` | déclencheur `scene` (défaut des nouveaux jeux) ; `engine.verbs.save_game` | A |\n| `ui.menu` | indépendant | — (le moteur écoute `ui.menu.perform`) | aucun | — |\n| `ui.prompts` | indépendant | — | aucun | — |\n| `ui.theme` | indépendant | — | aucun | — |\n| `ui.cursor` | indépendant | — | aucun | — |\n| `ui.webui` | indépendant | hôte des panneaux déclarés (§5.5), lu par le moteur | aucun dans la tranche ; phase 5 : lit `ui.panels` à la demande | — |\n| `settings.graphics` | indépendant | — | aucun | — |\n| `input.actions` | indépendant | — | aucun | — |\n| `input.remap` | indépendant | — | aucun | — |\n| `input.virtualpad` | indépendant (kit par défaut depuis l'intégration) | — | aucun | — |\n| `audio.core` | indépendant | — (le moteur appelle son service) | aucun | — |\n| `i18n.text` | indépendant | — | aucun | — |\n| `render.lod` | indépendant | — | aucun | — |\n| `asset.meta` | indépendant | — (lu à la demande pour `kits.engine`) | aucun | — |\n| `fx.hit_flash` | indépendant | — | aucun | — |\n| `fx.ability_vfx` | indépendant | — | aucun | — |\n| `physics.port` | indépendant | — | aucun | — |\n| `net.transport` | indépendant | — | aucun | — |\n| `net.claim` | indépendant | — | aucun | — |\n| `net.authoritative` | indépendant | — | aucun | — |\n| `net.rollback` | indépendant | — | aucun | — |\n| `net.state` | indépendant | — | aucun | — |\n| `net.async` | indépendant | — | aucun | — |\n| `net.physics` | indépendant | — | aucun | — |\n| `legacy.fps_tactical` | indépendant (client hérité) | — | aucun ; hors `KitHost` | — |\n| `legacy.kart` | indépendant (client hérité) | — | aucun | — |\n| `legacy.royale` | indépendant (client hérité) | — | aucun | — |\n| `legacy.rules_engine` | indépendant (client hérité) | — | aucun | — |\n\n**Totaux.**\n- 56 kits dépendants, plus `game.engine`.\n- 27 kits indépendants, soit 23 services purs et 4 clients hérités.\n- 56 + 27 = 83.\n\nCe classement rejoint la liste provisoire transmise au propriétaire. Les cas limites sont tranchés au §7.2.\n\nLes kits réseau sont indépendants : le moteur ne leur demande rien. Pour eux, une instance d'archétype est une\nentité comme une autre, à répliquer, et un changement de scène est un événement du bus.\n\n### 7.5 Versionnement\n\n- **Le contrat est la capacité `game.engine`, en semver.**\n  - Une version **mineure** ajoute : un verbe, un sucre, un crochet facultatif, une clé de scène.\n  - Une version **majeure** casse : un champ renommé, un crochet devenu obligatoire.\n- Un kit dépendant passe en **version mineure** quand il ajoute `requires: ['game.engine@^1']`. Le manifeste\n  précédent est gelé dans `manifest-<version>.ts`, ce qui est la règle existante.\n- La politique « toujours la dernière version » s'applique. Une version majeure de `game.engine` sort avec les\n  versions des kits qui la suivent, dans une seule publication du catalogue. Les migrations manuelles deviennent\n  des tâches `migration_manual`.\n- **Formats** : `gripforge.archetype/1`, `gripforge.scene/1` et `gripforge.script/1`. Les lectures acceptent\n  les versions précédentes et réécrivent à l'écriture suivante, comme `gripforge.slot/1` → `/2`.\n\n### 7.6 Migration des jeux existants\n\nDes jeux vivent en production. **Invariant absolu : un projet existant joue exactement comme avant.**\n\n**Mécanisme.**\n1. **Installation automatique à l'ouverture.** `autoUpdateProject` gagne une étape, `ensureEngine` :\n   - si le projet n'est pas hérité, n'a pas `game.engine` et ne porte pas `doc.removed['game.engine']`, elle\n     appelle `resolveInstall(game.engine)` avec la source `default` ;\n   - la révision s'appelle `gamekits:auto-update — engine`.\n\n   C'est une exception explicite à « Existing projects are never changed automatically » (`BASE_KITS`). Elle se\n   justifie parce que le mode transparent ne change aucun comportement. Le même résultat arrive de toute façon\n   quand un kit installé passe à une version qui le requiert : le résolveur ajoute le fournisseur.\n2. **Mode transparent** (§3.1). Pas de contenu moteur donc scène implicite, aucune entité, aucune règle et aucun\n   événement de plus.\n3. **Ordre de montage inchangé.** C'est le point le plus fin.\n   - Le lockfile ordonne les kits par Kahn, avec départage par id. Ajouter des arêtes vers `game.engine`\n     pourrait réordonner les autres kits, donc l'ordre des abonnés au bus et des `update`, donc les traces.\n   - Règle : **`game.engine` est monté en tête, hors tri.** L'ordre des autres se calcule en ignorant les arêtes\n     vers lui.\n   - Il est satisfait par construction, donc l'ordre des autres kits est identique à celui d'avant.\n4. **Sauvegardes.**\n   - Une sauvegarde faite sous l'ancien lock se charge avec `migrated: true`, comme pour toute mise à jour.\n   - En mode `compatibility: strict`, une sauvegarde d'un autre lock est refusée. La comparaison de lock\n     **ignore donc `game.engine` en mode transparent**, sinon les jeux stricts perdraient leurs sauvegardes.\n     C'est une question au propriétaire (§16).\n5. **Jeux livrés aux moteurs.**\n   - La livraison suivante ajoute les fichiers de `game.engine`, gérés, sous `gripforge/kits/game.engine/` et\n     leurs équivalents, et met à jour le cœur.\n   - Les scènes de l'utilisateur ne sont pas touchées.\n   - Un jeu livré qui n'est pas relivré continue de tourner sur ses fichiers.\n   - Proposition : la livraison de `game.engine` est **gratuite**, hors du crédit par version majeure de kit.\n6. **Projets hérités** (`legacy.*`, `doc.legacy`) : non touchés.\n\n**Ordre de mise en œuvre (strict).**\n1. Les ports moteur de `game.engine` existent, au moins en transparent, sur les quatre cibles.\n2. Ensuite seulement, un kit peut le requérir. Sinon, sa livraison moteur tomberait en `target_unsupported`.\n\n**Preuve avant activation de `ensureEngine` (phase 2).**\n- Tous les scénarios `qa/gameplay-engines/scenarios/*.json` sont rejoués **avec** `game.engine` et donnent des\n  traces identiques, à l'octet, à celles d'avant, sur les quatre cibles.\n- `qa:gamekits:full-slice` rejoue la mission de démonstration à l'identique.\n- `qa:save-slots`, y compris `legacy-1.0.0.json`, passe.\n- `qa:gamekits:delivery` : plans déterministes, avec `game.engine` ajouté.\n- Un échantillon de projets de production, en lecture seule, ouverts sur une copie : `autoUpdateProject` donne\n  le bon plan et un lockfile valide.\n\n---\n\n## 8 · Ce que `game.engine` donne à l'IA\n\nLa structure et les briques sont **la voie recommandée et le défaut**. Ce n'est jamais une barrière (§8.6).\n\n### 8.1 L'arborescence canonique d'un jeu\n\n```\ngame (gkp_…)                                  ← l'instance du moteur\n├── engine        game.engine : startScene, flow, story vars       (installed[0], config)\n├── kits          les mécaniques choisies (preset / composition)    (installed[])\n├── content\n│   ├── assets      slots liés + passeports                         (bindings, asset_passports)\n│   ├── archetypes  gabarits d'entités                              (archetypes)\n│   ├── scenes      niveaux, entrées, instances, couches, HUD       (scenes)\n│   ├── story       quêtes, dialogues, PNJ, objets, drapeaux        (missions, dialogues, npcs, items, story.*)\n│   ├── scripts     interactions                                    (scripts, triggers)\n│   └── ui          textes, thème, panneaux                         (translations, ui.theme, scene.ui)\n└── code          ce que le contenu ne couvre pas                   (code_modules + fichiers, §10)\n```\n\nC'est une **vue** sur le document de projet existant. Rien n'est déplacé.\n\n### 8.2 Le catalogue des briques\n\nLe catalogue est servi par `gripforge_game_engine {action:'blocks'}` et `GET …/engine/blocks`. Il est **calculé**\ndepuis les manifestes du catalogue et ceux des kits installés, donc il est toujours à jour.\n\n| Rubrique | Contenu | Source |\n|---|---|---|\n| Sortes d'entités | `player`, `npc`, `vehicle`, `prop`, et celles des modules de code | `engine.entityKinds`, fabriques |\n| Composants | nom, schéma, kit, exemple | `engine.components` |\n| Verbes | conditions et actions : nom, arguments, kit, exemple | `extensions` + `engine.scripts` |\n| Sucres de script | `interact`, `enter`, `talked`, `quest`, `state`, `gives` | `game.engine` |\n| Étapes de quête | `go_to`, `interact`, `talk_to`, `enter_vehicle`… | `extensions.missionSteps` |\n| Comportements de PNJ | `idle`, `patrol`, `chase`, `hunt`… | `extensions.npcBehaviors` |\n| Mondes | les kits `world`, leur document et leurs `entries` | `engine.world` |\n| Couches | clés surchargeables par scène | `engine.sceneConfig` |\n| Événements et variables | sujets émis, variables liables au HUD | `events`, `vars` |\n| Rôles d'asset | rôles de `kits.engine`, slots | passeports, `assets` |\n\n**Filtres** : `installed` (par défaut) ou `catalog`. Avec `catalog`, chaque brique non installée porte « installer\n`<kit>` ».\n\n### 8.3 L'ordre de construction recommandé\n\n| # | Étape | Outil | Vérification |\n|---|---|---|---|\n| 1 | Créer l'instance du moteur : cible confirmée, preset ou composition | `gripforge_game_project create` | paquet de départ (§8.4) |\n| 2 | Poser le squelette : une scène, son monde, une entrée | `gripforge_game_content put scene` ou `gripforge_game_scene import` | rapport : scène jouable |\n| 3 | Rendre jouable tout de suite (personnage, caméra) | `gripforge_game_play_url` | la scène se joue |\n| 4 | Assets : chercher, cloner, générer ; passeports | `gripforge_asset_search`, `…_clone`, génération (politique existante) | slots liés, passeports présents |\n| 5 | Archétypes et placement | `gripforge_game_content put archetype` / `place` | rapport : aucun composant orphelin |\n| 6 | Histoire : quêtes, dialogues, PNJ, objets, drapeaux | `gripforge_game_content put mission\\|dialogue\\|npc\\|item` | rapport : références résolues |\n| 7 | Scripts d'interaction | `gripforge_game_content put script` | rapport : verbes connus |\n| 8 | Interface : textes (deux langues au moins), thème, HUD par scène | `gripforge_game_content put translations`, `gripforge_gamekit_configure ui.theme` | `missing()` d'`i18n.text` vide |\n| 9 | Valider, jouer, capturer, juger | `gripforge_game_engine report`, `gripforge_game_play_url`, `gripforge game-check` | politique existante (capture, verdict) |\n| 10 | Livrer au moteur choisi | `gripforge_gamekit_deliver(_local)` | fumée moteur |\n| 11 | Code propre, seulement pour ce que le contenu ne couvre pas | fichiers + `code_modules` (§10) | rapport : verbes déclarés |\n\n### 8.4 Ce qu'un agent reçoit au démarrage\n\n`gripforge_game_project create` (inchangé dans ses entrées) renvoie en plus un bloc `engine`, aussi lisible par\n`gripforge_game_engine {action:'start'}` :\n\n```json\n{\n  \"engine\": {\n    \"version\": \"1.0.0\",\n    \"structure\": { \"engine\": \"installed[0]\", \"kits\": 14, \"content\": { \"archetypes\": 0, \"scenes\": 0, \"scripts\": 0, \"missions\": 0, \"dialogues\": 0 }, \"code\": [] },\n    \"scene\": { \"id\": \"main\", \"implicit\": true },\n    \"target\": \"godot\",\n    \"blocks\": { \"url\": \"/api/v1/gamekit-projects/gkp_…/engine/blocks\", \"digest\": { \"entityKinds\": [\"player\", \"npc\", \"prop\"], \"components\": [\"interactable\", \"npc\", \"talk\", \"container\", \"pickup\", \"state\", \"solid\"], \"verbs\": 31, \"steps\": [\"go_to\", \"interact\", \"talk_to\", \"wait\", \"event\", \"escape_zone\"] } },\n    \"order\": [\"scene\", \"playable\", \"assets\", \"archetypes\", \"story\", \"scripts\", \"ui\", \"validate\", \"deliver\", \"code\"],\n    \"next\": [\n      { \"step\": \"scene\", \"tool\": \"gripforge_game_content\", \"args\": { \"action\": \"put\", \"kind\": \"scene\", \"doc\": { \"id\": \"start\", \"world\": { \"kit\": \"world.terrain\" }, \"entries\": [{ \"id\": \"start\", \"at\": [0, 0, 0] }] } } }\n    ],\n    \"code\": { \"godot\": \"res://game/ (GfKit nodes, registered in code_modules)\", \"web\": \"custom Three.js app with the CLI (hosted play page runs catalogue kits only, §10)\" },\n    \"rules\": \"Content first, kits second, code for the rest. Never remove game.engine unless the user explicitly asks.\"\n  }\n}\n```\n\n### 8.5 Politique CLI, SKILL.md, manifeste de production\n\n- **`GAME_POLICY_VERSION`** passe à `3d-production-v8` (`packages/grip-forge/src/game-policy.ts`). On ajoute\n  quatre puces, en anglais comme le reste :\n  1. « A game is an engine instance plus content. Create the Game Kit project (game.engine comes first by\n     default), read the `engine` start pack, then drop content in the recommended order: scene → playable →\n     assets → archetypes → story → scripts → UI → validate → deliver. Prefer content and kit configuration over\n     engine code. »\n  2. « Interactions (\"this NPC gives this quest\", doors, chests, levers) are `scripts` documents and `gives`\n     declarations, not game code, unless the content model cannot express them. »\n  3. « Custom code is allowed and normal for what content cannot express: put it where the start pack says,\n     declare what it registers in `code_modules`, and call it from scripts with `call` or its own verbs. »\n  4. « Never remove or disable game.engine unless the user explicitly asks; a removal lists its dependents and\n     needs `with_dependents` and `confirm`. »\n- **`templates/SKILL.md`** reçoit les mêmes quatre puces, en plus court.\n- **`gripforge.production.json`** gagne un bloc facultatif :\n\n  ```json\n  \"engine\": { \"projectId\": \"gkp_…\", \"scenes\": [\"village\"], \"report\": { \"errors\": 0, \"warnings\": 2 } }\n  ```\n\n- **`gripforge game-check`** lit le rapport de contenu s'il est présent. Une erreur de contenu devient une\n  vérification `content` échouée, au même titre qu'un asset manquant. Un avertissement reste informatif.\n- **`REUSE_FIRST_RULE`** ne change pas : le contenu et les kits passent avant le code. C'est déjà la règle.\n\n### 8.6 Pas de barrière\n\n- Aucun outil ne refuse un appel parce que le jeu ne suit pas la structure. Un projet sans scène, sans\n  archétype, avec tout en code, est valide.\n- Le rapport de contenu n'est **jamais** une condition d'écriture. Seuls les schémas des documents le sont,\n  comme aujourd'hui.\n- Le paquet de départ propose l'étape suivante (`next`). Il ne l'impose pas.\n- `game-check` signale. Il ne bloque que ce qu'il bloque déjà : preuves périmées, assets absents.\n\n---\n\n## 9 · CLI et MCP\n\n### 9.1 Outils\n\n| Outil | Changement |\n|---|---|\n| `gripforge_game_project create` | Installe `game.engine` en tête des kits de base. Renvoie le bloc `engine` (§8.4). Entrées inchangées. Un interrupteur `{ \"game.engine\": false }` reste possible, explicite ; les kits qui le requièrent sont alors écartés et listés dans `dropped`. |\n| **`gripforge_game_engine`** (nouveau, lecture seule) | `action: start \\| structure \\| blocks \\| report \\| next`, `project_id`, `scope: installed\\|catalog`, `scene?` |\n| **`gripforge_game_content`** (nouveau) | `action: list \\| get \\| put \\| remove \\| place \\| validate`, `kind: archetype \\| scene \\| script \\| mission \\| dialogue \\| npc \\| item \\| translations \\| code_module`, `id`, `doc`, `dry_run`. Mince couche sur `PATCH …/data` qui choisit la collection selon `kind` et renvoie le rapport à jour. `place` : `{ scene, archetype \\| asset, at, yaw?, place? }`, avec le placement cuit. |\n| **`gripforge_game_scene`** (nouveau) | `action: import \\| bake`. `import` prend une `scene` du Scene Studio ou un plan `gripforge_level` (`plan`), et `gripforge_terrain_map_use` reste pour les cartes du studio terrain. `bake` recalcule les placements périmés. |\n| `gripforge_game_play_url` | Paramètre `scene` et `entry` (démarrer dans une scène) |\n| `gripforge_gamekit_install` | Le résultat liste les kits **ajoutés** pour satisfaire les dépendances (§9.3) |\n| `gripforge_gamekit_remove` | Gagne `dry_run`, `with_dependents` et `confirm` (§9.3) |\n| `gripforge_gamekit_configure` | `enabled: false` sur `game.engine` suit la même confirmation que le retrait |\n| `gripforge_gamekit_deliver(_local)` | Livre `game.engine` et le contenu dans `gameplay.json` (règles compilées, instances cuites). Par liste de kits, résout les dépendances (§9.3). |\n| `gripforge_game_creation` (création guidée) | Le planificateur produit aussi un **plan de contenu** (scènes, archétypes, quêtes, scripts) à côté de la composition de kits. Le montage les dépose. |\n| `gripforge_kit` (ancien, GameRules) | Description reprise : « kits Library hérités (document GameRules) » — plus « a game kit IS an engine » |\n\n**Routes HTTP** (mêmes conventions que `docs/gamekits.md`) :\n- `GET /api/v1/gamekit-projects/{id}/engine` : structure, rapport et `next`.\n- `GET /api/v1/gamekit-projects/{id}/engine/blocks?scope=` : le catalogue des briques.\n- `POST /api/v1/gamekit-projects/{id}/content/place` : poser une instance.\n- `POST /api/v1/gamekit-projects/{id}/scenes/import` : importer une scène.\n- Les écritures de contenu passent par `PATCH …/data`, qui existe déjà.\n- La cuisson de placement qui lit un fichier est un travail du service de calcul (`engine.place`), suivant la\n  règle 3 du `CLAUDE.md` : implémentation dans `worker.mjs`, nom dans `TRAVAUX_CONNUS`, contrat dans\n  `contract.ts`, cas dans `qa/compute-check.mjs`.\n\n**CLI `gripforge`.** Le CLI ne gère pas les kits directement : ses agents passent par le MCP. Seuls changent la\npolitique (§8.5) et `game-check`.\n\n### 9.2 Le parcours complet : un petit jeu d'aventure\n\n**Demande** : « un petit jeu d'aventure sous Godot : un village, un ancien qui demande de retrouver une lanterne\ndans la cave, une porte de cave fermée à clé, un coffre qui contient la clé ».\n\n**1. Créer l'instance du moteur**\n\n```json\ngripforge_game_project { \"action\": \"create\", \"name\": \"Village Lantern\", \"target\": \"godot\",\n  \"kits\": { \"input.actions\": true, \"spawn.system\": true, \"world.terrain\": true, \"character.third_person\": true,\n            \"interaction.system\": true, \"npc.core\": true, \"npc.dialogue\": true, \"mission.system\": true,\n            \"inventory.basic\": true, \"hud.open_world\": true } }\n```\n\n`game.engine` et les kits de base sont installés d'office. Les fournisseurs manquants arrivent tout seuls, par\nexemple `physics.port`. La réponse porte le bloc `engine` et la liste `added`.\n\n**2. Le squelette.** On dépose la scène `village` du §5.3, avec un monde `world.terrain` (graine) et l'entrée\n`start` :\n\n```json\ngripforge_game_content { \"action\": \"put\", \"kind\": \"scene\", \"doc\": { \"id\": \"village\", \"world\": { \"kit\": \"world.terrain\", \"config\": { \"size\": 160, \"seed\": 7 } }, \"entries\": [{ \"id\": \"start\", \"at\": [0, 0, 0] }] } }\ngripforge_gamekit_configure { \"id\": \"game.engine\", \"config\": { \"startScene\": \"village\" } }\ngripforge_game_play_url {}          // already playable: terrain + character\n```\n\n**3. Les assets.** `gripforge_asset_search` (espace de travail et Community), clonage, et génération si nécessaire\navec devis et budget, selon la politique existante. Quatre rôles : ancien (personnage animé), porte, coffre,\nlanterne. Les passeports viennent avec la Library et remplissent `asset_passports`.\n\n**4. Les archétypes et le placement.** Les archétypes `elder` (§6.5), `door_wood`, `chest_wood` (§5.2) et\n`lantern` :\n\n```json\n{ \"id\": \"lantern\", \"kind\": \"prop\", \"asset\": { \"item\": \"lib_…\" }, \"components\": { \"pickup\": { \"item\": \"lantern\" } } }\n```\n\nPuis le placement :\n\n```json\ngripforge_game_content { \"action\": \"place\", \"scene\": \"village\", \"archetype\": \"elder\", \"at\": [4, 0, 6], \"yaw\": 3.1 }\ngripforge_game_content { \"action\": \"place\", \"scene\": \"village\", \"archetype\": \"door_wood\", \"at\": [12, 0, -3], \"id\": \"door_cellar\" }\ngripforge_game_content { \"action\": \"place\", \"scene\": \"village\", \"archetype\": \"chest_wood\", \"at\": [-8, 0, 9], \"id\": \"chest_1\" }\ngripforge_game_content { \"action\": \"place\", \"scene\": \"village\", \"archetype\": \"lantern\", \"at\": [14, -2, -6], \"id\": \"lantern_1\" }\n```\n\n**5. L'histoire.**\n\n```json\ngripforge_game_content { \"action\": \"put\", \"kind\": \"item\", \"doc\": { \"id\": \"cellar_key\", \"name\": \"item.cellar_key\" } }\ngripforge_game_content { \"action\": \"put\", \"kind\": \"item\", \"doc\": { \"id\": \"lantern\", \"name\": \"item.lantern\" } }\ngripforge_game_content { \"action\": \"put\", \"kind\": \"npc\", \"doc\": { \"schema\": \"gripforge.npc/1\", \"id\": \"npc_elder\", \"kind\": \"npc\", \"name\": \"npc.elder\", \"faction\": \"villagers\",\n  \"locomotion\": { \"type\": \"static\", \"speed\": 0 }, \"perception\": { \"sight\": { \"range\": 8, \"fov\": 120 }, \"hearing\": 4, \"memory\": 2 },\n  \"behavior\": { \"initial\": \"idle\", \"behaviors\": [\"idle\"] }, \"assets\": { \"model\": \"content:elder\" } } }\ngripforge_game_content { \"action\": \"put\", \"kind\": \"mission\", \"doc\": { \"schema\": \"gripforge.mission/1\", \"id\": \"q_lantern\", \"title\": \"quest.lantern.title\",\n  \"giver\": { \"npc\": \"npc_elder\", \"auto\": false }, \"conditions\": {},\n  \"objectives\": [\n    { \"id\": \"o1\", \"type\": \"event\", \"label\": \"quest.lantern.o1\", \"event\": \"inventory.added\", \"match\": { \"item\": \"lantern\" } },\n    { \"id\": \"o2\", \"type\": \"talk_to\", \"label\": \"quest.lantern.o2\", \"npc\": \"npc_elder\" } ],\n  \"flow\": \"sequential\", \"actions\": { \"onComplete\": [ { \"set_var\": { \"path\": \"story.lantern_found\", \"value\": true } } ] },\n  \"rewards\": { \"money\": 50 } } }\ngripforge_game_content { \"action\": \"put\", \"kind\": \"dialogue\", \"doc\": { \"id\": \"d_elder_offer\", … } }\ngripforge_game_content { \"action\": \"put\", \"kind\": \"dialogue\", \"doc\": { \"id\": \"d_elder_thanks\", \"npc\": \"npc_elder\", \"lines\": [\"dlg.elder.thanks\"] } }\n```\n\n**6. Les scripts.** `s_cellar_door` (§6.1) et `s_chest` (§6.5). Pour l'ancien, le sucre `gives` de son\narchétype suffit : aucun script à écrire.\n\n**7. L'interface.**\n- Les tables `translations` en anglais et en français, pour toutes les clés citées.\n- `ui.theme` configuré.\n- `scene.ui.hud = \"hud.open_world\"`, qui affiche l'objectif courant et les toasts.\n\n**8. Valider et jouer.**\n\n```json\ngripforge_game_engine { \"action\": \"report\" }\n→ { \"errors\": [], \"warnings\": [ { \"code\": \"passport_missing\", \"ref\": \"content:lantern\", \"message\": \"…sans passeport : posée telle quelle, sans collision\" } ] }\ngripforge_game_play_url {}\n```\n\nL'agent joue la boucle complète :\n1. il parle à l'ancien et accepte ;\n2. il ouvre le coffre et reçoit la clé ;\n3. il ouvre la porte ;\n4. il prend la lanterne ;\n5. il revient voir l'ancien, et la quête se termine.\n\nEnsuite il capture, juge et lance `gripforge game-check`.\n\n**9. Livrer à Godot.**\n- `gripforge_gamekit_deliver_local { project_dir, target: \"godot\", verify: true }`.\n- Les fichiers moteur sont écrits : cœur, `game.engine`, kits et `gameplay.json` (scène, instances cuites, règles\n  compilées).\n- La scène principale amorce `gripforge/engine/main.tscn` est écrite une fois (`seed`).\n- La fumée de `game.engine` rejoue la même boucle sans rendu.\n\n**10. Le code.** Ici, rien. Si l'utilisateur veut que la lanterne éclaire la cave avec une lumière dynamique\npropre, l'agent écrit un nœud `GfKit` sous `res://game/` qui fournit le verbe `lantern_light`, le déclare dans\n`code_modules`, puis l'appelle depuis un script (§10).\n\n### 9.3 Installer et retirer : les dépendances, partout pareil\n\n**État actuel, constaté.**\n- **Installation par le projet.** C'est le chemin de l'API, du MCP et de l'interface (`service.installKit` →\n  `resolveInstall`). Il ajoute bien les fournisseurs manquants des `requires`, dans l'ordre, avec\n  `source: 'auto'` (étape `{ op: 'add', auto: true }`). `newProject` et la composition de la création guidée\n  (`game-creation/composition.ts`) passent par le même `resolveInstall`. ✓\n- **Mise à jour automatique.** `resolveUpdate` ajoute aussi les fournisseurs. En revanche, `AutoUpdateChange`\n  ne rapporte que le kit mis à jour : **les kits ajoutés au passage ne sont pas listés**.\n- **Livraison par liste de kits.** C'est `POST /gamekits/deliver` avec `kits`, sans `projectId`. Elle **valide\n  seulement** les `requires` : `delivery/compat.ts` donne l'avertissement « not provided … wire it in ».\n  **Elle n'ajoute rien.**\n- **Retrait.**\n  - `resolveRemove` répond `kit_in_use` s'il existe des dépendants.\n  - Avec `force`, il **désactive** les dépendants. Il ne les retire pas.\n  - Avec `prune`, il élague les fournisseurs `auto` orphelins.\n  - Il n'existe pas de « retirer avec ses dépendants ».\n\n**Changements.**\n1. **Résultat d'installation.** `KitWriteResult` gagne `added: [{ kit, version, reason, requiredBy }]`, tiré des\n   étapes `auto`. L'interface de la page projet l'affiche (« Ajoutés pour satisfaire les dépendances : … »). Le\n   MCP le renvoie tel quel.\n2. **Mise à jour automatique.** `AutoUpdateResult` gagne `added`. La révision le note.\n3. **Livraison par liste.** Elle résout la liste comme un projet virtuel (`resolveInstall` sur un document vide de\n   la cible), livre les kits ajoutés et les liste dans `plan.added`. L'avertissement reste pour un `requires` que\n   rien ne peut fournir.\n4. **Retrait avec dépendants.** C'est la **règle commune à tous les kits**, pas un cas propre à `game.engine` :\n   - sans option, `remove` d'un kit qui a des dépendants **n'applique rien**. Il répond avec le plan :\n     `{ applied: false, dependents: [...], confirm: \"<jeton lié à la révision>\" }`. Ce n'est pas un refus, c'est\n     l'étape de confirmation ;\n   - avec `with_dependents: true` et `confirm: \"<jeton>\"`, il retire le kit et ses dépendants ensemble, dans\n     l'ordre inverse du montage ;\n   - `force` (désactiver les dépendants) reste pour la compatibilité ;\n   - interface : la page projet montre la liste dans une boîte de confirmation (`Dialog` du kit UI), puis retire\n     le tout ;\n   - MCP : `gripforge_gamekit_remove { id, dry_run?, with_dependents?, confirm? }` ;\n   - CLI : la politique (§8.5) interdit à l'agent de retirer `game.engine` sans demande explicite de\n     l'utilisateur, et exige de lui montrer la liste avant d'envoyer `confirm`.\n5. **Jamais implicitement.**\n   - `prune` exclut les kits de `BASE_KITS`, dont `game.engine`.\n   - `configure enabled:false` d'un kit qui a des dépendants suit la même confirmation.\n   - Aucune autre opération (mise à jour, conversion, création guidée, rebase de copie) ne retire ni ne désactive\n     un kit de base.\n\n---\n\n## 10 · Ce qui reste du code\n\n« Ça reste un jeu codé. » Le code propre au jeu est **permis et normal**. Le moteur lui donne une place et des\nprises.\n\n### 10.1 Où il va\n\n| Cible | Emplacement | Forme |\n|---|---|---|\n| Godot | `res://game/` (hors de `gripforge/`, jamais réécrit par une livraison) | nœuds `GfKit` (`gf_setup`, `gf_update`, `gf_services`, crochets de scène) |\n| Unity | `Assets/Game/` | `MonoBehaviour` dérivés de `GfKit`, asmdef propre au jeu référençant `GripForge.Gameplay` |\n| Unreal | module de jeu du projet | `UGfKitComponent` dérivés, ou acteurs utilisant `UGfGameplaySubsystem` |\n| Web, application Three.js locale (CLI) | le dépôt du jeu | `KitRuntimeFactory` montée dans un `KitHost` local, avec les kits du catalogue |\n| Web, page de jeu hébergée | — dans la tranche 1 | La page n'exécute que les kits du catalogue et le contenu. Exécuter du code de jeu demande une origine isolée (question §16). |\n\n### 10.2 Comment il se branche\n\nCe sont les mêmes prises sur toutes les cibles :\n1. **Un service** : `provide('mygame.lantern', obj)`. Un script l'appelle par `{ \"call\": \"mygame.lantern.light\", \"args\": { … } }`.\n2. **Un verbe** : `engine.scripts.registerAction('lantern_light', schema, fn)`. Un script l'emploie comme un\n   verbe de kit.\n3. **Un composant** : `engine.content.registerComponent('flicker', handler)`. Un archétype le porte.\n4. **Une sorte d'entité** : `spawn.registerFactory('boat', …)`. Un archétype `kind: 'boat'` l'utilise.\n5. **Une étape de quête** : `objectives.registerStep(…)`.\n6. **Le bus, les variables, les entités, la sauvegarde** : directement (§3.7).\n\n### 10.3 Le déclarer : `code_modules`\n\n```json\n{ \"id\": \"lantern_fx\", \"target\": \"godot\", \"files\": [\"res://game/lantern_fx.gd\"],\n  \"provides\": { \"verbs\": [\"lantern_light\"], \"components\": [\"flicker\"], \"services\": [\"mygame.lantern\"], \"entityKinds\": [] },\n  \"note\": \"Lumière dynamique de la lanterne.\" }\n```\n\nCette déclaration est **facultative**. Elle sert à deux choses :\n- le rapport ne signale pas `lantern_light` comme verbe inconnu. Un verbe non déclaré est un **avertissement**,\n  jamais une erreur, puisque du code peut le fournir ;\n- le catalogue des briques le montre aux agents suivants.\n\n### 10.4 Du code à la brique\n\nLe chemin existe déjà :\n1. code du jeu ;\n2. **copie locale de kit** (`doc.overlays`) ;\n3. **kit du catalogue** publié.\n\nUn motif de contenu qui se répète (une porte à clé, un coffre à usage unique) devient un **archétype fourni** :\n`game.engine` peut publier un petit jeu d'archétypes de base dans ses données par défaut, comme les démos des\nkits. Une tâche d'agent peut le proposer quand le même verbe de code apparaît dans plusieurs projets. Cette\ntâche est facultative.\n\n---\n\n## 11 · Livraison à Godot, Unity et Unreal\n\n- **Le port de `game.engine` est une extension des cœurs**, pas un nouveau cœur.\n  - Godot : `gf_engine.gd` (autoload `GfEngine`), `gf_content.gd`, `gf_scenes.gd`.\n  - Unity : `GfEngine.cs`, `GfContent.cs`, `GfScenes.cs`.\n  - Unreal : `UGfEngineSubsystem`, `GfContent`, `GfScenes`.\n  - Chacun lit le même `gameplay.json`, qui porte désormais `archetypes`, `scenes`, `scripts` compilés et\n    instances cuites.\n- **Les scripts arrivent compilés.** Les moteurs n'embarquent pas de compilateur. Ils reçoivent des\n  `TriggerRule`, déjà exécutées par `GfTriggers`.\n- **Les instances** :\n  1. le moteur crée un nœud (ou un `GameObject`, ou un acteur) ;\n  2. il y attache un `GfEntity` (ou son équivalent) ;\n  3. il y attache le modèle lié au slot, avec le chargement de modèles déjà utilisé par chaque cœur pour les\n     slots de kits ;\n  4. il ajoute la collision (`solid`) ;\n  5. il appelle les gestionnaires de composants des kits.\n- **La scène principale amorce** est un fichier `seed`, écrit une fois et jamais réécrit sans `force` :\n  - Godot : `gripforge/engine/main.tscn` ;\n  - Unity : `Assets/GripForge/Engine/Main.unity` ;\n  - Unreal : une recette, car un `.umap` est binaire. Unreal fait apparaître les instances à l'exécution dans\n    un niveau vide, et la recette dit comment le créer.\n\n  La consigne « drop the kit nodes in your main scene » devient « la scène amorce les monte toutes ».\n  L'utilisateur peut aussi garder sa propre scène et y poser `GfEngine`.\n- **Scènes natives** (§5.3) : `scene.native` désigne une scène du moteur, chargée par le moteur. Les `GfEntity`\n  qu'elle contient sont indexés.\n- **Conformité.** Il y a quatre scénarios nouveaux :\n  - `engine-content` : instances, composants, placement cuit ;\n  - `engine-scripts` : sucres, `else`, `once`, état d'instance ;\n  - `engine-village` : la tranche 1 complète, avec sauvegarde et chargement à mi-parcours ;\n  - `engine-scenes` : phase 3, changement de scène et sauvegarde dans la scène B.\n\n  Les fumées moteur (`smoke.gd`, équivalents Unity / Unreal) rejouent `engine-village`.\n- **Coût** : proposition de livraison gratuite (§7.6).\n\n---\n\n## 12 · Les studios produisent du contenu\n\nUn studio ne parle jamais au moteur. Il produit des documents et des assets qui s'y déposent.\n\n| Studio | Produit | Dépôt |\n|---|---|---|\n| Mesh / Character / Grip | assets + passeports. Nouvel outil du registre `studio-tools` : « Préparer pour le jeu », qui calcule `kits.engine`. Étapes `code` : emprise, alignement, points depuis les landmarks, clips. Étape `ai` facultative : rôle et archétype proposés. Une étape `ai` absente ne casse rien (`docs/architecture-studios-outils.md` §2). | `asset_passports`, `place` |\n| Scene Studio | cartes `SceneDocument` | `gripforge_game_scene import` → `scenes` |\n| Terrain Studio | cartes cuites `.gftm` | `PUT …/terrain-map` (existant) → monde d'une scène |\n| Audio | sons, signaux, musiques | `audio.core` (existant) ; `scene.audio` |\n| VFX | projets VFX | slots (existants) ; verbes `fx.*` |\n| Plan de niveau (`gripforge_level`) | salles, chemin critique, apparitions | `gripforge_game_scene import { plan }` |\n| Futur : éditeur de contenu dans la page Game Kits | archétypes, scènes, scripts, quêtes | `PATCH …/data` |\n\n**Calcul.** Tout ce qui lit un GLB, une carte ou une image tourne dans le service de calcul. La règle du\n`CLAUDE.md` s'applique. Le passeport, déjà calculé par les studios, évite de recharger les maillages côté web.\n\n---\n\n## 13 · Règles d'écriture d'un kit, à partir de `game.engine`\n\nÀ traduire en anglais dans `docs/gamekits.md`, section « Adding a kit », qui commencera par elles.\n\n0. **Commencer par le moteur.** Un jeu GripForge est une instance de `game.engine` plus du contenu. Avant\n   d'écrire un kit, vérifier que le besoin n'est pas **du contenu** : un archétype, une scène, un script, une\n   quête. Si c'est un comportement réutilisable, c'est un kit.\n1. **Choisir la classe** (§7.2) :\n   - le kit apporte du vocabulaire au contenu, bâtit ou habille une scène, réagit au cycle de vie ou affiche le\n     contenu : il est dépendant, avec `requires: ['game.engine@^1']` et un bloc `engine` ;\n   - c'est un service pur : il est indépendant, sans `requires` vers le moteur, qu'il peut lire à la demande.\n2. **Déclarer, pas coder la découverte.** Composants (`engine.components`, avec schéma et description), verbes,\n   étapes et comportements (`extensions`), collections par scène (`engine.sceneCollections`), clés de couche\n   (`engine.sceneConfig`), sortes d'entités (`engine.entityKinds`). Le validateur et le catalogue des briques\n   lisent ces déclarations.\n3. **Revendiquer ses composants au `setup()`** par `engine.content.registerComponent`. Ne jamais lire un\n   composant qu'un autre kit revendique : passer par son service.\n4. **Crochets de scène** : un kit `world` ou `layer` implémente `sceneEnter` / `sceneExit`. Un kit sans crochet\n   est global.\n5. **Scène implicite** : avec la seule scène implicite, le kit se comporte exactement comme sans moteur. Ses\n   scénarios de conformité le prouvent.\n6. **Verbes** enregistrés via `engine.scripts`, avec un schéma d'arguments et un exemple.\n7. **Textes** en clés `i18n.text`, touches par `labelFor`, apparence par `ui.theme`. Ces règles existent déjà.\n8. **Sauvegarde** : l'état par instance passe par `state`. L'état propre du kit passe par `save()` / `load()`.\n9. **Quatre cibles** : modèle TypeScript pur, ports, scénario `≡ web`. Ces règles existent déjà.\n10. Les règles 1 à 8 actuelles de « Adding a kit » suivent : manifeste, capacités, `configSchema`, slots,\n    événements, catalogue, enregistrement, QA.\n\n---\n\n## 14 · Plan par phases\n\n### 14.1 Phase 1 : la première tranche (« le village »)\n\n**But** : prouver le principe sur les quatre cibles avec le plus petit ensemble.\n\n**Contenu.**\n- **Kit `game.engine` 1.0.0.** Web (`kits/game.engine/`) plus ports Godot, Unity et Unreal dans les cœurs. Il\n  contient :\n  - les collections `archetypes`, `scenes` et `scripts` ;\n  - **une seule scène active** : la scène de départ ou la scène implicite, sans changement de scène ;\n  - la fabrique `prop` ;\n  - les composants gérés par le moteur : `state`, `solid`, `model` ;\n  - des **ponts provisoires** vers les services existants pour `interactable` (`interaction.use.register`),\n    `npc` (`kind: 'npc'`), `talk` (`dialogue.lines`), `container` et `pickup` (verbes `give_item` /\n    événements `inventory.*`). Les lots C les remplacent par les gestionnaires des kits ; les ponts restent comme\n    repli ;\n  - les verbes `set_state`, `play_clip`, `set_solid`, `show`, `hide`, `call` ;\n  - les sucres `interact`, `enter`, `state`, `quest`, `talked`, `gives`, avec `else` et `once` ;\n  - la compilation vers `TriggerRule`, l'index et le rapport (TypeScript pur) ;\n  - la sauvegarde de sa section ;\n  - le placement cuit, en version minimale : `snap: ground` contre le monde de la scène, résolu côté serveur par\n    le service de calcul quand le monde est une carte, sinon pur.\n- **Montage en tête**, hors tri.\n- **`BASE_KITS`** : `game.engine` en tête, **pour les nouveaux projets seulement**. Pas encore `ensureEngine`.\n- **Aucun kit existant n'est modifié.**\n- **MCP / HTTP** :\n  - `gripforge_game_engine` (`start`, `blocks`, `report`) ;\n  - `gripforge_game_content` (`put`, `get`, `list`, `remove`, `place`, `validate`) ;\n  - le bloc `engine` à la création ;\n  - `added` dans le résultat d'installation.\n- **Page de jeu web** : les instances `prop` sont dessinées par le rendu générique (`render/entity-renderer.ts`,\n  modèle lié au slot). Les invites passent par `ui.prompts`, l'objectif par `hud.open_world`.\n- **QA** :\n  - scénarios `engine-content`, `engine-scripts` et `engine-village`, avec la parité ≡ web sur Godot, Unity et\n    Unreal ;\n  - rejeu de **tous** les scénarios existants avec `game.engine` monté : traces identiques ;\n  - `qa/game-engine-check.mjs` (pur) : compilation, rapport, sucres, scène implicite.\n- **Documentation** : `docs/game-engine.md` (ce document, mis à l'état) et une section dans\n  `docs/gamekits.md`.\n\n**Ce qui prouve le principe.**\n- Le même document de contenu donne la même trace sur web, Godot, Unity et Unreal.\n- Un agent construit le village par le MCP seulement, sans écrire de code moteur.\n- Ajouter un second coffre, c'est un `place` et un script, sans code.\n\n**Hors tranche** : plusieurs scènes, `ensureEngine` sur les projets existants, rattachement des kits, import\nScene Studio, section `kits.engine` des passeports, déclarations d'interface, `code_modules`, code web hébergé.\n\n### 14.2 Phases suivantes\n\n| Phase | Contenu | Condition d'entrée |\n|---|---|---|\n| **2 · Les jeux existants et les agents** | `ensureEngine` dans `autoUpdateProject`, avec la preuve du §7.6. Retrait avec dépendants (§9.3). Politique `3d-production-v8`, `SKILL.md`, `game-check`. Catalogue des briques complet. Création guidée avec plan de contenu. | Tranche 1 en production, preuve de transparence verte |\n| **3 · Scènes et cycle de vie ; gel du contrat 1.x** | Plusieurs scènes, `load_scene`, entrées, `sceneEnter` / `sceneExit`, `sceneCollections`, `layers`, `engine.flow` (titre, fin, rejouer), sauvegarde dans la scène B, `registerComponent` ouvert aux kits, bloc `engine` du manifeste. **Contrat 1.x gelé**, publié dans `docs/game-engine.md`. | Phase 2 |\n| **4 · Rattachement des kits (lots parallèles)** | Lots A à H (§14.3), puis intégration | Contrat 1.x gelé |\n| **5 · Contenu riche** | Import Scene Studio et plan de niveau, outil studio « Préparer pour le jeu » (`kits.engine`), placement par passeport, `ui.panels` / `ui.webui`, `code_modules`, déclaration des vues par les kits, éditeur de contenu dans la page Game Kits | Phase 4 en cours |\n| **6 · Héritage** | Plan de sortie des `legacy.*` : conversion vers des presets natifs ou retrait. Reformulation de `gripforge_kit`. | Décision du propriétaire |\n\n### 14.3 Les lots parallèles de migration des kits\n\nChaque lot ne touche **que ses propres fichiers** :\n- `packages/gamekits/src/kits/<ses kits>/**` (manifeste, manifestes gelés, `docs.ts`, `runtime/web`, `model.ts`,\n  `text.ts`) ;\n- `packages/gamekits/src/delivery/gameplay/engines/{godot,unity,unreal}/kits/<ses kits>/**` ;\n- ses scénarios `qa/gameplay-engines/scenarios/<kit>-*.json`, découverts automatiquement ;\n- ses vérifications `qa/<lot>-*.mjs`.\n\n| Lot | Kits | Travail type |\n|---|---|---|\n| **A · interface, réglages, sauvegarde** | `hud.open_world`, `hud.action`, `hud.minimap`, `ui.endscreen`, `save.persistence` (dépendants) ; vérifier `ui.menu`, `ui.prompts`, `ui.theme`, `ui.cursor`, `ui.webui`, `settings.graphics`, `input.*` (indépendants, aucun changement) | lecture de `engine.content` / `engine.flow`, HUD par scène, rejouer, lieu de sauvegarde |\n| **B · monde, terrain, streaming, couches** | `world.terrain`, `world.streaming`, `world.city_block`, `world.district`, `world.rooms`, `world.platforms`, `world.racetrack`, `world.lighting`, `world.weather`, `world.water`, `world.fluids`, `world.tracks`, `world.scenery`, `world.elements` | `sceneEnter` / `sceneExit`, `engine.world`, `sceneConfig`, `sceneCollections` |\n| **C · PNJ, quêtes, dialogue, interaction, objets** | `spawn.system`, `npc.core`, `npc.dialogue`, `interaction.system`, `mission.system` (avec `giver.npc`), `inventory.basic`, `faction.system`, `economy.money` | revendiquer les composants des ponts de la tranche 1, `start_dialogue`, données par scène |\n| **D · combat, armes, ennemis** | `combat.core`, `combat.melee`, `combat.ranged`, `combat.projectiles`, `combat.abilities`, `weapons.loadout`, `upgrades.boons`, `enemy.ai`, `enemy.boss`, `encounters.waves` ; vérifier `fx.*` (indépendants) | composants, verbes via `engine.scripts`, rencontres par scène |\n| **E · véhicules et monde vivant** | `vehicle.driveable`, `vehicle.enter_exit`, `vehicle.doors`, `vehicle.damage`, `traffic.system`, `npc.pedestrian`, `wanted.police`, `race.kart` | composants, ambiance par scène, entrées |\n| **F · arènes, voies, tactique** | `moba.lanes`, `moba.hero`, `minion.waves`, `hud.moba`, `fps.tactical`, `combat.duel` | carte = scène, entrées, routes par scène |\n| **G · personnages et mouvement** | `character.third_person`, `character.top_down`, `character.platformer`, `movement.dash`, `movement.traversal` | apparition aux entrées, composants du joueur |\n| **H · services transverses (contrôle seulement)** | `audio.core`, `i18n.text`, `ui.theme`, `render.lod`, `asset.meta`, `physics.port`, `net.*`, `legacy.*` | aucun changement attendu ; vérifier l'absence de régression, documenter la lecture à la demande (`asset.meta` → `kits.engine`) |\n\nLes lots sont indépendants entre eux. Une seule contrainte d'ordre : le lot C, s'il est fini, donne au lot A ce\nqu'il lira (`giver.npc`, repères), mais A peut avancer sur les ponts de la tranche 1.\n\n**Fichiers partagés.** Aucun lot ne les modifie : ils appartiennent à l'**étape d'intégration finale**.\n\n| Fichier ou ensemble | Pourquoi il est partagé |\n|---|---|\n| `packages/gamekits/src/registry.ts` (`CATALOG_VERSION`) | une seule montée par publication |\n| `packages/gamekits/src/kits/index.ts` | enregistrement des modules et des versions |\n| `packages/gamekits/src/delivery/gameplay/sources.ts` (**généré** par `scripts/embed-gameplay-sources.mjs`) | contient les sources de tous les kits |\n| `packages/gamekits/src/kit-covers.generated.ts`, `src/abilities/generated-web.ts`, `src/delivery/unity/settings.generated.ts`, sorties de `scripts/gen-*.mjs` (i18n, audio, net, virtualpad) | générés |\n| `packages/gamekits/src/kits/i18n.text/defaults.ts` (et les données moteur générées) | chaînes de tous les kits |\n| `packages/gamekits/src/presets.ts` (`BASE_KITS`, presets, `expects`) | commun |\n| `packages/gamekits/src/capabilities.ts` (`CAPABILITY_CATALOG`, `DEFAULT_PROVIDERS`, hôte) | commun |\n| `packages/gamekits/src/kits/shared*.ts`, `src/types.ts`, `src/runtime/**`, `src/resolve.ts`, `src/autoupdate.ts` | contrat et hôte |\n| `packages/gamekits/src/kits/game.engine/**` et les cœurs `delivery/gameplay/engines/*/core/**` | le moteur |\n| QA communes : `qa/gameplay-engines-check.mjs`, `qa/gameplay-engines/{web,godot,unity,unreal,trace}.mjs`, listes et comptes de kits des `qa/gamekits-*-check.mjs`, `qa/save-slots/**`, scripts de `package.json` | harnais |\n| `docs/gamekits.md`, `docs/game-engine.md` | comptes, tableaux, sections communes |\n| `packages/grip-forge/src/game-policy.ts`, `templates/SKILL.md`, version et `release/` du CLI | politique |\n| `packages/mcp-client/src/gamekit-tools.ts`, `apps/web/src/lib/mcp-server.ts` | descriptions des outils |\n| `apps/web/src/lib/gamekits/**` (service, rendu, page de jeu), `apps/web/src/components/gamekits/**` | web |\n\n**Règles.**\n1. **Un lot n'édite jamais un fichier partagé.** S'il a besoin d'un changement, il l'écrit dans la description de\n   sa branche, rubrique « Demandes d'intégration » : capacité à ajouter, chaînes à ajouter à `defaults.ts`,\n   entrée de preset, ligne de doc. Le texte doit être prêt à coller.\n2. **Les fichiers générés ne sont jamais commités par un lot.** Le lot régénère localement pour ses\n   vérifications, puis annule. L'intégration régénère une fois. En cas de conflit sur un fichier généré, on\n   régénère, on ne fusionne jamais à la main.\n3. **Versions** : chaque lot monte la version mineure de **ses** kits et gèle leur manifeste précédent dans le\n   dossier du kit. Seule l'intégration monte `CATALOG_VERSION`.\n4. **Contrat du moteur** : un besoin nouveau du contrat (verbe, crochet, champ) passe par une **demande** au\n   propriétaire de `game.engine`. Il n'est pas fait dans le lot. Le contrat 1.x étant gelé à l'entrée de la\n   phase 4, les demandes vont en 1.(x+1) après l'intégration.\n5. **L'intégration finale** est un seul agent, séquentiel :\n   1. fusion des lots ;\n   2. application des demandes ;\n   3. régénération ;\n   4. `CATALOG_VERSION` ;\n   5. docs et comptes ;\n   6. politique CLI et descriptions MCP ;\n   7. `pnpm qa:gamekits`, `qa:gamekits:full-slice`, `qa:save-slots`, `qa:gamekits:delivery`, conformité quatre\n      cibles, `qa:mcp`.\n\n---\n\n## 15 · Risques\n\n| Risque | Parade |\n|---|---|\n| Changer le comportement des jeux vivants en ajoutant le moteur | Mode transparent ; montage en tête hors tri ; rejeu de toutes les traces ; `ensureEngine` seulement en phase 2 |\n| Réordonner le montage en ajoutant des arêtes `requires` | Règle du montage en tête, ordre des autres calculé sans les arêtes vers le moteur (§7.6) |\n| Jeux en `compatibility: strict` qui perdent leurs sauvegardes | Comparaison de lock qui ignore `game.engine` transparent (§16) |\n| Deux notions de niveau : `scene` et les collections de niveau des kits | La scène **désigne** le document du kit, elle ne le recopie pas. Scène implicite par défaut. |\n| Placement différent selon le moteur | Placement cuit à l'écriture, empreinte, repli avec avertissement |\n| Un kit requiert le moteur avant que les ports existent : `target_unsupported` | Ordre strict : ports d'abord (§7.6) |\n| Ponts provisoires de la tranche 1 qui divergent des gestionnaires des kits | Les gestionnaires des kits prennent la priorité, les ponts restent en repli. Scénarios `engine-*` rejoués à chaque lot. |\n| Page de jeu web codée en dur par genre | Rendu générique des instances dès la tranche 1. Déclaration des vues en phase 5. |\n| Unreal : pas de niveau binaire généré | Apparition à l'exécution dans un niveau vide, plus une recette |\n| Ampleur (83 kits) | Lots parallèles, contrat gelé, intégration unique, 27 kits sans changement |\n| Code de jeu exécuté dans la page hébergée : exécution de code tiers sur le domaine du site | Non exécuté dans la tranche. Origine isolée ou worker sans DOM à décider (§16). |\n| Charge dans Next (index, cuisson) | Index et rapport purs et légers. Toute lecture de fichier passe par le service de calcul (`engine.place`). |\n| Agents qui ignorent la structure, puisqu'elle n'est pas une barrière | Paquet de départ, `next`, politique v8, `game-check` qui lit le rapport : on mesure, on ne bloque pas |\n| Confusion avec « a game kit IS an engine » (`gripforge_kit`) | Reformulation de l'outil hérité (phase 2) |\n| Retrait du moteur par un agent qui « fait le ménage » | Jamais implicite, `prune` exclu, confirmation avec liste (§9.3), politique |\n\n---\n\n## 16 · Décisions\n\nRéponses du propriétaire (2026-10-02), puis les choix pris sur la recommandation de la conception — à corriger\npar le propriétaire si besoin.\n\n| # | Question | Décision | Qui |\n|---|---|---|---|\n| 1 | Migration des jeux vivants | Les **nouveaux** jeux reçoivent `game.engine` (premier de `BASE_KITS`). Un jeu existant le reçoit **seulement** quand un de ses kits se met à le requérir (le résolveur ajoute le fournisseur à la mise à jour automatique). Pas d'`ensureEngine`. Réglable plus tard. | propriétaire |\n| 2 | Sauvegardes strictes | Le hachage de lock (`lockHashOf`) **ignore toujours** `game.engine` (pas seulement en mode transparent : le moteur versionne lui-même sa section de sauvegarde). Une sauvegarde `compatibility: strict` survit à son arrivée. | choix (§7.6) |\n| 3 | Format de scène | Un document de scène **léger** (`gripforge.scene/1`) qui désigne le monde et **importe** les cartes du Scene Studio. | propriétaire |\n| 4 | Code de jeu sur la page hébergée | **Non** pour l'instant : moteurs et application Three.js locale du CLI seulement. La page hébergée n'exécute que les kits du catalogue et le contenu. | propriétaire |\n| 5 | `triggers.rules` | Le fournisseur reste `mission.system`. L'exécuteur est l'hôte ; le changer n'apporterait rien à la tranche. | choix |\n| 6 | Vocabulaire | « Quête » pour les agents, `missions` dans les données (l'outil accepte `kind: quest` comme alias). Collections `archetypes`, `scenes`, `scripts`, `code_modules`. | choix |\n| 7 | Section `kits.engine` du passeport | Taxonomie des rôles **ouverte** ; rôle et archétype proposés par une étape `ai` facultative, confirmés à la main (phase 5). | choix |\n| 8 | Facturation | La livraison de `game.engine` aux moteurs est **gratuite** (hors crédit par version majeure) — appliquée avec les ports. | choix |\n| 9 | Preset `adventure` | **Oui** : le jeu de référence (le village du §9.2), contenu complet, aucune ligne de code. | propriétaire |\n| 10 | Héritage | Hors tranche ; `gripforge_kit` inchangé. | choix |\n| 11 | Création guidée | Voie MCP / CLI d'abord ; le plan de contenu du planificateur viendra en phase 2. | choix |\n\nRègles du propriétaire déjà portées par la conception, tenues dans la construction : `game.engine` est un kit par\ndéfaut et une dépendance normale (installer un kit qui le requiert l'installe ; le retirer demande une demande\nexplicite qui montre et retire ses dépendants ensemble ; jamais retiré implicitement) ; il donne aux agents, au MCP\net au CLI la structure et les briques de chaque jeu comme une **direction**, jamais une barrière ; un jeu codé à la\nmain peut en utiliser les pièces à la carte.\n\n## 17 · Construction de la tranche 1 : état et écarts\n\n### 17.1 Ce qui est construit (web + contrat)\n\n| Pièce | Où |\n|---|---|\n| Contrat (documents, services, événements, sauvegarde) | `packages/gamekits/src/kits/game.engine/contract.ts` |\n| Modèle pur : lecture du contenu, compilation, rapport, catalogue des briques, prochaines étapes | `kits/game.engine/model.ts` |\n| Placement cuit (échantillonneur du sol, empreinte) | `kits/game.engine/place.ts`, travail `engine.place` (`services/compute/src/jobs-game-engine.mjs`) |\n| Runtime web | `kits/game.engine/runtime/web/index.ts` |\n| Manifeste, schémas des collections, README | `kits/game.engine/{manifest,docs,index}.ts` |\n| Bloc `engine` du manifeste et sa validation | `types.ts` (`EngineKitDecl`), `manifest.ts` (`checkEngine`) |\n| Crochets `ready` / `sceneEnter` / `sceneExit`, `SceneView`, `runtime.core.runtimes()` | `runtime/types.ts`, `runtime/host.ts` |\n| Montage en tête hors tri, retrait avec dépendants, `prune` qui épargne les kits de base, `added`, trace `removed` | `resolve.ts`, `project.ts` |\n| Livraison par liste résolue (`DeliverRequest.resolve`, `plan.added`) | `delivery/index.ts`, route `gamekits/deliver` |\n| `BASE_KITS` (moteur en tête, installé là où il tourne), preset `adventure`, contenu de référence | `presets.ts`, `project.ts`, `demos/adventure-village.ts` |\n| Serveur : paquet de départ, rapport, briques, opérations de contenu, cuisson | `apps/web/src/lib/gamekits/engine.ts`, routes `…/engine`, `…/engine/blocks`, `…/content`, `…/content/place` |\n| Retrait confirmé, `added` à l'installation et à la création, désactivation confirmée du moteur | `apps/web/src/lib/gamekits/service.ts`, route `…/kits/{kit}` |\n| Outils MCP | `packages/mcp-client/src/gamekit-tools.ts` (`gripforge_game_engine`, `gripforge_game_content`, `gripforge_gamekit_remove` étendu) |\n| QA | `qa/gamekits-engine-check.mjs` (pur), scénarios `engine-content`, `engine-scripts`, `engine-village`, `qa/gameplay-engines-check.mjs --with-engine` (transparence prouvée), cas `engine.place` de `qa/compute-check.mjs` |\n\n### 17.2 Écarts avec la conception (décidés à la construction)\n\n1. **`{ \"interact\": \"self\" }`** se compile en `{ event: 'engine.interact', match: { instance } }` et non en\n   `interaction.requested` filtré par l'entité : l'id d'entité n'existe qu'à l'exécution, alors que la compilation\n   est faite une fois pour les quatre cibles. Le moteur réémet `engine.interact { instance, entity, by }` quand\n   `interaction.requested` vise une de ses instances (le `target` de l'événement, pas `entity`, qui est le joueur).\n2. **`if` + `else`** : une seule règle dont l'action `engine_if` évalue la garde **une fois** et joue une branche.\n   Deux règles (`when ∧ if`, `when ∧ ¬if`) relisaient l'état après que la branche `then` l'avait changé (un levier\n   se rebasculait aussitôt). `if` seul reste une conjonction `when ∧ if`.\n3. **`once`** : un marqueur `engine_once` en tête de la branche `then` retire la règle quand elle joue (sauvé dans\n   `once`). La branche `else` se répète tant que `then` n'a pas joué : une porte fermée redit « fermée » à chaque\n   essai, puis ne dit plus rien une fois ouverte.\n4. **`gives`** : `{ quest, offer, progress?, thanks?, after? }`. Il se compile en règles `set_talk` (nouveau verbe\n   du moteur) : l'offre d'abord, `progress` au départ de la quête, `thanks` quand l'étape `talk_to` de retour vers\n   ce PNJ démarre, `after ?? thanks` à la fin, l'offre de nouveau sur échec ou abandon. Le repère « quête\n   disponible » est l'état d'instance `quest_available` (variable `instance.<id>.quest_available`), que le HUD lira\n   (lot A).\n5. **Composant non revendiqué** : un **avertissement** (gardé sur l'instance pour un gestionnaire que du code de jeu\n   enregistrerait), comme un verbe non déclaré, et non une erreur. Un composant d'un kit du catalogue non installé\n   reste un avertissement avec `fix: gripforge_gamekit_install`.\n6. **`world.zones`** : `game.engine` fournit la capacité (zones de scène et collection `zones`, dans les zones de\n   l'hôte), **en dernier recours** : un kit qui la fournit aussi (city block, district, rooms) reste choisi et garde\n   son arête de tri. Sans service propre, pour ne pas changer le démarrage de `mission.system`. Sans cela, le\n   preset `adventure` (monde `world.terrain`) se voyait ajouter un quartier de ville.\n7. **Crochet `ready()`** ajouté à `KitRuntime` (appelé quand tous les kits ont fait leur `setup()`), et\n   `runtime.core.runtimes()` : le moteur fait apparaître les instances après l'enregistrement des fabriques des\n   autres kits (`npc`), puis appelle leurs crochets de scène.\n8. **Empreinte de placement** : le monde de la scène **plus** la config du kit monde installé et l'id de la carte\n   liée (`sceneBasis`). Le placement d'une instance dont l'empreinte a changé retombe sur `at` (avertissement\n   `placement_stale`, `fix: gripforge_game_content { action: 'bake' }`).\n9. **Changement de scène** (`load_scene`, `engine.scenes.enter`, chargement dans une autre scène) est déjà fait\n   sur le web, en avance sur la phase 3, pour geler le contrat des crochets avant les lots. Le changement de scène\n   est différé à la fin du pas (`runtime.core.defer`).\n10. **Retrait** : sans option, le retrait d'un kit qui a des dépendants — et de `game.engine` toujours — n'applique\n    rien et répond 409 (`kit_in_use`, ou `confirm_required`) avec `details { dependents, confirm, applied: false }` :\n    c'est l'étape de confirmation, gardée en 409 pour que l'interface actuelle (qui affiche les dépendants sur\n    `kit_in_use`) reste juste sans être touchée. `dry_run` rend le plan et le jeton en 200. `with_dependents` +\n    `confirm` (jeton lié à la révision) retire l'ensemble dans l'ordre inverse du montage. `configure enabled:false` sur `game.engine`\n    suit le même jeton. Un kit de base retiré sur demande laisse `removed[kit] = { at, by, reason? }`, effacé si un\n    kit le ramène.\n11. **Kits de base installés là où ils tournent** : un kit de `BASE_KITS` sans adaptateur pour la cible n'est pas\n    installé. Depuis les ports (jalon 2), `game.engine` déclare les cibles Godot, Unity et Unreal : un projet moteur\n    neuf l'a, et un kit qui requiert `game.engine@^1` s'installe sur les trois moteurs.\n12. **Pas d'outil `gripforge_game_scene`** dans la tranche : la cuisson est `gripforge_game_content { action:\n    'bake' }` ; l'import Scene Studio / plan de niveau reste en phase 5.\n13. **Pont `container`** : interagir donne les objets une fois (état `looted`). Les scripts restent le moyen\n    recommandé (le coffre du village est un script).\n14. **Rapport côté moteurs** : les moteurs reçoivent le contenu compilé, pas le rapport ; le scénario\n    `engine-content` ne compare donc pas le rapport (vérifié en pur).\n15. **Surface escaladable** (lot G) : c'est un composant d'archétype `climbable` (booléen, `movement.traversal`), pas\n    un champ du passeport d'asset : un passeport décrit l'objet, l'archétype dit ce qu'on en fait dans le jeu.\n\n### 17.3 Tranche 1, moteurs (jalon 2)\n\n| Pièce | Où |\n|---|---|\n| Godot : nœud `GfEngine` (`gf_order() = 0`), crochets `gf_ready` / `gf_scene_enter` / `gf_scene_exit` du cœur | `delivery/gameplay/engines/godot/kits/game.engine/gf_game_engine.gd`, `core/gf_kit.gd`, `core/gf_gameplay.gd` |\n| Unity : composant `GfEngine` (`GfEngine.Instance`), `IEngineContentService`, `IEngineScenesService`, `GfSceneView` | `engines/unity/kits/game.engine/Runtime/GfEngine.cs`, `core/Runtime/GfContracts.cs`, `GfKit.cs` |\n| Unreal : `UGfGameEngineComponent`, `UGfEngineContentService`, `FGfSceneView`, `KitReady` / `KitSceneEnter` / `KitSceneExit` (+ événements Blueprint) | `engines/unreal/kits/game.engine/…`, `core/…/GfKitComponent.h`, `GfService.h`, `GfGameplayTypes.h` |\n| Contenu compilé dans `gameplay.json` (section `engine`) à la livraison | `delivery/pipeline.ts` (`withEngineContent`) |\n| QA : scénarios `engine-content`, `engine-scripts`, `engine-village`, `engine-flow` ≡ web, fumées natives, rejeu `--with-engine` | `qa/gameplay-engines-check.mjs`, `qa/gameplay-engines/{godot,unity,unreal}…` |\n\nÉcarts avec les noms prévus : Unreal a un composant de kit (`UGfGameEngineComponent`) et non un sous-système, comme\nles autres kits ; les crochets Unity s'appellent `OnGfSceneEnter` / `OnGfSceneExit` et les méthodes de flux\n`FlowStart` / `FlowEnd` / `FlowRestart` (`Start` est une méthode magique d'Unity). La livraison d'un moteur ne lit\npas les passeports : la taille de `solid: passport` est résolue à la compilation.\n\n**Contrat 1.1** (demandes des lots A à H, détail : docs/game-engine-contract.md §9) : sortie de l'écran titre sur\n`menu.action`, `InstanceView.talk`, `engine.scenes.pending()`, `next` à la sortie de scène, `self` pour les verbes\nde kit, entité prêtée (le joueur) gardée, `container` revendiqué donné par son kit, passeports résolus comme\n`asset.meta`, musique et ambiance de scène par `audio.core`, rapport (`ui_hud_unknown`, `entry_missing`,\n`passport_missing`). Sans rupture : `game.engine@^1`.\n\n### 17.4 Ce qui reste\n\n- **Contrat suivant** : entrées fournies par un kit monde (lots B, F), plusieurs cartes cuites par projet (lot B,\n  propriétaire des assets), validation de `world.config` et `layers` (lot F).\n- **Page de jeu web** : le rendu générique dessine les entités (modèle lié au slot, sinon un substitut) et, depuis\n  l'intégration, les repères de quête ; les clips et la visibilité attendent la déclaration des vues (phase 5). Le\n  circuit de `world.racetrack` (maillage de la route, mini-carte) n'est pas encore relu à un changement de scène\n  (demande B §5, laissée : le rendu de course est construit une fois pour la partie).\n- **Intégration** : `mcp-docs` (catalogue des outils du site) n'a pas encore les deux nouveaux outils — demande à\n  l'équipe du site. La politique CLI `3d-production-v8` et `SKILL.md` sont écrits (§17.5) ; la publication du CLI et\n  la lecture du rapport de contenu par `game-check` (§8.5) restent à faire.\n- **asset.meta** : la ligne `engine` du tableau « Kit sections » de son README attend sa prochaine version (lot H, R5).\n- **Couverture** : `game.engine` n'a pas encore d'image de catalogue ni de direction artistique dans\n  `tools/gamekits/kit-cover-art.mjs`.\n\n### 17.5 Intégration des huit lots (catalogue 2026.10.02.8)\n\nBranche `engine-integration`, au-dessus de la tranche 1 moteurs (`ecde3e6e`). Les huit lots sont repris tels quels\n(un ou deux commits chacun, sans conflit), puis l'intégration applique leurs demandes :\n\n- **Contrôles communs** : ordre de montage (corps du lot D, et les kits par défaut qui requièrent le moteur —\n  `save.persistence`, `ui.endscreen` — écartés avec lui quand on le désactive), hachage de lock, dépendants au retrait\n  (dans l'ordre inverse du montage), versions (`resolve`, `economy`, `surfaces`, `lighting`, `save-slots`), `sunport`.\n- **Textes** : `ui.endscreen.stat.scenes` et `ui.endscreen.stat.quests` dans les chaînes par défaut d'`i18n.text`.\n- **Ponts** : `BRIDGE_VERBS` et `BRIDGE_COMPONENTS` sont vides ; chaque verbe et composant du premier jet est\n  déclaré par son kit ; `talk` a son gestionnaire dans `npc.dialogue` (sujet lu dans `InstanceView.talk`). Les ponts\n  des runtimes restent en repli pour une ancienne version d'un kit.\n- **Rattachements retenus** : `fps.tactical` 1.5.0 et `combat.duel` 1.2.0 requièrent `game.engine@^1` (rôle `world`)\n  maintenant que le moteur a ses ports ; la déclaration est versée dans la mineure non publiée du lot F plutôt qu'une\n  mineure de plus.\n- **Page de jeu** (`components/gamekits`, `lib/gamekits` seulement) : un HUD dont `hud.active` est faux ne dessine\n  rien (l'offre de bienfaits d'`hud.action` reste), repères de quête au-dessus des donneurs (`hud.bind.markers()`),\n  eau et décor relus à `engine.scene.entered`.\n- **Kit par défaut** : `input.virtualpad` est le dernier de `BASE_KITS` (mode `auto`) ; jeux existants inchangés.\n- **Politique** : CLI `3d-production-v8` (§8.5), `SKILL.md`, descriptions MCP.\n\nTraces de référence : `character-third-person-engine` passe de `$#2` à `$#1` après la sortie de `cave` (joueur prêté,\ncontrat 1.1), comme le lot G l'annonçait ; `character-top-down-engine` de même ; `character-platformer-engine` et\n`movement-traversal-engine` gardent la capsule du joueur (écarts de position de l'ordre du millimètre) ;\n`enemy-ai-engine` gagne une attaque à 1,68 s (l'ennemi garde son corps physique, il marche jusqu'au héros) ; les vues\nd'instance portent `talk` ; `i18n-text` liste les deux nouvelles chaînes. Le retrait des ponts ne change aucune trace.\n\n**Ports moteur des lots.** Les lots B à F (et une partie de A et G) avaient laissé leurs ports Godot, Unity et Unreal\ninchangés, faute de ports de `game.engine`. Une fois ceux-ci livrés, les scénarios `<kit>-engine` sont rejoués sur\nles trois moteurs : l'intégration a donc câblé les ports des kits (crochets de scène, gestionnaires de composants,\nverbes déclarés, sauvegarde par scène) avec les noms gelés du contrat §5, kit par kit, sans toucher aux cœurs ni à\n`game.engine`. `inventory.basic` monte avant `interaction.system` sous Unity et Unreal (ordre du web). Ajustements de\nscénario : `npc-core-engine` tolère 5 cm (le CharacterMovementComponent d'Unreal tient le PNJ à 2 cm du sol), et\nl'aller-retour de sauvegarde de `combat-ranged-engine` est écarté (`roundtripSkip` : la dispersion vient d'un flux\naléatoire du kit qu'aucune sauvegarde ne garde, ni sur le web ni sur les moteurs).\n\nRepris depuis dans les ports de `game.engine` (branche `engine-port-fixes`), et les contournements des kits retirés :\nla boîte d'une instance `solid` est inscrite au physics.port sous Unity et Unreal, sous l'entité de l'instance (le\nmoteur n'exige pas physics.port : il l'atteint par son nom — réflexion C#, réflexion UFunction — et ne fait rien sans\nlui), comme `addStaticBox(…, entity)` sur le web ; sous Godot, `_apply_collider` crée le nœud physics.port s'il manque\n(`physics_port()`), `_verb_call` appelle une méthode sans paramètre sans l'objet d'arguments (et coupe les arguments\npositionnels en trop, comme JavaScript) ; le `remove()` du physics.port Godot sort le corps de toute collision et de\ntoute requête tout de suite (calques à zéro), comme le `Remove` Unity. Contrôles : les tests natifs `game.engine` des\ntrois moteurs (le corps de la porte fermée connu du port sous son entité, retiré quand elle s'ouvre ; sous Godot, un\nrayon la nomme puis la traverse dans la même image, et un verbe `call` vers une méthode sans paramètre), et les\nscénarios `combat-ranged-engine`, `movement-traversal-engine`, `encounters-waves-engine`, `character-top-down-engine`\net `movement-dash-engine` sans contournement.\n\n## Annexe · Ce qui a été lu\n\n- GripForge (`origin/kits-integration-2`) :\n  - docs : `docs/gamekits.md`, `docs/game-creation.md`, `docs/architecture-studios-outils.md`,\n    `docs/map-structures.md` ;\n  - noyau des kits : `packages/gamekits/src/{runtime/types.ts, data/dsl.ts, types.ts, presets.ts,\n    capabilities.ts, resolve.ts, autoupdate.ts, registry.ts}` ;\n  - les manifestes des 83 kits (`provides`, `requires`, `data`, `extensions`, adaptateurs) ;\n  - les kits `asset.meta`, `mission.system`, `npc.dialogue`, `interaction.system`, `ui.webui` ;\n  - la livraison : `delivery/gameplay/layout.ts`, le README du cœur Godot, la liste des cœurs Unity et\n    Unreal, `delivery/compat.ts` ;\n  - le noyau partagé : `packages/core/src/mesh-passport.ts`, `packages/core/src/scene/types.ts` ;\n  - la QA : `qa/gameplay-engines/trace.mjs`, `qa/gameplay-engines-check.mjs` ;\n  - le CLI et le MCP : `packages/grip-forge/src/game-policy.ts`, `templates/SKILL.md`,\n    `packages/mcp-client/src/gamekit-tools.ts`, `apps/web/src/lib/mcp-server.ts` (`gripforge_level`,\n    `gripforge_kit`) ;\n  - le web : `apps/web/src/lib/gamekits/service.ts`, `game-creation/composition.ts`.\n- Projet voisin, lu sans rien en reprendre que les idées :\n  - le registre de maps, le validateur et le bâtisseur de monde ;\n  - le registre d'entités ;\n  - le guide d'ajout de map et l'audit de frontière moteur ;\n  - le contexte général.\n\n\n### HUD art direction and web presentation\n\n`gripforge_hud` retains the saved brief when planning an existing project. Named visual references belong in that brief, independently of the world theme. `plan` and `quote` return the exact `concept_prompt`; check it before paid generation. Concept identity covers the brief, palette, widget composition and capabilities, so a changed art request cannot reuse an unrelated image. Edits made while generating prevent the old concept from being linked; its Library archive remains available.\n\nThe existing HUD v2 element `props` supports the bounded presentation properties returned by `templates.presentation`: `surface` (legacy/flat/glass/none), `frame` (square/cut/rounded), `density`, `radarShape` (square/circle), `portraitStyle` (outline/solid), `loadoutStyle` (labels/silhouettes, shared with the shop), `feedStyle` (labels/silhouettes), `ammoStyle` (stacked/inline), `fontSize`, `numeralSize`, `secondaryNumeralSize`, `iconSize`, `tracking`, `padding`, `portraitSize`, `rosterGap`, `showLabels`, `showPlayerLabels`, `showProgress`. `style` supplies the actual colours, border width and opacity. `ui.theme` supplies shared typography. The same web presenter resolves these properties in Studio and over the Bevy player; this does not claim a native Bevy UI renderer. Existing documents keep the legacy treatment until opted in. No gameplay rules are duplicated.\n\nA concept is a visual reference, not the final interface. Adapt composition, typography, framing and density, then inspect the rendered widgets on bright/dark backgrounds and during purchase, objective, elimination and round-end states. Player portraits require explicit portrait inputs; model or environment preview thumbnails are not portraits. The default marker is an intentional neutral silhouette.\n\nFor concept fidelity, measure the gameplay panel separately from any menu studies on the concept board. Transfer relative panel sizes, glyph sizes and primary/secondary number hierarchy, then compare at the same viewport and HUD scale. Hiding roster labels does not remove player names from their accessible description. Inline ammo retains reload feedback; silhouette feeds retain the weapon and headshot indication together. Reference art is not evidence of inventory, available actions, teammate health or objective ownership.\n"
 }
];

export interface DocSection { id: string; title: string; level: number }

/** The headings (`##`, `###`) of a topic: `id` is the heading text in lower case, dashes for spaces. */
export function docSections(topic: DocTopic): DocSection[] {
  const out: DocSection[] = [];
  let fence = false;
  for (const line of topic.text.split('\n')) {
    if (line.startsWith('```')) fence = !fence;
    const m = !fence && /^(#{2,3}) +(.+)$/.exec(line);
    if (m) out.push({ id: slug(m[2]), title: m[2].trim(), level: m[1].length });
  }
  return out;
}

const slug = (s: string) => s.toLowerCase().replace(/[`*]/g, '').replace(/[^a-z0-9§.]+/g, '-').replace(/^-+|-+$/g, '');

/** A topic by id (or a unique prefix of it). */
export function findDoc(id: string): DocTopic | undefined {
  const q = id.trim().toLowerCase();
  return DOC_TOPICS.find((t) => t.id === q) ?? (DOC_TOPICS.filter((t) => t.id.startsWith(q)).length === 1 ? DOC_TOPICS.find((t) => t.id.startsWith(q)) : undefined);
}

/**
 * The text of a topic, or of one of its sections (a heading id, a number such as `4.2` or `§3`, or words of the
 * heading): the section with everything under it, up to the next heading of the same or a higher level.
 */
export function readDoc(topic: DocTopic, section?: string): { text: string; section?: DocSection; sections: DocSection[] } | null {
  const sections = docSections(topic);
  if (!section) return { text: topic.text, sections };
  const q = section.trim().toLowerCase().replace(/^§/, '');
  const hit = sections.find((s) => s.id === slug(q))
    ?? sections.find((s) => new RegExp('^(§\\s*)?' + q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '[.\\s)]').test(s.title.toLowerCase()))
    ?? sections.find((s) => s.title.toLowerCase().includes(q));
  if (!hit) return null;
  const lines = topic.text.split('\n');
  let fence = false, start = -1, end = lines.length;
  for (let i = 0; i < lines.length; i++) {
    if (lines[i].startsWith('```')) fence = !fence;
    const m = !fence && /^(#{1,3}) +(.+)$/.exec(lines[i]);
    if (!m) continue;
    if (start < 0 && m[1].length === hit.level && m[2].trim() === hit.title) { start = i; continue; }
    if (start >= 0 && m[1].length <= hit.level) { end = i; break; }
  }
  return start < 0 ? null : { text: lines.slice(start, end).join('\n').trim() + '\n', section: hit, sections };
}
